typedef struct DL_TCH {
    // Downlink transport channel details
    int CRC_Status;
} DL_TCH;

typedef struct LTE_UE_List {
    LTE_UE_Context *context;
    DL_TCH **dl_tch_list;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
} LTE_UE_List;

LTE_UE_List* create_LTE_UE_List() {
    LTE_UE_List *list = malloc(sizeof(LTE_UE_List));
    if (list) {
        list->size = 0;
        list->capacity = 10; // Initial capacity
        list->context = malloc(list->capacity * sizeof(LTE_UE_Context));
        list->dl_tch_list = malloc(list->capacity * sizeof(DL_TCH*));
        pthread_mutex_init(&list->lock, NULL);
    }
    return list;
}

void destroy_LTE_UE_List(LTE_UE_List *list) {
    if (list) {
        pthread_mutex_lock(&list->lock);
        free(list->context);
        for (size_t i = 0; i < list->size; i++) {
            free(list->dl_tch_list[i]);
        }
        free(list->dl_tch_list);
        pthread_mutex_unlock(&list->lock);
        pthread_mutex_destroy(&list->lock);
        free(list);
    }
}

void add_LTE_UE(Context *context, LTE_UE_List *list) {
    if (list) {
        pthread_mutex_lock(&list->lock);
        if (list->size == list->capacity) {
            list->capacity *= 2;
            list->context = realloc(list->context, list->capacity * sizeof(LTE_UE_Context));
            list->dl_tch_list = realloc(list->dl_tch_list, list->capacity * sizeof(DL_TCH*));
