#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <netdb.h>
#include <arpa/inet.h>
#include <unistd.h>
#include <pthread.h>

#define MAX_IP_LEN 16
#define MAX_CONCURRENT_QUERIES 100
#define QUERY_CACHE_SIZE 256

typedef struct {
    char hostname[MAX_HOSTNAME_LEN];
    u_char ip[MAX_IP_LEN];
} Query;

Query query_cache[QUERY_CACHE_SIZE];
int cache_size = 0;
pthread_mutex_t cache_lock = PTHREAD_MUTEX_INITIALIZER;

void* dns_resolution_thread(void* arg) {
    Query* query = (Query*)arg;
    struct addrinfo hints, *res, *p;
    int status;
    char ipstr[MAX_IP_LEN];

    memset(&hints, 0, sizeof hints);
    hints.ai_family = AF_UNSPEC; // AF_INET or AF_INET6 to force version
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(query->hostname, NULL, &hints, &res)) != 0) {
        fprintf(stderr, "getaddrinfo: %s\n", gai_strerror(status));
        return (void*)-1;
    }

    for(p = res; p != NULL; p = p->ai_next) {
        void* addr;
        char* ipver;

        // get the pointer to the address itself,
        // different fields in IPv4 and IPv6:
        if (p->ai_family == AF_INET) { // IPv4
            struct sockaddr_in *ipv4 = (struct sockaddr_in *)p->ai_addr;
            addr = &(ipv4->sin_addr);
            ipver = "IPv4";
        } else { // IPv6
            struct sockaddr_in6 *ipv6 = (struct sockaddr_in6 *)p->ai_addr;
            addr = &(ipv6->sin6_addr);
            ipver = "IPv6";
        }

        // convert the IP to a string and print it:
        inet_ntop(p->ai_family, addr, ipstr, sizeof ipstr);
        printf("  %s: %s\n", ipver, ipstr);

        memcpy(query->ip, ipstr, MAX_IP_LEN);
    }

    freeaddrinfo(res); // all done with this structure
    return NULL;
}

int dns_resolution(const char* hostname, u_char* ip) {
    pthread_t thread_id;
    Query query;

    if (pthread_create(&thread_id, NULL, dns_resolution_thread, &query) != 0) {
        fprintf(stderr, "Failed to create thread\n");
        return -1;
    }

    // Wait for the DNS resolution thread to complete
    pthread_join(thread_id, NULL);

    memcpy(ip, query.ip, MAX_IP_LEN);
    return 0;
}

int main() {
    u_char ip[MAX_IP_LEN];
    if (dns_resolution("example.com", ip) == 0) {
        printf("IP address: %s\n", inet_ntoa(*(struct in_addr*)ip));
    }
    return 0;
}
