#include <stdio.h>
#include <stdlib.h>

// Helper function to find the largest integer in an array
int find_largest(int* arr, int size) {
    int max = arr[0];
    for (int i = 1; i < size; i++) {
        if (arr[i] > max) {
            max = arr[i];
        }
    }
    return max;
}

// Main function to read integers from input, find the largest, and print it
void process_input() {
    int n, *arr, size;

    // Read the number of elements from user
    printf("Enter the number of integers: ");
    if (scanf("%d", &n) != 1 || n <= 0) {
        printf("Invalid input. Please enter a positive integer.\n");
        return;
    }

    // Dynamically allocate memory for the array
    arr = (int*)malloc(n * sizeof(int));
    if (arr == NULL) {
        printf("Memory allocation failed.\n");
        return;
    }

    // Read integers from standard input
    printf("Enter %d integers:\n", n);
    size = 0;
    while (size < n && scanf("%d", &arr[size]) == 1) {
        size++;
    }

    if (size != n) {
        printf("Failed to read all integers. Please try again.\n");
        free(arr);
        return;
    }

    // Find and print the largest integer
    int largest = find_largest(arr, n);
    printf("The largest integer is: %d\n", largest);

    // Free dynamically allocated memory
    free(arr);
}

int main() {
    process_input();
    return 0;
}
```

