#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

// Define log levels
typedef enum {
    LOG_DEBUG,
    LOG_INFO,
    LOG_WARNING,
    LOG_ERROR
} LogLevel;

// Define log rotation policies
typedef enum {
    ROTATE_SIZE,
    ROTATE_TIME
} LogRotatePolicy;

// Define log entry structure
typedef struct {
    LogLevel level;
    const char* message;
    time_t timestamp;
    char module[256];
    int line_number;
} LogEntry;

// Define log configuration structure
typedef struct {
    FILE* log_file;
    LogLevel min_log_level;
    size_t max_log_size;
    time_t rotate_interval;
    LogRotatePolicy rotate_policy;
    pthread_mutex_t mutex;
    struct timespec last_log_time;
    int rate_limit_countdown;
} LoggerConfig;

// Initialize logger configuration
void init_logger(LoggerConfig* config, const char* log_file_path, LogLevel min_level, size_t max_size, time_t interval, LogRotatePolicy policy) {
    config->log_file = fopen(log_file_path, "a");
    if (config->log_file == NULL) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }
    config->min_log_level = min_level;
    config->max_log_size = max_size;
    config->rotate_interval = interval;
    config->rotate_policy = policy;
    pthread_mutex_init(&config->mutex, NULL);
    clock_gettime(CLOCK_REALTIME, &config->last_log_time);
    config->rate_limit_countdown = 0;
}

// Log a message
void log_message(LoggerConfig* config, LogLevel level, const char* module, int line_number, const char* format, ...) {
    if (level < config->min_log_level) {
        return;
    }

    va_list args;
    va_start(args, format);
    vfprintf(config->log_file, format, args);
    va_end(args);

    // Add timestamp and contextual information
    time_t now = time(NULL);
    fprintf(config->log_file, " [%s] %s:%d\n", ctime(&now), module, line_number);

    fflush(config->log_file);
}

// Rotate log file if necessary
void rotate_log(LoggerConfig* config) {
    // Implement log rotation logic based on policy and size
    // For simplicity, assume a fixed size for demonstration
    fseek(config->log_file, 0, SEEK_END);
    long current_size = ftell(config->log_file);
    if (current_size > config->max_log_size) {
        fclose(config->log_file);
        rename("error.log", "error.old");
        config->log_file = fopen("error.log", "a");
    }
}

// Rate-limiting mechanism
void rate_limit(LoggerConfig* config, int interval_ms) {
    struct timespec now;
    clock_gettime(CLOCK_REALTIME, &now);
    double elapsed_time = (double)(now.tv_sec - config->last_log_time.tv_sec) + (double)(now.tv_nsec - config->last_log_time.tv_nsec) / 1e9;
    if (elapsed_time < interval_ms / 1000.0) {
        config->rate_limit_countdown += elapsed_time * 1000;
        return;
    }
    config->last_log_time = now;
}

// Cleanup logger resources
void cleanup_logger(LoggerConfig* config) {
    fclose(config->log_file);
    pthread_mutex_destroy(&config->mutex);
}
```

This code snippet provides a basic structure for a logging system in C. It includes functions to initialize the logger, log messages with different levels and contextual information, rotate the log file based on size or time, rate-limit logging, and cleanup resources. The actual implementation of log rotation logic and external logging service integration is left as an exercise for the junior developer to complete.']

