    else if (strcmp(mode, "EDE") == 0) return EVP_des_ede();
    else if (strcmp(mode, "EDE3") == 0) return EVP_des_ede3();
    else if (strcmp(mode, "CFB") == 0) return EVP_des_cfb();
    else if (strcmp(mode, "NULL") == 0) return NULL_CIPHER;
    return NULL;
