bool validate_oauth_token(const char* token_json) {
    struct json_object *parsed_json;
    parsed_json = json_tokener_parse(token_json);

    const struct json_object *access_token;
    const struct json_object *expires_in;
    const struct json_object *token_type;
    const struct json_object *refresh_token;

    if (!json_object_object_get_ex(parsed_json, "access_token", &access_token) ||
        !json_object_object_get_ex(parsed_json, "expires_in", &expires_in) ||
        !json_object_object_get_ex(parsed_json, "token_type", &token_type)) {
        return false;
    }

    int expires_in_value = json_object_get_int(expires_in);
    const char* token_type_str = json_object_get_string(token_type);

    if (strcmp(token_type_str, "Bearer") != 0 || expires_in_value <= 0) {
        return false;
    }

    if (json_object_object_get_ex(parsed_json, "refresh_token", &refresh_token)) {
        // Optional field, can be ignored or validated further
    }

    json_object_put(parsed_json);
    return true;
}
