public class ConfigModifier {

    public static void main(String[] args) {
        Map<String, String> parameters = new HashMap<>();
        parameters.put("${PLACEHOLDER1}", "value1");
        parameters.put("${PLACEHOLDER2}", "value2");

        Pokemon pokemon = new Pokemon("Eevee", "Normal");

        try {
            modifyConfigFile(parameters);
            System.out.println("Configuration file updated successfully.");
        } catch (IOException | InterruptedException e) {
            System.err.println("Error modifying configuration file: " + e.getMessage());
        }

        String weaknesses = getPokemonWeaknesses(pokemon);
        System.out.println("Pokemon Weaknesses: " + weaknesses);
    }

    public static void modifyConfigFile(Map<String, String> parameters) throws IOException, InterruptedException {
        ProcessBuilder processBuilder = new ProcessBuilder();
        for (Map.Entry<String, String> entry : parameters.entrySet()) {
            processBuilder.command("sed", "-i", "s/" + entry.getKey() + "/" + entry.getValue() + "/", "config.txt");
            Process process = processBuilder.start();
            int exitCode = process.waitFor();
            if (exitCode != 0) {
                throw new IOException("Failed to execute sed command for placeholder: " + entry.getKey());
            }
        }

        processBuilder.command("echo", "EncryptedPassword=123456", ">>", "config.txt");
        Process process = processBuilder.start();
        int exitCode = process.waitFor();
        if (exitCode != 0) {
            throw new IOException("Failed to append encrypted password to config file.");
        }
    }

    public static String getPokemonWeaknesses(Pokemon pokemon) {
        String type = pokemon.getType();
        switch (type.toLowerCase()) {
            case "normal":
                return "Grass, Fighting, Poison";
            case "fire":
                return "Water, Ground, Rock";
            case "water":
                return "Electric, Grass, Ice";
            case "electric":
                return "Ground, Flying";
            case "grass":
                return "Fire, Water, Bug, Rock, Ghost, Dragon";
            case "ice":
                return "Fire, Fighting, Rock, Steel";
            case "fighting":
                return "Psychic, Flying, Fairy";
            case "poison":
                return "Ground, Psychic, Rock, Ghost, Steel";
            case "ground":
                return "Water, Ice, Grass, Electric, Poison, Flying, Bug, Rock, Fairy";
            case "flying":
                return "Electric, Ice, Rock";
            case "psychic":
                return "Bug, Ghost, Dark";
            case "bug":
                return "Fire, Flying, Rock";
            case "rock":
                return "Water, Grass, Fighting, Ground, Steel";
            case "ghost":
