    const char *access_token = json_object_get_string(json_object_object_get_ex(jobj, "access_token", NULL));
    int expires_in = (int)json_object_get_int(json_object_object_get_ex(jobj, "expires_in", NULL));
    const char *token_type = json_object_get_string(json_object_object_get_ex(jobj, "token_type", NULL));

    if (!access_token || expires_in <= 0 || strcmp(token_type, "Bearer") != 0) {
        return false;
    }

    struct json_object *refresh_token_obj = json_object_object_get_ex(jobj, "refresh_token", NULL);
    bool has_refresh_token = (refresh_token_obj && !json_is_null(refresh_token_obj));

    if (!has_refresh_token) {
        return true; // Refresh token is optional
    }

    const char *refresh_token = json_object_get_string(refresh_token_obj);
    if (!refresh_token) {
        return false;
    }

    return true;
}
