#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    pthread_mutex_t mutex;
    int initial_lock_state;
} SafeMutex;

int safe_mutex_init(SafeMutex *mutex, int initial_lock_state) {
    if (mutex == NULL) {
        fprintf(stderr, "Error: Invalid mutex pointer\n");
        return -1;
    }

    int result = pthread_mutex_init(&mutex->mutex, NULL);
    if (result != 0) {
        fprintf(stderr, "Error: Failed to initialize mutex\n");
        return result;
    }

    mutex->initial_lock_state = initial_lock_state;
    if (initial_lock_state == PTHREAD_MUTEX_LOCKED) {
        result = pthread_mutex_lock(&mutex->mutex);
        if (result != 0) {
            fprintf(stderr, "Error: Failed to lock initially locked mutex\n");
            pthread_mutex_destroy(&mutex->mutex);
            return result;
        }
    }

    return 0;
}

void safe_mutex_cleanup(SafeMutex *mutex) {
    if (mutex == NULL) {
        fprintf(stderr, "Error: Invalid mutex pointer\n");
        return;
    }

    int result = pthread_mutex_unlock(&mutex->mutex);
    if (result != 0) {
        fprintf(stderr, "Error: Failed to unlock mutex during cleanup\n");
    }

    result = pthread_mutex_destroy(&mutex->mutex);
    if (result != 0) {
        fprintf(stderr, "Error: Failed to destroy mutex during cleanup\n");
    }
}

// Example usage
void* thread_function(void* arg) {
    SafeMutex *mutex = (SafeMutex *)arg;

    if (safe_mutex_init(mutex, PTHREAD_MUTEX_LOCKED) == 0) {
        // Critical section code here
        safe_mutex_cleanup(mutex);
    }

    return NULL;
}
