pub fn generate_llvm_ir(file_path: &str, allowed_dir: &Path) -> Result<String, String> {
    let path = PathBuf::from(file_path);

    if !path.starts_with(allowed_dir) {
        return Err(format!("File path is outside the allowed directory tree."));
    }

    if !path.is_file() || !fs::metadata(&path).is_ok() {
        return Err(format!("Invalid file path or file does not exist."));
    }

    let content = fs::read_to_string(&path).map_err(|_| "Failed to read file content.")?;

    let lexer = Lexer::new(&content);
    let tokens = lexer.tokenize(&content);

    let parser = Parser::new(lexer);
    let syntax_tree = parser.parse(tokens);

    let ir_code = generate_ir(&syntax_tree);
    println!("Parsed Syntax Tree: {:?}", syntax_tree);
    println!("Generated LLVM IR:\n{}", ir_code);

    Ok(ir_code)
