void insertAfterKey(std::unordered_map<int, std::vector<int>>& myMap, int key1, int key2) {
    if (myMap.find(key1) == myMap.end()) {
        myMap[key1] = myMap[key2];
    } else {
        auto it = myMap.find(key1);
        myMap.insert({key2, std::vector<int>()});
        for (auto& pair : myMap) {
            if (&pair != &*it) {
                myMap[key2].insert(myMap[key2].end(), pair.second.begin(), pair.second.end());
            }
        }
    }
