namespace Simulation {

    namespace RandomGen {
        std::mutex mtx;
    }

    class ConfigurableRandomGenerator {
    public:
        static ConfigurableRandomGenerator* GetInstance(const std::string& type, int seed = 0) {
            std::lock_guard<std::mutex> lock(RandomGen::mtx);
            if (!instanceMap[type]) {
                instanceMap[type] = new ConfigurableRandomGenerator(type, seed);
            }
            return instanceMap[type];
        }

        ~ConfigurableRandomGenerator() {
            delete distribution;
        }

        void SetSeed(int seed) {
            generator.seed(seed);
        }

        double GenerateNumber() const {
            if (type == "uniform") {
                return uniform_distribution(generator);
            } else if (type == "normal") {
                return normal_distribution(generator);
            }
            throw std::runtime_error("Unsupported distribution type");
        }

    private:
        ConfigurableRandomGenerator(const std::string& t, int seed) : type(t), generator(seed) {
            if (t == "uniform") {
                uniform_distribution = new std::uniform_real_distribution<>(0.0, 1.0);
            } else if (t == "normal") {
                normal_distribution = new std::normal_distribution<>(0.0, 1.0);
            } else {
                throw std::runtime_error("Unsupported distribution type");
            }
        }

        ConfigurableRandomGenerator(const ConfigurableRandomGenerator&) = delete;
        ConfigurableRandomGenerator& operator=(const ConfigurableRandomGenerator&) = delete;

        static std::unordered_map<std::string, ConfigurableRandomGenerator*> instanceMap;
        std::string type;
        mutable std::mt19937 generator;
        std::uniform_real_distribution<double>* uniform_distribution = nullptr;
        std::normal_distribution<double>* normal_distribution = nullptr;
    };

    std::unordered_map<std::string, ConfigurableRandomGenerator*> ConfigurableRandomGenerator::instanceMap;

}

int main() {
    Simulation::ConfigurableRandomGenerator* gen1 = Simulation::ConfigurableRandomGenerator::GetInstance("uniform");
    Simulation::ConfigurableRandomGenerator* gen2 = Simulation::ConfigurableRandomGenerator::GetInstance("normal");

    std::thread t1([&]() {
        for (int i = 0; i < 10; ++i) {
            std::cout << "Thread 1: " << gen1->GenerateNumber() << std::endl;
        }
    });

    std::thread t2([&]() {
        for (int i = 0; i < 10; ++i) {
            std::cout << "Thread 2: " << gen2->GenerateNumber() << std::endl;
        }
    });

    t1.join();
    t2.join();

    return 0;
}
