using System;
using System.Data;
using System.Data.SqlClient;

public class SqlQueryBuilder
{
    public static IDataReader GenerateSqlQuery(SqlConnection connection, Configuration config, string sortBy = null, int page = 1, int pageSize = 10)
    {
        try
        {
            using (var command = new SqlCommand())
            {
                command.Connection = connection;
                command.CommandText = ConstructSqlQuery(config);

                if (!string.IsNullOrEmpty(sortBy))
                    command.CommandText += $" ORDER BY {sortBy}";

                if (page > 0 && pageSize > 0)
                {
                    int offset = (page - 1) * pageSize;
                    command.CommandText += $" OFFSET {offset} ROWS FETCH NEXT {pageSize} ROWS ONLY";
                }

                return command.ExecuteReader();
            }
        }
        catch (Exception ex)
        {
            // Handle exception and log or rethrow
            throw new InvalidOperationException("Error generating SQL query", ex);
        }
    }

    private static string ConstructSqlQuery(Configuration config)
    {
        string query = $"SELECT {string.Join(", ", config.Columns)} FROM {config.Table}";

        if (config.Joins != null && config.Joins.Count > 0)
        {
            foreach (var join in config.Joins)
                query += $" INNER JOIN {join.Table} ON {join.On}";
        }

        if (!string.IsNullOrEmpty(config.Where))
            query += $" WHERE {config.Where}";

        return query;
    }
}

public class Configuration
{
    public string Table { get; set; }
    public string[] Columns { get; set; }
    public Join[] Joins { get; set; }
    public string Where { get; set; }
}

public class Join
{
    public string Table { get; set; }
    public string On { get; set; }
}
