from flask import Flask, request, jsonify

app = Flask(__name__)

resources = {}

@app.route('/resource', methods=['PUT'])
def update_resource():
    data = request.json
    resource_id = data.get('id')
    if resource_id in resources:
        resources[resource_id] = data
        return jsonify({"message": "Resource updated successfully"}), 200
    else:
        return jsonify({"error": "Resource not found"}), 404

@app.route('/resources', methods=['POST'])
def bulk_add_resources():
    data = request.json
    added_ids = []
    for resource in data:
        resources[resource['id']] = resource
        added_ids.append(resource['id'])
    return jsonify({"message": "Resources added successfully", "ids": added_ids}), 201

@app.route('/resources', methods=['DELETE'])
def delete_resources():
    start_id = request.args.get('start', type=int)
    end_id = request.args.get('end', type=int)
    deleted_ids = []
    for id in range(start_id, end_id + 1):
        if str(id) in resources:
            del resources[str(id)]
            deleted_ids.append(str(id))
    return jsonify({"message": "Resources deleted successfully", "ids": deleted_ids}), 200

if __name__ == '__main__':
    app.run(debug=True)
