using System;
using System.Collections.Generic;
using System.Linq;
using System.Xml;
using System.Xml.XPath;

public class XmlParser
{
    private static Dictionary<string, XmlDocument> cache = new Dictionary<string, XmlDocument>();

    public List<XmlNode> GetElementsByTagName(string xmlString, string elementName, string namespaceURI = null, int? maxResults = null)
    {
        try
        {
            XmlDocument doc;
            if (!cache.ContainsKey(xmlString))
            {
                doc = new XmlDocument();
                doc.LoadXml(xmlString);
                cache[xmlString] = doc;
            }
            else
            {
                doc = cache[xmlString];
            }

            XPathNavigator navigator = doc.CreateNavigator();
            XPathNodeIterator iterator;

            if (string.IsNullOrEmpty(namespaceURI))
            {
                iterator = navigator.Select($"//i:{elementName}[lower-case(local-name())='{elementName.ToLower()}']");
            }
            else
            {
                string prefix = GetPrefixFromNamespace(navigator, namespaceURI);
                iterator = navigator.Select($"//{prefix}:{elementName}[lower-case(local-name())='{elementName.ToLower()}']");
            }

            List<XmlNode> result = new List<XmlNode>();
            while (iterator.MoveNext() && (!maxResults.HasValue || result.Count < maxResults.Value))
            {
                result.Add(iterator.Current.CloneNode(true));
            }

            return result;
        }
        catch (XmlException ex)
        {
            Console.WriteLine($"XML parsing error: {ex.Message}");
            return new List<XmlNode>();
        }
    }

    private string GetPrefixFromNamespace(XPathNavigator navigator, string namespaceURI)
    {
        foreach (string prefix in navigator.GetNamespacesInScope(Xml NamespaceScope.All))
        {
            if (navigator.LookupNamespace(prefix) == namespaceURI)
            {
                return prefix;
            }
        }
        return null;
    }
}
