class UserAccountManager {
    private $db;
    private $rateLimiter;

    public function __construct($db, $rateLimiter) {
        $this->db = $db;
        $this->rateLimiter = $rateLimiter;
    }

    public function handleRequest($_REQUEST) {
        if (!$this->rateLimiter->allowRequest($_SERVER['REMOTE_ADDR'])) {
            return json_encode(['message' => 'error', 'reason' => 'Rate limit exceeded']);
        }

        if (!isset($_REQUEST['name']) || !isset($_REQUEST['email']) || !isset($_REQUEST['password'])) {
            return json_encode(['message' => 'error', 'reason' => 'Missing required fields']);
        }

        $id = isset($_REQUEST['id']) ? intval($_REQUEST['id']) : null;
        $subAction = isset($_REQUEST['sub_action']) && $_REQUEST['sub_action'] === 'delete' ? true : false;

        try {
            $this->db->beginTransaction();

            if ($subAction) {
                if (!$this->validateId($id)) {
                    throw new Exception('Invalid user ID');
                }
                $this->deleteUser($id);
            } else {
                $name = $_REQUEST['name'];
                $email = $_REQUEST['email'];
                $password = $_REQUEST['password'];

                if (!$this->validateName($name) || !$this->validateEmail($email) || !$this->validatePassword($password)) {
                    throw new Exception('Invalid input data');
                }
                $this->createUser($name, $email, $password);
            }

            $this->db->commit();
        } catch (Exception $e) {
            $this->db->rollBack();
            return json_encode(['message' => 'error', 'reason' => $e->getMessage()]);
        }

        $transactionId = uniqid();
        $logData = [
            'timestamp' => date('Y-m-d H:i:s'),
            'ip_address' => $_SERVER['REMOTE_ADDR'],
            'action_type' => $subAction ? 'delete' : 'create',
            'data' => json_encode(['id' => $id, 'name' => $_REQUEST['name'], 'email' => $_REQUEST['email']])
        ];
        $this->logAction($transactionId, $logData);

        if ($subAction) {
