            .HasRequired(u => u.Lockout)
            .WithRequiredDependent(l => l.User);

        modelBuilder.Entity<IdentityUserLogin>()
            .HasKey(l => new { l.LoginProvider, l.ProviderKey, l.UserId });
    }
