const { promisify } = require('util');
const { parse, format } = require('date-fns');

// External configuration file handling (simulated)
const config = {
  directory: './files',
  fileDependencies: {
    'file2.txt': ['file1.txt'],
    // Add more dependencies as needed
  }
};

async function readFilesWithDependencies(directory, fileDependencies) {
  const filesToRead = Object.keys(fileDependencies).sort((a, b) => {
    if (fileDependencies[b].includes(a)) return 1;
    if (fileDependencies[a].includes(b)) return -1;
    return 0;
  });

  const results = {};

  for (const file of filesToRead) {
    try {
      const filePath = path.join(directory, file);
      const content = await fs.readFile(filePath, 'utf8');
      const stats = await fs.stat(filePath);

      results[file] = {
        content,
        size: stats.size,
        lastModified: format(stats.mtime, 'yyyy-MM-dd HH:mm:ss'),
      };
    } catch (error) {
      console.error(`Error reading file ${file}:`, error);
      results[file] = { error: error.message };
    }
  }

  return results;
}

// Usage example
(async () => {
  try {
    const results = await readFilesWithDependencies(config.directory, config.fileDependencies);
    console.log(results);
  } catch (error) {
    console.error('Error in main function:', error);
  }
})();
```

