class DataStreamManager {
  constructor() {
    this.stream = [];
    this.paused = false;
    this.graphDB = new GraphDatabase();
  }

  async addData(data) {
    if (!this.paused) {
      this.stream.push(data);
      await this.updateGraph(data);
    }
  }

  pauseStream() {
    this.paused = true;
  }

  resumeStream() {
    this.paused = false;
    this.processPendingData();
  }

  async processPendingData() {
    while (this.stream.length > 0 && !this.paused) {
      const data = this.stream.shift();
      await this.updateGraph(data);
    }
  }

  async updateGraph(data) {
    // Simulate adding vertices and edges
