["```javascript
function copyBytesFromChunks(chunks, byteOffset, byteCount) {
  if (!Array.isArray(chunks) || typeof byteOffset !== 'number' || typeof byteCount !== 'number') {
    throw new Error('Invalid input parameters');
  }

  const totalLength = chunks.reduce((acc, chunk) => acc + chunk.length, 0);
  if (byteOffset < 0 || byteOffset >= totalLength || byteCount < 0) {
    throw new Error('Byte offset or count out of bounds');
  }

  let bytesRead = 0;
  const targetBuffer = Buffer.allocUnsafe(byteCount);
  for (const chunk of chunks) {
    if (bytesRead + chunk.length > byteCount) {
      chunk.copy(targetBuffer, bytesRead, 0, byteCount - bytesRead);
      break;
    }
    chunk.copy(targetBuffer, bytesRead);
    bytesRead += chunk.length;
    if (bytesRead === byteCount) break;
  }

  return targetBuffer;
}
