import java.io.IOException;
import java.net.InetSocketAddress;
import java.nio.ByteBuffer;
import java.nio.channels.SelectionKey;
import java.nio.channels.Selector;
import java.nio.channels.ServerSocketChannel;
import java.nio.channels.SocketChannel;
import java.util.Iterator;
import java.util.Set;

public class SecureConnectionServer {

    public void startServer(int port) throws IOException {
        Selector selector = Selector.open();
        ServerSocketChannel serverSocketChannel = ServerSocketChannel.open();
        serverSocketChannel.bind(new InetSocketAddress(port));
        serverSocketChannel.configureBlocking(false);
        serverSocketChannel.register(selector, SelectionKey.OP_ACCEPT);

        while (true) {
            selector.select();

            Set<SelectionKey> selectedKeys = selector.selectedKeys();
            Iterator<SelectionKey> keyIterator = selectedKeys.iterator();

            while (keyIterator.hasNext()) {
                SelectionKey key = keyIterator.next();

                if (key.isAcceptable()) {
                    handleAccept(key, selector);
                } else if (key.isReadable()) {
                    handleRead(key);
                }

                keyIterator.remove();
            }
        }
    }

    private void handleAccept(SelectionKey key, Selector selector) throws IOException {
        ServerSocketChannel serverSocketChannel = (ServerSocketChannel) key.channel();
        SocketChannel clientSocketChannel = serverSocketChannel.accept();
        clientSocketChannel.configureBlocking(false);
        clientSocketChannel.register(selector, SelectionKey.OP_READ);
        logConnectionState(clientSocketChannel.socket().getInetAddress(), true);
    }

    private void handleRead(SelectionKey key) {
        SocketChannel clientSocketChannel = (SocketChannel) key.channel();
        ByteBuffer buffer = ByteBuffer.allocate(1024);

        try {
            int bytesRead = clientSocketChannel.read(buffer);
            if (bytesRead == -1) {
                closeConnection(clientSocketChannel);
            } else {
                processBuffer(buffer);
            }
        } catch (IOException e) {
            closeConnection(clientSocketChannel);
        }
    }

    private void processBuffer(ByteBuffer buffer) {
        // Process the received data
    }

    private void closeConnection(SocketChannel clientSocketChannel) throws IOException {
        clientSocketChannel.close();
        logConnectionState(clientSocketChannel.socket().getInetAddress(), false);
    }

    private void logConnectionState(InetAddress address, boolean isConnected) {
        System.out.println(isConnected ? "Connected: " + address : "Disconnected: " + address);
    }
}
