import threading
import time
from collections import OrderedDict

class SessionManager:
    def __init__(self, max_sessions=100):
        self.sessions = OrderedDict()
        self.max_sessions = max_sessions
        self.lock = threading.Lock()

    def generate_session_token(self):
        return str(time.time())

    def validate_and_update_session(self, session_token):
        with self.lock:
            if session_token not in self.sessions or self.is_token_expired(self.sessions[session_token]):
                self.invalidate_session(session_token)
                new_token = self.generate_session_token()
                self.sessions[new_token] = time.time()
                return new_token
            else:
                # Move to the end to mark it as most recently used
                self.sessions.move_to_end(session_token)
                return session_token

    def is_token_expired(self, timestamp):
        return time.time() - timestamp > 3600  # Token expires after 1 hour

    def invalidate_session(self, session_token):
        with self.lock:
            if session_token in self.sessions:
                del self.sessions[session_token]

    def check_and_manage_storage(self):
        with self.lock:
            while len(self.sessions) > self.max_sessions:
                oldest_key = next(iter(self.sessions))
                self.invalidate_session(oldest_key)

    def load_user_preferences(self, session_token):
        with self.lock:
            preferences_path = f"path/to/session_root/{session_token}/preferences.json"
            try:
                with open(preferences_path, 'r') as file:
                    preferences = json.load(file)
                    # Update session settings based on preferences
                    print("User Preferences Loaded:", preferences)
            except FileNotFoundError:
                print("No preferences file found.")

# Example usage
session_manager = SessionManager()
new_session_token = session_manager.validate_and_update_session("existing_token")
session_manager.check_and_manage_storage()
session_manager.load_user_preferences(new_session_token)
