['```rust
use reqwest::{Client, RequestBuilder, Url};
use std::time::{Duration, Instant};

fn create_http_client(url: &str) -> Result<RequestBuilder, Box<dyn std::error::Error>> {
    let client = Client::builder()
        .danger_accept_invalid_certs(true)
        .timeout(Duration::from_secs(5))
        .build()?;

    Ok(client.request(reqwest::Method::GET, url))
}

fn retry_request(
    request: RequestBuilder,
    max_retries: u32,
) -> Result<reqwest::Response, Box<dyn std::error::Error>> {
    let mut retries = 0;
    loop {
        match request.send().await {
            Ok(response) => return Ok(response),
            Err(_) if retries < max_retries => {
                retries += 1;
                tokio::time::sleep(Duration::from_secs(2u64.pow(retries))).await;
            }
            _ => return Err("Max retries reached".into()),
        }
    }
}

fn handle_redirects(
    response: reqwest::Response,
    max_redirects: u32,
) -> Result<reqwest::Response, Box<dyn std::error::Error>> {
    if let Some(location) = response.headers().get(reqwest::header::LOCATION) {
        let url = Url::parse(&location.to_str()?)?;
        if max_redirects > 0 {
            return Ok(request(url)
                .send()
                .await?
                .handle_redirects(max_redirects - 1)?);
        }
    }
    Ok(response)
}

fn log_request_response(
    request: &reqwest::Request,
    response: &reqwest::Response,
) -> Result<(), Box<dyn std::error::Error>> {
    println!("Request URL: {:?}", request.url());
    println!("Status Code: {}", response.status());
    Ok(())
}
