use std::process::{Command, Stdio};
use std::time::{Instant, Duration};
use libc::{sysconf, _SC_PHYS_PAGES, _SCPageSize};
use std::sync::{Arc, Mutex};
use rustc_driver::{self, CompilerInput, CompilationMode};
use rustc_interface::{Config, CompilerCallbacks};
use log::{info, error};

struct DetailedReport {
    time_taken: Duration,
    initial_rss: u64,
    final_rss: u64,
}

impl DetailedReport {
    fn new() -> Self {
        DetailedReport {
            time_taken: Duration::new(0, 0),
            initial_rss: 0,
            final_rss: 0,
        }
    }

    fn measure_time<F>(&mut self, f: F) where F: FnOnce() {
        let start = Instant::now();
        f();
        self.time_taken = start.elapsed();
    }

    fn get_rss(&self) -> u64 {
        unsafe {
            let pages = sysconf(_SC_PHYS_PAGES).unwrap() as u64;
            let page_size = sysconf(_SCPageSize).unwrap() as u64;
            pages * page_size
        }
    }

    fn log_memory_usage(&mut self) {
        self.initial_rss = self.get_rss();
        info!("Initial RSS: {} bytes", self.initial_rss);
    }

    fn log_final_memory_usage(&mut self) {
        self.final_rss = self.get_rss();
        info!("Final RSS: {} bytes", self.final_rss);
    }
}

struct CustomCallbacks;

impl CompilerCallbacks for CustomCallbacks {
    fn early_exit(&self, compiler_session: rustc_interface::CompilerSession) -> ! {
        rustc_driver::early_exit(compiler_session);
    }
}

fn compile_with_report() -> DetailedReport {
    let mut report = DetailedReport::new();
    report.log_memory_usage();

    let start_time = Instant::now();
    let result = rustc_driver::catch_with_exit_code(|| {
        let compiler_input = CompilerInput::File(std::path::PathBuf::from("src/main.rs"));
        let config = Config {
            input: compiler_input,
            mode: CompilationMode::Normal,
            callbacks: Arc::new(Mutex::new(CustomCallbacks {})),
            ..Default::default()
        };
        rustc_driver::run_compiler(config, |compiler| compiler.compile());
    });
    report.time_taken = start_time.elapsed();

    if let Err(e) = result {
        error!("Compilation failed with error: {:?}", e);
    } else {
        info!("Compilation successful");
    }

    report.log_final_memory_usage();
    report
}
