    private $gateway;

    public function __construct($db, $gateway) {
        $this->db = $db;
        $this->gateway = $gateway;
    }

    public function processTransaction($orderId, $amount, $customerEmail, $merchantEmail) {
        // Validate input data
        if (!filter_var($customerEmail, FILTER_VALIDATE_EMAIL)) {
            throw new Exception("Invalid customer email");
        }
        if (!filter_var($merchantEmail, FILTER_VALIDATE_EMAIL)) {
            throw new Exception("Invalid merchant email");
        }

        // Check for duplicate transactions
        $existingTransaction = $this->db->query(
            "SELECT * FROM transactions WHERE order_id = ?",
            [$orderId]
        );

        if ($existingTransaction) {
            throw new Exception("Duplicate transaction detected");
        }

        try {
            // Send payment request to the third-party gateway
            $paymentResponse = $this->gateway->processPayment($orderId, $amount);

            if ($paymentResponse['status'] !== 'success') {
                throw new Exception("Gateway error: " . $paymentResponse['message']);
            }

            // Store transaction details in the database
            $transactionId = $this->db->insert(
                "INSERT INTO transactions (order_id, amount, customer_email, merchant_email, payment_gateway_response) VALUES (?, ?, ?, ?, ?)",
                [$orderId, $amount, $customerEmail, $merchantEmail, json_encode($paymentResponse)]
            );

            // Send confirmation email to the customer
            $this->sendConfirmationEmail(
                $customerEmail,
                "Transaction Confirmation",
                "Dear Customer,\n\nYour transaction has been processed successfully. Thank you for choosing our service."
            );

            // Send confirmation email to the merchant
            $this->sendConfirmationEmail(
                $merchantEmail,
                "New Transaction Notification",
                "A new transaction has been received. Order ID: {$orderId}, Amount: {$amount}"
            );

            return ['status' => 'success', 'transaction_id' => $transactionId];
        } catch (Exception $e) {
            // Log the error and retry if necessary
            error_log($e->getMessage());
            throw new Exception("Transaction processing failed");
        }
    }

    private function sendConfirmationEmail($email, $subject, $message) {
        mail($email, $subject, $message);
    }
}
