public class PasswordService {

    @Autowired
    private UserDAO userDAO;

    @Autowired
    private AuthService authService;

    public void updatePassword(String userId, String newPassword) throws Exception {
        // Validate password complexity requirements
        if (!isValidPassword(newPassword)) {
            throw new IllegalArgumentException("Invalid password");
        }

        // Hash the new password
        String hashedPassword = hashPassword(newPassword);

        // Update user's password in database with DAO layer
        userDAO.updateUserPassword(userId, hashedPassword);

        // Notify external authentication service about the password change
        authService.notifyPasswordChange(userId);
    }

    private boolean isValidPassword(String password) {
        // Implement complexity requirements validation logic here
        return true;
    }

    private String hashPassword(String password) throws NoSuchAlgorithmException {
        MessageDigest md = MessageDigest.getInstance("SHA-256");
        byte[] hashBytes = md.digest(password.getBytes());
        StringBuilder hexString = new StringBuilder();
        for (byte b : hashBytes) {
            String hex = Integer.toHexString(0xff & b);
            if(hex.length() == 1) hexString.append('0');
            hexString.append(hex);
        }
        return hexString.toString();
    }
}
