import os
import time
from tenacity import retry, wait_exponential

@retry(wait=wait_exponential(multiplier=2, min=1, max=60))
def read_last_line_from_log(file_path):
    with open(file_path, 'r', buffering=8*1024) as file:
        while True:
            try:
                file.seek(0, os.SEEK_END)
                last_line = file.readline()
                if not last_line:
                    time.sleep(1)
                    continue
                break
            except IOError:
                time.sleep(1)
    return int(last_line.strip().split(',')[0])

def main():
    log_file_path = '\\\\shared_network_drive\\logs\\log.txt'
    try:
        sequence_number = read_last_line_from_log(log_file_path)
        print(f"Last sequence number: {sequence_number}")
    except Exception as e:
        print(f"Error processing log file: {e}")

if __name__ == "__main__":
    main()
