typedef struct {
    uint62_t transaction_id[MAX_CONCURRENT_PROCESSES];
    bool processed[MAX_CONCURRENT_PROCESSES];
    time_t last_processed[MAX_CONCURRENT_PROCESSES];
    int count;
} ProcessedTransactions;

ProcessedTransactions processed_transactions = {0};

int process_transaction(Transaction *transaction, int max_age, int window_size) {
    // Check for duplicate transactions
    for (int i = 0; i < processed_transactions.count; ++i) {
        if (processed_transactions.transaction_id[i] == transaction->id) {
            time_t current_time = time(NULL);
            if ((current_time - processed_transactions.last_processed[i]) > window_size) {
                // Reschedule the transaction for later processing
                return 1;
            } else {
                // Duplicate detected, skip processing
                return 0;
            }
        }
    }

    // Process the transaction
    // Update metrics (average age, total transactions, max weighted sum)
    // Example: update_metrics(transaction->age);

    // Add the transaction to the processed list
    if (processed_transactions.count < MAX_CONCURRENT_PROCESSES) {
        processed_transactions.transaction_id[processed_transactions.count] = transaction->id;
        processed_transactions.processed[processed_transactions.count] = true;
        processed_transactions.last_processed[processed_transactions.count] = time(NULL);
        processed_transactions.count++;
    }

    // Return the maximum weighted sum and corresponding ID
    return transaction->weighted_sum;
}

void reset_processed_transactions() {
    memset(processed_transactions.transaction_id, 0, sizeof(processed_transactions.transaction_id));
    memset(processed_transactions.processed, false, sizeof(processed_transactions.processed));
    processed_transactions.count = 0;
