class GameCharacter {
public:
    GameCharacter() : lastAttackTime(0), cooldown(9) {}

    void selectAndExecuteAttack() {
        std::lock_guard<std::mutex> lock(mutex);
        auto currentTime = std::chrono::steady_clock::now();
        if (currentTime - lastAttackTime >= std::chrono::seconds(cooldown)) {
            std::random_device rd;
            std::mt19937 gen(rd());
            std::uniform_int_distribution<> dis(0, 1);
            bool useFirstAttack = dis(gen) == 0;

            if (useFirstAttack) {
                executeFirstAttack();
            } else {
                executeSecondAttack();
            }

            lastAttackTime = currentTime;
        }
    }

private:
    void executeFirstAttack() {
        std::cout << "Executing first attack!" << std::endl;
    }

    void executeSecondAttack() {
        std::cout << "Executing second attack!" << std::endl;
    }

    std::chrono::time_point<std::chrono::steady_clock> lastAttackTime;
    int cooldown;
    std::mutex mutex;
};

int main() {
    GameCharacter character1;
    GameCharacter character2;

    std::thread t1([&character1]() {
        for (int i = 0; i < 10; ++i) {
            character1.selectAndExecuteAttack();
            std::this_thread::sleep_for(std::chrono::seconds(1));
        }
    });

    std::thread t2([&character2]() {
        for (int i = 0; i < 10; ++i) {
            character2.selectAndExecuteAttack();
            std::this_thread::sleep_for(std::chrono::seconds(1));
        }
    });

    t1.join();
    t2.join();

