using UnityEngine;

public class RandomValueGenerator : System.IComparable<RandomValueGenerator>
{
    private float minValue;
    private float maxValue;

    public RandomValueGenerator(float minValue, float maxValue)
    {
        if (minValue > maxValue)
        {
            throw new ArgumentOutOfRangeException("maxValue", "Max value must be greater than or equal to min value.");
        }
        this.minValue = minValue;
        this.maxValue = maxValue;
    }

    /// <summary>
    /// Generates a random float within the specified range, inclusive.
    /// </summary>
    public float GetRandomFloat()
    {
        return UnityEngine.Random.Range(minValue, maxValue);
    }

    /// <summary>
    /// Generates a random integer within the specified range, inclusive.
    /// </summary>
    public int GetRandomInt()
    {
        return (int)UnityEngine.Random.Range(minValue, maxValue + 1f);
    }

    /// <summary>
    /// Generates a random float within the specified range, excluding the upper bound.
    /// </summary>
    public float GetRandomFloatExclusiveUpper()
    {
        return UnityEngine.Random.Range(minValue, maxValue);
    }

    /// <summary>
    /// Generates a random integer within the specified range, excluding the upper bound.
    /// </summary>
    public int GetRandomIntExclusiveUpper()
    {
        return (int)UnityEngine.Random.Range(minValue, maxValue - 1f);
    }

    /// <summary>
    /// Generates a random integer within the specified range, excluding both bounds.
    /// </summary>
    public int GetRandomIntExclusiveBounds()
    {
        if (minValue == maxValue)
        {
            throw new InvalidOperationException("Cannot generate exclusive values when min value equals max value.");
        }
        return UnityEngine.Random.Range((int)(minValue + 1f), (int)maxValue);
    }

    public int CompareTo(RandomValueGenerator other)
    {
        if (other == null)
        {
            return 1;
        }
        return minValue.CompareTo(other.minValue) != 0 ? minValue.CompareTo(other.minValue) : maxValue.CompareTo(other.maxValue);
    }

    public override string ToString()
    {
        return $"Range[{minValue}, {maxValue}]";
    }
}
