async function asyncReduce(arr, initialValue, callback) {
    if (!Array.isArray(arr)) throw new Error('Input must be an array');
    if (typeof initialValue === 'undefined') throw new Error('Initial value is required');

    let accumulator = initialValue;

    for (const num of arr) {
        try {
            accumulator = await callback(accumulator, num);
        } catch (error) {
            console.error(`Error processing number ${num}:`, error);
            // Handle error based on your requirements
        }
    }

    return accumulator;
}

// Example usage:
(async () => {
    const numbers = Array.from({ length: 1000000 }, (_, i) => i); // Large array of numbers

    try {
        const result = await asyncReduce(numbers, 0, async (acc, num) => {
            // Simulate asynchronous operation
            return new Promise(resolve => setTimeout(() => resolve(acc + num), 1));
        });

        console.log('Reduced result:', result);
    } catch (error) {
        console.error('Error in reduce function:', error);
    }
})();
