int loadResourceBundle(const char *path, ResourceItem **bundle, size_t *numItems) {
    FILE *file = fopen(path, "rb");
    if (!file) {
        perror("Failed to open file");
        return -1; // Error opening file
    }

    fseek(file, 0, SEEK_END);
    long fileSize = ftell(file);
    fseek(file, 0, SEEK_SET);

    char *buffer = (char *)malloc(fileSize);
    if (!buffer) {
        fclose(file);
        perror("Failed to allocate memory for buffer");
        return -2; // Error allocating memory
    }

    size_t bytesRead = fread(buffer, 1, fileSize, file);
    if (bytesRead != fileSize) {
        free(buffer);
        fclose(file);
        perror("Failed to read file completely");
        return -3; // Error reading file
    }
    fclose(file);

    *bundle = (ResourceItem *)malloc(sizeof(ResourceItem));
    if (!*bundle) {
        free(buffer);
        perror("Failed to allocate memory for bundle");
        return -4; // Error allocating memory
    }

    (*bundle)->type = TEXT; // Placeholder, actual type should be determined from file content
    (*bundle)->data = (void *)buffer;
    (*bundle)->dataSize = fileSize;

    *numItems = 1;

    // Additional logic to handle multiple types of resources and manage memory properly

    return 0; // Success
}

// Example usage
int main() {
    ResourceItem *bundle;
    size_t numItems;
    int result = loadResourceBundle("path_to_resource_file", &bundle, &numItems);
    if (result == 0) {
        printf("Loaded %zu items from the resource bundle.\n", numItems);
        // Free allocated memory
        free(bundle->data);
        free(bundle);
    } else {
        printf("Failed to load resource bundle with error code: %d\n", result);
    }
    return 0;
}
```

