#define MAX_LOG_SIZE 1024

typedef struct {
    char *log_buffer;
    size_t log_length;
    size_t max_log_size;
    pthread_mutex_t log_lock;
} LogSystem;

void init_log_system(LogSystem *log) {
    log->max_log_size = MAX_LOG_SIZE;
    log->log_buffer = (char *)malloc(MAX_LOG_SIZE);
    if (log->log_buffer == NULL) {
        perror("Failed to allocate memory for log buffer");
        exit(EXIT_FAILURE);
    }
    log->log_length = 0;
    pthread_mutex_init(&log->log_lock, NULL);
}

void append_to_log(LogSystem *log, const char *message) {
    pthread_mutex_lock(&log->log_lock);
    size_t message_len = strlen(message);
    if (log->log_length + message_len + 1 < log->max_log_size) {
        strcpy(log->log_buffer + log->log_length, message);
        log->log_length += message_len;
        if (message[message_len - 1] != '\n') {
            log->log_buffer[log->log_length++] = '\n';
        }
    } else {
        fprintf(stderr, "Log buffer overflow\n");
    }
    pthread_mutex_unlock(&log->log_lock);
}

char* append_slash_if_within_limit(const char *input, size_t limit, LogSystem *log) {
    if (strlen(input) < limit) {
        char *new_string = (char *)malloc(strlen(input) + 2); // +1 for slash, +1 for null terminator
        if (new_string == NULL) {
            perror("Failed to allocate memory");
            return NULL;
        }
        strcpy(new_string, input);
        new_string[strlen(input)] = '/';
        new_string[strlen(input) + 1] = '\0';
        append_to_log(log, "String modified: appended slash\n");
        return new_string;
    } else {
        append_to_log(log, "String not modified: exceeds limit\n");
        return NULL;
    }
}

void free_string(char *str) {
    if (str != NULL) {
        free(str);
    }
}
