#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_LINE_LENGTH 1024

typedef struct {
    double sum;
    int count;
} AverageData;

void process_line(const char *line, AverageData *data, FILE *output_file) {
    char *token = strtok((char *)line, " ");
    double last_value = 0.0, second_last_value = 0.0;
    int value_count = 0;

    while (token != NULL) {
        if (*token == '\n') continue; // Skip the newline character
        second_last_value = last_value;
        last_value = atof(token);
        value_count++;
        token = strtok(NULL, " ");
    }

    if (value_count >= 2) {
        data->sum += (last_value + second_last_value) / 2.0;
        data->count++;
        fprintf(output_file, "%.2f\n", (last_value + second_last_value) / 2.0);
    } else {
        fprintf(output_file, "N/A\n");
    }
}

void export_statistics(AverageData *data, FILE *output_file) {
    fprintf(output_file, "Total lines processed: %d\n", data->count);
    if (data->count > 0) {
        fprintf(output_file, "Average of averages: %.2f\n", data->sum / data->count);
    } else {
        fprintf(output_file, "No valid averages to calculate.\n");
    }
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        printf("Usage: %s <input_file> <output_file>\n", argv[0]);
        return 1;
    }

    FILE *input_file = fopen(argv[1], "r");
    if (!input_file) {
        perror("Failed to open input file");
        return 1;
    }

    FILE *output_file = fopen(argv[2], "w");
    if (!output_file) {
        perror("Failed to open output file");
        fclose(input_file);
        return 1;
    }

    AverageData data = {0, 0};
    char line[MAX_LINE_LENGTH];
    size_t bytes_read;

    while ((bytes_read = getline(&line, &MAX_LINE_LENGTH, input_file)) != -1) {
        process_line(line, &data, output_file);
    }

    fclose(input_file);
    fclose(output_file);

    export_statistics(&data, stdout);

    return 0;
}
