EncryptedImage* parseTIFFandEncrypt(const char* imagePath, const char* option) {
    TIFF* tif = TIFFOpen(imagePath, "r");
    if (!tif) {
        fprintf(stderr, "Failed to open TIFF file.\n");
        return NULL;
    }

    ImageMetadata metadata;
    if (TIFFGetField(tif, TIFFTAG_BITSPERSAMPLE, &metadata.bitsPerSample)) {
        if (!(metadata.bitsPerSample == 1 || metadata.bitsPerSample == 2 || metadata.bitsPerSample == 4 ||
              metadata.bitsPerSample == 8 || metadata.bitsPerSample == 16)) {
            fprintf(stderr, "Unsupported bits per sample: %d\n", metadata.bitsPerSample);
            TIFFClose(tif);
            return NULL;
        }
    } else {
        fprintf(stderr, "Failed to get bits per sample.\n");
        TIFFClose(tif);
        return NULL;
    }

    if (TIFFGetField(tif, TIFFTAG_SAMPLESPERPIXEL, &metadata.samplesPerPixel)) {
        if (metadata.samplesPerPixel < 1) {
            fprintf(stderr, "Invalid samples per pixel: %d\n", metadata.samplesPerPixel);
            TIFFClose(tif);
            return NULL;
        }
    } else {
        fprintf(stderr, "Failed to get samples per pixel.\n");
        TIFFClose(tif);
        return NULL;
    }

    uint16_t extraSamples = 0;
    if (TIFFGetField(tif, TIFFTAG_EXTRASAMPLES, &extraSamples)) {
        metadata.extraSamplesCount = extraSamples;
        // Handle extra samples as needed
    } else {
        metadata.extraSamplesCount = 0;
    }

    EVP_CIPHER_CTX *cipherCtx = NULL;
    if (strcmp(option, "-aes") == 0) {
        cipherCtx = EVP_CIPHER_CTX_new();
        if (!EVP_EncryptInit_ex(cipherCtx, EVP_aes_256_cbc(), NULL, key, iv)) {
            fprintf(stderr, "Failed to initialize AES encryption.\n");
            TIFFClose(tif);
            EVP_CIPHER_CTX_free(cipherCtx);
            return NULL;
        }
    } else if (strcmp(option, "-rsa") == 0) {
        cipherCtx = EVP_CIPHER_CTX_new();
        if (!EVP_EncryptInit_ex(cipherCtx, EVP_rsa_2048(), NULL, key, iv)) {
            fprintf(stderr, "Failed to initialize RSA encryption.\n");
            TIFFClose(tif);
            EVP_CIPHER_CTX_free(cipherCtx);
            return NULL;
        }
    } else {
        fprintf(stderr, "Unsupported encryption option: %s\n", option);
        TIFFClose(tif);
        return NULL;
    }

    EncryptedImage *result = (EncryptedImage *)malloc(sizeof(EncryptedImage));
    if (!result) {
        fprintf(stderr, "Failed to allocate memory for result.\n");
        TIFFClose(tif);
        EVP_CIPHER_CTX_free(cipherCtx);
        return NULL;
    }
    result->metadata = metadata;
    result->cipherCtx = cipherCtx;

    TIFFClose(tif);
    return result;
}
