#define MAX_FILENAME_LENGTH 256

static int sequenceNumber = 0;
static char timestamp[32];

void generateTimestamp() {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y%m%d%H%M%S", tm_info);
}

char* generateRandomString(int length) {
    static const char charset[] = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
    char *randomString = (char*)malloc((length + 1) * sizeof(char));
    if (!randomString) return NULL;

    for (int i = 0; i < length; ++i) {
        randomString[i] = charset[rand() % (sizeof(charset) - 1)];
    }
    randomString[length] = '\0';
    return randomString;
}

int modifyFilename(const char *filename, char *newFilename) {
    if (strlen(filename) >= MAX_FILENAME_LENGTH) {
        printf("Error: Filename too long\n");
        return -1;
    }

    strncpy(newFilename, filename, MAX_FILENAME_LENGTH);
    newFilename[MAX_FILENAME_LENGTH - 1] = '\0';

    char baseName[257];
    char extension[32];
    int hasExtension = sscanf(filename, "%[^.]", baseName) > 0;
    if (hasExtension) {
        sscanf(filename, ".%s", extension);
    } else {
        strcpy(extension, "");
    }

    generateTimestamp();
    char *randomString = generateRandomString(8);

    sprintf(newFilename, "%s_%s_%d_%s%s", baseName, timestamp, sequenceNumber++, randomString, hasExtension ? "." : "");

    free(randomString);
    return 0;
}

int main() {
    srand(time(NULL));
    char newFilename[MAX_FILENAME_LENGTH];

    if (modifyFilename("example.txt", newFilename) == 0) {
        printf("New filename: %s\n", newFilename);
    }

    return 0;
}
