EVP_CIPHER_CTX *initialize_aes_cbc(const char *password, size_t password_len) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) return NULL;

    unsigned char salt[16];
    if (RAND_bytes(salt, sizeof(salt)) != 1) {
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    unsigned char key[32];
    if (PKCS5_PBKDF2_HMAC(password, password_len, salt, sizeof(salt), 100000, EVP_sha256(), key, sizeof(key)) != 1) {
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    if (EVP_EncryptInit_ex2(ctx, EVP_aes_256_cbc(), NULL, key, salt, EVP_CIPHER_FLAG_WRAP_ALLOW) != 1) {
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    return ctx;
}

void cleanup_cipher(EVP_CIPHER_CTX *ctx) {
    if (ctx) {
        EVP_CIPHER_CTX_reset(ctx);
        EVP_CIPHER_CTX_free(ctx);
    }
}
