#include <unistd.h>
#include <sys/wait.h>
#include <signal.h>
#include <limits.h>
#include <sys/resource.h>

void handle_signal(int signum) {
    // Handle signals gracefully
}

int execute_command_in_background(const char *command, const char *user, pid_t *pid) {
    struct rlimit resource_limits;
    uid_t target_user;

    // Set up signal handling
    signal(SIGCHLD, handle_signal);

    // Change the effective user ID
    target_user = getpwnam(user)->pw_uid;
    if (seteuid(target_user) != 0) {
        perror("Failed to set effective user ID");
        return 0;
    }

    // Set resource limits
    resource_limits.rlim_cur = RLIM_INFINITY; // Adjust as needed
    resource_limits.rlim_max = RLIM_INFINITY; // Adjust as needed
    if (setrlimit(RLIMIT_AS, &resource_limits) != 0 || setrlimit(RLIMIT_CPU, &resource_limits) != 0) {
        perror("Failed to set resource limits");
        return 0;
    }

    // Log command execution details
    printf("Executing command: %s\n", command);

    *pid = fork();
    if (*pid == -1) {
        perror("Fork failed");
        return 0;
    } else if (*pid == 0) {
        // Child process
        execl("/bin/sh", "sh", "-c", command, (char *)NULL);
        perror("Exec failed");
        exit(EXIT_FAILURE);
    }

    // Parent process
    printf("Command executed in background with PID: %d\n", *pid);

    return 1;
}
