using System;
using System.Diagnostics;
using System.IO;

public class WebsiteManager
{
    public static string AddAndStartWebsite(string directoryPath, string siteName, string[] dependencyPaths)
    {
        // Check for web.config file existence
        if (!File.Exists(Path.Combine(directoryPath, "web.config")))
        {
            Console.WriteLine("Information: web.config not found. Aborting.");
            return null;
        }

        int maxRetries = 5;
        int delayBetweenRetries = 1000; // 1 second

        for (int attempt = 0; attempt < maxRetries; attempt++)
        {
            try
            {
                // Create directory entry
                Directory.CreateDirectory(directoryPath);

                // Start website using Process class
                Process process = new Process();
                process.StartInfo.FileName = "cmd.exe";
                process.StartInfo.Arguments = $"/c iisreset /start /site:{siteName}";
                process.Start();

                return siteName;
            }
            catch (Exception ex)
            {
                if (ex.Message.Contains("ERROR 5: Access is denied") || ex.Message.Contains("ERROR 1068: The dependency service or group failed to start."))
                {
                    // Handle race conditions with a retry
                    if (attempt < maxRetries - 1)
                    {
                        System.Threading.Thread.Sleep(delayBetweenRetries);
                        continue;
                    }
                }

                // Log error and return null on failure
                Console.WriteLine($"Error: {ex.Message}");
                return null;
            }
        }

        // Return null on all retries failing
        return null;
    }
}
