import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class CommandExecutor {
    private ExecutorService executorService = Executors.newFixedThreadPool(5);

    public void executeCommand(String command, String[] envp, File dir, Path logFile) throws IOException, InterruptedException {
        ProcessBuilder processBuilder = new ProcessBuilder(command.split(" "));
        processBuilder.environment().putAll(System.getenv());
        if (envp != null) {
            processBuilder.environment().putAll(envp);
        }
        processBuilder.directory(dir);

        deleteLogFile(logFile);

        try (PrintWriter out = new PrintWriter(Files.newOutputStream(logFile, true))) {
            Process process = processBuilder.start();

            handleProcess(process.getInputStream(), out);
            handleProcess(process.getErrorStream(), out);

            int exitCode = process.waitFor();
            System.out.println("Command exited with code: " + exitCode);

            long cpuUsage = getCPUUsage(process.pid());
            long memoryUsage = getMemoryUsage(process.pid());

            logResourceUsage(logFile, cpuUsage, memoryUsage);
        }
    }

    private void deleteLogFile(Path logFile) {
        if (Files.exists(logFile)) {
            try {
                Files.delete(logFile);
            } catch (IOException e) {
                e.printStackTrace();
            }
        }
    }

    private void handleProcess(InputStream input, PrintWriter out) {
        new Thread(() -> {
            try (BufferedReader reader = new BufferedReader(new InputStreamReader(input))) {
                String line;
                while ((line = reader.readLine()) != null) {
                    out.println(line);
                    System.out.println(line);
                }
            } catch (IOException e) {
                e.printStackTrace();
            }
        }).start();
    }

    private long getCPUUsage(long processId) {
        // Implement logic to retrieve CPU usage for the given process
        return 0;
    }

    private long getMemoryUsage(long processId) {
        // Implement logic to retrieve memory usage for the given process
        return 0;
    }

    private void logResourceUsage(Path logFile, long cpuUsage, long memoryUsage) throws IOException {
        try (PrintWriter out = new PrintWriter(Files.newOutputStream(logFile, true))) {
            out.println("CPU Usage: " + cpuUsage);
            out.println("Memory Usage: " + memoryUsage);
        }
    }

    public void shutdown() {
        executorService.shutdown();
        try {
            if (!executorService.awaitTermination(60, java.util.concurrent.TimeUnit.SECONDS)) {
                executorService.shutdownNow();
            }
        } catch (InterruptedException e) {
            executorService.shutdownNow();
        }
    }
}
