#define MAX_TOKEN_LENGTH 1024

bool is_valid_uuid(const char *uuid) {
    // Simple UUID v4 validation (not full RFC 4122 compliance)
    if (strlen(uuid) != 36 || uuid[8] != '-' || uuid[13] != '-' || uuid[18] != '-' || uuid[23] != '-') return false;
    for (int i = 0; i < 36; ++i) {
        if (i == 8 || i == 13 || i == 18 || i == 23) continue;
        if (!isxdigit(uuid[i])) return false;
    }
    return true;
}

bool is_valid_access_token(const char *token) {
    // Check non-empty, at least one alphanumeric
    if (strlen(token) == 0 || !strpbrk(token, "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ1234567890")) return false;
    return strlen(token) <= MAX_TOKEN_LENGTH;
}

bool is_valid_expires_in(const char *expires_in_str) {
    long expires_in = atol(expires_in_str);
    // Check positive and within a reasonable range
    return expires_in > 0 && expires_in < 2147483647; // Assuming int32 for simplicity
}

bool is_valid_token_type(const char *token_type) {
    // Case-insensitive check
    if (strlen(token_type) != 6) return false;
    for (int i = 0; i < 6; ++i) {
        if (tolower(token_type[i]) != 'b' && tolower(token_type[i]) != 'earer') return false;
    }
    return true;
}

