using System;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;
using Serilog;

public class HashGenerator
{
    private readonly ILogger _logger;

    public HashGenerator(ILogger logger)
    {
        _logger = logger ?? throw new ArgumentNullException(nameof(logger));
    }

    public async Task<string> GenerateMd5HashAsync(string input)
    {
        if (string.IsNullOrEmpty(input))
            return string.Empty;

        using var md5 = MD5.Create();
        var inputBytes = Encoding.UTF8.GetBytes(input);
        var hashBytes = await Task.Run(() => md5.ComputeHashAsync(inputBytes));

        var sb = new StringBuilder();
        foreach (var b in hashBytes)
        {
            sb.Append(b.ToString("x2"));
        }

        _logger.Information("MD5 Hash generated: {Hash} at {Timestamp}", sb.ToString(), DateTime.UtcNow);

        return sb.ToString();
    }
}

public class Program
{
    public static async Task Main(string[] args)
    {
        var logger = new LoggerConfiguration()
            .MinimumLevel.Debug()
            .WriteTo.Console()
            .CreateLogger();

        var hashGenerator = new HashGenerator(logger);

        // Unit tests
        Console.WriteLine("Unit Tests:");
        await TestHashGeneration(hashGenerator, "Hello, World!", "65a8e27d8879283831b664bd8b7f0ad4");
        await TestHashGeneration(hashGenerator, string.Empty, string.Empty);
        await TestHashGeneration(hashGenerator, null, string.Empty);

        // Example usage
        var hash = await hashGenerator.GenerateMd5HashAsync("Hello, World!");
        Console.WriteLine($"MD5 Hash: {hash}");
    }

    private static async Task TestHashGeneration(HashGenerator hashGenerator, string input, string expected)
    {
        var hash = await hashGenerator.GenerateMd5HashAsync(input);
        Console.WriteLine($"Input: \"{input}\", Expected: \"{expected}\", Actual: \"{hash}\"");
        if (hash != expected)
            throw new InvalidOperationException("Hash generation test failed.");
    }
}
