using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;

public class AesCbcDecryptor
{
    public static byte[] Decrypt(byte[] ciphertext, byte[] key, byte[] iv)
    {
        using (Aes aes = Aes.Create())
        {
            aes.Key = key;
            aes.IV = iv;
            aes.Mode = CipherMode.CBC;
            aes.Padding = PaddingMode.PKCS7; // Assuming PKCS7 padding for simplicity

            ICryptoTransform decryptor = aes.CreateDecryptor(aes.Key, aes.IV);

            using (MemoryStream ms = new MemoryStream(ciphertext))
            {
                using (CryptoStream cs = new CryptoStream(ms, decryptor, CryptoStreamMode.Read))
                {
                    byte[] decryptedData = new byte[ciphertext.Length];
                    int bytesRead = cs.Read(decryptedData, 0, decryptedData.Length);

                    // Correct padding
                    int paddingLength = decryptedData[bytesRead - 1];
                    if (paddingLength > 0 && paddingLength <= aes.BlockSize / 8)
                    {
                        Array.Resize(ref decryptedData, decryptedData.Length - paddingLength);
                    }

                    return decryptedData;
                }
            }
        }
    }

    public static void Main()
    {
        byte[] ciphertext = ...; // Your ciphertext here
        byte[] key = ...; // Your encryption key here
        byte[] iv = ...; // Your initialization vector here

        byte[] plaintext = Decrypt(ciphertext, key, iv);
        string decryptedText = Encoding.UTF8.GetString(plaintext);

        Console.WriteLine("Decrypted Text: " + decryptedText);
    }
}
