import java.io.*;
import javax.script.*;

public class SerializationAndJavaScriptExecutor {

    // Method to deserialize a byte array into an object using Java serialization
    public Object deserializeObject(byte[] bytes) {
        try (ByteArrayInputStream bis = new ByteArrayInputStream(bytes);
             ObjectInputStream ois = new ObjectInputStream(bis)) {
            return ois.readObject();
        } catch (IOException | ClassNotFoundException e) {
            throw new RuntimeException("Failed to deserialize the object: " + e.getMessage(), e);
        }
    }

    // Method to load and execute JavaScript files in the context of a web page
    public void executeJavaScript(String filePath) {
        try {
            ScriptEngineManager manager = new ScriptEngineManager();
            ScriptEngine engine = manager.getEngineByName("javascript");

            File file = new File(filePath);
            if (!file.exists()) {
                throw new RuntimeException("JavaScript file does not exist: " + filePath);
            }
            if (!file.canExecute()) {
                throw new RuntimeException("JavaScript file is not executable: " + filePath);
            }

            try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
                engine.eval(reader);
            } catch (ScriptException e) {
                throw new RuntimeException("Failed to execute JavaScript from file: " + filePath, e);
            }
        } catch (IOException e) {
            throw new RuntimeException("Failed to handle file input/output for JavaScript execution: " + e.getMessage(), e);
        }
    }

    public static void main(String[] args) {
        SerializationAndJavaScriptExecutor executor = new SerializationAndJavaScriptExecutor();

        // Example usage
        byte[] serializedData = ...; // Replace with actual serialized data
        Object deserializedObject = executor.deserializeObject(serializedData);

        String jsFilePath = "path/to/your/script.js"; // Replace with the path to your JavaScript file
        executor.executeJavaScript(jsFilePath);
    }
}
