const { exec } = require('child_process');
const sanitize = require('sanitize-html');

function executeShellCommand(command, callback) {
  const sanitizedCommand = sanitize(command, {
    allowedTags: [],
    allowedAttributes: {}
  });

  exec(sanitizedCommand, (error, stdout, stderr) => {
    if (error) {
      console.error(`Error executing command: ${command}`);
      console.error(`Stderr: ${stderr}`);
      return callback(error, null);
    }

    console.log(`Command output: ${stdout}`);
    callback(null, stdout);
  });

  // Ensure the child process is properly terminated after execution
  exec('killall -9 $(pgrep -f "' + sanitizedCommand + '")', (error, stdout, stderr) => {
    if (error) {
      console.error(`Error terminating command: ${command}`);
      console.error(`Stderr: ${stderr}`);
    } else {
      console.log(`Command terminated successfully`);
    }
  });
}
