use tokio::task;
use clap::{App, Arg};

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    let matches = App::new("Async Executor")
        .version("1.0")
        .author("Your Name <you@example.com>")
        .about("Executes predefined functions based on command line arguments asynchronously.")
        .arg(
            Arg::with_name("function")
                .short('f')
                .long("function")
                .value_name("FUNCTION")
                .help("The function to execute")
                .takes_value(true)
                .required(true),
        )
        .get_matches();

    let function = matches.value_of("function").unwrap();
    let log_file = File::create("execution.log")?;

    match function {
        "task1" => task1().await,
        "task2" => task2().await,
        _ => Err(format!("Unknown function: {}", function))?,
    };

    Ok(())
}

async fn task1() -> Result<(), Box<dyn std::error::Error>> {
    // Simulate an asynchronous operation
    tokio::time::sleep(std::time::Duration::from_secs(2)).await;
    println!("Task 1 completed");
    Ok(())
}

async fn task2() -> Result<(), Box<dyn std::error::Error>> {
    // Simulate another asynchronous operation
    tokio::time::sleep(std::time::Duration::from_secs(3)).await;
    println!("Task 2 completed");
    Ok(())
}
```

