use std::env;
use std::fs;
use std::path::{Path, PathBuf};
use std::sync::{Mutex, Once};

static INIT: Once = ONCE_INIT;

fn init_config_dir() -> Result<(), String> {
    let home_dir = env::var("HOME").map_err(|_| "Failed to get user home directory".to_string())?;
    let config_dir_path = PathBuf::from(&home_dir).join("config");

    if !config_dir_path.exists() {
        fs::create_dir_all(&config_dir_path)
            .map_err(|e| format!("Failed to create config directory: {}", e))?;
    }

    env::set_var("CONFIG_DIR", &config_dir_path);
    Ok(())
}

fn get_config_dir() -> Option<String> {
    env::var("CONFIG_DIR").ok()
}

fn set_config_dir_once() {
    INIT.call_once(|| {
        init_config_dir().unwrap_or_else(|e| eprintln!("Error initializing config dir: {}", e));
    });
}

fn main() {
    set_config_dir_once();
    if let Some(config_dir) = get_config_dir() {
        println!("Config directory is set to: {}", config_dir);
    } else {
        println!("Failed to initialize or retrieve config directory.");
    }
}
```

This Rust code snippet defines a function `set_config_dir_once` that ensures the `config` directory is created within the user's home directory and sets an environment variable `CONFIG_DIR` to its path. The function uses a global static once cell (`INIT`) to ensure that the initialization logic runs only once, even if multiple threads or processes call it concurrently. This helps in avoiding race conditions and ensures that the environment variable is set only once.

The `init_config_dir` function checks if the home directory exists and then creates the `config` directory within it. If the directory already exists, it simply sets the `CONFIG_DIR` environment variable to the existing path. The `get_config_dir` function retrieves the value of the `CONFIG_DIR` environment variable.

In the `main` function, we call `set_config_dir_once` to initialize the configuration directory and then attempt to retrieve and print its path. This example demonstrates how to handle real-world engineering challenges like race conditions, system dependencies, external data sources, integration issues, and scalability in a Rust application.']

