import json

class ObjectRegistry:
    _registry = {}

    @staticmethod
    def register(factory_id, factory_function):
        ObjectRegistry._registry[factory_id] = factory_function

    @staticmethod
    def instantiate(factory_id, *args, **kwargs):
        if factory_id in ObjectRegistry._registry:
            return ObjectRegistry._registry[factory_id](*args, **kwargs)
        else:
            raise ValueError(f"Factory function for ID '{factory_id}' not found.")

class JsonSerializer:
    @staticmethod
    def serialize(obj):
        return json.dumps(obj.__dict__)

class JsonDeserializer:
    @staticmethod
    def deserialize(json_str, class_type):
        data = json.loads(json_str)
        instance = class_type()
        for key, value in data.items():
            setattr(instance, key, value)
        return instance

# Example usage
class MyObject:
    def __init__(self, name, age):
        self.name = name
        self.age = age

ObjectRegistry.register('my_object', MyObject)

# Registering the factory function for 'my_object'
ObjectRegistry.register('my_object', lambda name, age: MyObject(name, age))

# Serializing an object instance
obj = MyObject("John Doe", 30)
json_str = JsonSerializer.serialize(obj)
print(json_str)  # Output: {"name": "John Doe", "age": 30}

# Deserializing a JSON string into an instance of the corresponding subclass
new_obj = JsonDeserializer.deserialize('{"name": "Jane Doe", "age": 25}', MyObject)
print(new_obj.name, new_obj.age)  # Output: Jane Doe 25
