import os
import hashlib
from concurrent.futures import ThreadPoolExecutor, as_completed
import sys

def file_md5(file_path):
    hasher = hashlib.md5()
    with open(file_path, 'rb') as f:
        for chunk in iter(lambda: f.read(4096), b""):
            hasher.update(chunk)
    return hasher.hexdigest()

class FileHasher:
    def __init__(self, directory, num_workers=4):
        self.directory = directory
        self.num_workers = num_workers

    def process_files(self):
        file_paths = [os.path.join(self.directory, f) for f in os.listdir(self.directory) if os.path.isfile(os.path.join(self.directory, f))]
        with ThreadPoolExecutor(max_workers=self.num_workers) as executor:
            future_to_file = {executor.submit(file_md5, file_path): file_path for file_path in file_paths}
            for future in as_completed(future_to_file):
                file_path = future_to_file[future]
                try:
                    md5_hash = future.result()
                    print(f"Processed: {file_path}, MD5: {md5_hash}")
                except Exception as e:
                    print(f"Failed to process: {file_path}, error: {e}", file=sys.stderr)

if __name__ == "__main__":
    hasher = FileHasher('/path/to/large/files', num_workers=4)
    hasher.process_files()
```

This code provides a basic structure for a Python module that processes a directory of large files, calculating their MD5 hashes efficiently. It uses threading to handle multiple files concurrently and includes error handling to manage potential interruptions gracefully. The `FileHasher` class encapsulates the functionality, making it easy to integrate with an existing file processing pipeline while allowing for future enhancements.']

