    struct json_object *access_token, *expires_in, *token_type, *refresh_token;
    if (json_object_object_get_ex(parsed_json, "access_token", &access_token) &&
        json_object_object_get_ex(parsed_json, "expires_in", &expires_in) &&
        json_object_object_get_ex(parsed_json, "token_type", &token_type)) {

        const char *type_str = json_object_get_string(token_type);
        if (strcmp(type_str, "Bearer") != 0 && strcmp(type_str, "client_credentials") != 0 &&
            strcmp(type_str, "password") != 0 && strcmp(type_str, "mac") != 0) {
            return false;
        }

        int expires_in_int = json_object_get_int(expires_in);
        if (expires_in_int <= 0) {
            return false;
        }

        // Optional field
        json_object_object_get_ex(parsed_json, "refresh_token", &refresh_token);

        json_object_put(parsed_json);
        return true;
    } else {
        json_object_put(parsed_json);
        return false;
    }
}

// Function to fetch additional user information using OAuth2 token
bool fetch_user_info(const char *access_token) {
    CURL *curl;
    CURLcode res;

    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();
    if(curl) {
        struct curl_slist *headers = NULL;
        headers = curl_slist_append(headers, "Authorization: Bearer ");
        headers = curl_slist_append(headers, access_token);

        curl_easy_setopt(curl, CURLOPT_URL, "https://api.example.com/userinfo");
        curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);
        res = curl_easy_perform(curl);

        if(res != CURLE_OK) {
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
            return false;
        }

        curl_easy_cleanup(curl);
    }
    curl_global_cleanup();
    return true;
}

// Function to get EVP_CIPHER based on input parameters
const EVP_CIPHER *get_cipher(const char *cipher_type) {
    if (strcmp(cipher_type, "ECB") == 0) {
