from time import strftime

def calculate_md5_hash(file_path):
    hash_md5 = hashlib.md5()
    with open(file_path, "rb") as f:
        for chunk in iter(lambda: f.read(4096), b""):
            hash_md5.update(chunk)
    return hash_md5.hexdigest()

def generate_timestamp():
    return strftime("%Y%m%d%H%M%S", os.times())

def generate_sequence_number():
    # Implement logic to retrieve and increment the sequence number
    pass

def generate_random_string(length=8):
    import secrets
    return ''.join(secrets.choice('abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789') for _ in range(length))

def modify_file_extension(file_path, base_name, extension):
    timestamp = generate_timestamp()
    sequence_number = generate_sequence_number()
    random_string = generate_random_string()
    new_extension = f"{timestamp}_{sequence_number}_{random_string}"

    if not extension:
        new_filename = f"{base_name}.{new_extension}"
    else:
        new_filename = f"{base_name}{os.path.extsep}{new_extension}"

    return os.path.join(os.path.dirname(file_path), new_filename)

def process_files_concurrently(file_paths):
    import concurrent.futures
    with concurrent.futures.ThreadPoolExecutor() as executor:
        results = list(executor.map(calculate_md5_hash, file_paths))
    return results

