import threading
from queue import Queue
import time

class DatabaseMigration:
    def __init__(self, max_concurrency=5):
        self.max_concurrency = max_concurrency
        self.task_queue = Queue()
        self.lock = threading.Lock()

    def add_task(self, task, *args, **kwargs):
        with self.lock:
            self.task_queue.put((task, args, kwargs))

    def worker(self):
        while True:
            task, args, kwargs = self.task_queue.get()
            if task is None:
                break
            try:
                task(*args, **kwargs)
            except Exception as e:
                print(f"Error during migration: {e}")
            finally:
                self.task_queue.task_done()

    def start(self):
        threads = []
        for _ in range(self.max_concurrency):
            t = threading.Thread(target=self.worker)
            t.start()
            threads.append(t)

        for t in threads:
            t.join()

class MigrationTask:
    def __init__(self, table_name, data):
        self.table_name = table_name
        self.data = data

    def execute(self):
        # Simulate database migration
        print(f"Migrating {len(self.data)} records to {self.table_name}")
        time.sleep(0.5)  # Simulate processing time

# Example usage
if __name__ == "__main__":
    migration_manager = DatabaseMigration(max_concurrency=3)

    tables = ["table1", "table2", "table3"]
    data_sets = [list(range(1000)), list(range(1500)), list(range(2000))]

    for table, data in zip(tables, data_sets):
        migration_task = MigrationTask(table, data)
        migration_manager.add_task(migration_task.execute)

    migration_manager.start()
    print("Migration completed.")
```

This code snippet defines a `DatabaseMigration` class that manages the execution of database migration tasks concurrently. It uses a thread pool to handle multiple tasks simultaneously, ensuring efficient resource management and concurrent processing. The `MigrationTask` class represents an individual migration task, which in this example simulates migrating data to a specific table. The progress indicator is implicitly managed through the thread pool's inherent handling of tasks.']

['```c
#include <openssl/evp.h>
#include <openssl/rand.h>
#include <openssl/pbkdf2.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

EVP_CIPHER_CTX *initialize_secure_aes_cipher(const char *password) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) return NULL;

    unsigned char salt[16];
    if (RAND_bytes(salt, sizeof(salt)) != 1) {
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    unsigned char key[32];
    if (PKCS5_PBKDF2_HMAC(password, strlen(password), salt, sizeof(salt),
                           100000, EVP_sha256(), sizeof(key), key) != 1) {
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    if (EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, salt) != 1) {
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    EVP_CIPHER_CTX_set_auto_padding(ctx, 0);

    return ctx;
}

void cleanup_cipher(EVP_CIPHER_CTX *ctx) {
    if (ctx) {
        EVP_CIPHER_CTX_cleanup(ctx);
        EVP_CIPHER_CTX_free(ctx);
    }
}
