#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int connection_id;
    int bandwidth_usage;
    int *packet_queue;
    size_t queue_size;
    size_t max_queue_size;
    time_t last_activity;
} TCPConnection;

TCPConnection* create_connection(int id, int initial_bandwidth, size_t initial_max_queue_size) {
    TCPConnection *conn = (TCPConnection*)malloc(sizeof(TCPConnection));
    if (!conn) return NULL;

    conn->connection_id = id;
    conn->bandwidth_usage = initial_bandwidth;
    conn->packet_queue = (int*)malloc(initial_max_queue_size * sizeof(int));
    if (!conn->packet_queue) {
        free(conn);
        return NULL;
    }

    conn->queue_size = 0;
    conn->max_queue_size = initial_max_queue_size;
    time(&conn->last_activity);

    pthread_mutex_init(&conn->lock, NULL);
    return conn;
}

void destroy_connection(TCPConnection *conn) {
    free(conn->packet_queue);
    pthread_mutex_destroy(&conn->lock);
    free(conn);
}

void add_packet_to_queue(TCPConnection *conn, int packet) {
    pthread_mutex_lock(&conn->lock);
    if (conn->queue_size >= conn->max_queue_size) {
        // Handle queue overflow
        // Optionally increase the size of the queue dynamically
    }
    conn->packet_queue[conn->queue_size++] = packet;
    time(&conn->last_activity);
    pthread_mutex_unlock(&conn->lock);
}

void transmit_packets(TCPConnection *conn, int bandwidth) {
    pthread_mutex_lock(&conn->lock);
    while (conn->queue_size > 0 && conn->bandwidth_usage < bandwidth) {
        // Transmit the packet
        printf("Transmitting packet %d from connection %d\n", conn->packet_queue[0], conn->connection_id);
        int *temp = conn->packet_queue;
        memmove(temp, temp + 1, (conn->queue_size - 1) * sizeof(int));
        conn->queue_size--;
    }
    time(&conn->last_activity);
    pthread_mutex_unlock(&conn->lock);
}

void adjust_bandwidth(TCPConnection *conn, int new_bandwidth) {
    pthread_mutex_lock(&conn->lock);
    conn->bandwidth_usage = new_bandwidth;
    pthread_mutex_unlock(&conn->lock);
}

int main() {
    TCPConnection *conn1 = create_connection(101, 100, 10);
    add_packet_to_queue(conn1, 50);
    transmit_packets(conn1, 200);
    adjust_bandwidth(conn1, 150);

    destroy_connection(conn1);
    return 0;
}
