            new_state = (State*)malloc(sizeof(State));
            if (new_state == NULL) {
                // Handle memory allocation failure
                return NULL;
            }
        }

        new_state->state_id = initial_states[i];
        new_state->next = NULL; // Initialize next pointer

        *current = new_state;

        for (int j = 0; j < last_state; j++) {
            if (fsa_rules[j].state_id == initial_states[i] && should_add_state(fsa_rules[j])) {
                // Append state based on FSA rules and criteria
                State* appended_state = append_state(fsa_rules[j]);
                if (appended_state != NULL) {
                    new_state->next = appended_state;
                    current = &new_state->next; // Move to the next state in the list
