// Function to get the AVCodecContext based on runtime configuration
AVCodecContext* select_codec(CodecInfo *config) {
    AVCodecContext *codec_ctx = NULL;
    AVCodec *codec = NULL;

    // Select video codec based on config->codec_name
    if (strcmp(config->codec_name, "mpeg2") == 0) {
        codec = avcodec_find_decoder(AV_CODEC_ID_MPEG2VIDEO);
    } else if (strcmp(config->codec_name, "h264") == 0) {
        codec = avcodec_find_decoder(AV_CODEC_ID_H264);
    } else if (strcmp(config->codec_name, "hevc") == 0) {
        codec = avcodec_find_decoder(AV_CODEC_ID_HEVC);
    } else {
        // Fallback to identity transformation
        return NULL;
    }

    // Allocate and initialize the AVCodecContext
    if (codec != NULL) {
        codec_ctx = avcodec_alloc_context3(codec);
        if (codec_ctx == NULL) {
            fprintf(stderr, "Failed to allocate AVCodecContext\n");
            goto cleanup;
        }

        // Configure codec context for multi-threading
        codec_ctx->thread_count = 4; // Example value
        codec_ctx->active_thread_type = FF_THREAD_SLICE;

        // Open the codec
        if (avcodec_open2(codec_ctx, codec, NULL) < 0) {
            fprintf(stderr, "Failed to open codec\n");
            goto cleanup;
        }
    }

cleanup:
    if (codec_ctx == NULL && codec != NULL) {
        avcodec_free_context(&codec);
    }

    return codec_ctx;
}

// Example usage
int main() {
    CodecInfo config = {"h264"};
    AVCodecContext *codec_ctx = select_codec(&config);

    if (codec_ctx != NULL) {
        printf("Selected codec: %s\n", codec_ctx->codec->name);
        avcodec_free_context(&codec_ctx);
    } else {
