    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (ctx == NULL) return NULL;

    // Generate salt
    unsigned char salt[16];
    if (!RAND_bytes(salt, sizeof(salt))) {
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    // Derive key using PBKDF2
    unsigned char key[32];
    if (PKCS5_PBKDF2_HMAC(password, strlen(password), salt, sizeof(salt), 100000,
                          EVP_sha256(), sizeof(key), key) != 1) {
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    // Set up cipher context
    if (EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, salt) != 1 ||
        EVP_CIPHER_CTX_set_padding(ctx, EVP_PADDING_PKCS7) != 1) {
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    // Set IV for AES-256-CBC
    unsigned char iv[16];
    if (!RAND_bytes(iv, sizeof(iv))) {
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }
    if (EVP_EncryptUpdate(ctx, iv, NULL, iv, sizeof(iv)) != 1) {
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    return ctx;
}

