EVP_CIPHER_CTX* create_cipher_context(const char* algorithm, const char* mode, int authenticated) {
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (ctx == NULL) {
        // Handle error
        return NULL;
    }

    const EVP_CIPHER* cipher = NULL;
    if (strcmp(algorithm, "AES") == 0) {
        if (authenticated) {
            cipher = EVP_aes_256_gcm();
        } else {
            cipher = EVP_aes_256_cbc();
        }
    } else if (strcmp(algorithm, "ChaCha20") == 0) {
        if (authenticated) {
            // ChaCha20 does not natively support authentication
            return NULL;
        } else {
            cipher = EVP_chacha20_poly1305();
        }
    } else if (strcmp(algorithm, "XChaCha20") == 0) {
        if (authenticated) {
            // XChaCha20 does not natively support authentication
            return NULL;
        } else {
            cipher = EVP_xchaCha20_poly1305();
        }
    }

    if (cipher == NULL) {
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    int result = EVP_EncryptInit_ex(ctx, cipher, NULL, NULL, NULL);
    if (!result) {
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    return ctx;
}
