#include <arpa/inet.h>

#define MAX_IP_LENGTH 46
#define MAX_LINE_LENGTH 256

int initialize_secure_dns_resolver_and_sort_file(const char *hostname, u_char *ip_address) {
    struct addrinfo hints, *res, *p;
    int status;

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET; // IPv4
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        fprintf(stderr, "getaddrinfo error: %s\n", gai_strerror(status));
        return -1;
    }

    for (p = res; p != NULL; p = p->ai_next) {
        void *addr;
        char ip_str[MAX_IP_LENGTH];

        if (p->ai_family == AF_INET) {
            struct sockaddr_in *ipv4 = (struct sockaddr_in *)p->ai_addr;
            addr = &(ipv4->sin_addr);
        } else {
            continue;
        }

        inet_ntop(p->ai_family, addr, ip_str, sizeof(ip_str));
        strncpy((char *)ip_address, ip_str, MAX_IP_LENGTH - 1);
    }

    freeaddrinfo(res);

    FILE *file = fopen("sequence.txt", "r");
    if (file == NULL) {
        perror("Failed to open file");
        return -2;
    }

    char lines[MAX_LINE_LENGTH][MAX_LINE_LENGTH];
    int count = 0;

    while (fgets(lines[count], MAX_LINE_LENGTH, file)) {
        lines[count][strcspn(lines[count], "\n")] = '\0';
        count++;
    }
    fclose(file);

    if (count == 0) {
        fprintf(stderr, "No lines in the file\n");
        return -3;
    }

    qsort(lines, count, sizeof(char *), (int (*)(const void *, const void *))strcmp);

    char sequence_number[MAX_LINE_LENGTH];
    strcpy(sequence_number, lines[count - 1]);

    // Remove non-digit characters from the sequence number
    int j = 0;
    for (int i = 0; i < strlen(sequence_number); i++) {
        if (isdigit(sequence_number[i])) {
            sequence_number[j++] = sequence_number[i];
        }
    }
    sequence_number[j] = '\0';

    // Convert the extracted sequence number to a u_char array
    int seq_num;
    sscanf(sequence_number, "%d", &seq_num);
    memcpy(ip_address + strlen((char *)ip_address), (u_char *)&seq_num, sizeof(seq_num));

    return 0; // Success
}
