    NetworkPacketValidator(int min, int max) : minSeqNum(min), maxSeqNum(max) {
        if (min > max) {
            throw std::out_of_range("Minimum sequence number must be less than or equal to maximum.");
        }
    }

    // Method to generate and return a random sequence number within the specified range
    int GetRandomSeqNum(bool inclusive = false) const {
        int range = maxSeqNum - minSeqNum + (inclusive ? 1 : 0);
        if (range <= 0) {
            throw std::invalid_argument("Range is too narrow for valid sequence generation.");
        }
        return minSeqNum + static_cast<int>(rand() % range);
    }

    // Method to validate a UDP packet
    bool ValidateUDPPacket(const std::string& source_port, const std::string& destination_port,
                           int length, int checksum) const {
