        if (inclusive) {
            return "[" + std::to_string(minSeqNum) + ", " + std::to_string(maxSeqNum) + ")";
        } else {
            return "(" + std::to_string(minSeqNum) + ", " + std::to_string(maxSeqNum) + ")";
        }
    }

    // Method to insert a string after the first occurrence of another string in a forward list
    void InsertAfter(std::forward_list<std::string>& list, const std::string& target,
                     const std::string& to_insert) {
        auto it = list.begin();
        while (it != list.end()) {
            if (*it == target) {
                it = list.insert_after(it, to_insert);
                break;
            }
            ++it;
        }
        // If not found, insert at the end
        if (it == list.end()) {
            list.push_back(to_insert);
        }
    }
};

