    srand(static_cast<unsigned int>(time(nullptr)));
    NetworkPacketValidator validator(100, 999);

    std::forward_list<std::string> packetList = {"data1", "target", "data2"};
    validator.InsertAfter(packetList, "target", "new_data");

    for (const auto& packet : packetList) {
        std::cout << packet << " ";
    }
    return 0;
}
