#include <openssl/evp.h>
#include <stdlib.h>

EVP_CIPHER* get_cipher(const char* cipher_name) {
    if (strcmp(cipher_name, "DES-ECB") == 0) return EVP_des_ecb();
    else if (strcmp(cipher_name, "DES-EDE") == 0) return EVP_des_ede();
    else if (strcmp(cipher_name, "DES-EDE3") == 0) return EVP_des_ede3();
    else if (strcmp(cipher_name, "DES-CFB") == 0) return EVP_des_cfb();
    else if (strcmp(cipher_name, "NULL") == 0) return NULL;
    return NULL;
}

struct State {
    int id;
    struct State* next;
};

struct FSA {
    int (*transition)(int current_state, int input);
};

int* expand_states(int* initial_states, int size, struct FSA fsa, int last_state) {
    if (!initial_states || size <= 0) return NULL;

    struct State** states = (struct State**)malloc(size * sizeof(struct State*));
    if (!states) return NULL;

    for (int i = 0; i < size; i++) {
        states[i] = (struct State*)malloc(sizeof(struct State));
        if (!states[i]) {
            for (int j = 0; j < i; j++) free(states[j]);
            free(states);
            return NULL;
        }
        states[i]->id = initial_states[i];
        states[i]->next = NULL;
    }

    struct State* new_list_head = NULL;
    for (int i = 0; i < size; i++) {
        int current_state = states[i]->id;
        for (int input = 0; input <= last_state; input++) {
            int next_state = fsa.transition(current_state, input);
            if (!new_list_head) {
                new_list_head = (struct State*)malloc(sizeof(struct State));
                if (!new_list_head) {
                    for (int j = 0; j < size; j++) free(states[j]);
                    free(states);
                    return NULL;
                }
                new_list_head->id = next_state;
                new_list_head->next = states[i]->next;
            } else {
                struct State* current = new_list_head;
                while (current->next) current = current->next;
                current->next = (struct State*)malloc(sizeof(struct State));
                if (!current->next) {
                    for (int j = 0; j < size; j++) free(states[j]);
                    free(states);
                    return NULL;
                }
                current->next->id = next_state;
                current->next->next = states[i]->next;
            }
        }
    }

    for (int i = 0; i < size; i++) free(states[i]);
    free(states);

    int* new_states = (int*)malloc(new_list_head->id * sizeof(int));
    if (!new_states) return NULL;

    struct State* current = new_list_head;
    int index = 0;
    while (current) {
        new_states[index++] = current->id;
        struct State* temp = current;
        current = current->next;
        free(temp);
    }

    return new_states;
}
