typedef struct {
    int id;
    struct State* next;
} State;

typedef struct {
    State** states;
    int size;
    int capacity;
} FSA;

EVP_CIPHER* select_cipher(int cipher_type) {
    switch (cipher_type) {
        case 1: return EVP_des_ecb();
        case 2: return EVP_des_ede();
        case 3: return EVP_des_ede3();
        case 4: return EVP_des_cfb();
        default: return NULL;
    }
}

FSA* initialize_fsa(int size) {
    FSA* fsa = (FSA*)malloc(sizeof(FSA));
    if (!fsa) return NULL;

    fsa->states = (State**)calloc(size, sizeof(State*));
    if (!fsa->states) {
        free(fsa);
        return NULL;
    }

    fsa->size = size;
    fsa->capacity = size;

    for (int i = 0; i < size; i++) {
        fsa->states[i] = NULL;
    }

    return fsa;
}

State* add_state_to_fsa(FSA* fsa, int state_id) {
    if (!fsa || state_id < 0 || state_id >= fsa->size) return NULL;

    State* new_state = (State*)malloc(sizeof(State));
    if (!new_state) return NULL;

    new_state->id = state_id;
    new_state->next = NULL;

    for (int i = 0; i < fsa->size; i++) {
        if (!fsa->states[i]) {
            fsa->states[i] = new_state;
            break;
        }
    }

    return new_state;
}

void* manage_fsa_states(State** states, int size, FSA* fsa, int last_state) {
    for (int i = 0; i < size; i++) {
        if (!states[i]) continue;

        State* new_state = add_state_to_fsa(fsa, states[i]->id);
        if (!new_state) return NULL;
    }

    // Update next pointers to link states into a single linked list
    for (int i = 0; i < size; i++) {
        if (states[i] && states[i]->next) {
            State* current = new_state;
            while (current->next) current = current->next;
            current->next = states[i]->next;
        }
    }

    return new_state;
}

void register_callback(int event_type, void (*callback)(void)) {
