#include <openssl/evp.h>
#include <openssl/rand.h>

EVP_CIPHER* select_cipher(const char* cipher_name) {
    if (strcmp(cipher_name, "NULL") == 0) {
        return EVP_enc_null();
    } else if (strcmp(cipher_name, "DES-ECB") == 0) {
        return EVP_des_ecb();
    } else if (strcmp(cipher_name, "DES-EDE") == 0) {
        return EVP_des_ede();
    } else if (strcmp(cipher_name, "DES-EDE3") == 0) {
        return EVP_des_ede3();
    } else if (strcmp(cipher_name, "DES-CFB") == 0) {
        return EVP_des_cfb();
    } else {
        return NULL;
    }
}

int encrypt_with_cipher(EVP_CIPHER* cipher, const unsigned char* key, const unsigned char* iv,
                       const unsigned char* plaintext, int plaintext_len, unsigned char* ciphertext) {
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        return -1;
    }

    if (1 != EVP_EncryptInit_ex(ctx, cipher, NULL, key, iv)) {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }

    int len;
    if (1 != EVP_EncryptUpdate(ctx, ciphertext, &len, plaintext, plaintext_len)) {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }
    int ciphertext_len = len;

    if (1 != EVP_EncryptFinal_ex(ctx, ciphertext + len, &len)) {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }
    ciphertext_len += len;

    EVP_CIPHER_CTX_free(ctx);
    return ciphertext_len;
}

int decrypt_with_cipher(EVP_CIPHER* cipher, const unsigned char* key, const unsigned char* iv,
                       const unsigned char* ciphertext, int ciphertext_len, unsigned char* plaintext) {
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        return -1;
    }

    if (1 != EVP_DecryptInit_ex(ctx, cipher, NULL, key, iv)) {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }

    int len;
    if (1 != EVP_DecryptUpdate(ctx, plaintext, &len, ciphertext, ciphertext_len)) {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }
    int plaintext_len = len;

    if (1 != EVP_DecryptFinal_ex(ctx, plaintext + len, &len)) {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }
    plaintext_len += len;

    EVP_CIPHER_CTX_free(ctx);
    return plaintext_len;
}
