    struct timeval now;
    int ret;

    ret = jwt_decode(&jwt, NULL, 0, token);
    if (ret != JWT_OK) {
        return false;
    }

    ret = jwt_get_grant(jwt, "sub", &user_id, JSON_TYPE_STRING);
    if (ret != JWT_OK || user_id == NULL) {
        jwt_free(jwt);
        return false;
    }

    ret = jwt_get_grant(jwt, "exp", expiration_time, JSON_TYPE_NUMBER);
    if (ret != JWT_OK || *expiration_time <= 0) {
        jwt_free(jwt);
        free(user_id);
        return false;
    }

    jwt_free(jwt);
    return true;
