#include <iostream>
#include <string>
#include <vector>
#include <random>
#include <json/json.h>

class NetworkHealthMonitor {
private:
    double minLatency, maxLatency;
    int minLoss, maxLoss;
    std::mt19937 gen;

public:
    NetworkHealthMonitor(double minLatency, double maxLatency, int minLoss, int maxLoss)
        : minLatency(minLatency), maxLatency(maxLatency), minLoss(minLoss), maxLoss(maxLoss), gen(std::random_device{}()) {
        if (minLatency > maxLatency || minLoss > maxLoss) throw std::out_of_range("Invalid range");
    }

    double GetRandomLatency() {
        std::uniform_real_distribution<> dis(minLatency, maxLatency);
        return dis(gen);
    }

    int GetRandomLoss() {
        std::uniform_int_distribution<> dis(minLoss, maxLoss - 1);
        return dis(gen);
    }

    bool EvaluateNetworkHealth(const std::string& config) {
        Json::Value root;
        Json::CharReaderBuilder builder;
        std::unique_ptr<Json::CharReader> reader(builder.newCharReader());
        JSONCPP_STRING errs;

        if (!reader->parse(config.c_str(), config.c_str() + config.size(), &root, &errs)) {
            return false;
        }

        if (!root.isMember("latency") || !root["latency"].isNumber() ||
            !root.isMember("packet_loss") || !root["packet_loss"].isUInt()) {
            return false;
        }

        double latency = root["latency"].asDouble();
        unsigned int packetLoss = root["packet_loss"].asUInt();

        if (latency < 0 || packetLoss > 100) {
            return false;
        }

        Json::Value optionalJitter = root.get("jitter", Json::nullValue);
        if (!optionalJitter.isNull() && !optionalJitter.isNumber()) {
            return false;
        }

        return true;
    }

    std::string toString() const {
        return "Latency: [" + std::to_string(minLatency) + ", " + std::to_string(maxLatency) +
               "], Loss: [" + std::to_string(minLoss) + ", " + std::to_string(maxLoss) + ")";
    }

    double CalculateMean(const std::vector<double>& data) {
        return std::accumulate(data.begin(), data.end(), 0.0) / data.size();
    }

    double CalculateMedian(std::vector<double> data) {
        size_t n = data.size() / 2;
        nth_element(data.begin(), data.begin() + n, data.end());
        return (data.size() % 2 != 0) ? data[n] : (data[n - 1] + data[n]) / 2.0;
    }

    double CalculateStandardDeviation(const std::vector<double>& data) {
        double mean = CalculateMean(data);
        double variance = 0.0;
        for (double value : data) {
            variance += std::pow(value - mean, 2);
        }
        return std::sqrt(variance / data.size());
    }
};

int main() {
    NetworkHealthMonitor monitor(1.0, 5.0, 0, 5);
    std::cout << monitor.toString() << std::endl;

    std::vector<double> latencies = {monitor.GetRandomLatency(), monitor.GetRandomLatency()};
    std::cout << "Mean: " << monitor.CalculateMean(latencies) << ", Median: " << monitor.CalculateMedian(latencies)
              << ", Std Dev: " << monitor.CalculateStandardDeviation(latencies) << std::endl;

    return 0;
}
