#include <cmath>

class NetworkHealthMonitor {
private:
    std::mt19937 generator;
    std::uniform_real_distribution<> latencyDistribution;
    std::uniform_int_distribution<> lossDistribution;
    std::uniform_real_distribution<> jitterDistribution;

    double minLatency, maxLatency;
    int minLoss, maxLoss;
    double jitterMin, jitterMax;

public:
    NetworkHealthMonitor(double minLatency, double maxLatency, int minLoss, int maxLoss, double jitterMin, double jitterMax)
        : generator(std::random_device()()), latencyDistribution(minLatency, maxLatency), lossDistribution(0, 100),
          jitterDistribution(jitterMin, jitterMax) {
        if (minLatency > maxLatency || minLoss > maxLoss || jitterMin >= jitterMax) {
            throw std::out_of_range("Invalid range for network metrics");
        }
    }

    double GetRandomLatency() { return latencyDistribution(generator); }
    int GetRandomLoss() { return lossDistribution(generator); }
    double GetRandomJitter() { return jitterDistribution(generator); }

    bool EvaluateNetworkHealth(const std::string& config) {
        Json::Value root;
        if (!Json::Reader().parse(config, root)) return false;

