import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.*;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ExecutionException;
import java.util.stream.Collectors;

public class StringBatchProcessor {

    private static final Logger logger = LoggerFactory.getLogger(StringBatchProcessor.class);
    private static final MessageDigest md5Digest;

    static {
        try {
            md5Digest = MessageDigest.getInstance("MD5");
        } catch (NoSuchAlgorithmException e) {
            throw new RuntimeException("Failed to initialize MD5 digest", e);
        }
    }

    public static Map<String, String> processBatch(List<String> strings, int batchSize) throws ExecutionException, InterruptedException {
        long startTime = System.currentTimeMillis();
        AtomicLong processedCount = new AtomicLong(0);
        AtomicLong skippedCount = new AtomicLong(0);

        List<CompletableFuture<Void>> futures = new ArrayList<>();
        for (int i = 0; i < strings.size(); i += batchSize) {
            int end = Math.min(i + batchSize, strings.size());
            List<String> batch = strings.subList(i, end);
            CompletableFuture<Void> future = CompletableFuture.runAsync(() -> processBatch(batch, processedCount, skippedCount));
            futures.add(future);
        }

        CompletableFuture.allOf(futures.toArray(new CompletableFuture[0])).get();
        long endTime = System.currentTimeMillis();

        logger.info("Processed {} strings, skipped {} strings in {} ms", processedCount.get(), skippedCount.get(), endTime - startTime);

        return new HashMap<>();
    }

    private static void processBatch(List<String> batch, AtomicLong processedCount, AtomicLong skippedCount) {
        for (String str : batch) {
            if (str == null || str.isEmpty()) {
                logger.warn("Skipping empty or null string");
                skippedCount.incrementAndGet();
            } else {
                try {
                    byte[] hash = md5Digest.digest(str.getBytes());
                    String md5Hash = bytesToHex(hash);
                    // Process MD5 hash...
                    processedCount.incrementAndGet();
                } catch (Exception e) {
                    logger.error("Error processing string: {}", str, e);
                }
            }
        }
    }

    private static String bytesToHex(byte[] bytes) {
        StringBuilder sb = new StringBuilder();
        for (byte b : bytes) {
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }

    public static void main(String[] args) {
        List<String> strings = Arrays.asList("example1", "example2", null, "", "example3");
        try {
            Map<String, String> result = processBatch(strings, 2);
            // Handle result...
        } catch (Exception e) {
            logger.error("Error processing batch", e);
        }
    }
}
