        printf("Maximum number of sessions reached.\n");
        return;
    }

    // Validate token and extract claims
    if (!validate_token(token)) {
        printf("Invalid session token.\n");
        return;
    }

    Session new_session = {user_id, time(NULL) + SESSION_EXPIRY_TIME, NULL};
    sessions[session_count++] = new_session;
}

void update_session(int session_index, const char *custom_attributes) {
    if (session_index < 0 || session_index >= session_count) {
        printf("Invalid session index.\n");
        return;
    }

    // Validate custom attributes
    if (!validate_custom_attributes(custom_attributes)) {
        printf("Invalid custom attributes.\n");
        return;
    }

    sessions[session_index].custom_attributes = strdup(custom_attributes);
}

const char* get_session(int session_index) {
    if (session_index < 0 || session_index >= session_count) {
        printf("Invalid session index.\n");
        return NULL;
    }

    // Validate session expiry
    if (time(NULL) > sessions[session_index].expiry_time) {
        printf("Session expired.\n");
        return NULL;
    }

    return sessions[session_index].custom_attributes;
}

void clean_expired_sessions() {
    time_t current_time = time(NULL);

    for (int i = 0; i < session_count; i++) {
        if (sessions[i].expiry_time <= current_time) {
            // Clean up expired session
            free(sessions[i].custom_attributes);
            memmove(&sessions[i], &sessions[i + 1], sizeof(Session) * (session_count - i - 1));
            session_count--;
            i--; // Adjust index after removal
