#include <openssl/evp.h>
#include <openssl/rand.h>
#include <string.h>

EVP_CIPHER_CTX* performCryptographicOperation(const char *operation) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (ctx == NULL) {
        return NULL;
    }

    const EVP_CIPHER *cipher = NULL;
    if (strcmp(operation, "ENCRYPT") == 0) {
        cipher = EVP_aes_256_cbc();
    } else if (strcmp(operation, "DECRYPT") == 0) {
        cipher = EVP_aes_256_cbc();
    }

    if (cipher == NULL) {
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    // Initialize context for encryption or decryption
    int ret = EVP_CipherInit_ex(ctx, cipher, NULL, NULL, NULL, 1); // Set to 1 for encrypt and 0 for decrypt
    if (ret != 1) {
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    // Generate a random key and IV
    unsigned char key[EVP_MAX_KEY_LENGTH];
    unsigned char iv[EVP_MAX_IV_LENGTH];
    RAND_bytes(key, sizeof(key));
    RAND_bytes(iv, sizeof(iv));

    // Set the key and IV
    ret = EVP_CipherInit_ex(ctx, NULL, NULL, key, iv, 1);
    if (ret != 1) {
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    return ctx;
}
