import re

def process_config_file(file_path):
    try:
        with open(file_path, 'r') as file:
            lines = file.readlines()
            lines.sort()

            if not lines:
                raise ValueError("No data in the configuration file")

            last_line = lines[-1]
            sequence_number_match = re.search(r'sequence_number:(\d+)', last_line)

            if sequence_number_match:
                return int(sequence_number_match.group(1))
            else:
                raise ValueError("Sequence number not found in the last line")
    except FileNotFoundError:
        print(f"Error: File '{file_path}' not found.")
    except Exception as e:
        print(f"An error occurred: {e}")

    return None
