class NetworkHealthMonitor {
private:
    double minLatency, maxLatency;
    int minLoss, maxLoss;
    double jitterMin, jitterMax;
    int throughputMin, throughputMax;
    int congestionLow, congestionHigh;

public:
    NetworkHealthMonitor(double initialMinLatency, double initialMaxLatency,
                          int initialMinLoss, int initialMaxLoss,
                          double initialJitterMin, double initialJitterMax,
                          int initialThroughputMin, int initialThroughputMax,
                          int initialCongestionLow, int initialCongestionHigh)
        : minLatency(initialMinLatency), maxLatency(initialMaxLatency),
          minLoss(initialMinLoss), maxLoss(initialMaxLoss),
          jitterMin(initialJitterMin), jitterMax(initialJitterMax),
          throughputMin(initialThroughputMin), throughputMax(initialThroughputMax),
          congestionLow(initialCongestionLow), congestionHigh(initialCongestionHigh) {}

    double GetRandomLatency() {
        return minLatency + (maxLatency - minLatency) * ((double)rand() / RAND_MAX);
    }

    int GetRandomLoss() {
        return minLoss + rand() % (maxLoss - minLoss + 1);
    }

    double GetRandomJitter() {
        return jitterMin + (jitterMax - jitterMin) * ((double)rand() / RAND_MAX);
    }

    int GetRandomThroughput() {
        return throughputMin + rand() % (throughputMax - throughputMin + 1);
    }

    void AdjustDynamicRanges(double newMinLatency, double newMaxLatency,
                              int newMinLoss, int newMaxLoss,
                              double newJitterMin, double newJitterMax,
                              int newThroughputMin, int newThroughputMax,
                              int newCongestionLow, int newCongestionHigh) {
        minLatency = std::max(newMinLatency, 0.0);
        maxLatency = std::min(newMaxLatency, 10000.0); // Assuming maximum latency of 10000 ms
        minLoss = std::max(newMinLoss, 0);
        maxLoss = std::min(newMaxLoss, 100);
        jitterMin = std::max(newJitterMin, 0.0);
        jitterMax = std::min(newJitterMax, 10.0); // Assuming maximum jitter of 10 ms
        throughputMin = std::max(newThroughputMin, 0);
        throughputMax = std::min(newThroughputMax, 1000000); // Assuming maximum throughput of 1 Gbps
        congestionLow = std::max(newCongestionLow, 0);
        congestionHigh = std::min(newCongestionHigh, 100);
    }

    bool ValidateHealthMetrics(const std::string& config) {
        Json::Value root;
        if (!Json::Reader().parse(config, root)) return false;

        if (!root.isMember("latency") || !root["latency"].isNumeric() ||
            !root.isMember("packet_loss") || !root["packet_loss"].isInt() ||
            !root.isMember("jitter") || !root["jitter"].isNumeric() ||
            !root.isMember("throughput") || !root["throughput"].isInt() ||
            !root.isMember("congestion_level") || !root["congestion_level"].isInt()) {
            return false;
        }

        double latency = root["latency"].asDouble();
        int packetLoss = root["packet_loss"].asInt();
        double jitter = root["jitter"].asDouble();
        int throughput = root["throughput"].asInt();
        int congestionLevel = root["congestion_level"].asInt();

        if (latency < 0 || packetLoss < 0 || packetLoss > 100 ||
            jitter < 0 || throughput < 0 || congestionLevel < 0) {
            return false;
        }

        if (packetLoss > latency) return false;

        return true;
    }
};

int main() {
    srand(time(0));
    NetworkHealthMonitor monitor(0.5, 10.0, 0, 5, 0, 2, 0, 1000, 0, 10);
    std::cout << "Random Latency: " << monitor.GetRandomLatency() << std::endl;
    std::cout << "Random Loss: " << monitor.GetRandomLoss() << std::endl;
    std::cout << "Random Jitter: " << monitor.GetRandomJitter() << std::endl;
    std::cout << "Random Throughput: " << monitor.GetRandomThroughput() << std::endl;
    return 0;
}
