void log_message(const char *condition, ...) {
    va_list args;
    char message[256];

    va_start(args, condition);
    vsnprintf(message, sizeof(message), condition, args);
    va_end(args);

    fprintf(stderr, "Error: %s\n", message);
}

int allocate_connection() {
    pthread_mutex_lock(&global_lock);
    int id = next_connection_id;
    if (next_connection_id < MAX_CONNECTIONS) {
        next_connection_id++;
        memset(&connections[id], 0, sizeof(TCPConnection));
        pthread_mutex_init(&connections[id].lock, NULL);
    } else {
        log_message("Maximum connections reached");
    }
    pthread_mutex_unlock(&global_lock);
    return id;
}

void free_connection(int id) {
    pthread_mutex_destroy(&connections[id].lock);
    memset(&connections[id], 0, sizeof(TCPConnection));
    pthread_mutex_lock(&global_lock);
    if (id < next_connection_id) {
        next_connection_id = id;
    }
    pthread_mutex_unlock(&global_lock);
}

void add_packet_to_queue(int id, int packet) {
    pthread_mutex_lock(&connections[id].lock);
    if (connections[id].queue_size < MAX_QUEUE_SIZE) {
        connections[id].packet_queue[connections[id].queue_size] = packet;
        connections[id].queue_size++;
    } else {
        log_message("Queue overflow for connection %d", id);
    }
    pthread_mutex_unlock(&connections[id].lock);
