int perform_dns_resolution(const char *hostname, u_char *ip_buffer) {
    int query_count = 0;
    time_t current_time = time(NULL);

    // Check rate limiting
    if (current_time - dns_cache[cache_size - 1].last_updated < 1) {
        return -1; // Rate limit exceeded
    }

    // Check local cache
    for (int i = 0; i < cache_size; i++) {
        if (strcmp(dns_cache[i].hostname, hostname) == 0 && current_time - dns_cache[i].last_updated < 3600) {
            memcpy(ip_buffer, &dns_cache[i].ip_address, sizeof(in_addr_t));
            return 0;
        }
    }

    // Perform DNS query
    struct hostent *host = gethostbyname(hostname);
    if (host == NULL) {
        herror("gethostbyname");
        return -1; // Network failure or invalid hostname
    }

    memcpy(ip_buffer, host->h_addr_list[0], sizeof(in_addr_t));

    // Update local cache
    if (cache_size < CACHE_SIZE) {
        strcpy(dns_cache[cache_size].hostname, hostname);
        dns_cache[cache_size].ip_address = *(in_addr_t *)host->h_addr_list[0];
        dns_cache[cache_size].last_updated = current_time;
        cache_size++;
    }

    return 0;
}

