        connections.push_back(conn);
    }

    void removeConnection(const std::string& macAddress) {
        std::lock_guard<std::mutex> lock(mtx);
        connections.erase(std::remove_if(connections.begin(), connections.end(),
                                          [&macAddress](const NetworkDeviceConnection& conn) {
                                              return conn.getMACAddress() == macAddress;
                                          }),
                          connections.end());
    }

    void setInactiveThreshold(int threshold) {
        std::lock_guard<std::mutex> lock(mtx);
        inactiveThreshold = threshold;
    }

private:
    void pruneInactiveConnections() {
        while (true) {
            std::this_thread::sleep_for(std::chrono::seconds(60)); // Check every minute
            std::lock_guard<std::mutex> lock(mtx);
            connections.erase(std::remove_if(connections.begin(), connections.end(),
                                              [](const NetworkDeviceConnection& conn) {
                                                  return conn.getIdleTime() > conn.getInactiveThreshold();
                                              }),
                              connections.end());
        }
    }
