        std::thread([this]() {
            while (running) {
                pruneInactiveConnections();
                std::this_thread::sleep_for(std::chrono::seconds(60));
            }
        }).detach();
    }

    void stop() {
        running = false;
        cv.notify_all();
    }

    void addConnection(NetworkDeviceConnection* conn, const std::string& sessionID) {
        std::lock_guard<std::mutex> lock(mutex);
        connections.push_back(conn);
        sessionIDs[sessionID] = connections.size() - 1;
    }

