import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.HashMap;
import java.util.Map;

public class MD5BatchProcessor {

    private static final Map<String, String> cache = new HashMap<>();

    public static synchronized Map<String, String> processBatch(String[] inputs) {
        Map<String, String> results = new HashMap<>();
        for (String input : inputs) {
            try {
                String hash = getMD5Hash(input);
                if (hash != null) {
                    results.put(input, hash);
                }
            } catch (NoSuchAlgorithmException e) {
                System.err.println("MD5 algorithm not found: " + e.getMessage());
            }
        }
        return results;
    }

    private static synchronized String getMD5Hash(String input) throws NoSuchAlgorithmException {
        if (cache.containsKey(input)) {
            return cache.get(input);
        }
        MessageDigest md = MessageDigest.getInstance("MD5");
        byte[] messageDigest = md.digest(input.getBytes());
        StringBuilder hexString = new StringBuilder();
        for (byte b : messageDigest) {
            String hex = Integer.toHexString(0xff & b);
            if (hex.length() == 1) hexString.append('0');
            hexString.append(hex);
        }
        cache.put(input, hexString.toString());
        return hexString.toString();
    }

    public static void main(String[] args) {
        // Example usage
        String[] inputs = {"input1", "input2", "input3"};
        Map<String, String> results = processBatch(inputs);
        System.out.println(results);
    }
}
```

This code snippet defines a class `MD5BatchProcessor` with a static method `processBatch` that takes an array of strings and returns a `HashMap` containing the MD5 hashes of the input strings. It uses a synchronized `cache` to store previously computed hashes, ensuring thread safety and reducing redundant calculations. The `getMD5Hash` method computes the hash using Java's `MessageDigest` and caches the result for future use. This approach optimizes memory usage by avoiding recomputation of hashes for inputs that have already been processed.']

