#include <mutex>
#include <unordered_map>
#include <thread>
#include <condition_variable>

class NetworkDeviceManager {
public:
    using MACAddress = std::string;
    using SessionID = int;
    using DataRate = double;

    struct DeviceConnection {
        MACAddress mac_address;
        double latency;
        std::vector<std::pair<SessionID, DataRate>> sessions;
    };

private:
    mutable std::mutex mutex_;
    std::unordered_map<MACAddress, DeviceConnection> device_connections_;
    std::condition_variable cv_;
    bool stop_pruning_{false};

    void PruneInactiveConnections() {
        while (true) {
            std::unique_lock<std::mutex> lock(mutex_);
            cv_.wait(lock, [this] { return stop_pruning_ || !device_connections_.empty(); });

            if (stop_pruning_) break;

            // Assuming inactive connections are those with no sessions
            device_connections_.erase(
                std::remove_if(device_connections_.begin(), device_connections_.end(),
                               [](const auto& pair) {
                                   return pair.second.sessions.empty();
                               }),
                device_connections_.end());
        }
    }

public:
    NetworkDeviceManager() {
        // Start pruning thread
        prune_thread_ = std::thread(&NetworkDeviceManager::PruneInactiveConnections, this);
    }

    ~NetworkDeviceManager() {
        {
            std::lock_guard<std::mutex> lock(mutex_);
            stop_pruning_ = true;
        }
        cv_.notify_all();
        if (prune_thread_.joinable()) prune_thread_.join();
    }

    void AddOrUpdateConnection(const MACAddress& mac_address, double latency) {
        std::lock_guard<std::mutex> lock(mutex_);
        device_connections_[mac_address] = {mac_address, latency, {}};
    }

    void RemoveConnection(const MACAddress& mac_address) {
        std::lock_guard<std::mutex> lock(mutex_);
        device_connections_.erase(mac_address);
    }

    void AddSession(const MACAddress& mac_address, SessionID session_id, DataRate data_rate) {
        std::lock_guard<std::mutex> lock(mutex_);
        auto& connection = device_connections_[mac_address];
        connection.sessions.emplace_back(session_id, data_rate);
    }

    void RemoveSession(const MACAddress& mac_address, SessionID session_id) {
        std::lock_guard<std::mutex> lock(mutex_);
        auto& connection = device_connections_[mac_address];
        connection.sessions.erase(std::remove_if(connection.sessions.begin(), connection.sessions.end(),
                                                [session_id](const auto& pair) {
                                                    return pair.first == session_id;
                                                }),
                                 connection.sessions.end());
    }

    // Method to integrate with external monitoring service
    void UpdateDeviceStatus(const MACAddress& mac_address, bool is_active) {
        std::lock_guard<std::mutex> lock(mutex_);
        if (is_active) {
            device_connections_[mac_address].latency = 0.0; // Reset latency on active connection
        } else {
            RemoveConnection(mac_address);
        }
    }

private:
    std::thread prune_thread_;
};
