        return NULL;
    }
    conn->connection_id = id;
    conn->bandwidth_usage = bw;
    conn->priority = 0; // Default priority
    pthread_mutex_init(&conn->queue_mutex, NULL);
    // Initialize other fields...
    return conn;
}

void destroy_tcp_connection(TCPConnection* conn) {
    if (conn != NULL) {
        pthread_mutex_destroy(&conn->queue_mutex);
        free(conn);
    }
}

TCPConnectionList* create_tcp_connection_list(int initial_capacity) {
    TCPConnectionList* list = (TCPConnectionList*)malloc(sizeof(TCPConnectionList));
    if (list == NULL) {
        log_error("Failed to allocate memory for connection list");
        return NULL;
    }
    list->connections = (TCPConnection**)malloc(initial_capacity * sizeof(TCPConnection*));
    if (list->connections == NULL) {
        free(list);
        log_error("Failed to allocate memory for connection array");
        return NULL;
