typedef struct {
    EVP_CIPHER_CTX *ctx;
    unsigned char key[32];
    unsigned char iv[16];
} CipherContext;

CipherContext* initialize_secure_crypto_cipher(const char* password) {
    CipherContext* ctx = malloc(sizeof(CipherContext));
    if (!ctx) return NULL;

    unsigned char salt[16];
    if (RAND_bytes(salt, sizeof(salt)) != 1) {
        free(ctx);
        return NULL;
    }

    unsigned char derived_key[32];
    if (PKCS5_PBKDF2_HMAC(password, strlen(password), salt, sizeof(salt), 100000, EVP_sha256(), sizeof(derived_key), derived_key) != 1) {
        free(ctx);
        return NULL;
    }

    memcpy(ctx->key, derived_key, sizeof(ctx->key));
    memset(ctx->iv, 0, sizeof(ctx->iv));

    ctx->ctx = EVP_CIPHER_CTX_new();
    if (!ctx->ctx) {
        free(ctx->key);
        free(ctx);
        return NULL;
    }

    // Set up DES cipher (ECB, EDE, EDE3, CFB)
    if (!EVP_EncryptInit_ex(ctx->ctx, EVP_des_ecb(), NULL, ctx->key, ctx->iv)) {
        EVP_CIPHER_CTX_free(ctx->ctx);
        free(ctx->key);
        free(ctx);
        return NULL;
    }

    // Set up AES-256-CBC
    if (!EVP_EncryptInit_ex(ctx->ctx, EVP_aes_256_cbc(), NULL, ctx->key, ctx->iv)) {
        EVP_CIPHER_CTX_free(ctx->ctx);
        free(ctx->key);
        free(ctx);
        return NULL;
    }

    // Disable automatic memory management
    EVP_CIPHER_CTX_set_flags(ctx->ctx, EVP_CIPHER_CTX_FLAG_NO_PADDING);

    return ctx;
}

void cleanup_cipher(CipherContext* ctx) {
    if (ctx->ctx) EVP_CIPHER_CTX_free(ctx->ctx);
    free(ctx->key);
    free(ctx);
}

void rederive_keys(CipherContext* ctx, const char* password) {
    unsigned char derived_key[32];
    unsigned char salt[16];

    // Assume salt is already generated and stored
    if (RAND_bytes(salt, sizeof(salt)) != 1) return;

    if (PKCS5_PBKDF2_HMAC(password, strlen(password), salt, sizeof(salt), 100000, EVP_sha256(), sizeof(derived_key), derived_key) != 1) return;

    memcpy(ctx->key, derived_key, sizeof(ctx->key));
}

void* thread_safe_cipher_function(CipherContext** ctx, const char* password) {
    if (*ctx == NULL) *ctx = initialize_secure_crypto_cipher(password);
    if (!*ctx) return NULL;

    // Perform cipher operations here
    return (void*)*ctx;
}

void log_key_derivation(const char* mode, const char* status) {
    printf("Key derivation for %s: %s\n", mode, status);
}

void log_cipher_usage(CipherContext* ctx, const char* operation) {
    printf("Cipher operation (%s): Key used\n", operation);
}

void log_error(const char* error_message) {
    fprintf(stderr, "Error: %s\n", error_message);
}
