const EVP_CIPHER* get_cipher(const char* cipher_type) {
    if (strcmp(cipher_type, "ECB") == 0) return EVP_des_ecb();
    else if (strcmp(cipher_type, "EDE") == 0) return EVP_des_ede();
    else if (strcmp(cipher_type, "EDE3") == 0) return EVP_des_ede3();
    else if (strcmp(cipher_type, "CFB") == 0) return EVP_des_cfb8();
    else if (strcmp(cipher_type, "NULL") == 0) return NULL;
    return NULL;
}

int encrypt_data(const unsigned char* key, const unsigned char* iv, const unsigned char* plaintext, size_t plaintext_len, unsigned char** ciphertext, size_t* ciphertext_len, const EVP_CIPHER* cipher) {
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (!ctx) return -1;

    int len;
    if (EVP_EncryptInit_ex(ctx, cipher, NULL, key, iv) != 1 ||
        EVP_EncryptUpdate(ctx, *ciphertext, &len, plaintext, plaintext_len) != 1) {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }

    *ciphertext_len = len;
    if (EVP_EncryptFinal_ex(ctx, (*ciphertext) + len, &len) != 1) {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }

    *ciphertext_len += len;
    EVP_CIPHER_CTX_free(ctx);
    return 0;
}

int decrypt_data(const unsigned char* key, const unsigned char* iv, const unsigned char* ciphertext, size_t ciphertext_len, unsigned char** plaintext, size_t* plaintext_len, const EVP_CIPHER* cipher) {
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (!ctx) return -1;

    int len;
    if (EVP_DecryptInit_ex(ctx, cipher, NULL, key, iv) != 1 ||
        EVP_DecryptUpdate(ctx, *plaintext, &len, ciphertext, ciphertext_len) != 1) {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }

    *plaintext_len = len;
    if (EVP_DecryptFinal_ex(ctx, (*plaintext) + len, &len) != 1) {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }

    *plaintext_len += len;
    EVP_CIPHER_CTX_free(ctx);
    return 0;
}
