### PHP Front-End Module for User Authentication

```php
<?php
class OAuth2Authenticator {
    private $oauth2Client;
    private $sessionKey = 'user_token';

    public function __construct($clientId, $clientSecret, $redirectUri) {
        $this->oauth2Client = new \League\OAuth2\Client\Client([
            'clientId' => $clientId,
            'clientSecret' => $clientSecret,
            'redirectUri' => $redirectUri,
            'provider' => 'google'
        ]);
    }

    public function authenticate() {
        if (!isset($_SESSION[$this->sessionKey])) {
            $authUrl = $this->oauth2Client->getAuthenticationUrl();
            header('Location: ' . $authUrl);
            exit;
        }
    }

    public function getUserInfo() {
        if (isset($_SESSION[$this->sessionKey])) {
            try {
                $accessToken = $_SESSION[$this->sessionKey];
                $client = $this->oauth2Client->getHttpClient();
                $response = $client->request('GET', 'https://www.googleapis.com/oauth2/v3/userinfo', [
                    'headers' => ['Authorization' => 'Bearer ' . $accessToken]
                ]);
                return json_decode($response->getBody()->getContents(), true);
            } catch (\Exception $e) {
                unset($_SESSION[$this->sessionKey]);
                header('Location: ' . $_SERVER['PHP_SELF']);
                exit;
            }
        }
        return null;
    }

    public function handleCallback() {
        if (isset($_GET['code'])) {
            try {
                $token = $this->oauth2Client->getAccessToken('authorization_code', [
                    'code' => $_GET['code']
                ]);
                $_SESSION[$this->sessionKey] = $token->getToken();
                header('Location: ' . $_SERVER['PHP_SELF']);
                exit;
            } catch (\Exception $e) {
                // Handle error
            }
        }
    }
}
```

