#define MAX_BUFFER_SIZE 256

void printUsage() {
    fprintf(stderr, "Usage: program_name [CSV_FILE]\n");
}

int* readIntegersFromCSV(const char* filename, int* size) {
    FILE* file = fopen(filename, "r");
    if (!file) {
        perror("Failed to open CSV file");
        return NULL;
    }

    *size = 0;
    int capacity = 10;
    int* integers = malloc(capacity * sizeof(int));
    if (!integers) {
        perror("Memory allocation failed");
        fclose(file);
        return NULL;
    }

    char buffer[MAX_BUFFER_SIZE];
    while (fgets(buffer, MAX_BUFFER_SIZE, file)) {
        char* token = strtok(buffer, ",");
        if (!token) continue;

        int num;
        if (sscanf(token, "%d", &num) != 1) {
            fprintf(stderr, "Invalid data format in CSV\n");
            free(integers);
            fclose(file);
            return NULL;
        }

        integers[*size] = num;
        (*size)++;
        if (*size == capacity) {
            capacity *= 2;
            int* temp = realloc(integers, capacity * sizeof(int));
            if (!temp) {
                perror("Memory reallocation failed");
                free(integers);
                fclose(file);
                return NULL;
            }
            integers = temp;
        }
    }

    fclose(file);
    return integers;
}

void findAndPrintLargestInteger(int* integers, int size) {
    if (size == 0) {
        fprintf(stderr, "No integers to process\n");
        return;
    }

    int largest = INT_MIN;
    for (int i = 0; i < size; i++) {
        if ((long long)largest + (long long)integers[i] > LLONG_MAX) {
            fprintf(stderr, "Integer overflow detected\n");
            return;
        }
        if (integers[i] > largest) {
            largest = integers[i];
        }
    }

    printf("Largest integer: %d\n", largest);
}

// Add cryptographic operations here

int main(int argc, char* argv[]) {
    int size = 0;
    int* integers = NULL;

    if (argc == 2) {
        integers = readIntegersFromCSV(argv[1], &size);
    } else {
        printUsage();
        return EXIT_FAILURE;
    }

    if (!integers || size == 0) {
        free(integers);
        return EXIT_FAILURE;
    }

    findAndPrintLargestInteger(integers, size);

    // Call cryptographic operations here

    free(integers);
    return EXIT_SUCCESS;
}
