EVP_CIPHER* select_cipher(const char* algorithm, const char* mode) {
    EVP_CIPHER* cipher = NULL;
    if (strcmp(algorithm, "AES") == 0 && strcmp(mode, "CBC") == 0) {
        cipher = EVP_aes_256_cbc();
    } else if (strcmp(algorithm, "DES") == 0 && strcmp(mode, "ECB") == 0) {
        cipher = EVP_des_ecb();
    } else if (strcmp(algorithm, "Triple DES") == 0 && strcmp(mode, "CTR") == 0) {
        cipher = EVP_aes_128_ctr();
    }
    return cipher;
}

void* kdf(const char* password, int password_len, const char* algorithm) {
    void* kdf_params = NULL;
    if (strcmp(algorithm, "SHA-256") == 0) {
        SHA256_CTX sha256;
        unsigned char hash[SHA256_DIGEST_LENGTH];
        SHA256_Init(&sha256);
        SHA256_Update(&sha256, password, password_len);
        SHA256_Final(hash, &sha256);
        kdf_params = malloc(SHA256_DIGEST_LENGTH);
        memcpy(kdf_params, hash, SHA256_DIGEST_LENGTH);
    } else if (strcmp(algorithm, "SHA-512") == 0) {
        SHA512_CTX sha512;
        unsigned char hash[SHA512_DIGEST_LENGTH];
        SHA512_Init(&sha512);
        SHA512_Update(&sha512, password, password_len);
        SHA512_Final(hash, &sha512);
        kdf_params = malloc(SHA512_DIGEST_LENGTH);
        memcpy(kdf_params, hash, SHA512_DIGEST_LENGTH);
    }
    return kdf_params;
}

void* encrypt(const unsigned char* plaintext, int plaintext_len, EVP_CIPHER* cipher, const void* key) {
    void* ciphertext = malloc(plaintext_len + EVP_CIPHER_block_size(cipher));
    int len, ciphertext_len;
    EVP_EncryptInit_ex(NULL, cipher, NULL, (unsigned char*)key, NULL);
    EVP_EncryptUpdate(NULL, ciphertext, &len, plaintext, plaintext_len);
    ciphertext_len = len;
    EVP_EncryptFinal_ex(NULL, ciphertext + len, &len);
    ciphertext_len += len;
    return ciphertext;
}

int decrypt(const unsigned char* ciphertext, int ciphertext_len, EVP_CIPHER* cipher, const void* key, unsigned char* decryptedtext) {
    int len, plaintext_len;
    EVP_DecryptInit_ex(NULL, cipher, NULL, (unsigned char*)key, NULL);
    EVP_DecryptUpdate(NULL, decryptedtext, &len, ciphertext, ciphertext_len);
    plaintext_len = len;
    if (!EVP_DecryptFinal_ex(NULL, decryptedtext + len, &len)) {
        return -1; // Decryption failed
    }
    plaintext_len += len;
    return plaintext_len;
}

void free_resources(EVP_CIPHER* cipher, void* kdf_params) {
    EVP_CIPHER_free(cipher);
    free(kdf_params);
}
