// Define encryption modes
typedef enum {
    ECB,
    EDE,
    EDE3
} EncryptionMode;

// Define CFB mode support
typedef enum {
    CFB_ENABLED,
    CFB_DISABLED
} CFBModeSupport;

// Function to encrypt data
int encrypt_data(const unsigned char *key, const unsigned char *iv, const unsigned char *plaintext, size_t plaintext_len, unsigned char **ciphertext, size_t *ciphertext_len, EncryptionMode mode, CFBModeSupport cfb_support) {
    EVP_CIPHER_CTX *ctx;
    int len;
    int ciphertext_len_out;

    // Allocate context
    if (!(ctx = EVP_CIPHER_CTX_new())) return -1;

    // Initialize encryption operation
    switch (mode) {
        case ECB:
            if (EVP_EncryptInit_ex(ctx, EVP_aes_256_ecb(), NULL, key, iv) != 1) goto cleanup;
            break;
        case EDE:
            if (EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv) != 1) goto cleanup;
            break;
        case EDE3:
            if (EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv) != 1) goto cleanup;
            break;
    }

    // Allocate ciphertext buffer
    *ciphertext_len = plaintext_len + EVP_CIPHER_block_size(EVP_CIPHER_CTX_cipher(ctx));
    if (!(*ciphertext = (unsigned char *)malloc(*ciphertext_len))) goto cleanup;

    // Perform encryption
    if (EVP_EncryptUpdate(ctx, *ciphertext, &len, plaintext, plaintext_len) != 1) goto cleanup;
    ciphertext_len_out = len;

    // Finalize encryption
    if (EVP_EncryptFinal_ex(ctx, (*ciphertext + len), &len) != 1) goto cleanup;
    ciphertext_len_out += len;

    *ciphertext_len = ciphertext_len_out;
    EVP_CIPHER_CTX_free(ctx);
    return 0;

cleanup:
    EVP_CIPHER_CTX_free(ctx);
    if (*ciphertext) {
        free(*ciphertext);
        *ciphertext = NULL;
    }
    return -1;
}

// Function to decrypt data
int decrypt_data(const unsigned char *key, const unsigned char *iv, const unsigned char *ciphertext, size_t ciphertext_len, unsigned char **plaintext, size_t *plaintext_len, EncryptionMode mode, CFBModeSupport cfb_support) {
    EVP_CIPHER_CTX *ctx;
    int len;

    // Allocate context
    if (!(ctx = EVP_CIPHER_CTX_new())) return -1;

    // Initialize decryption operation
    switch (mode) {
        case ECB:
            if (EVP_DecryptInit_ex(ctx, EVP_aes_256_ecb(), NULL, key, iv) != 1) goto cleanup;
            break;
        case EDE:
            if (EVP_DecryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv) != 1) goto cleanup;
            break;
        case EDE3:
            if (EVP_DecryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv) != 1) goto cleanup;
            break;
    }

    // Allocate plaintext buffer
    *plaintext_len = ciphertext_len;
    if (!(*plaintext = (unsigned char *)malloc(*plaintext_len))) goto cleanup;

    // Perform decryption
    if (EVP_DecryptUpdate(ctx, *plaintext, &len, ciphertext, ciphertext_len) != 1) goto cleanup;

    *plaintext_len = len;
    EVP_CIPHER_CTX_free(ctx);
    return 0;

cleanup:
    EVP_CIPHER_CTX_free(ctx);
    if (*plaintext) {
        free(*plaintext);
        *plaintext = NULL;
    }
    return -1;
}

// Example usage
int main() {
    unsigned char key[32] = { /* ... */ };
    unsigned char iv[16] = { /* ... */ };
    unsigned char plaintext[] = "Hello, world!";
    size_t plaintext_len = sizeof(plaintext) - 1;
    unsigned char *ciphertext = NULL;
    size_t ciphertext_len = 0;

    // Encrypt
    if (encrypt_data(key, iv, plaintext, plaintext_len, &ciphertext, &ciphertext_len, ECB, CFB_DISABLED) != 0) {
        fprintf(stderr, "Encryption failed\n");
        return -1;
    }

    // Decrypt
    unsigned char *decrypted_text = NULL;
    size_t decrypted_text_len = 0;
    if (decrypt_data(key, iv, ciphertext, ciphertext_len, &decrypted_text, &decrypted_text_len, ECB, CFB_DISABLED) != 0) {
        fprintf(stderr, "Decryption failed\n");
        free(ciphertext);
        return -1;
    }

    // Output decrypted text
    printf("Decrypted text: %s\n", decrypted_text);

    // Clean up
    free(ciphertext);
    free(decrypted_text);
    return 0;
}
