// C library for AES encryption in ECB, CBC, GCM, and optional CFB mode

#include <openssl/evp.h>
#include <openssl/rand.h>
#include <openssl/hmac.h>
#include <openssl/cmac.h>

#define BUFFER_SIZE 1024

int aes_encrypt_ecb(const unsigned char *key, int key_len,
                   const unsigned char *in, unsigned char *out, size_t in_len) {
    EVP_CIPHER_CTX *ctx;
    int len;
    ctx = EVP_CIPHER_CTX_new();
    EVP_EncryptInit_ex(ctx, EVP_aes_256_ecb(), NULL, key, NULL);
    EVP_EncryptUpdate(ctx, out, &len, in, in_len);
    int ciphertext_len = len;
    EVP_EncryptFinal_ex(ctx, out + len, &len);
    ciphertext_len += len;
    EVP_CIPHER_CTX_free(ctx);
    return ciphertext_len;
}

int aes_decrypt_ecb(const unsigned char *key, int key_len,
                   const unsigned char *in, unsigned char *out, size_t in_len) {
    EVP_CIPHER_CTX *ctx;
    int len;
    ctx = EVP_CIPHER_CTX_new();
    EVP_DecryptInit_ex(ctx, EVP_aes_256_ecb(), NULL, key, NULL);
    EVP_DecryptUpdate(ctx, out, &len, in, in_len);
    int plaintext_len = len;
    EVP_DecryptFinal_ex(ctx, out + len, &len);
    plaintext_len += len;
    EVP_CIPHER_CTX_free(ctx);
    return plaintext_len;
}

