<?php

class SessionManager {
    private $encryptionKey;
    private $storage;

    public function __construct($encryptionKey, $storage) {
        $this->encryptionKey = $encryptionKey;
        $this->storage = $storage;
    }

    public function storeSession($userId, $data) {
        $encryptedData = openssl_encrypt(serialize($data), 'aes-256-cbc', $this->encryptionKey);
        $this->storage->store($userId, base64_encode($encryptedData));
    }

    public function retrieveSession($userId) {
        $encodedData = $this->storage->retrieve($userId);
        if ($encodedData === null) return null;
        $data = openssl_decrypt(base64_decode($encodedData), 'aes-256-cbc', $this->encryptionKey);
        return unserialize($data);
    }
}

interface StorageInterface {
    public function store($key, $value);
    public function retrieve($key);
}

class ArrayStorage implements StorageInterface {
    private $storage = [];

    public function store($key, $value) {
        $this->storage[$key] = $value;
    }

    public function retrieve($key) {
        return isset($this->storage[$key]) ? $this->storage[$key] : null;
    }
}

// Usage
$encryptionKey = openssl_random_pseudo_bytes(32);
$storage = new ArrayStorage();
$sessionManager = new SessionManager($encryptionKey, $storage);

$userId = 'user123';
$data = ['username' => 'john_doe', 'email' => 'john@example.com'];
$sessionManager->storeSession($userId, $data);

$retrievedData = $sessionManager->retrieveSession($userId);
print_r($retrievedData);

?>
