EVP_CIPHER* get_cipher_from_string(const char* cipher_name, int key_length) {
    EVP_CIPHER* cipher = NULL;

    if (strcmp(cipher_name, "null") == 0) {
        cipher = EVP_enc_null();
    } else if (strcmp(cipher_name, "des-ecb") == 0) {
        cipher = EVP_des_ecb();
    } else if (strcmp(cipher_name, "des-ede-cbc") == 0) {
        if (key_length == 16) {
            cipher = EVP_des_ede_cbc();
        }
    } else if (strcmp(cipher_name, "des-ede3-cbc") == 0) {
        if (key_length == 24) {
            cipher = EVP_des_ede3_cbc();
        }
    } else if (strcmp(cipher_name, "des-cfb1") == 0) {
        cipher = EVP_des_cfb1();
    } else {
        fprintf(stderr, "Unsupported cipher: %s\n", cipher_name);
        return NULL;
    }

    if (!cipher) {
        fprintf(stderr, "Failed to create cipher for key length %d\n", key_length);
        return NULL;
    }

    return cipher;
}

void initialize_cryptography() {
    OpenSSL_add_all_algorithms();
}

int main(int argc, char* argv[]) {
    initialize_cryptography();

    if (argc != 3) {
        fprintf(stderr, "Usage: %s <cipher_name> <key_length>\n", argv[0]);
        return EXIT_FAILURE;
    }

    const char* cipher_name = argv[1];
    int key_length = atoi(argv[2]);

    EVP_CIPHER* cipher = get_cipher_from_string(cipher_name, key_length);
    if (!cipher) {
        return EXIT_FAILURE;
    }

    // Use the cipher for cryptographic operations...

    EVP_cleanup();
    return EXIT_SUCCESS;
}
