#include <openssl/evp.h>
#include <openssl/rand.h>
#include <openssl/pbkdf2.h>
#include <stdio.h>
#include <stdlib.h>

EVP_CIPHER* get_cipher(const char *mode, int key_size, const char *password) {
    EVP_CIPHER *cipher = NULL;
    if (strcmp(mode, "ECB") == 0) {
        cipher = EVP_des_ecb();
    } else if (strcmp(mode, "EDE") == 0) {
        cipher = EVP_des_ede3_cbc();
    } else if (strcmp(mode, "CFB") == 0) {
        cipher = EVP_des_cfb128();
    }

    if (!cipher) return NULL;

    // Derive key using PBKDF2
    unsigned char *key = (unsigned char *)malloc(key_size);
    if (!key) return NULL;

    int iterations = 10000; // Adjust based on security requirements
    PKCS5_PBKDF2_HMAC(password, strlen(password), NULL, 0, iterations, EVP_sha256(), key_size, key);

    return cipher;
}

void encrypt_data(const EVP_CIPHER *cipher, const unsigned char *key, const unsigned char *iv,
                  const unsigned char *in, unsigned char *out, size_t length) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) return;

    if (1 != EVP_EncryptInit_ex(ctx, cipher, NULL, key, iv)) {
        EVP_CIPHER_CTX_free(ctx);
        return;
    }

    if (1 != EVP_EncryptUpdate(ctx, out, &length, in, length)) {
        EVP_CIPHER_CTX_free(ctx);
        return;
    }

    if (1 != EVP_EncryptFinal_ex(ctx, out + length, &length)) {
        EVP_CIPHER_CTX_free(ctx);
        return;
    }

    EVP_CIPHER_CTX_free(ctx);
}

void decrypt_data(const EVP_CIPHER *cipher, const unsigned char *key, const unsigned char *iv,
                  const unsigned char *in, unsigned char *out, size_t length) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) return;

    if (1 != EVP_DecryptInit_ex(ctx, cipher, NULL, key, iv)) {
        EVP_CIPHER_CTX_free(ctx);
        return;
    }

    if (1 != EVP_DecryptUpdate(ctx, out, &length, in, length)) {
        EVP_CIPHER_CTX_free(ctx);
        return;
    }

    if (1 != EVP_DecryptFinal_ex(ctx, out + length, &length)) {
        EVP_CIPHER_CTX_free(ctx);
        return;
    }

    EVP_CIPHER_CTX_free(ctx);
}

void secure_memory(void *ptr, size_t len) {
    memset(ptr, 0, len);
    free(ptr);
}

// Example usage
int main() {
    const char *mode = "ECB";
    int key_size = DES_KEY_SZ; // DES key size is typically 56 bits or 8 bytes
    const char *password = "mySecretPassword";

    EVP_CIPHER *cipher = get_cipher(mode, key_size, password);
    if (!cipher) {
        fprintf(stderr, "Error getting cipher\n");
        return 1;
    }

    unsigned char iv[DES_BLOCK_SIZE];
    if (RAND_bytes(iv, DES_BLOCK_SIZE) != 1) {
        fprintf(stderr, "Error generating IV\n");
        EVP_CIPHER_free(cipher);
        return 1;
    }

    const unsigned char *in = (const unsigned char *)"Hello, World!";
    size_t in_len = strlen((char *)in);

    unsigned char *out = (unsigned char *)malloc(in_len + EVP_CIPHER_block_size(cipher));
    if (!out) {
        fprintf(stderr, "Error allocating memory for output\n");
        EVP_CIPHER_free(cipher);
        return 1;
    }

    encrypt_data(cipher, in, iv, in, out, in_len);

    unsigned char *decrypted = (unsigned char *)malloc(in_len + EVP_CIPHER_block_size(cipher));
    if (!decrypted) {
        fprintf(stderr, "Error allocating memory for decrypted output\n");
        free(out);
        EVP_CIPHER_free(cipher);
        return 1;
    }

    decrypt_data(cipher, out, iv, out, decrypted, in_len);

    printf("Decrypted: %s\n", decrypted);

    secure_memory(decrypted, in_len + EVP_CIPHER_block_size(cipher));
    secure_memory(out, in_len + EVP_CIPHER_block_size(cipher));
    free(out);
    EVP_CIPHER_free(cipher);

    return 0;
}
