<?php

// Define constants for OAuth2.0 provider configuration
define('OAUTH_PROVIDER_URL', 'https://oauth-provider.com/auth');
define('CLIENT_ID', 'your_client_id');
define('CLIENT_SECRET', 'your_client_secret');

session_start();

function authenticateUser($code) {
    // Exchange code for access token
    $tokenResponse = file_get_contents(OAUTH_PROVIDER_URL . '?grant_type=authorization_code&code=' . urlencode($code) . '&client_id=' . CLIENT_ID . '&client_secret=' . CLIENT_SECRET);
    $tokenData = json_decode($tokenResponse, true);

    // Store access token in session
    $_SESSION['access_token'] = $tokenData['access_token'];

    return $tokenData;
}

function getUserInfo() {
    if (!isset($_SESSION['access_token'])) {
        return null;
    }

    $userInfoResponse = file_get_contents(OAUTH_PROVIDER_URL . '/userinfo?access_token=' . urlencode($_SESSION['access_token']));
    $userInfo = json_decode($userInfoResponse, true);

    return $userInfo;
}

// Example usage
if (isset($_GET['code'])) {
    $authResult = authenticateUser($_GET['code']);
    if ($authResult) {
        echo "Authentication successful. User Info: ";
        print_r(getUserInfo());
    } else {
        echo "Authentication failed.";
    }
} else {
    // Redirect to OAuth2.0 provider for authorization
    header('Location: ' . OAUTH_PROVIDER_URL . '?response_type=code&client_id=' . CLIENT_ID . '&redirect_uri=http://yourdomain.com/auth.php');
    exit;
}
