typedef struct {
    FILE *log_file;
    int log_verbosity;
} LoggingConfig;

void log_event(LoggingConfig *config, const char *original_string, size_t original_size, int slash_added) {
    if (config->log_file && config->log_verbosity > 0) {
        fprintf(config->log_file, "String: %s, Size: %zu, Slash Added: %d\n", original_string, original_size, slash_added);
    }
}

char* append_slash_if_within_limit(const char *input, size_t limit, LoggingConfig *config) {
    if (input == NULL || config == NULL) {
        return NULL;
    }

    size_t input_len = strlen(input);

    if (input_len < limit) {
        char *new_string = malloc(input_len + 2);
        if (new_string == NULL) {
            log_event(config, input, input_len, -1); // Log failure
            return NULL;
        }
        strcpy(new_string, input);
        new_string[input_len] = '/';
        new_string[input_len + 1] = '\0';
        log_event(config, input, input_len, 1); // Log success
        return new_string;
    } else {
        log_event(config, input, input_len, -2); // Log truncation
        return NULL;
    }
}

// Example usage and thread-safe initialization
LoggingConfig global_config;

void init_logging(const char *log_path, int verbosity) {
    global_config.log_file = fopen(log_path, "a");
    if (global_config.log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        exit(EXIT_FAILURE);
    }
    global_config.log_verbosity = verbosity;
}

void cleanup_logging() {
    if (global_config.log_file != NULL) {
        fclose(global_config.log_file);
    }
}

// Thread-safe function for appending a slash
char* thread_safe_append_slash(const char *input, size_t limit) {
    pthread_mutex_lock(&some_mutex); // Assume some_mutex is defined and initialized
    char *result = append_slash_if_within_limit(input, limit, &global_config);
    pthread_mutex_unlock(&some_mutex);
    return result;
}

// Example thread function
void* thread_function(void *arg) {
    const char *input = "ExampleString";
    size_t limit = 20;
    char *new_string = thread_safe_append_slash(input, limit);
    if (new_string != NULL) {
        printf("New string: %s\n", new_string);
        free(new_string);
    }
    return NULL;
}
