#include <openssl/evp.h>
#include <openssl/rand.h>

EVP_CIPHER_CTX* select_cipher(const char* algorithm, int mode, const unsigned char* key, int key_len, const unsigned char* iv) {
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (!ctx) return NULL;

    if (strcmp(algorithm, "AES-256-GCM") == 0 && mode == EVP_ENCRYPT) {
        if (1 != EVP_EncryptInit_ex(ctx, EVP_aes_256_gcm(), NULL, key, iv)) {
            EVP_CIPHER_CTX_free(ctx);
            return NULL;
        }
    } else if (strcmp(algorithm, "AES-256-GCM") == 0 && mode == EVP_DECRYPT) {
        if (1 != EVP_DecryptInit_ex(ctx, EVP_aes_256_gcm(), NULL, key, iv)) {
            EVP_CIPHER_CTX_free(ctx);
            return NULL;
        }
    } else if (strcmp(algorithm, "ChaCha20-Poly1305") == 0 && mode == EVP_ENCRYPT) {
        if (1 != EVP_EncryptInit_ex(ctx, EVP_chacha20_poly1305(), NULL, key, iv)) {
            EVP_CIPHER_CTX_free(ctx);
            return NULL;
        }
    } else if (strcmp(algorithm, "ChaCha20-Poly1305") == 0 && mode == EVP_DECRYPT) {
        if (1 != EVP_DecryptInit_ex(ctx, EVP_chacha20_poly1305(), NULL, key, iv)) {
            EVP_CIPHER_CTX_free(ctx);
            return NULL;
        }
    } else {
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    return ctx;
}
