void process_filenames(const char *filename_list[], int count, int max_modifications) {
    for (int i = 0; i < count && modification_count < max_modifications; i++) {
        if (strlen(filename_list[i]) > MAX_FILENAME_LENGTH) {
            printf("Filename too long: %s\n", filename_list[i]);
            continue;
        }

        pthread_mutex_lock(&lock);
        int index = modification_count++;
        pthread_mutex_unlock(&lock);

        char new_extension[256];
        generate_random_string(new_extension, sizeof(new_extension));
        struct tm *now = localtime(&time(NULL));
        strftime(new_extension, sizeof(new_extension), "_%Y%m%d%H%M%S_%d", now);
        int sequence_number = 1;
        while (modification_count > 0 && strcmp(modifications[modification_count - 1].new_filename, filename_list[i] + new_extension) == 0) {
            sequence_number++;
            strftime(new_extension, sizeof(new_extension), "_%Y%m%d%H%M%S_%d", now);
        }
        snprintf(modifications[index].original_filename, sizeof(modifications[index].original_filename), "%s", filename_list[i]);
        snprintf(modifications[index].new_filename, sizeof(modifications[index].new_filename), "%.*s%s.%s", (int)strlen(filename_list[i]) - strlen(strrchr(filename_list[i], '.')), filename_list[i], new_extension, strrchr(filename_list[i], '.') + 1);
        modifications[index].modification_timestamp = time(NULL);

        if (!is_valid_filename(modifications[index].new_filename)) {
            printf("Invalid new filename: %s\n", modifications[index].new_filename);
            continue;
        }

        int result = rename_file_with_lock(filename_list[i], modifications[index].new_filename);
        if (result != 0) {
            retry_operation(index, 5, 1000); // Retry up to 5 times with a delay of 1 second
        } else {
            log_modification(&modifications[index]);
        }
    }

    export_log_to_server("modification_log.enc");
}

int main() {
    pthread_mutex_init(&lock, NULL);

    const char *filename_list[] = {"file1.txt", "file2.docx", "image.jpg"};
    int count = sizeof(filename_list) / sizeof(filename_list[0]);
    process_filenames(filename_list, count, MAX_MODIFICATIONS_PER_SESSION);

    pthread_mutex_destroy(&lock);
    return 0;
}
