// cryptolib.h
#ifndef CRYPTOLIB_H
#define CRYPTOLIB_H

typedef struct {
    char *name;
    void (*init)(void);
    void (*process_data)(unsigned char *data, size_t length);
    void (*finalize)(unsigned char **output, size_t *output_length);
    void (*cleanup)(void);
} CryptographicOperation;

CryptographicOperation *load_crypto_operation(const char *operation_name);
void unload_crypto_operation(CryptographicOperation *operation);

#endif // CRYPTOLIB_H

// cryptolib.c
#include "cryptolib.h"
#include <stdlib.h>
#include <pthread.h>

static pthread_mutex_t crypto_lock = PTHREAD_MUTEX_INITIALIZER;
static CryptographicOperation *crypto_operations[] = {
    // Initialize list of cryptographic operations
};
static int num_crypto_operations = sizeof(crypto_operations) / sizeof(crypto_operations[0]);

CryptographicOperation *load_crypto_operation(const char *operation_name) {
    for (int i = 0; i < num_crypto_operations; ++i) {
        if (strcmp(crypto_operations[i]->name, operation_name) == 0) {
            pthread_mutex_lock(&crypto_lock);
            crypto_operations[i]->init();
            pthread_mutex_unlock(&crypto_lock);
            return crypto_operations[i];
        }
    }
    return NULL;
}

void unload_crypto_operation(CryptographicOperation *operation) {
    pthread_mutex_lock(&crypto_lock);
    operation->cleanup();
    pthread_mutex_unlock(&crypto_lock);
}

// Example usage
#include <stdio.h>

int main() {
    CryptographicOperation *md5 = load_crypto_operation("MD5");
    if (md5 != NULL) {
        unsigned char output[16];
        size_t output_length;
        md5->process_data((unsigned char *)"Hello, World!", 13);
        md5->finalize(&output, &output_length);
        printf("MD5: ");
        for (size_t i = 0; i < output_length; ++i) {
            printf("%02x", output[i]);
        }
        unload_crypto_operation(md5);
    } else {
        printf("Operation not found.\n");
    }
    return 0;
}
