from threading import Lock

# Define a class to handle file operations with locking
class FileHandler:
    def __init__(self):
        self.lock = Lock()

    def read_file_in_chunks(self, filepath, chunk_size=4096):
        with open(filepath, 'rb') as file:
            while True:
                data = file.read(chunk_size)
                if not data:
                    break
                yield data

# Function to calculate MD5 hash of a large file
def calculate_md5_hash(file_path, progress_callback=None):
    hasher = hashlib.md5()
    file_handler = FileHandler()

    for chunk in file_handler.read_file_in_chunks(file_path):
        hasher.update(chunk)
        if progress_callback:
            progress_callback(file_path, len(chunk))

    return hasher.hexdigest()

# Function to get the current timestamp
def get_timestamp():
    return strftime("%Y-%m-%d %H:%M:%S", time.localtime())

# Function to generate a cryptographically secure random string
