#include <openssl/evp.h>
#include <string.h>
#include <stdlib.h>

#define MAX_BUFFER_SIZE 1024

const char* implementAdvancedCipherAndValidateString(const char* input, int limit, const char* key, int keyLen, const char* iv, int ivLen, const char* mode, int bufferSize) {
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        return "Error: Failed to create cipher context";
    }

    const EVP_CIPHER* cipher;
    if (strcmp(mode, "ECB") == 0) {
        cipher = EVP_des_ede3_ecb();
    } else if (strcmp(mode, "EDE") == 0) {
        cipher = EVP_des_ede_ecb();
    } else if (strcmp(mode, "EDE3") == 0) {
        cipher = EVP_des_ede3_cbc();
    } else if (strcmp(mode, "CFB") == 0) {
        cipher = EVP_des_cfb128();
    } else {
        EVP_CIPHER_CTX_free(ctx);
        return "Error: Invalid mode";
    }

    if (!EVP_EncryptInit_ex(ctx, cipher, NULL, key, iv)) {
        EVP_CIPHER_CTX_free(ctx);
        return "Error: Failed to initialize cipher";
    }

    int inputLen = strlen(input);
    if (inputLen > limit) {
        EVP_CIPHER_CTX_free(ctx);
        return "Error: String exceeds limit";
    }

    char* output = malloc(bufferSize);
    if (!output) {
        EVP_CIPHER_CTX_free(ctx);
        return "Error: Failed to allocate memory for output string";
    }

    int outLen;
    if (!EVP_EncryptUpdate(ctx, (unsigned char*)output, &outLen, (const unsigned char*)input, inputLen)) {
        free(output);
        EVP_CIPHER_CTX_free(ctx);
        return "Error: Encryption failed";
    }

    if (!EVP_EncryptFinal_ex(ctx, (unsigned char*)&output[outLen], &outLen)) {
        free(output);
        EVP_CIPHER_CTX_free(ctx);
        return "Error: Final encryption failed";
    }

    output[outLen] = '\0';

    EVP_CIPHER_CTX_free(ctx);

    return output;
}
