    // Initialize cipher
    EVP_CIPHER *cipher = NULL;
    switch (mode) {
        case ECB: cipher = EVP_des_ecb(); break;
        case EDE: cipher = EVP_des_ede3_cbc(); break; // Note: EDE mode might require a different approach
        case CFB: cipher = EVP_des_cfb128(); break;
    }
    if (!cipher) {
        return NULL;
    }

    // Validate key and IV lengths
    if (EVP_CIPHER_key_length(cipher) != strlen(key) || EVP_CIPHER_iv_length(cipher) != strlen(iv)) {
        return NULL;
    }

    // Process string and validate length
    size_t inputLen = strlen(input);
    char *output = malloc(bufferSize + 1);
    if (!output) {
        return NULL;
    }
    if (inputLen > limit) {
        strcpy(output, "ERROR: String overflow");
    } else {
        if (nullEncrypt) {
            strcpy(output, input);
        } else {
