            for (size_t i = 0; i < inputLen; i++) {
                output[i] = input[i] ^ obfuscateByte;
            }
            output[inputLen] = '\0';
        }

        // Encrypt string
        EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
        if (!ctx) {
            free(output);
            return NULL;
        }
        if (1 != EVP_EncryptInit_ex(ctx, cipher, NULL, (unsigned char *)key, iv)) {
            EVP_CIPHER_CTX_free(ctx);
            free(output);
            return NULL;
        }
        int len;
        if (1 != EVP_EncryptUpdate(ctx, (unsigned char *)(output + inputLen), &len, (unsigned char *)output, inputLen)) {
            EVP_CIPHER_CTX_free(ctx);
            free(output);
            return NULL;
        }
        inputLen += len;
        output[inputLen] = '\0';

        // Apply termination character
        if (inputLen < bufferSize) {
            output[inputLen++] = '@';
        }

        // Log operation
        FILE *logFile = fopen(logFilePath, "a");
        if (logFile) {
            switch (logLevel) {
                case 1: fprintf(logFile, "DEBUG: Mode=%d, Input=%s, Output=%s\n", mode, input, output); break;
                case 2: fprintf(logFile, "INFO: Mode=%d, Input=%s, Output=%s\n", mode, input, output); break;
                case 3: fprintf(logFile, "ERROR: Mode=%d, Input=%s, Output=%s\n", mode, input, output); break;
            }
            fclose(logFile);
        }

        EVP_CIPHER_CTX_free(ctx);
    }

    return (EVP_CIPHER *)output;
