#define MAX_LOG_SIZE 1024

typedef enum {
    DEBUG,
    INFO,
    ERROR
} LogLevel;

typedef struct {
    EVP_CIPHER *cipher;
    unsigned char key[32];
    unsigned char iv[16];
    int bufferSize;
    char logFilePath[MAX_LOG_SIZE];
    LogLevel logLevel;
} EncryptionConfig;

void logMessage(LogLevel level, const char *message) {
    if (level >= config.logLevel) {
        FILE *logFile = fopen(config.logFilePath, "a");
        if (logFile != NULL) {
            fprintf(logFile, "%s: %s\n", level == DEBUG ? "DEBUG" : level == INFO ? "INFO" : "ERROR", message);
            fclose(logFile);
        }
    }
}

int validateKeyAndIV(const unsigned char *key, const unsigned char *iv, int keyLen, int ivLen) {
    if (keyLen < EVP_CIPHER_key_length(config.cipher)) return 0;
    if (ivLen < EVP_CIPHER_iv_length(config.cipher)) return 0;
    return 1;
}

int processStringAndValidateSize(const char *input, int sizeLimit, char **output) {
    int inputLength = strlen(input);
    if (inputLength > sizeLimit) {
        *output = strdup("ERROR: String overflow");
        return -1;
    }
    *output = malloc((inputLength + 2) * sizeof(char));
    strcpy(*output, input);
    (*output)[inputLength] = '\0';
    (*output)[inputLength + 1] = '*'; // Unique termination character
    return 0;
}

void applyObfuscation(char *input, int length) {
    for (int i = 0; i < length; i++) {
        input[i] ^= 0x5A; // Simple XOR obfuscation
    }
}

int encryptString(const char *input, int length, unsigned char **output, int *outputLen) {
    *outputLen = EVP_CIPHER_block_size(config.cipher) * ((length + EVP_CIPHER_block_size(config.cipher) - 1) / EVP_CIPHER_block_size(config.cipher));
    *output = malloc(*outputLen);
    if (!*output) return -1;

    int numBytesWritten;
    EVP_EncryptInit_ex(NULL, config.cipher, NULL, config.key, config.iv);
    EVP_EncryptUpdate(NULL, *output, &numBytesWritten, (unsigned char *)input, length);
    int finalNumBytesWritten;
    EVP_EncryptFinal_ex(NULL, *output + numBytesWritten, &finalNumBytesWritten);
    *outputLen += finalNumBytesWritten;

    return 0;
}

void freeResources(unsigned char *buffer) {
    if (buffer) {
        free(buffer);
    }
}

int implementAdvancedCipherAndValidateString(const char *mode, const unsigned char *key, const unsigned char *iv, int keyLen, int ivLen, const char *input, int sizeLimit, int obfuscate, unsigned char **output, int *outputLen) {
    if (!validateKeyAndIV(key, iv, keyLen, ivLen)) {
        return -1;
    }

    logMessage(INFO, "Validating string and validating size");
    int result = processStringAndValidateSize(input, sizeLimit, (char **)output);
    if (result != 0) {
        return result;
    }

    if (obfuscate) {
        applyObfuscation((char *)*output, strlen((char *)*output));
    }

    logMessage(INFO, "Encrypting string");
    result = encryptString((const char *)*output, strlen((const char *)*output), output, outputLen);
    if (result != 0) {
        freeResources(*output);
        return result;
    }

    logMessage(INFO, "Encryption successful");
    return 0;
}
