#define BLOCK_SIZE 16

// AES-ECB encryption function
void aes_ecb_encrypt(const unsigned char *plaintext, int plaintext_len,
                      const unsigned char *key, unsigned char *ciphertext) {
    EVP_CIPHER_CTX *ctx;
    ctx = EVP_CIPHER_CTX_new();
    EVP_EncryptInit_ex(ctx, EVP_aes_128_ecb(), NULL, key, NULL);
    EVP_EncryptUpdate(ctx, ciphertext, &plaintext_len, plaintext, plaintext_len);
    EVP_EncryptFinal_ex(ctx, ciphertext + plaintext_len, &plaintext_len);
    EVP_CIPHER_CTX_free(ctx);
}

// AES-ECB decryption function
void aes_ecb_decrypt(const unsigned char *ciphertext, int ciphertext_len,
                      const unsigned char *key, unsigned char *decrypted_text) {
    EVP_CIPHER_CTX *ctx;
    ctx = EVP_CIPHER_CTX_new();
    EVP_DecryptInit_ex(ctx, EVP_aes_128_ecb(), NULL, key, NULL);
    EVP_DecryptUpdate(ctx, decrypted_text, &ciphertext_len, ciphertext, ciphertext_len);
    EVP_DecryptFinal_ex(ctx, decrypted_text + ciphertext_len, &ciphertext_len);
    EVP_CIPHER_CTX_free(ctx);
}

// AES-CBC encryption function
void aes_cbc_encrypt(const unsigned char *plaintext, int plaintext_len,
                      const unsigned char *key, const unsigned char *iv,
                      unsigned char *ciphertext) {
    EVP_CIPHER_CTX *ctx;
    ctx = EVP_CIPHER_CTX_new();
    EVP_EncryptInit_ex(ctx, EVP_aes_128_cbc(), NULL, key, iv);
    EVP_EncryptUpdate(ctx, ciphertext, &plaintext_len, plaintext, plaintext_len);
    EVP_EncryptFinal_ex(ctx, ciphertext + plaintext_len, &plaintext_len);
    EVP_CIPHER_CTX_free(ctx);
}

// AES-CBC decryption function
void aes_cbc_decrypt(const unsigned char *ciphertext, int ciphertext_len,
                      const unsigned char *key, const unsigned char *iv,
                      unsigned char *decrypted_text) {
    EVP_CIPHER_CTX *ctx;
    ctx = EVP_CIPHER_CTX_new();
    EVP_DecryptInit_ex(ctx, EVP_aes_128_cbc(), NULL, key, iv);
    EVP_DecryptUpdate(ctx, decrypted_text, &ciphertext_len, ciphertext, ciphertext_len);
    EVP_DecryptFinal_ex(ctx, decrypted_text + ciphertext_len, &ciphertext_len);
    EVP_CIPHER_CTX_free(ctx);
}

// AES-GCM encryption function
void aes_gcm_encrypt(const unsigned char *plaintext, int plaintext_len,
                      const unsigned char *key, const unsigned char *iv,
                      const unsigned char *aad, int aad_len,
                      unsigned char *ciphertext, unsigned char *tag) {
    EVP_CIPHER_CTX *ctx;
    ctx = EVP_CIPHER_CTX_new();
    EVP_EncryptInit_ex(ctx, EVP_aes_128_gcm(), NULL, key, iv);
    EVP_EncryptUpdate(ctx, ciphertext, &plaintext_len, plaintext, plaintext_len);
    EVP_EncryptFinal_ex(ctx, ciphertext + plaintext_len, &plaintext_len, aad, aad_len);
    EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_GET_TAG, BLOCK_SIZE, tag);
    EVP_CIPHER_CTX_free(ctx);
}

// AES-GCM decryption function
void aes_gcm_decrypt(const unsigned char *ciphertext, int ciphertext_len,
                      const unsigned char *tag, const unsigned char *key, const unsigned char *iv,
                      const unsigned char *aad, int aad_len,
                      unsigned char *decrypted_text) {
    EVP_CIPHER_CTX *ctx;
    ctx = EVP_CIPHER_CTX_new();
    EVP_DecryptInit_ex(ctx, EVP_aes_128_gcm(), NULL, key, iv);
    EVP_GCM_AddAuthData(ctx, aad, aad_len);
    EVP_GCM_Finalize_auth_tag(ctx, tag, BLOCK_SIZE);
    int decrypted_text_len;
    EVP_DecryptUpdate(ctx, decrypted_text, &decrypted_text_len, ciphertext, ciphertext_len);
    EVP_CIPHER_CTX_free(ctx);
}

// CFB mode encryption function
void aes_cfb_encrypt(const unsigned char *plaintext, int plaintext_len,
                      const unsigned char *key, const unsigned char *iv,
                      unsigned char *ciphertext) {
    EVP_CIPHER_CTX *ctx;
    ctx = EVP_CIPHER_CTX_new();
    EVP_EncryptInit_ex(ctx, EVP_aes_128_cfb(), NULL, key, iv);
    EVP_EncryptUpdate(ctx, ciphertext, &plaintext_len, plaintext, plaintext_len);
    EVP_EncryptFinal_ex(ctx, ciphertext + plaintext_len, &plaintext_len);
    EVP_CIPHER_CTX_free(ctx);
}

// CFB mode decryption function
void aes_cfb_decrypt(const unsigned char *ciphertext, int ciphertext_len,
                      const unsigned char *key, const unsigned char *iv,
                      unsigned char *decrypted_text) {
    EVP_CIPHER_CTX *ctx;
    ctx = EVP_CIPHER_CTX_new();
    EVP_DecryptInit_ex(ctx, EVP_aes_128_cfb(), NULL, key, iv);
    EVP_DecryptUpdate(ctx, decrypted_text, &ciphertext_len, ciphertext, ciphertext_len);
    EVP_EncryptFinal_ex(ctx, decrypted_text + ciphertext_len, &ciphertext_len);
    EVP_CIPHER_CTX_free(ctx);
}

int main() {
    unsigned char key[16] = {0}; // 128-bit key
    unsigned char iv[BLOCK_SIZE] = {0}; // Initialization vector

    // Example usage of AES-ECB encryption and decryption
    unsigned char plaintext[] = "Hello, World!";
    int plaintext_len = strlen((char *)plaintext);
    unsigned char ciphertext[plaintext_len + BLOCK_SIZE];
    unsigned char decrypted_text[plaintext_len];

    aes_ecb_encrypt(plaintext, plaintext_len, key, ciphertext);
    aes_ecb_decrypt(ciphertext, plaintext_len, key, decrypted_text);

    printf("Decrypted text: %s\n", decrypted_text);

    return 0;
}
