#include <string.h>
#include <stdio.h>
#include <stdlib.h>

typedef struct {
    EVP_CIPHER_CTX *ctx;
    unsigned char *header;
    size_t header_len;
} CipherState;

CipherState* handleComplexDataTransformationAndStorage(const char *mode, const unsigned char *key, size_t key_len, 
                                                      const unsigned char *iv, size_t iv_len,
                                                      const unsigned char *data, size_t data_len, size_t max_size,
                                                      int enable_null_encryption, unsigned char xor_byte) {
    CipherState *state = malloc(sizeof(CipherState));
    state->ctx = EVP_CIPHER_CTX_new();
    if (!state->ctx || !EVP_EncryptInit_ex(state->ctx, EVP_aes_256_cbc(), NULL, key, iv)) {
        free(state);
        return NULL;
    }

    // Validate key and IV lengths based on the mode
    if (strcmp(mode, "CBC") == 0 && key_len != 32 || iv_len != 16) {
        EVP_CIPHER_CTX_free(state->ctx);
        free(state);
        return NULL;
    } else if (strcmp(mode, "GCM") == 0 && key_len != 32 || iv_len != 12) {
        EVP_CIPHER_CTX_free(state->ctx);
        free(state);
        return NULL;
    } else if (strcmp(mode, "CTR") == 0 && key_len != 32 || iv_len != 16) {
        EVP_CIPHER_CTX_free(state->ctx);
        free(state);
        return NULL;
    } else if (strcmp(mode, "OFB") == 0 && key_len != 32 || iv_len != 16) {
        EVP_CIPHER_CTX_free(state->ctx);
        free(state);
        return NULL;
    }

    // Process data and handle encryption
    unsigned char *output = malloc(max_size + state->header_len);
    if (!output) {
        EVP_CIPHER_CTX_free(state->ctx);
        free(state);
        return NULL;
    }

    if (enable_null_encryption) {
        memcpy(output, state->header, state->header_len);
        memcpy(output + state->header_len, data, data_len);
        memcpy(output + state->header_len + data_len, state->header, state->header_len);
    } else {
        EVP_EncryptUpdate(state->ctx, output + state->header_len, &data_len, data, data_len);
        if (data_len > max_size - state->header_len) {
            free(output);
            EVP_CIPHER_CTX_free(state->ctx);
            free(state);
            return NULL;
        }
        memcpy(output, state->header, state->header_len);
        EVP_EncryptFinal_ex(state->ctx, output + state->header_len + data_len, &data_len);
        memcpy(output + state->header_len + data_len, state->header, state->header_len);
    }

    // Apply simple reversible transformation
    for (size_t i = 0; i < data_len * 2 + state->header_len * 2; i++) {
        output[i] ^= xor_byte;
    }

    state->ctx = NULL;
    state->header = NULL;
    return state;
}
