EVP_CIPHER* get_cipher_mode(const char* mode, const unsigned char* key, int key_len) {
    EVP_CIPHER* cipher = NULL;
    if (strcmp(mode, "DES-ECB") == 0) {
        cipher = EVP_des_ecb();
    } else if (strcmp(mode, "DES-EDE") == 0) {
        cipher = EVP_des_ede();
    } else if (strcmp(mode, "DES-EDE3") == 0) {
        cipher = EVP_des_ede3();
    } else if (strcmp(mode, "DES-CFB") == 0) {
        cipher = EVP_des_cfb8();
    } else if (strcmp(mode, "NULL") == 0) {
        // Null encryption mode
        return NULL;
    }

    if (cipher == NULL) {
        fprintf(stderr, "Unsupported cipher mode: %s\n", mode);
        return NULL;
    }

    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (ctx == NULL) {
        fprintf(stderr, "Failed to create cipher context.\n");
        return NULL;
    }

    if (!EVP_EncryptInit_ex(ctx, cipher, NULL, key, NULL)) {
        fprintf(stderr, "Failed to initialize cipher.\n");
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    // Set up the encryption or decryption
    // ...

    // Return the cipher mode context
    return ctx;
}

