#include <openssl/evp.h>
#include <openssl/rand.h>
#include <stdio.h>
#include <stdlib.h>

typedef struct {
    EVP_CIPHER *cipher;
    int key_length;
    int iv_length;
} CipherConfig;

CipherConfig* create_cipher_config(const char* mode, const unsigned char* key, const unsigned char* iv) {
    CipherConfig* config = (CipherConfig*)malloc(sizeof(CipherConfig));
    if (!config) return NULL;

    EVP_CIPHER* cipher = NULL;
    int key_length = 0, iv_length = 0;

    if (strcmp(mode, "ECB") == 0) {
        cipher = EVP_des_ecb();
        key_length = EVP_des_key_length();
        iv_length = 0; // ECB does not use IV
    } else if (strcmp(mode, "EDE") == 0) {
        cipher = EVP_des_ede_cbc();
        key_length = EVP_des_ede_key_length();
        iv_length = EVP_CIPHER_iv_length(cipher);
    } else if (strcmp(mode, "EDE3") == 0) {
        cipher = EVP_des_ede3_cbc();
        key_length = EVP_des_ede3_key_length();
        iv_length = EVP_CIPHER_iv_length(cipher);
    } else if (strcmp(mode, "NULL") == 0) {
        cipher = NULL; // Null encryption mode
        key_length = 0;
        iv_length = 0;
    } else {
        free(config);
        return NULL; // Unsupported mode
    }

    config->cipher = cipher;
    config->key_length = key_length;
    config->iv_length = iv_length;

    if (key && iv) {
        if (EVP_CIPHER_key_length(cipher) != key_length || EVP_CIPHER_iv_length(cipher) != iv_length) {
            free(config);
            return NULL; // Invalid key or IV length
        }
    }

    return config;
}

void encrypt_data(const CipherConfig* config, const unsigned char* input, size_t input_len, unsigned char* output) {
    if (config->cipher == NULL) {
        memcpy(output, input, input_len); // Null encryption mode
        return;
    }

    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        fprintf(stderr, "Failed to create cipher context\n");
        return;
    }

    int len;
    if (1 != EVP_EncryptInit_ex(ctx, config->cipher, NULL, config->key, config->iv)) {
        fprintf(stderr, "Encryption initialization failed\n");
        EVP_CIPHER_CTX_free(ctx);
        return;
    }

    if (1 != EVP_EncryptUpdate(ctx, output, &len, input, input_len)) {
        fprintf(stderr, "Encryption update failed\n");
        EVP_CIPHER_CTX_free(ctx);
        return;
    }
    int final_len;
    if (1 != EVP_EncryptFinal_ex(ctx, output + len, &final_len)) {
        fprintf(stderr, "Encryption finalization failed\n");
        EVP_CIPHER_CTX_free(ctx);
        return;
    }

    *output = len + final_len; // Store the total length of the output
    EVP_CIPHER_CTX_free(ctx);
}

void decrypt_data(const CipherConfig* config, const unsigned char* input, size_t input_len, unsigned char* output) {
    if (config->cipher == NULL) {
        memcpy(output, input, input_len); // Null encryption mode
        return;
    }

    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        fprintf(stderr, "Failed to create cipher context\n");
        return;
    }

    int len;
    if (1 != EVP_DecryptInit_ex(ctx, config->cipher, NULL, config->key, config->iv)) {
        fprintf(stderr, "Decryption initialization failed\n");
        EVP_CIPHER_CTX_free(ctx);
        return;
    }

    if (1 != EVP_DecryptUpdate(ctx, output, &len, input, input_len)) {
        fprintf(stderr, "Decryption update failed\n");
        EVP_CIPHER_CTX_free(ctx);
        return;
    }
    int final_len;
    if (1 != EVP_DecryptFinal_ex(ctx, output + len, &final_len)) {
        fprintf(stderr, "Decryption finalization failed\n");
        EVP_CIPHER_CTX_free(ctx);
        return;
    }

    *output = len + final_len; // Store the total length of the output
    EVP_CIPHER_CTX_free(ctx);
}

void free_cipher_config(CipherConfig* config) {
    free(config);
}
