from typing import List

class DistributedDBMigration:
    def __init__(self, max_workers: int):
        self.max_workers = max_workers
        self.task_queue = queue.Queue()
        self.threads = []

    def add_migration_task(self, task: callable):
        self.task_queue.put(task)

    def start_migrations(self):
        for _ in range(self.max_workers):
            thread = threading.Thread(target=self.worker)
            thread.start()
            self.threads.append(thread)

        for _ in range(len(self.threads)):
            self.task_queue.put(None)  # Signal workers to exit

        for thread in self.threads:
            thread.join()

    def worker(self):
        while True:
            task = self.task_queue.get()
            if task is None:
                break
            try:
                task()
                print(f"Task {task.__name__} completed successfully.")
            except Exception as e:
                print(f"Error in {task.__name__}: {e}")
            finally:
                self.task_queue.task_done()

    def track_migration_history(self):
        # Implement logic to track migration history
        pass

