import java.security.MessageDigest;
import javax.crypto.Cipher;
import javax.crypto.spec.IvParameterSpec;
import javax.crypto.spec.SecretKeySpec;
import java.io.FileWriter;
import java.io.IOException;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

public class BatchProcessor {
    private static final String CONFIG_FILE = "config.properties";
    private static final String LOG_FILE = "encryption.log";

    public Map<String, String> processBatchWithAdvancedEncryptionAndMD5Hashing(List<String> batch, String mode) {
        Config config = loadConfig(CONFIG_FILE);
        Map<String, String> results = new HashMap<>();
        long startTime = System.currentTimeMillis();

        for (String input : batch) {
            if (input == null || input.isEmpty()) {
                System.out.println("Skipping empty or null string");
                continue;
            }

            try {
                String encrypted = encrypt(input, mode, config);
                String md5Hash = computeMD5(encrypted);
                results.put(input, md5Hash);

                log(config, "INFO", "Processed: " + input + " -> Encrypted: " + encrypted + " -> MD5: " + md5Hash);
            } catch (Exception e) {
                log(config, "ERROR", "Failed to process string: " + input, e);
            }
        }

        long endTime = System.currentTimeMillis();
        logPerformanceReport(batch.size(), results.size(), batch.size() - results.size(), endTime - startTime, config);

        return results;
    }

    private Config loadConfig(String configFile) {
        // Load configuration properties from file
        return new Config(/* Load properties */);
    }

    private String encrypt(String input, String mode, Config config) throws Exception {
        byte[] key = config.getEncryptionKey().getBytes();
        byte[] iv = config.getInitializationVector().getBytes();

        Cipher cipher = Cipher.getInstance(mode + "/" + config.getBlockMode() + "/" + config.getPadding());
        SecretKeySpec secretKeySpec = new SecretKeySpec(key, "DES");
        IvParameterSpec ivParameterSpec = new IvParameterSpec(iv);

        if (config.isObfuscationEnabled()) {
            input = obfuscate(input, config.getObfuscationByte());
        }

        cipher.init(Cipher.ENCRYPT_MODE, secretKeySpec, ivParameterSpec);
        byte[] encryptedBytes = cipher.doFinal(input.getBytes());

        return bytesToHex(encryptedBytes);
    }

    private String computeMD5(String input) throws Exception {
        MessageDigest md = MessageDigest.getInstance("MD5");
        byte[] digest = md.digest(input.getBytes());
        return bytesToHex(digest);
    }

    private String obfuscate(String input, byte obfuscationByte) {
        StringBuilder sb = new StringBuilder();
        for (char c : input.toCharArray()) {
            sb.append((char) (c ^ obfuscationByte));
        }
        return sb.toString();
    }

    private String bytesToHex(byte[] bytes) {
        StringBuilder sb = new StringBuilder();
        for (byte b : bytes) {
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }

    private void log(Config config, String level, String message) {
        try (FileWriter writer = new FileWriter(LOG_FILE, true)) {
            writer.write(String.format("[%s] [%s] %s%n", level, System.currentTimeMillis(), message));
        } catch (IOException e) {
            System.err.println("Failed to log: " + message);
        }
    }

    private void log(Config config, String level, String message, Exception e) {
        try (FileWriter writer = new FileWriter(LOG_FILE, true)) {
            writer.write(String.format("[%s] [%s] %s - %s%n", level, System.currentTimeMillis(), message, e.getMessage()));
        } catch (IOException ioe) {
            System.err.println("Failed to log: " + message);
        }
    }

    private void logPerformanceReport(int total, int processed, int skipped, long timeTaken, Config config) {
        // Generate and log performance report
    }

    static class Config {
        // Configuration properties
        String encryptionKey;
        String initializationVector;
        String blockMode;
        String padding;
        boolean obfuscationEnabled;
        byte obfuscationByte;
        String loggerLevel;

        public Config(/* Load properties */) {
            // Initialize configuration from properties
        }

        // Getters for configuration properties
    }
}
