    unsigned int GetRandomSeqNum(bool inclusive, bool exclusive) {
        static std::random_device rd;
        static std::mt19937 gen(rd());
        if (inclusive && exclusive) throw std::invalid_argument("Cannot have both inclusive and exclusive options.");
        unsigned int range = maxSeqNum - minSeqNum;
        if (range == 0) return minSeqNum; // Avoid division by zero
        if (inclusive) {
            std::uniform_int_distribution<> dis(minSeqNum, maxSeqNum);
            return dis(gen);
        } else {
            std::uniform_int_distribution<> dis(minSeqNum, maxSeqNum - 1);
            return dis(gen);
        }
    }

private:
    unsigned int minSeqNum;
    unsigned int maxSeqNum;
};

