using System;
using System.Collections.Generic;
using System.Net.Http;
using System.Threading.Tasks;

public abstract class NetworkHealthMonitor
{
    protected int timeout;
    protected int retryCount;
    private readonly object lockObject = new object();

    public NetworkHealthMonitor(int timeout, int retryCount)
    {
        if (timeout < 0)
            throw new ArgumentException("Timeout cannot be negative");
        if (retryCount < 0)
            throw new ArgumentException("Retry count cannot be negative");

        this.timeout = timeout;
        this.retryCount = retryCount;
    }

    public abstract Task<NetworkStatus> CheckHealthAsync(string endpoint, string protocol);
    public abstract Task<List<PerformanceMetric>> GetPerformanceMetricsAsync();

    protected async Task<HttpResponseMessage> SendRequestAsync(HttpClient client, string url)
    {
        var taskCompletionSource = new TaskCompletionSource<HttpResponseMessage>();
        using (var cancellationSource = new System.Threading.CancellationTokenSource(timeout))
        {
            try
            {
                HttpResponseMessage response = await client.GetAsync(url, HttpCompletionOption.ResponseHeadersRead, cancellationSource.Token);
                taskCompletionSource.SetResult(response);
            }
            catch (TaskCanceledException)
            {
                if (!cancellationSource.IsCancellationRequested)
                    taskCompletionSource.SetException(new TimeoutException("Request timed out"));
                else
                    taskCompletionSource.SetCanceled();
            }
            catch (Exception ex)
            {
                taskCompletionSource.SetException(ex);
            }
        }

        return await taskCompletionSource.Task;
    }

    protected void Log(string message)
    {
        // Implement logging logic here
        Console.WriteLine(message);
    }
}

public class HttpHealthMonitor : NetworkHealthMonitor
{
    public HttpHealthMonitor(int timeout, int retryCount) : base(timeout, retryCount) { }

    public override async Task<NetworkStatus> CheckHealthAsync(string endpoint, string protocol)
    {
        using (var client = new HttpClient())
        {
            for (int i = 0; i <= retryCount; i++)
            {
                HttpResponseMessage response = await SendRequestAsync(client, endpoint);
                if (response.IsSuccessStatusCode)
                    return NetworkStatus.Healthy;
            }
            return NetworkStatus.Unhealthy;
        }
    }

    public override async Task<List<PerformanceMetric>> GetPerformanceMetricsAsync()
    {
        List<PerformanceMetric> metrics = new List<PerformanceMetric>();
        using (var client = new HttpClient())
        {
            for (int i = 0; i <= retryCount; i++)
            {
                var stopwatch = System.Diagnostics.Stopwatch.StartNew();
                HttpResponseMessage response = await SendRequestAsync(client, "http://example.com");
                stopwatch.Stop();

                metrics.Add(new PerformanceMetric
                {
                    Latency = stopwatch.ElapsedMilliseconds,
                    Throughput = response.Content.Headers.ContentLength.HasValue ? response.Content.Headers.ContentLength.Value : 0
                });
            }
        }

        return metrics;
    }
}

public enum NetworkStatus
{
    Healthy,
    Unhealthy
}

public class PerformanceMetric
{
    public long Latency { get; set; }
    public long Throughput { get; set; }
}
