    strncpy(logs[logCount].method, method, sizeof(logs[logCount].method) - 1);
    strncpy(logs[logCount].url, url, sizeof(logs[logCount].url) - 1);
    strncpy(logs[logCount].headers, headers, sizeof(logs[logCount].headers) - 1);
    logs[logCount].bodySize = bodySize;
