        cJSON *firmware_version = cJSON_GetObjectItemCaseSensitive(item, "firmware_version");
        if (cJSON_IsString(firmware_version) && is_valid_firmware_version(firmware_version->valuestring)) {
            config.firmware_version = strdup(firmware_version->valuestring);
        } else {
            const char *new_version = get_newer_version(firmware_version->valuestring);
            if (new_version) {
                fprintf(stderr, "Outdated firmware version %s. Suggested upgrade to %s\n", firmware_version->valuestring, new_version);
                config.firmware_version = strdup(new_version);
            } else {
                continue;
            }
        }

        // Extract and validate status
        cJSON *status = cJSON_GetObjectItemCaseSensitive(item, "status");
        if (cJSON_IsString(status) && is_valid_status(status->valuestring)) {
            config.status = strdup(status->valuestring);
        } else {
            const char *corrected_status = get_corrected_status(status->valuestring);
            if (corrected_status) {
                fprintf(stderr, "Invalid status %s. Corrected to %s\n", status->valuestring, corrected_status);
                config.status = strdup(corrected_status);
            } else {
                continue;
            }
        }

        // Apply transformations based on mode
        apply_transformations(&config, mode);

        configs[(*count)++] = config;
    }

    cJSON_Delete(root);
    return configs;
}

void free_configs(DeviceConfig *configs, int count) {
