#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    char *buffer;
    size_t bufferSize;
    size_t dataLength;
    pthread_mutex_t mutex;
} DataBuffer;

void initBuffer(DataBuffer *buf, size_t initialSize) {
    buf->buffer = (char *)malloc(initialSize);
    if (buf->buffer == NULL) {
        perror("Failed to allocate memory for buffer");
        exit(EXIT_FAILURE);
    }
    buf->bufferSize = initialSize;
    buf->dataLength = 0;
    pthread_mutex_init(&buf->mutex, NULL);
}

void freeBuffer(DataBuffer *buf) {
    pthread_mutex_lock(&buf->mutex);
    free(buf->buffer);
    pthread_mutex_unlock(&buf->mutex);
    pthread_mutex_destroy(&buf->mutex);
}

int appendData(DataBuffer *buf, const char *data, size_t dataSize) {
    pthread_mutex_lock(&buf->mutex);
    if (buf->dataLength + dataSize > buf->bufferSize) {
        size_t newSize = buf->bufferSize + dataSize;
        char *newBuffer = (char *)realloc(buf->buffer, newSize);
        if (newBuffer == NULL) {
            perror("Failed to reallocate memory for buffer");
            pthread_mutex_unlock(&buf->mutex);
            return -1;
        }
        buf->buffer = newBuffer;
        buf->bufferSize = newSize;
    }
    memcpy(buf->buffer + buf->dataLength, data, dataSize);
    buf->dataLength += dataSize;
    pthread_mutex_unlock(&buf->mutex);
    return 0;
}

char* processAndLogString(const char *input, size_t sizeLimit, FILE *logFile, DataBuffer *buf) {
    pthread_mutex_lock(&buf->mutex);
    if (appendData(buf, input, strlen(input)) != 0) {
        pthread_mutex_unlock(&buf->mutex);
        return NULL;
    }
    pthread_mutex_unlock(&buf->mutex);

    char *result = (char *)malloc(sizeLimit + 2); // +1 for '/' and +1 for '\0'
    if (result == NULL) {
        perror("Failed to allocate memory for result");
        return NULL;
    }

    if (strlen(input) <= sizeLimit) {
        snprintf(result, sizeLimit + 2, "%s/", input);
    } else {
        free(result);
        return NULL;
    }

    pthread_mutex_lock(&buf->mutex);
    appendData(buf, "/", 1);
    pthread_mutex_unlock(&buf->mutex);

    fprintf(logFile, "Processed string: %s (original size: %zu, added slash: %d)\n", result, strlen(input), strlen(result) > sizeLimit);
    return result;
}
