typedef struct State {
    int id;
    struct State *next;
} State;

typedef struct FSA {
    // Define the structure of your FSA here
    // ...
} FSA;

State* create_state_list(int *states, int num_states, FSA *fsa, int last_state, int max_capacity, int clear_existing) {
    if (states == NULL || fsa == NULL || max_capacity <= 0) {
        return NULL;
    }

    State *new_state_list = NULL;
    State **tail_ptr = &new_state_list;

    for (int i = 0; i < num_states && new_state_list != NULL && (clear_existing || *tail_ptr != NULL); ++i) {
        if (!clear_existing && *tail_ptr == NULL) {
            break;
        }

        State *new_state = (State *)malloc(sizeof(State));
        if (new_state == NULL) {
            return new_state_list;
        }

        new_state->id = states[i];
        new_state->next = NULL;

        if (*tail_ptr != NULL) {
            (*tail_ptr)->next = new_state;
        }
        *tail_ptr = new_state;
    }

    if (last_state >= 0 && last_state < num_states) {
        State *current = new_state_list;
        for (int i = 0; current != NULL && i < last_state; ++i) {
            current = current->next;
        }
        if (current != NULL) {
            current->next = new_state_list;
        }
    }

    return new_state_list;
}

