#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define SESSION_EXPIRATION_TIME 3600

typedef struct {
    char *token;
    time_t expiration_time;
    pthread_mutex_t lock;
} Session;

Session* create_session(const char *user_id) {
    Session *session = (Session*)malloc(sizeof(Session));
    session->token = strdup(user_id);
    session->expiration_time = time(NULL) + SESSION_EXPIRATION_TIME;
    pthread_mutex_init(&session->lock, NULL);
    return session;
}

void destroy_session(Session *session) {
    free(session->token);
    pthread_mutex_destroy(&session->lock);
    free(session);
}

int validate_session(const char *user_id, Session *session) {
    if (strcmp(user_id, session->token)) {
        return 0; // Invalid user ID
    }
    if (time(NULL) > session->expiration_time) {
        return 0; // Session expired
    }
    return 1; // Valid session
}

int encrypt_data(const unsigned char *plaintext, size_t plaintext_len,
                  const unsigned char *key, size_t key_len,
                  const EVP_CIPHER *cipher, unsigned char **ciphertext,
                  size_t *ciphertext_len) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) return -1;

    if (1 != EVP_EncryptInit_ex(ctx, cipher, NULL, key, NULL)) {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }

    *ciphertext_len = EVP_CIPHER_block_size(cipher) * ((plaintext_len / EVP_CIPHER_block_size(cipher)) + 1);
    *ciphertext = (unsigned char*)malloc(*ciphertext_len);

    if (!*ciphertext) {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }

    int len;
    if (1 != EVP_EncryptUpdate(ctx, *ciphertext, &len, plaintext, plaintext_len)) {
        free(*ciphertext);
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }
    size_t ciphertext_len_out = len;

    if (1 != EVP_EncryptFinal_ex(ctx, *ciphertext + len, &len)) {
        free(*ciphertext);
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }
    ciphertext_len_out += len;

    *ciphertext_len = ciphertext_len_out;
    EVP_CIPHER_CTX_free(ctx);
    return 0;
}

int decrypt_data(const unsigned char *ciphertext, size_t ciphertext_len,
                  const unsigned char *key, size_t key_len,
                  const EVP_CIPHER *cipher, unsigned char **plaintext,
                  size_t *plaintext_len) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) return -1;

    if (1 != EVP_DecryptInit_ex(ctx, cipher, NULL, key, NULL)) {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }

    *plaintext_len = ciphertext_len;
    *plaintext = (unsigned char*)malloc(*plaintext_len);

    if (!*plaintext) {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }

    int len;
    if (1 != EVP_DecryptUpdate(ctx, *plaintext, &len, ciphertext, ciphertext_len)) {
        free(*plaintext);
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }
    size_t plaintext_len_out = len;

    if (1 != EVP_DecryptFinal_ex(ctx, *plaintext + len, &len)) {
        free(*plaintext);
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }
    plaintext_len_out += len;

    *plaintext_len = plaintext_len_out;
    EVP_CIPHER_CTX_free(ctx);
    return 0;
}

// Additional functions for handling concurrent requests, load balancing, caching, etc. would be implemented here
