#include <string.h>
#include <pthread.h>
#include <time.h>

typedef struct http_log_entry {
    int request_id;
    char method[10];
    char url[256];
    char headers[1024];
    size_t body_size;
    time_t start_time;
    time_t end_time;
    int status_code;
} http_log_entry;

typedef struct dynamic_list {
    http_log_entry **entries;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
} dynamic_list;

dynamic_list *create_dynamic_list() {
    dynamic_list *list = (dynamic_list *)malloc(sizeof(dynamic_list));
    list->entries = NULL;
    list->size = 0;
    list->capacity = 0;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void add_log_entry(dynamic_list *list, http_log_entry *entry) {
    pthread_mutex_lock(&list->lock);
    if (list->size == list->capacity) {
        size_t new_capacity = (list->capacity == 0) ? 1 : list->capacity * 2;
        http_log_entry **new_entries = (http_log_entry **)realloc(list->entries, new_capacity * sizeof(http_log_entry *));
        if (!new_entries) {
            fprintf(stderr, "Memory allocation failed\n");
            return;
        }
        list->entries = new_entries;
        list->capacity = new_capacity;
    }
    list->entries[list->size++] = entry;
    pthread_mutex_unlock(&list->lock);
}

void destroy_dynamic_list(dynamic_list *list) {
    pthread_mutex_lock(&list->lock);
    for (size_t i = 0; i < list->size; ++i) {
        free(list->entries[i]);
    }
    free(list->entries);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int main() {
    dynamic_list *log_list = create_dynamic_list();

    // Example usage
    http_log_entry *entry = (http_log_entry *)malloc(sizeof(http_log_entry));
    entry->request_id = 1;
    strcpy(entry->method, "GET");
    strcpy(entry->url, "https://example.com/api/data");
    strcpy(entry->headers, "User-Agent: ExampleClient/1.0");
    entry->body_size = 0;
    time(&entry->start_time);
    time(&entry->end_time);
    entry->status_code = 200;

    add_log_entry(log_list, entry);

    destroy_dynamic_list(log_list);
    return 0;
}
