    time_t last_interaction;
} HTTPRequest;

typedef struct {
    HTTPRequest** requests;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} RequestQueue;

void init_request_queue(RequestQueue* queue, size_t initial_capacity) {
    queue->requests = (HTTPRequest**)malloc(initial_capacity * sizeof(HTTPRequest*));
    if (!queue->requests) {
        perror("Failed to allocate memory for request queue");
        exit(EXIT_FAILURE);
    }
    queue->count = 0;
    queue->capacity = initial_capacity;
    pthread_mutex_init(&queue->lock, NULL);
}

void enqueue_request(RequestQueue* queue, HTTPRequest* request) {
    pthread_mutex_lock(&queue->lock);
    if (queue->count == queue->capacity) {
        queue->capacity *= 2;
        queue->requests = realloc(queue->requests, queue->capacity * sizeof(HTTPRequest*));
        if (!queue->requests) {
            perror("Failed to reallocate memory for request queue");
            exit(EXIT_FAILURE);
        }
    }
    queue->requests[queue->count++] = request;
    pthread_mutex_unlock(&queue->lock);
}

HTTPRequest* dequeue_request(RequestQueue* queue) {
    pthread_mutex_lock(&queue->lock);
    if (queue->count == 0) {
        pthread_mutex_unlock(&queue->lock);
        return NULL;
    }
    HTTPRequest* request = queue->requests[0];
    for (size_t i = 1; i < queue->count; i++) {
        queue->requests[i - 1] = queue->requests[i];
    }
    queue->count--;
    pthread_mutex_unlock(&queue->lock);
    return request;
}

void destroy_request_queue(RequestQueue* queue) {
    free(queue->requests);
    pthread_mutex_destroy(&queue->lock);
}

void log_error(const char* condition, ...) {
    if (condition && *condition != '\0') {
        va_list args;
        va_start(args, condition);
        vfprintf(stderr, "Error: ", args);
        va_end(args);
    }
}

int main() {
    RequestQueue queue;
    init_request_queue(&queue, 10);

    // Simulate adding requests
    HTTPRequest request1 = { .request_id = 1, .payload_size = 1024, .priority = 5, .urgency = 3 };
    enqueue_request(&queue, &request1);

    // Simulate processing requests
    HTTPRequest* processed_request = dequeue_request(&queue);
    if (processed_request) {
        printf("Processed request ID: %d\n", processed_request->request_id);
        free(processed_request); // Assuming dynamically allocated memory for demonstration purposes
    }

    destroy_request_queue(&queue);

    log_error("Condition met");

    return 0;
}
```

This code provides a basic structure for managing a dynamic list of HTTP requests with thread safety and basic logging capabilities. It uses mutexes to ensure that the request queue operations are performed safely in a multi-threaded environment. The `log_error` function demonstrates how to use `snprintf` and `va_start/va_end` to format and log error messages. Note that this is a simplified example, and additional features such as dynamic segment limits, priority thresholds, backend server management, asynchronous I/O operations, and cache optimization would need to be added for a complete implementation.']

