#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

// Define a structure for LTE UE context information
typedef struct {
    int rnti;
    int rsrp;
    int rsrq;
    // Other metadata and transport channels
} LteUeContext;

// Define a structure for the dynamic list of UE contexts
typedef struct ListNode {
    LteUeContext *context;
    struct ListNode *next;
} ListNode;

// Global variables for managing the context list and synchronization
ListNode *head = NULL;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
time_t lastPruneTime = 0;
int pruneInterval = 3600; // Prune every hour

// Function to allocate memory safely and handle errors
void* safe_malloc(size_t size) {
    void *ptr = malloc(size);
    if (ptr == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    return ptr;
}

// Function to add a new LTE UE context to the list
void addUeContext(int rnti, int rsrp, int rsrq) {
    pthread_mutex_lock(&mutex);
    ListNode *newNode = safe_malloc(sizeof(ListNode));
    newNode->context = safe_malloc(sizeof(LteUeContext));
    newNode->context->rnti = rnti;
    newNode->context->rsrp = rsrp;
    newNode->context->rsrq = rsrq;
    newNode->next = head;
    head = newNode;
    pthread_mutex_unlock(&mutex);
}

// Function to remove an LTE UE context from the list
void removeUeContext(int rnti) {
    pthread_mutex_lock(&mutex);
    ListNode *current = head;
    ListNode *previous = NULL;

    while (current != NULL) {
        if (current->context->rnti == rnti) {
            if (previous == NULL) {
                head = current->next;
            } else {
                previous->next = current->next;
            }
            free(current->context);
            free(current);
            break;
        }
        previous = current;
        current = current->next;
    }
    pthread_mutex_unlock(&mutex);
}

// Function to prune inactive contexts from the list
void pruneInactiveContexts() {
    time_t now = time(NULL);

    if (now - lastPruneTime > pruneInterval) {
        pthread_mutex_lock(&mutex);
        ListNode *current = head;
        ListNode *previous = NULL;

        while (current != NULL) {
            // Check for pruning criteria here
            if (/* Pruning condition */) {
                ListNode *temp = current;
                current = current->next;

                free(temp->context);
                free(temp);

                if (previous == NULL) {
                    head = current;
                } else {
                    previous->next = current;
                }
            } else {
                previous = current;
                current = current->next;
            }
        }

        lastPruneTime = now;
        pthread_mutex_unlock(&mutex);
    }
}

// Function to update the signal quality metrics of an LTE UE context
void updateUeContext(int rnti, int rsrp, int rsrq) {
    pthread_mutex_lock(&mutex);
    ListNode *current = head;

    while (current != NULL) {
        if (current->context->rnti == rnti) {
            current->context->rsrp = rsrp;
            current->context->rsrq = rsrq;
            break;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&mutex);
}

// Function to log the health and performance of the context list
void logContextList() {
    pthread_mutex_lock(&mutex);
    ListNode *current = head;
    int activeCount = 0;

    while (current != NULL) {
        // Log each context here
        printf("RNTI: %d, RSRP: %d, RSRQ: %d\n", current->context->rnti, current->context->rsrp, current->context->rsrq);
        activeCount++;
        current = current->next;
    }

    // Log summary information
    printf("Active contexts: %d\n", activeCount);
    pthread_mutex_unlock(&mutex);
}

// Thread function to periodically prune inactive contexts
void* pruneThread(void *arg) {
    while (1) {
        pruneInactiveContexts();
        sleep(60); // Prune every minute
    }
    return NULL;
}

int main() {
    // Initialize the pruning thread
    pthread_t prune_tid;
    pthread_create(&prune_tid, NULL, pruneThread, NULL);

    // Example usage of the functions
    addUeContext(12345, -90, -15);
    updateUeContext(12345, -85, -10);
    removeUeContext(12345);

    logContextList();

    pthread_join(prune_tid, NULL);

    return 0;
}
