        free(list->contexts[i]);
    }
    free(list->contexts);
    list->count = 0;
    list->capacity = 0;
    pthread_mutex_destroy(&list->lock);
}

void add_LTE_UE_Context(LTE_UE_List* list, LTE_UE_Context* context) {
    pthread_mutex_lock(&list->lock);
    if (list->count >= list->capacity) {
        size_t new_capacity = list->capacity == 0 ? 1 : list->capacity * 2;
        LTE_UE_Context** new_contexts = realloc(list->contexts, new_capacity * sizeof(LTE_UE_Context*));
        if (!new_contexts) {
            pthread_mutex_unlock(&list->lock);
            return; // Handle memory allocation failure
        }
        list->contexts = new_contexts;
        list->capacity = new_capacity;
    }
    list->contexts[list->count++] = context;
