    int status = getaddrinfo(hostname, NULL, NULL, (struct addrinfo**)&ip);
    if (status != 0) {
        fprintf(stderr, "DNS resolution failed: %s\n", gai_strerror(status));
        return NULL;
    }

    // Rate limiting and concurrency management
    static size_t requestCount = 0;
    const size_t maxRequests = 10; // Example limit
    while (requestCount >= maxRequests) {
        // Wait or sleep until the rate limit is reset
    }
    requestCount++;

    // Encryption Initialization
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        fprintf(stderr, "Failed to create cipher context\n");
        return NULL;
    }

    const EVP_CIPHER* cipherType;
    switch (cipherMode) {
        case 1: cipherType = EVP_ecb_cipher(); break; // ECB
        case 2: cipherType = EVP_cbc_cipher(); break; // EDE
        case 3: cipherType = EVP_ede3_cipher(); break; // EDE3
        case 4: cipherType = EVP_cfb_cipher(); break; // CFB
        default:
            fprintf(stderr, "Invalid cipher mode\n");
            EVP_CIPHER_CTX_free(ctx);
            return NULL;
    }

    if (1 != EVP_EncryptInit_ex(ctx, cipherType, NULL, NULL, NULL)) {
        fprintf(stderr, "Error initializing encryption\n");
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    // Process input string
    char* inputString = "your_input_string_here";
    size_t inputLength = strlen(inputString);
    if (inputLength > sizeLimit) {
        printf("String length exceeds limit\n");
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }
    char outputBuffer[inputLength + 1];
    strncpy(outputBuffer, inputString, inputLength);
    outputBuffer[inputLength] = '/';

    // Encryption
    int len;
    if (1 != EVP_EncryptUpdate(ctx, (unsigned char*)outputBuffer, &len, (const unsigned char*)outputBuffer, strlen(outputBuffer))) {
        fprintf(stderr, "Error during encryption\n");
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }
    int finalLen;
    if (1 != EVP_EncryptFinal_ex(ctx, outputBuffer + len, &finalLen)) {
        fprintf(stderr, "Error during finalization of encryption\n");
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    // Return the resolved IP address and encrypted string
    u_char* result = malloc(sizeof(struct in_addr) + strlen(outputBuffer));
    if (!result) {
        fprintf(stderr, "Memory allocation failed\n");
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }
    memcpy(result, &ip.sin_addr, sizeof(struct in_addr));
    strcpy((char*)(result + sizeof(struct in_addr)), outputBuffer);

    EVP_CIPHER_CTX_free(ctx);
    return result;
}
