// Define the structure for LTE UE context information
typedef struct {
    uint16_t rnti;
    int rsrp;
    int rsrq;
    // List of DL-TCH with CRC indication status
} LteUeContext;

// Structure to manage dynamic list of UE contexts in a thread-safe manner
typedef struct {
    pthread_mutex_t lock;
    LteUeContext** ue_list;
    size_t capacity;
    size_t size;
} UeContextManager;

// Function to initialize the UE context manager
void init_ue_context_manager(UeContextManager* manager, size_t initial_capacity) {
    manager->capacity = initial_capacity;
    manager->size = 0;
    pthread_mutex_init(&manager->lock, NULL);
    manager->ue_list = (LteUeContext**)malloc(initial_capacity * sizeof(LteUeContext*));
}

// Function to add a new UE context
void add_ue_context(UeContextManager* manager, LteUeContext* ue_context) {
    pthread_mutex_lock(&manager->lock);
    if (manager->size >= manager->capacity) {
        // Resize the list if necessary
        manager->capacity *= 2;
        manager->ue_list = (LteUeContext**)realloc(manager->ue_list, manager->capacity * sizeof(LteUeContext*));
    }
    manager->ue_list[manager->size++] = ue_context;
    pthread_mutex_unlock(&manager->lock);
}

// Function to remove an UE context based on RNTI
void remove_ue_context(UeContextManager* manager, uint16_t rnti) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->size; ++i) {
        if (manager->ue_list[i]->rnti == rnti) {
            // Free the memory and shift elements
            free(manager->ue_list[i]);
            for (size_t j = i; j < manager->size - 1; ++j) {
                manager->ue_list[j] = manager->ue_list[j + 1];
            }
            --manager->size;
            break;
        }
    }
    pthread_mutex_unlock(&manager->lock);
}

// Function to prune inactive UE contexts based on thresholds
void prune_inactive_ues(UeContextManager* manager, int rsrp_threshold, int rsrq_threshold) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->size;) {
        if (manager->ue_list[i]->rsrp < rsrp_threshold || manager->ue_list[i]->rsrq < rsrq_threshold) {
            // Free the memory and shift elements
            free(manager->ue_list[i]);
            for (size_t j = i; j < manager->size - 1; ++j) {
                manager->ue_list[j] = manager->ue_list[j + 1];
            }
            --manager->size;
        } else {
            ++i;
        }
    }
    pthread_mutex_unlock(&manager->lock);
}

// Function to destroy the UE context manager
void destroy_ue_context_manager(UeContextManager* manager) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->size; ++i) {
        free(manager->ue_list[i]);
    }
    free(manager->ue_list);
    pthread_mutex_destroy(&manager->lock);
}
```

