    if (resolve_dns(hostname, result->ip_address) != 0) {
        free(result);
        return NULL;
    }
    strcpy(result->hostname, hostname);

    pthread_mutex_lock(&lock);
    query_count++;
    last_query_time = time(NULL);
    pthread_mutex_unlock(&lock);

    return result;
}

int analyze_bible_text(const char *text, BibleTextAnalysis *analysis) {
    regex_t reg_book[39];
    const char *book_names[39] = {"Genesis", "Exodus", "Leviticus", ..., "Malachi"};
    int book_counts[39] = {0};

    // Compile regex patterns for each book
    for (int i = 0; i < 39; i++) {
        if (regcomp(&reg_book[i], book_names[i], REG_EXTENDED) != 0) {
            return -1;
        }
    }

    // Loop through the text and match books
    char *token = strtok(text, " ,.;:!");
    while (token != NULL) {
        for (int i = 0; i < 39; i++) {
            if (regexec(&reg_book[i], token, 0, NULL, 0) == 0) {
                book_counts[i]++;
            }
        }
        token = strtok(NULL, " ,.;:!");
    }

    // Free regex patterns
    for (int i = 0; i < 39; i++) {
        regfree(&reg_book[i]);
    }

    analysis->text = strdup(text);
    memcpy(analysis->book_counts, book_counts, sizeof(book_counts));

    return 0;
}

void* dns_thread_func(void *arg) {
    char **hostname_list = (char **)arg;
    DnsResult *results[MAX_CONCURRENT_QUERIES];

    for (int i = 0; i < MAX_CONCURRENT_QUERIES && hostname_list[i] != NULL; i++) {
        results[i] = perform_dns_resolution(hostname_list[i]);
    }

    // Process and log results
    for (int i = 0; i < MAX_CONCURRENT_QUERIES && hostname_list[i] != NULL; i++) {
        if (results[i] != NULL) {
            printf("Hostname: %s, IP Address: %d.%d.%d.%d\n",
                   results[i]->hostname, results[i]->ip_address[0],
                   results[i]->ip_address[1], results[i]->ip_address[2],
                   results[i]->ip_address[3]);
            free(results[i]);
        }
    }

    return NULL;
}

int main() {
    char *hostnames[] = {"example.com", "google.com", ..., NULL};
    pthread_t threads[MAX_CONCURRENT_QUERIES];

    for (int i = 0; i < MAX_CONCURRENT_QUERIES && hostnames[i] != NULL; i++) {
        if (pthread_create(&threads[i], NULL, dns_thread_func, hostnames) != 0) {
            fprintf(stderr, "Failed to create thread\n");
            return 1;
        }
    }

    for (int i = 0; i < MAX_CONCURRENT_QUERIES && hostnames[i] != NULL; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
