    int cache_size;
    char **recent_queries;
    pthread_mutex_t mutex;
} DNS_RESOLVER;

typedef struct DNS_REGISTRY {
    DNS_RESOLVER resolvers[MAX_RESOLVERS];
    pthread_mutex_t registry_mutex;
} DNS_REGISTRY;

DNS_REGISTRY *dns_registry_init() {
    DNS_REGISTRY *registry = malloc(sizeof(DNS_REGISTRY));
    if (!registry) {
        perror("Failed to allocate memory for DNS registry");
        return NULL;
    }
    pthread_mutex_init(&registry->registry_mutex, NULL);
    return registry;
}

DNS_QUERY* create_dns_query(const char *type) {
    DNS_QUERY *query = malloc(sizeof(DNS_QUERY));
    if (!query) {
        perror("Failed to allocate memory for DNS query");
        return NULL;
    }
    // Initialize the query based on type
    return query;
}

void dns_registry_add(DNS_REGISTRY *registry, int sid, int timeout, int cache_size) {
    pthread_mutex_lock(&registry->registry_mutex);
    for (int i = 0; i < MAX_RESOLVERS; i++) {
        if (!registry->resolvers[i].sid) {
            registry->resolvers[i].sid = sid;
            registry->resolvers[i].timeout = timeout;
            registry->resolvers[i].cache_size = cache_size;
            pthread_mutex_init(&registry->resolvers[i].mutex, NULL);
            registry->resolvers[i].recent_queries = malloc(sizeof(char *) * cache_size);
            if (!registry->resolvers[i].recent_queries) {
                perror("Failed to allocate memory for recent queries");
                pthread_mutex_unlock(&registry->registry_mutex);
                return;
            }
            break;
        }
    }
    pthread_mutex_unlock(&registry->registry_mutex);
}

// Add more functions as per the requirements

int main() {
    DNS_REGISTRY *registry = dns_registry_init();
    if (!registry) {
        return 1;
    }

    dns_registry_add(registry, 1, DEFAULT_TIMEOUT, DEFAULT_CACHE_SIZE);

    // Use other functions to manipulate and query the DNS registry

    dns_registry_free(registry);
    return 0;
}
