#define RATE_LIMIT_INTERVAL 60
#define DNS_CACHE_DURATION 3600

typedef struct {
    const char *hostname;
    size_t size_limit;
    int cipher_mode;
    bool dns_caching;
} Config;

typedef struct {
    struct in_addr ip;
    time_t last_resolved;
} DnsCacheEntry;

DnsCacheEntry dns_cache[MAX_DNS_REQUESTS];
int dns_cache_size = 0;
time_t last_rate_limit_reset = 0;
int failed_dns_requests = 0;

EVP_CIPHER *get_cipher_from_mode(int mode) {
    switch (mode) {
        case 1: return EVP_aes_128_ecb();
        case 2: return EVP_aes_128_cbc();
        case 3: return EVP_aes_192_cbc();
        case 4: return EVP_aes_256_cbc();
        default: return NULL;
    }
}

const char* dnsAndEncryptionHandler(const char *hostname, size_t size_limit, int cipher_mode, bool dns_caching) {
    Config config = {hostname, size_limit, cipher_mode, dns_caching};

    if (failed_dns_requests >= MAX_DNS_REQUESTS) {
        printf("Too many failed DNS requests. Denial-of-service detected.\n");
        return NULL;
    }

    struct in_addr resolved_ip;
    bool cache_hit = false;

    // Check DNS cache
    if (dns_caching) {
        for (int i = 0; i < dns_cache_size; i++) {
            if (strcmp(dns_cache[i].ip.s_addr, resolved_ip.s_addr) == 0) {
                if (time(NULL) - dns_cache[i].last_resolved <= DNS_CACHE_DURATION) {
                    cache_hit = true;
                    break;
                }
            }
        }
    }

    // Perform DNS resolution
    if (!cache_hit) {
        int status = getaddrinfo(hostname, NULL, NULL, &res);
        if (status != 0) {
            failed_dns_requests++;
            printf("Failed to resolve hostname: %s\n", gai_strerror(status));
            return NULL;
        }
        resolved_ip.s_addr = ((struct sockaddr_in *)res->ai_addr)->sin_addr.s_addr;

        // Cache the result
        if (dns_cache_size < MAX_DNS_REQUESTS) {
            dns_cache[dns_cache_size].ip.s_addr = resolved_ip.s_addr;
            dns_cache[dns_cache_size].last_resolved = time(NULL);
            dns_cache_size++;
        }
    }

    // Limit rate of DNS requests
    if (time(NULL) - last_rate_limit_reset < RATE_LIMIT_INTERVAL) {
        failed_dns_requests++;
        printf("Rate limit exceeded. Please try again later.\n");
        return NULL;
    } else {
        last_rate_limit_reset = time(NULL);
        failed_dns_requests = 0;
    }

    // Initialize encryption
    EVP_CIPHER *cipher = get_cipher_from_mode(cipher_mode);
    if (cipher == NULL) {
        printf("Unsupported cipher mode.\n");
        return NULL;
    }

    // Check and append slash if within size limit
    char *result = malloc(strlen(hostname) + 2);
    if (strlen(hostname) < size_limit) {
        snprintf(result, size_limit + 1, "%s/", hostname);
    } else {
        free(result);
        return NULL;
    }

    return result;
}
