    int query_length;
    DNS_QUERY_TYPE type;
    pthread_mutex_t lock;
} DNS_QUERY;

DNS_QUERY* create_dns_query(const char* query_string, DNS_QUERY_TYPE type) {
    if (strlen(query_string) > MAX_QUERY_LENGTH - 1) {
        return NULL; // Query string too long
    }
    DNS_QUERY* dns_query = (DNS_QUERY*)malloc(sizeof(DNS_QUERY));
    if (!dns_query) {
        return NULL; // Memory allocation failed
    }
    dns_query->query_string = strdup(query_string);
    dns_query->query_length = strlen(query_string);
    dns_query->type = type;
    pthread_mutex_init(&dns_query->lock, NULL);
    return dns_query;
}

void free_dns_query(DNS_QUERY* dns_query) {
    if (dns_query) {
        free(dns_query->query_string);
        pthread_mutex_destroy(&dns_query->lock);
        free(dns_query);
    }
}
