use std::env;
use tokio::task;

struct NFAPI_CRC_INDICATION_PDU_T {
    rx_ue_information_tag: u32,
    rnti: u16,
    crc_indication_rel8_tag: CRC_INDICATION_REL8_TAG,
}

struct CRC_INDICATION_REL8_TAG {
    crcflag: bool,
}

fn generate_pdu_list(n: usize) -> Vec<NFAPI_CRC_INDICATION_PDU_T> {
    let mut pdu_list = Vec::new();
    for _ in 0..n {
        let rx_ue_information_tag = rand::random();
        let rnti = rand::random();
        let crcflag = rand::random();
        let pdu = NFAPI_CRC_INDICATION_PDU_T {
            rx_ue_information_tag,
            rnti,
            crc_indication_rel8_tag: CRC_INDICATION_REL8_TAG { crcflag },
        };
        pdu_list.push(pdu);
    }
    pdu_list
}

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    let args: Vec<String> = env::args().collect();
    if args.len() != 2 {
        eprintln!("Usage: {} <number_of_pdus>", args[0]);
        return Ok(());
    }

    let n = args[1].parse::<usize>()?;
    let pdu_list = generate_pdu_list(n);

    for pdu in pdu_list {
        task::spawn(async move {
            // Simulate asynchronous handling of each PDU
            println!("Processing PDU with RNTI: {}, CRCFLAG: {}", pdu.rnti, pdu.crc_indication_rel8_tag.crcflag);
        });
    }

    Ok(())
}
