    int status;

    // Rate limiting check
    if (gettimeofday(&limiter->last_query_time, NULL) == -1) {
        return NULL; // Error getting current time
    }
    if (limiter->query_count >= MAX_DNS_QUERIES_PER_SEC) {
        if (difftime(limiter->last_query_time.tv_sec, limiter->last_query_time.tv_sec) < 1.0) {
            return NULL; // Rate limit exceeded
        }
        limiter->query_count = 0;
    }

    memset(&hints, 0, sizeof hints);
    hints.ai_family = AF_UNSPEC; // IPv4 and IPv6
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        fprintf(stderr, "getaddrinfo error: %s\n", gai_strerror(status));
        return NULL;
    }

    for (p = res; p != NULL; p = p->ai_next) {
        void* addr;
        char ipstr[INET6_ADDRSTRLEN];

        if (p->ai_family == AF_INET) { // IPv4
            struct sockaddr_in *ipv4 = (struct sockaddr_in *)p->ai_addr;
            addr = &(ipv4->sin_addr);
        } else { // IPv6
            struct sockaddr_in6 *ipv6 = (struct sockaddr_in6 *)p->ai_addr;
            addr = &(ipv6->sin6_addr);
        }

        inet_ntop(p->ai_family, addr, ipstr, sizeof ipstr);

        if (inet_pton(p->ai_family, ipstr, ip) != 1) {
            continue; // Invalid IP address
        }

        limiter->last_query_time = p->ai_next ? p->ai_next->ai_addr : p->ai_addr;
        limiter->query_count++;
        freeaddrinfo(res);
        return ip;
    }

    freeaddrinfo(res);
    return NULL; // No valid addresses found
}

int main() {
    DNSRateLimiter limiter = {0};
    u_char* ip;

    ip = resolve_hostname("www.example.com", &limiter);
    if (ip) {
        printf("IP Address: %.*s\n", p->ai_addrlen, (char*)ip);
    } else {
        printf("Failed to resolve hostname.\n");
    }

    return 0;
}
