use tokio::sync::{mpsc, Semaphore};
use rand::Rng;
use std::collections::HashMap;
use std::time::{Duration, Instant};

#[derive(Debug)]
struct NFAPI_CRC_INDICATION_PDU_T {
    rx_ue_information_tag: String,
    rnti: u32,
    crc_indication_rel8_tag: CRCIndicationRel8Tag,
}

#[derive(Debug)]
enum CRCIndicationRel8Tag {
    Valid(bool),
}

async fn generate_structure(
    ue_info_source: &UEInfoSource,
    semaphore: &Semaphore,
) -> Result<NFAPI_CRC_INDICATION_PDU_T, String> {
    let _permit = semaphore.acquire().await.map_err(|_| "Failed to acquire semaphore")?;

    // Simulate fetching UE information from an external source
    let ue_info = ue_info_source.fetch_ue_info().await.map_err(|e| format!("UE info fetch failed: {}", e))?;

    let rnti = rand::thread_rng().gen_range(1..=1000);
    let crcflag = rand::thread_rng().gen();
    Ok(NFAPI_CRC_INDICATION_PDU_T {
        rx_ue_information_tag: ue_info,
        rnti,
        crc_indication_rel8_tag: CRCIndicationRel8Tag::Valid(crcflag),
    })
}

async fn run_mode_a(
    num_structures: usize,
    time_window: Duration,
) -> Result<(), String> {
    let semaphore = Semaphore::new(10); // Limit concurrency
    let ue_info_source = UEInfoSource::new();

    let start_time = Instant::now();
    let mut generated_count = 0;

    while generated_count < num_structures && start_time.elapsed() < time_window {
        if generate_structure(&ue_info_source, &semaphore).await.is_ok() {
            generated_count += 1;
        }
    }

    Ok(())
}

async fn run_mode_b(
    request_receiver: mpsc::Receiver<()>,
    semaphore: Semaphore,
) -> Result<(), String> {
    let ue_info_source = UEInfoSource::new();

    while let Some(_) = request_receiver.recv().await {
        if generate_structure(&ue_info_source, &semaphore).await.is_err() {
            return Err("Failed to generate structure".to_string());
        }
    }

    Ok(())
}

async fn run_mode_c(
    rate: f64,
) -> Result<(), String> {
    let semaphore = Semaphore::new(10); // Limit concurrency
    let ue_info_source = UEInfoSource::new();

    let delay = Duration::from_secs_f64(1.0 / rate);
    loop {
        if generate_structure(&ue_info_source, &semaphore).await.is_err() {
            return Err("Failed to generate structure".to_string());
        }
        tokio::time::sleep(delay).await;
    }
}

struct UEInfoSource;

impl UEInfoSource {
    fn new() -> Self {
        UEInfoSource
    }

    async fn fetch_ue_info(&self) -> Result<String, String> {
        // Simulate fetching data from an external source
        Ok("ue_info".to_string())
    }
}

#[tokio::main]
async fn main() -> Result<(), String> {
    let args: Vec<String> = std::env::args().collect();

    if args.len() < 2 {
        return Err("Missing mode argument".to_string());
    }

    match &args[1] as &str {
        "A" => {
            if args.len() < 4 {
                return Err("Mode A requires num_structures and time_window arguments".to_string());
            }
            let num_structures = args[2].parse::<usize>().map_err(|_| "Invalid number of structures")?;
            let time_window: Duration = args[3]
                .parse()
                .map_err(|_| "Invalid time window format")?;
            run_mode_a(num_structures, time_window).await
        }
        "B" => {
            if args.len() < 2 {
                return Err("Mode B requires request_receiver argument".to_string());
            }
            let (request_sender, request_receiver) = mpsc::channel(32);
            // Simulate sending requests to the receiver
            tokio::spawn(async move {
                for _ in 0..10 {
                    request_sender.send(()).await.unwrap();
                    tokio::time::sleep(Duration::from_secs(1)).await;
                }
            });
            run_mode_b(request_receiver, Semaphore::new(10)).await
        }
        "C" => {
            if args.len() < 2 {
                return Err("Mode C requires rate argument".to_string());
            }
            let rate = args[2]
                .parse::<f64>()
                .map_err(|_| "Invalid rate format")?;
            run_mode_c(rate).await
        }
        _ => Err("Invalid mode".to_string()),
    }
}
