#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_PDUS 1024

typedef struct {
    // LTE UE CONTEXT structure
} LTE_UE_CONTEXT;

typedef struct {
    // LYRASIG_TAG structure
    unsigned int sync_seq;
} LYRASIG_TAG;

typedef struct {
    LTE_UE_CONTEXT *ue_context;
    LYRASIG_TAG tag;
} LYRASIG_PDU_T;

LYRASIG_PDU_T pdus[MAX_PDUS];
pthread_mutex_t pdus_lock;
int pdu_count = 0;

void initialize_pdus(int num_pdus) {
    if (num_pdus > MAX_PDUS) {
        fprintf(stderr, "Error: Exceeds maximum number of PDUs\n");
        return;
    }

    srand(time(NULL));
    pthread_mutex_init(&pdus_lock, NULL);

    for (int i = 0; i < num_pdus; i++) {
        pdus[i].ue_context = malloc(sizeof(LTE_UE_CONTEXT));
        if (!pdus[i].ue_context) {
            fprintf(stderr, "Error: Failed to allocate memory for UE context\n");
            return;
        }

        pdus[i].tag.sync_seq = rand();
    }

    pdu_count = num_pdus;
}

void cleanup_pdus() {
    pthread_mutex_lock(&pdus_lock);
    for (int i = 0; i < pdu_count; i++) {
        free(pdus[i].ue_context);
    }
    pthread_mutex_unlock(&pdus_lock);

    pthread_mutex_destroy(&pdus_lock);
}

void *process_pdu(void *arg) {
    int index = *(int *)arg;
    if (index >= pdu_count) {
        fprintf(stderr, "Error: Invalid PDU index\n");
        return NULL;
    }

    pthread_mutex_lock(&pdus_lock);
    // Process the PDU
    printf("Processing PDU %d with sync seq: %u\n", index, pdus[index].tag.sync_seq);
    pthread_mutex_unlock(&pdus_lock);

    free(arg);
    return NULL;
}

int main() {
    int num_pdus = 5;

    initialize_pdus(num_pdus);

    pthread_t threads[num_pdus];
    for (int i = 0; i < num_pdus; i++) {
        int *arg = malloc(sizeof(int));
        if (!arg) {
            fprintf(stderr, "Error: Failed to allocate memory for thread arg\n");
            cleanup_pdus();
            return 1;
        }
        *arg = i;

        if (pthread_create(&threads[i], NULL, process_pdu, arg)) {
            fprintf(stderr, "Error: Failed to create thread\n");
            free(arg);
            cleanup_pdus();
            return 1;
        }
    }

    for (int i = 0; i < num_pdus; i++) {
        pthread_join(threads[i], NULL);
    }

    cleanup_pdus();

    return 0;
}
```

