void* create_and_populate_pdus(void* arg) {
    int num_pdus = *(int*)arg;
    NFAPI_CRC_INDICATION_PDU_T* pdus = (NFAPI_CRC_INDICATION_PDU_T*)malloc(num_pdus * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!pdus) {
        perror("Failed to allocate memory for PDUs");
        pthread_exit(NULL);
    }

    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_cond_t cond = PTHREAD_COND_INITIALIZER;
    int pdus_created = 0;

    for (int i = 0; i < num_pdus; ++i) {
        pdus[i].rx_ue_info_tag = rand();
        pdus[i].rnti = rand() % 1024;
        pdus[i].crc_indication_rel8_tag = (rand() % 2);

        pthread_mutex_lock(&mutex);
        while (pdus_created >= MAX_PDUS) {
            pthread_cond_wait(&cond, &mutex);
        }
        pdus_created++;
        pthread_mutex_unlock(&mutex);
    }

    // Simulate processing of PDUs
    for (int i = 0; i < num_pdus; ++i) {
        printf("Processed PDU %d: RX_UE_INFO_TAG=%u, RNTI=%u, CRC_INDICATION_REL8_TAG=%u\n",
               i, pdus[i].rx_ue_info_tag, pdus[i].rnti, pdus[i].crc_indication_rel8_tag);
    }

    free(pdus);
    pthread_exit(NULL);
}

int main() {
    int num_pdus = 5000;
    pthread_t thread_id;

    if (pthread_create(&thread_id, NULL, create_and_populate_pdus, &num_pdus) != 0) {
        perror("Failed to create thread");
        return EXIT_FAILURE;
    }

    pthread_join(thread_id, NULL);
    printf("All PDUs processed.\n");

    return EXIT_SUCCESS;
}
