#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct LTE_RRC_CU_Transmission_Config_Dedicated_TN {
    int cellID;
    // Transport Channel parameters
    int tcParam1;
    int tcParam2;
    // RRC message tags
    char* rrcTags[10];
} LTE_RRC_CU_Transmission_Config_Dedicated_TN;

typedef struct ListNode {
    LTE_RRC_CU_Transmission_Config_Dedicated_TN config;
    struct ListNode* next;
} ListNode;

typedef struct TCConfigList {
    pthread_mutex_t mutex;
    ListNode* head;
    ListNode* tail;
    size_t count;
} TCConfigList;

void initTCConfigList(TCConfigList* list) {
    pthread_mutex_init(&list->mutex, NULL);
    list->head = NULL;
    list->tail = NULL;
    list->count = 0;
}

void addTCConfig(TCConfigList* list, LTE_RRC_CU_Transmission_Config_Dedicated_TN config) {
    ListNode* newNode = (ListNode*)malloc(sizeof(ListNode));
    if (newNode == NULL) {
        perror("Failed to allocate memory for new TC config");
        return;
    }
    newNode->config = config;
    newNode->next = NULL;

    pthread_mutex_lock(&list->mutex);
    if (list->head == NULL) {
        list->head = newNode;
    } else {
        list->tail->next = newNode;
    }
    list->tail = newNode;
    list->count++;
    pthread_mutex_unlock(&list->mutex);
}

void removeTCConfig(TCConfigList* list, int cellID) {
    pthread_mutex_lock(&list->mutex);
    ListNode* current = list->head;
    ListNode* previous = NULL;

    while (current != NULL) {
        if (current->config.cellID == cellID) {
            if (previous == NULL) {
                list->head = current->next;
            } else {
                previous->next = current->next;
            }
            if (current->next == NULL) {
                list->tail = previous;
            }
            free(current);
            list->count--;
            break;
        }
        previous = current;
        current = current->next;
    }
    pthread_mutex_unlock(&list->mutex);
}

void printTCConfigList(TCConfigList* list) {
    pthread_mutex_lock(&list->mutex);
    ListNode* current = list->head;
    while (current != NULL) {
        printf("Cell ID: %d, TC Param1: %d, TC Param2: %d\n", 
               current->config.cellID, 
               current->config.tcParam1, 
               current->config.tcParam2);
        current = current->next;
    }
    pthread_mutex_unlock(&list->mutex);
}

void destroyTCConfigList(TCConfigList* list) {
    pthread_mutex_lock(&list->mutex);
    ListNode* current = list->head;
    while (current != NULL) {
        ListNode* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_unlock(&list->mutex);
    pthread_mutex_destroy(&list->mutex);
}
