import java.util.*;
import java.io.*;

public class WordProcessor {

    public static int countDuplicateWords(List<String> words) {
        try {
            Set<String> uniqueWords = new HashSet<>();
            Set<String> duplicateWords = new HashSet<>();

            for (String word : words) {
                String normalizedWord = normalize(word);
                if (!uniqueWords.add(normalizedWord)) {
                    duplicateWords.add(normalizedWord);
                }
            }

            return duplicateWords.size();
        } catch (Exception e) {
            System.err.println("An error occurred: " + e.getMessage());
            return -1;
        }
    }

    private static String normalize(String word) throws IOException {
        return new BufferedReader(new StringReader(word))
               .lines()
               .map(String::trim)
               .collect(Collectors.joining(" "));
    }
}
