void destroy_dynamic_list(LTE_RRC_CU_Transmission_Config_Dynamic_List* list) {
    if (list == NULL) {
        return;
    }
    free(list->configurations);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int add_configuration(LTE_RRC_CU_Transmission_Config_Dynamic_List* list, LTE_RRC_CU_Transmission_Config_Dedicated_TN config) {
    pthread_mutex_lock(&list->lock);
    if (list->count >= list->capacity) {
        size_t new_capacity = list->capacity == 0 ? 1 : list->capacity * 2;
        LTE_RRC_CU_Transmission_Config_Dedicated_TN* new_configurations = realloc(list->configurations, new_capacity * sizeof(LTE_RRC_CU_Transmission_Config_Dedicated_TN));
        if (new_configurations == NULL) {
            pthread_mutex_unlock(&list->lock);
            return -1;
        }
        list->configurations = new_configurations;
        list->capacity = new_capacity;
    }
    list->configurations[list->count++] = config;
    pthread_mutex_unlock(&list->lock);
    return 0;
}

LTE_RRC_CU_Transmission_Config_Dedicated_TN* get_configuration(LTE_RRC_CU_Transmission_Config_Dynamic_List* list, int cell_id) {
    pthread_mutex_lock(&list->lock);
    for (size_t i = 0; i < list->count; ++i) {
        if (list->configurations[i].cell_id == cell_id) {
            pthread_mutex_unlock(&list->lock);
            return &list->configurations[i];
        }
    }
    pthread_mutex_unlock(&list->lock);
    return NULL;
}
