#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/socket.h>
#include <arpa/inet.h>
#include <unistd.h>

// Function to perform DNS resolution for a given hostname
int resolve_dns(const char *hostname, u_char *ip_address, int timeout) {
    struct addrinfo hints, *res, *p;
    int status;

    memset(&hints, 0, sizeof hints);
    hints.ai_family = AF_UNSPEC; // Use IPv4 or IPv6, whichever is available
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        fprintf(stderr, "getaddrinfo error: %s\n", gai_strerror(status));
        return -1;
    }

    for (p = res; p != NULL; p = p->ai_next) {
        void *addr;
        char ipstr[INET6_ADDRSTRLEN];

        if (p->ai_family == AF_INET) { // IPv4
            struct sockaddr_in *ipv4 = (struct sockaddr_in *)p->ai_addr;
            addr = &(ipv4->sin_addr);
        } else { // IPv6
            struct sockaddr_in6 *ipv6 = (struct sockaddr_in6 *)p->ai_addr;
            addr = &(ipv6->sin6_addr);
        }

        inet_ntop(p->ai_family, addr, ipstr, sizeof ipstr);

        // Copy the IP address to the output buffer
        memcpy(ip_address, ipstr, INET_ADDRSTRLEN);
    }

    freeaddrinfo(res);
    return 0;
}

int main() {
    u_char ip_address[INET_ADDRSTRLEN];
    const char *hostname = "example.com";
    int timeout = 5; // Timeout in seconds

    if (resolve_dns(hostname, ip_address, timeout) == 0) {
        printf("Resolved IP address: %s\n", ip_address);
    } else {
        printf("Failed to resolve DNS for %s\n", hostname);
    }

    return 0;
}
```

