#include <libmemcached/memcached.h>

#define SESSION_EXPIRY_TIME 3600 // 1 hour in seconds

typedef struct {
    char *user_id;
    time_t expiration_time;
    memcached_st *memcache_client;
} Session;

Session* create_session(char *user_id) {
    Session *session = (Session*)malloc(sizeof(Session));
    session->user_id = strdup(user_id);
    session->expiration_time = time(NULL) + SESSION_EXPIRY_TIME;
    session->memcache_client = memcached_create(NULL);
    return session;
}

void update_session(Session *session, char *key, char *value) {
    memcached_return_t rc = memcached_set(session->memcache_client, key, strlen(key), value, strlen(value), 0, session->expiration_time);
    if (rc != MEMCACHED_SUCCESS) {
        fprintf(stderr, "Failed to update session: %s\n", memcached_strerror(session->memcache_client, rc));
    }
}

char* get_session_data(Session *session, char *key) {
    size_t value_length;
    uint32_t flags;
    char *value = memcached_get(session->memcache_client, key, strlen(key), &value_length, &flags, NULL);
    if (value == NULL) {
        fprintf(stderr, "Failed to get session data: %s\n", memcached_strerror(session->memcache_client, memcached_last_error(session->memcache_client)));
        return NULL;
    }
    char *data = strdup(value);
    free(value);
    return data;
}

void destroy_session(Session *session) {
    memcached_free(session->memcache_client);
    free(session->user_id);
    free(session);
}
