import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.context.annotation.Bean;
import reactor.core.publisher.Flux;

@SpringBootApplication
public class DataProcessingApplication {

    public static void main(String[] args) {
        SpringApplication.run(DataProcessingApplication.class, args);
    }

    @Bean
    public Flux<String> dataStream() {
        // Simulate a stream of JSON documents from an external REST API
        return Flux.interval(Duration.ofSeconds(1))
                   .map(sequence -> "{ \"id\": " + sequence + ", \"value\": \"" + UUID.randomUUID().toString() + "\" }");
    }

    @Bean
    public DataProcessor dataProcessor(@Value("${mode}") String mode) {
        switch (mode) {
            case "A":
                return new FastProcessingDataProcessor();
            case "B":
                return new OnDemandProcessingDataProcessor();
            case "C":
                return new ContinuousStreamingDataProcessor();
            default:
                throw new IllegalArgumentException("Invalid mode: " + mode);
        }
    }

    @Bean
    public ErrorHandling errorHandling() {
        return new ErrorHandling();
    }

    // Define operational modes as separate classes implementing a common interface
    interface DataProcessor {
        void process(Flux<String> dataStream);
    }

    static class FastProcessingDataProcessor implements DataProcessor {
        @Override
        public void process(Flux<String> dataStream) {
            dataStream.subscribe(data -> System.out.println("Processed document: " + data));
        }
    }

    static class OnDemandProcessingDataProcessor implements DataProcessor {
        private final Scheduler scheduler = Schedulers.boundedElastic();

        @Override
        public void process(Flux<String> dataStream) {
            dataStream.publishOn(scheduler)
                       .subscribe(data -> System.out.println("Processed document: " + data));
        }
    }

    static class ContinuousStreamingDataProcessor implements DataProcessor {
        private final Scheduler scheduler = Schedulers.boundedElastic();

        @Override
        public void process(Flux<String> dataStream) {
            dataStream.publishOn(scheduler)
                       .flatMap(data -> Mono.fromCallable(() -> {
                           // Simulate document processing time
                           Thread.sleep(10);
                           return data;
                       }))
                       .subscribe(System.out::println);
        }
    }

    // Define error handling class
    static class ErrorHandling {
        @EventListener(ApplicationRunner.class)
        public void handleErrors(ConfigurableApplicationContext context) {
            context.getEnvironment().getPropertySources()
                   .forEach(ps -> ps.getPropertyNames()
                                     .filter(name -> name.startsWith("error"))
                                     .forEach(name -> System.err.println("Error occurred: " + ps.getProperty(name))));
        }
    }

    // Define Spring Boot properties
    @Value("${mode}")
    private String mode;

    @Value("${api.url}")
    private String apiUrl;
}
```

