#include <openssl/rand.h>

#define MAX_INPUT_SIZE 1024

int read_integers(int **array, int *count) {
    char line[MAX_INPUT_SIZE];
    if (!fgets(line, sizeof(line), stdin)) {
        return -1;
    }
    char *token = strtok(line, " ");
    while (token != NULL && *count < MAX_INPUT_SIZE) {
        (*array)[(*count)++] = atoi(token);
        token = strtok(NULL, " ");
    }
    return 0;
}

void print_largest_integer(int *array, int count) {
    if (count == 0) {
        printf("Array is empty.\n");
        return;
    }
    int largest = array[0];
    for (int i = 1; i < count; i++) {
        if (array[i] > largest) {
            largest = array[i];
        }
    }
    printf("Largest integer: %d\n", largest);
}

EVP_CIPHER *get_cipher(int enable_encryption, int cipher_mode) {
    EVP_CIPHER *cipher;
    switch (cipher_mode) {
        case 0: cipher = EVP_des_ecb(); break;
        case 1: cipher = EVP_des_ede3_cbc(); break;
        case 2: cipher = EVP_des_cfb8(); break;
        default: return NULL; // Null encryption mode
    }
    if (!enable_encryption) {
        return NULL;
    }
    return cipher;
}

void encrypt_decrypt(int *array, int count, EVP_CIPHER *cipher, unsigned char *key, unsigned char *iv) {
    if (cipher == NULL) {
        return;
    }
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    EVP_EncryptInit_ex(ctx, cipher, NULL, key, iv);
    for (int i = 0; i < count; i++) {
        int len;
        int ciphertext_len;
        EVP_EncryptUpdate(ctx, array + i, &len, array + i, sizeof(int));
        ciphertext_len = len;
        EVP_EncryptFinal_ex(ctx, array + i, &len);
        ciphertext_len += len;
    }
    EVP_CIPHER_CTX_free(ctx);
}

int main() {
    int *array = (int *)malloc(MAX_INPUT_SIZE * sizeof(int));
    if (!array) {
        fprintf(stderr, "Memory allocation failed.\n");
        return 1;
    }

    int count;
    if (read_integers(&array, &count) != 0) {
        fprintf(stderr, "Failed to read integers from input.\n");
        free(array);
        return 1;
    }

    print_largest_integer(array, count);

    unsigned char key[EVP_MAX_KEY_LENGTH];
    unsigned char iv[EVP_MAX_IV_LENGTH];
    if (!RAND_bytes(key, sizeof(key)) || !RAND_bytes(iv, sizeof(iv))) {
        fprintf(stderr, "Failed to generate random bytes for key and IV.\n");
        free(array);
        return 1;
    }

    int enable_encryption = 1; // Change this to disable encryption
    int cipher_mode = 0; // Change this to select different cipher modes

    EVP_CIPHER *cipher = get_cipher(enable_encryption, cipher_mode);
    if (cipher != NULL) {
        encrypt_decrypt(array, count, cipher, key, iv);
    }

    free(array);
    return 0;
}
