// Helper functions for finding the largest and smallest numbers
float findLargest(float* arr, int size) {
    float max = -FLT_MAX;
    for (int i = 0; i < size; i++) {
        if (arr[i] > max) {
            max = arr[i];
        }
    }
    return max;
}

float findSmallest(float* arr, int size) {
    float min = FLT_MAX;
    for (int i = 0; i < size; i++) {
        if (arr[i] < min) {
            min = arr[i];
        }
    }
    return min;
}

// Function to calculate the mean of an array
float calculateMean(float* arr, int size) {
    float sum = 0.0;
    for (int i = 0; i < size; i++) {
        sum += arr[i];
    }
    return sum / size;
}

// Function to calculate the median of an array
float calculateMedian(float* arr, int size) {
    qsort(arr, size, sizeof(float), (int (*)(const void *, const void *))compare);
    if (size % 2 == 0) {
        return (arr[size / 2 - 1] + arr[size / 2]) / 2;
    } else {
        return arr[size / 2];
    }
}

// Function to calculate the mode of an array
float calculateMode(float* arr, int size) {
    float maxFreq = 0.0;
    float mode = -1.0;
    for (int i = 0; i < size; i++) {
        int freq = 1;
        for (int j = i + 1; j < size; j++) {
            if (arr[i] == arr[j]) {
                freq++;
            }
        }
        if (freq > maxFreq) {
            maxFreq = freq;
            mode = arr[i];
        }
    }
    return mode;
}

// Main function to handle the task
float* processTransactions(bool enableStats) {
    int size = 0;
    float *transactions = (float*)malloc(1024 * sizeof(float));

    // Read transactions from standard input
    while (scanf("%f", &transactions[size]) == 1 && size < 1024) {
        if (transactions[size] <= 0.0) break;
        size++;
    }

    if (size == 0 || !enableStats) {
        free(transactions);
        return NULL;
    }

    float mean = calculateMean(transactions, size);
    float median = calculateMedian(transactions, size);
    float mode = calculateMode(transactions, size);
    float largest = findLargest(transactions, size);
    float smallest = findSmallest(transactions, size);
    float maxWeightedSum = 0.0; // Assuming transaction ID is not provided in input
    int maxWeightedSumID = -1;

    free(transactions);

    float* result = (float*)malloc(8 * sizeof(float));
    result[0] = mean;
    result[1] = median;
    result[2] = mode;
    result[3] = largest;
    result[4] = smallest;
    result[5] = maxWeightedSum;
    result[6] = maxWeightedSumID;

    return result;
}

int main() {
    bool enableStats;
    printf("Enable statistical processing? (true/false): ");
    scanf("%d", &enableStats);

    float* stats = processTransactions(enableStats);

    if (stats != NULL) {
        printf("Mean: %f\n", stats[0]);
        printf("Median: %f\n", stats[1]);
        printf("Mode: %f\n", stats[2]);
        printf("Largest: %f\n", stats[3]);
        printf("Smallest: %f\n", stats[4]);
        printf("Max Weighted Sum: %f\n", stats[5]);
        printf("Max Weighted Sum ID: %d\n", (int)stats[6]);
    } else {
        printf("No statistical processing enabled.\n");
    }

    free(stats);
    return 0;
}
