import os
import glob
import hashlib
from concurrent.futures import ThreadPoolExecutor, as_completed
import time
import tarfile
import gzip
import zstd

def collect_logs(config):
    logs = set()
    for directory in config['log_directories']:
        for file_path in glob.glob(os.path.join(directory, '*.log')):
            if not is_file_being_updated(file_path) and is_file_complete(file_path):
                hash_value = calculate_hash(file_path)
                if hash_value not in logs:
                    logs.add(hash_value)
                    yield file_path

def compress_logs(logs, algorithm='gzip', num_threads=4):
    compression_map = {'gzip': gzip.compress, 'zstd': zstd.compress}
    with ThreadPoolExecutor(max_workers=num_threads) as executor:
        futures = {executor.submit(compression_map[algorithm], open(log, 'rb').read()): log for log in logs}
        for future in as_completed(futures):
            try:
                compressed_data = future.result()
                yield compressed_data
            except Exception as e:
                print(f"Error compressing file: {e}")

def archive_logs(compressed_logs, output_path):
    with tarfile.open(output_path, 'w:bz2') as tar:
        for compressed_log in compressed_logs:
            tarinfo = tarfile.TarInfo(name='log')
            tarinfo.size = len(compressed_log)
            tar.addfile(tarinfo, compressed_log)

def processAndArchiveLogs(config):
    logs = collect_logs(config)
    compressed_logs = compress_logs(logs, config.get('compression_algorithm', 'gzip'), config['num_threads'])
    archive_logs(compressed_logs, config['output_path'])

# Example usage
config = {
    'log_directories': ['/var/log/app1', '/var/log/app2'],
    'compression_algorithm': 'zstd',
    'num_threads': 8,
    'output_path': '/archive/logs.tar.bz2'
}
processAndArchiveLogs(config)
```

