xmlNode* parseXMLAndFindElement(const char* xmlContent, const char* elementName) {
    if (xmlContent == NULL || *xmlContent == '\0') {
        // Handle error: null or empty XML content
        return NULL;
    }

    xmlDocPtr doc = xmlReadMemory(xmlContent, strlen(xmlContent), "noname.xml", NULL, 0);
    if (!doc) {
        // Handle error: failed to parse XML
        return NULL;
    }

    xmlNode* rootElement = xmlDocGetRootElement(doc);
    if (!rootElement) {
        // Handle error: no root element found in XML
        xmlFreeDoc(doc);
        return NULL;
    }

    xmlXPathContextPtr xpathCtx = xmlXPathNewContext(doc);
    if (!xpathCtx) {
        // Handle error: failed to create XPath context
        xmlFreeDoc(doc);
        return NULL;
    }

    char xpathQuery[256];
    snprintf(xpathQuery, sizeof(xpathQuery), "/%s", elementName);

    xmlXPathObjectPtr xpathObj = xmlXPathEvalExpression(BAD_CAST xpathQuery, xpathCtx);
    if (!xpathObj) {
        // Handle error: failed to evaluate XPath expression
        xmlXPathFreeContext(xpathCtx);
        xmlFreeDoc(doc);
        return NULL;
    }

    if (xmlXPathVariableLookup(xpathCtx, BAD_CAST "result") != 1) {
        // Handle error: no matching elements found or multiple matches
        xmlXPathFreeObject(xpathObj);
        xmlXPathFreeContext(xpathCtx);
        xmlFreeDoc(doc);
        return NULL;
    }

    xmlNode* firstElement = xpathObj->nodesetval->nodeTab[0];
    xmlXPathFreeObject(xpathObj);
    xmlXPathFreeContext(xpathCtx);
    xmlFreeDoc(doc);

    return firstElement;
}

