#include <openssl/evp.h>
#include <openssl/rand.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

EVP_CIPHER_CTX *encrypt_file(const char *file_path, const unsigned char *key, const EVP_CIPHER *cipher) {
    FILE *in_file = fopen(file_path, "rb");
    if (!in_file) {
        perror("Error opening file for reading");
        return NULL;
    }

    size_t file_size = 0;
    fseek(in_file, 0, SEEK_END);
    file_size = ftell(in_file);
    fseek(in_file, 0, SEEK_SET);

    unsigned char *buffer = (unsigned char *)malloc(file_size + EVP_CIPHER_block_size(cipher));
    if (!buffer) {
        perror("Error allocating memory for buffer");
        fclose(in_file);
        return NULL;
    }

    size_t bytes_read = fread(buffer, 1, file_size, in_file);
    if (bytes_read != file_size) {
        perror("Error reading file");
        free(buffer);
        fclose(in_file);
        return NULL;
    }
    fclose(in_file);

    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        perror("Error creating cipher context");
        free(buffer);
        return NULL;
    }

    if (1 != EVP_EncryptInit_ex(ctx, cipher, NULL, key, NULL)) {
        perror("Error initializing encryption");
        EVP_CIPHER_CTX_free(ctx);
        free(buffer);
        return NULL;
    }

    unsigned char *output_buffer = (unsigned char *)malloc(file_size + EVP_CIPHER_block_size(cipher));
    if (!output_buffer) {
        perror("Error allocating memory for output buffer");
        EVP_CIPHER_CTX_free(ctx);
        free(buffer);
        return NULL;
    }

    int len;
    if (1 != EVP_EncryptUpdate(ctx, output_buffer, &len, buffer, bytes_read)) {
        perror("Error encrypting data");
        EVP_CIPHER_CTX_free(ctx);
        free(output_buffer);
        free(buffer);
        return NULL;
    }
    size_t total_len = len;

    int final_len;
    if (1 != EVP_EncryptFinal_ex(ctx, output_buffer + len, &final_len)) {
        perror("Error finalizing encryption");
        EVP_CIPHER_CTX_free(ctx);
        free(output_buffer);
        free(buffer);
        return NULL;
    }
    total_len += final_len;

    FILE *out_file = fopen(file_path, "wb");
    if (!out_file) {
        perror("Error opening file for writing");
        EVP_CIPHER_CTX_free(ctx);
        free(output_buffer);
        free(buffer);
        return NULL;
    }

    size_t bytes_written = fwrite(output_buffer, 1, total_len, out_file);
    if (bytes_written != total_len) {
        perror("Error writing to file");
        fclose(out_file);
        EVP_CIPHER_CTX_free(ctx);
        free(output_buffer);
        free(buffer);
        return NULL;
    }
    fclose(out_file);

    EVP_CIPHER_CTX_free(ctx);
    free(output_buffer);
    free(buffer);

    return ctx;
}
