#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define M 1000000

typedef struct PacketHeader {
    uint32_t sourceIP;
    uint32_t destinationIP;
    uint8_t protocolType;
    uint16_t payloadLength;
    uint8_t *payload;
} PacketHeader;

typedef struct Node {
    PacketHeader header;
    struct Node *next;
} Node;

Node* createPacketHeader(uint32_t srcIP, uint32_t dstIP, uint8_t protoType, uint16_t payloadLen) {
    Node *newNode = (Node *)malloc(sizeof(Node));
    if (newNode == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }
    newNode->header.sourceIP = srcIP;
    newNode->header.destinationIP = dstIP;
    newNode->header.protocolType = protoType;
    newNode->header.payloadLength = payloadLen;
    newNode->header.payload = (uint8_t *)malloc(payloadLen);
    if (newNode->header.payload == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        free(newNode);
        return NULL;
    }
    // Calculate checksum and set it as the first byte of the payload
    uint16_t checksum = calculateChecksum(&newNode->header);
    newNode->header.payload[0] = (uint8_t)(checksum >> 8) | (checksum & 0xFF);
    newNode->next = NULL;
    return newNode;
}

void freePacketHeader(Node *node) {
    if (node != NULL) {
        free(node->header.payload);
        free(node);
    }
}

Node* insertPacketHeader(Node **head, uint32_t srcIP, uint32_t dstIP, uint8_t protoType, uint16_t payloadLen) {
    Node *newNode = createPacketHeader(srcIP, dstIP, protoType, payloadLen);
    if (newNode == NULL) {
        return *head; // Return the current head on failure
    }
    newNode->next = *head;
    *head = newNode;
    return *head;
}

void deletePacketHeader(Node **head, Node *toDelete) {
    if (*head == toDelete) {
        *head = toDelete->next;
        freePacketHeader(toDelete);
    } else {
        Node *current = *head;
        while (current != NULL && current->next != toDelete) {
            current = current->next;
        }
        if (current != NULL) {
            current->next = toDelete->next;
            freePacketHeader(toDelete);
        }
    }
}

uint16_t calculateChecksum(PacketHeader *header) {
    uint32_t sum = 0;
    // Sum up all the fields in the header
    sum += header->sourceIP + header->destinationIP + (uint32_t)header->protocolType + header->payloadLength;
    for (int i = 1; i < header->payloadLength; i++) {
        sum += header->payload[i];
    }
    // Reduce to 16 bits
    while (sum >> 16) {
        sum = (sum & 0xFFFF) + (sum >> 16);
    }
    return ~sum;
}

// Example usage:
int main() {
    Node *head = NULL;
    head = insertPacketHeader(&head, 192.168.1.1, 10.0.0.1, IPPROTO_TCP, 1024);

    // Process the packet headers using the existing networking stack API

    deletePacketHeader(&head, head);
    return 0;
}
```

