#include <pthread.h>

typedef struct {
    long long total_sum;
    int line_count;
    double average_value;
} AggregateData;

typedef struct {
    const char* filename;
    pthread_mutex_t mutex;
} ThreadData;

AggregateData global_aggregate = {0, 0, 0};
pthread_mutex_t global_mutex;

void* thread_function(void* arg) {
    ThreadData* data = (ThreadData*)arg;
    FILE* file = fopen(data->filename, "r");
    if (!file) {
        perror("Failed to open file");
        pthread_exit(NULL);
    }

    AggregateData local_aggregate = {0, 0, 0};
    char buffer[256];
    while (fgets(buffer, sizeof(buffer), file)) {
        double value = strtod(buffer, NULL);
        if (!isnan(value)) {
            pthread_mutex_lock(&data->mutex);
            global_aggregate.total_sum += value;
            global_aggregate.line_count++;
            pthread_mutex_unlock(&data->mutex);

            local_aggregate.total_sum += value;
            local_aggregate.line_count++;
        }
    }

    fclose(file);
    double average = local_aggregate.line_count ? local_aggregate.total_sum / local_aggregate.line_count : 0;
    printf("Thread processed %d lines with total sum %.2f and average %.2f\n", local_aggregate.line_count, local_aggregate.total_sum, average);

    pthread_exit(NULL);
}

AggregateData* aggregate_file_data(const char* filename, int num_threads) {
    pthread_t threads[num_threads];
    ThreadData thread_data[num_threads];
    global_mutex = (pthread_mutex_t){0};
    pthread_mutex_init(&global_mutex, NULL);

    for (int i = 0; i < num_threads; i++) {
        thread_data[i].filename = filename;
        pthread_create(&threads[i], NULL, thread_function, &thread_data[i]);
    }

    for (int i = 0; i < num_threads; i++) {
        pthread_join(threads[i], NULL);
    }

    global_aggregate.average_value = global_aggregate.line_count ? global_aggregate.total_sum / global_aggregate.line_count : 0;
    pthread_mutex_destroy(&global_mutex);

    AggregateData* result = (AggregateData*)malloc(sizeof(AggregateData));
    if (!result) {
        perror("Failed to allocate memory");
        return NULL;
    }

    *result = global_aggregate;
    return result;
}

int main() {
    const char* filename = "data.txt";
    int num_threads = 4;

    AggregateData* data = aggregate_file_data(filename, num_threads);
    if (data) {
        printf("Total Sum: %lld\n", data->total_sum);
        printf("Line Count: %d\n", data->line_count);
        printf("Average Value: %.2f\n", data->average_value);
        free(data);
    }

    return 0;
}
