class SecureNetworkCommandExecutor {
    constructor(minSeqNum, maxSeqNum) {
        if (minSeqNum > maxSeqNum) {
            throw new Error("Invalid sequence number range");
        }
        if (minSeqNum < 0 || maxSeqNum > 65535) {
            throw new Error("Sequence numbers out of valid range");
        }

        this.cmdString = '';
        this.minSeqNum = minSeqNum;
        this.maxSeqNum = maxSeqNum;
        this.lastGeneratedSeqNum = null;
    }

    sanitizeCommand(input) {
        // Basic sanitization to prevent injection attacks
        return input.replace(/[^a-zA-Z0-9\s]/g, '');
    }

    async executeShellCommand(cmdString) {
        const sanitizedCmd = this.sanitizeCommand(cmdString);
        try {
            const { exec } = require('child_process');
            await new Promise((resolve, reject) => {
                exec(sanitizedCmd, (error, stdout, stderr) => {
                    if (error) {
                        console.error(`Execution error: ${error.message}`);
                        reject(error);
                    }
                    if (stderr) {
                        console.error(`Stderr output: ${stderr}`);
                        reject(new Error(stderr));
                    }
                    resolve(stdout);
                });
            });
        } catch (error) {
            console.error('Error executing shell command:', error);
        }
    }

    GetRandomSeqNum() {
        while (true) {
            const seqNum = Math.floor(Math.random() * (this.maxSeqNum - this.minSeqNum + 1)) + this.minSeqNum;
