public class WordProcessor {

    private static final ExecutorService executor = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors());
    private static final Map<String, Boolean> dictionaryCache = new ConcurrentHashMap<>();
    private static final Random random = new Random();

    public static int processWords(List<String> inputList) {
        if (inputList == null || inputList.isEmpty()) {
            return 0;
        }

        Set<String> uniqueWords = ConcurrentHashMap.newKeySet();
        ConcurrentMap<String, Integer> wordCount = new ConcurrentHashMap<>();

        try {
            // Normalize and filter words
            List<Future<Void>> futures = inputList.parallelStream()
                .mapAsync(executor, (String line) -> CompletableFuture.runAsync(() -> {
                    for (String word : normalizeLine(line)) {
                        if (isValidWord(word)) {
                            uniqueWords.add(word);
                            wordCount.merge(word, 1, Integer::sum);
                        }
                    }
                })).collect(Collectors.toList());

            // Wait for all tasks to complete
            CompletableFuture.allOf(futures.toArray(new CompletableFuture[0])).join();

        } catch (Exception e) {
            e.printStackTrace();
        }

        // Filter and count words that appear more than once
        int duplicateCount = wordCount.values().stream()
            .filter(count -> count > 1)
            .mapToInt(Integer::intValue)
            .sum();

        return duplicateCount;
    }

    private static List<String> normalizeLine(String line) {
        return Arrays.asList(line.trim().toLowerCase().split("\\s+"));
    }

    private static boolean isValidWord(String word) {
        if (dictionaryCache.containsKey(word)) {
            return dictionaryCache.get(word);
        }

        // Simulate external dictionary check
        boolean isValid = isEnglishWord(word); // Replace with actual dictionary service call
        dictionaryCache.put(word, isValid);

        return isValid;
    }

    private static boolean isEnglishWord(String word) {
        // Dummy implementation for demonstration purposes
        return !word.isEmpty() && word.matches("^[a-zA-Z]+$");
    }

    public static void main(String[] args) {
        List<String> inputList = Arrays.asList(
            "hello world hello",
            "world peace war peace",
            "",
            null,
            "special*characters"
        );

        int duplicateCount = processWords(inputList);
        System.out.println("Duplicate word count: " + duplicateCount);
    }
}
