#include <stdlib.h>
#include <time.h>

typedef struct {
    int value;
} record;

void initialize_data(int N, int M) {
    if (N <= 0 || M <= 0) return; // Handle edge case for zero or negative values

    long *offsets = malloc(N * sizeof(long));
    if (!offsets) {
        perror("Failed to allocate memory for offsets");
        return;
    }

    int *keys = malloc(N * sizeof(int));
    if (!keys) {
        free(offsets);
        perror("Failed to allocate memory for keys");
        return;
    }

    record *records = malloc(M * sizeof(record));
    if (!records) {
        free(offsets);
        free(keys);
        perror("Failed to allocate memory for records");
        return;
    }

    // Initialize offsets and keys with random values
    srand(time(NULL));
    for (int i = 0; i < N; ++i) {
        do {
            offsets[i] = rand() % INT_MAX;
        } while (i > 0 && offsets[i] == offsets[i - 1]);
        keys[i] = offsets[i];
    }

    // Shuffle records based on key values
    for (int i = M - 1; i > 0; --i) {
        int j = rand() % (i + 1);
        record temp = records[j];
        records[j] = records[i];
        records[i] = temp;
    }

    // Reset data structures to default values
    free(offsets);
    free(keys);
    free(records);

    // Log memory allocations and deallocations
    printf("Allocated %zu bytes for offsets\n", N * sizeof(long));
    printf("Allocated %zu bytes for keys\n", N * sizeof(int));
    printf("Allocated %zu bytes for records\n", M * sizeof(record));
}

int main() {
    // Example usage
    initialize_data(10, 5);
    return 0;
}
