        try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
            StringBuilder sb = new StringBuilder();
            String line;
            while ((line = reader.readLine()) != null) {
                sb.append(line);
            }
            return new JSONObject(sb.toString());
        }
    }

    private static void insertEntry(JSONObject json, String keyPath, Object value) {
        String[] keys = keyPath.split("\\.");
        JSONObject currentJson = json;
        for (int i = 0; i < keys.length - 1; i++) {
            if (!currentJson.has(keys[i])) {
                currentJson.put(keys[i], new JSONObject());
            }
            currentJson = currentJson.getJSONObject(keys[i]);
        }
        currentJson.put(keys[keys.length - 1], value);
