int dns_resolve(const char *hostname, IPAddress *ip_address) {
    int status;
    struct hostent *host_info;

    if ((status = gethostbyname_r(hostname, &host_info)) != 0) {
        return -1; // DNS resolution failed
    }

    memcpy(ip_address->ip, host_info->h_addr_list[0], INET_ADDRSTRLEN);
    return 0;
}

