LTE_MultiThreadSafeList* create_lte_list() {
    LTE_MultiThreadSafeList* list = (LTE_MultiThreadSafeList*)malloc(sizeof(LTE_MultiThreadSafeList));
    if (list == NULL) {
        perror("Failed to allocate memory for LTE Multi-Thread Safe List");
        return NULL;
    }
    pthread_mutex_init(&list->mutex, NULL);
    list->next_available_index = 0;
    memset(list->ue_contexts, 0, sizeof(list->ue_contexts));
    return list;
}

void destroy_lte_list(LTE_MultiThreadSafeList* list) {
    if (list != NULL) {
        pthread_mutex_destroy(&list->mutex);
        free(list);
    }
}

int add_ue_context(LTE_MultiThreadSafeList* list, LTE_UE_Context* ue_context) {
    if (list == NULL || ue_context == NULL) {
        fprintf(stderr, "Invalid input parameters\n");
        return -1;
    }

    pthread_mutex_lock(&list->mutex);
    int index = list->next_available_index++;
    if (index >= MAX_UE_CONTEXTS) {
        list->next_available_index = 0; // Reset for next time
        pthread_mutex_unlock(&list->mutex);
        fprintf(stderr, "LTE UE Context list is full\n");
        return -1;
    }
    memcpy(&list->ue_contexts[index], ue_context, sizeof(LTE_UE_Context));
    pthread_mutex_unlock(&list->mutex);

    return index;
}

