// Function to create a new SSL context
SSLContext* create_ssl_context(int cipher_suite) {
    SSLContext* ctx = (SSLContext*)malloc(sizeof(SSLContext));
    if (!ctx) {
        fprintf(stderr, "Memory allocation failed for SSL context.\n");
        return NULL;
    }
    switch (cipher_suite) {
        case 0: // TLS_ECDHE_RSA_WITH_AES_128_GCM_SHA256
