SessionContext session_pool[POOL_SIZE];

// Index to keep track of free slots in the memory pool
int pool_index = 0;

// Mutex to protect access to the memory pool
pthread_mutex_t pool_mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to initialize a new session context
SessionContext* init_session_context(int ue_id, const char* ip_address, int qos_params) {
    pthread_mutex_lock(&pool_mutex);
    if (pool_index >= POOL_SIZE) {
        pthread_mutex_unlock(&pool_mutex);
        return NULL; // Memory pool is full
    }

    SessionContext* ctx = &session_pool[pool_index++];
    ctx->ue_id = ue_id;
    snprintf(ctx->ip_address, sizeof(ctx->ip_address), "%s", ip_address);
    ctx->qos_params = qos_params;

    pthread_mutex_unlock(&pool_mutex);
    return ctx;
}

// Function to free all allocated session contexts
void free_session_contexts() {
    pthread_mutex_lock(&pool_mutex);
    pool_index = 0; // Reset the pool index to reuse memory
    pthread_mutex_unlock(&pool_mutex);
}
