#include <string.h>
#include <arpa/inet.h>
#include <resolv.h>

#define MAX_CONCURRENT_QUERIES 100
#define CACHE_SIZE 1024

typedef struct {
    char hostname[256];
    in_addr_t ip;
} DNSCacheEntry;

DNSCacheEntry cache[CACHE_SIZE];
int cache_size = 0;
int concurrent_queries = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

int dns_resolve(const char *hostname, u_char *ip) {
    pthread_mutex_lock(&lock);
    for (int i = 0; i < cache_size; i++) {
        if (strcmp(cache[i].hostname, hostname) == 0) {
            memcpy(ip, &cache[i].ip, sizeof(in_addr_t));
            pthread_mutex_unlock(&lock);
            return 0;
        }
    }

    if (concurrent_queries >= MAX_CONCURRENT_QUERIES) {
        pthread_mutex_unlock(&lock);
        return -1; // Too many concurrent queries
    }

    struct hostent *he = gethostbyname(hostname);
    if (!he) {
        pthread_mutex_unlock(&lock);
        return -2; // DNS resolution failed
    }

    in_addr_t resolved_ip = ((struct in_addr *)he->h_addr)->s_addr;
    memcpy(ip, &resolved_ip, sizeof(in_addr_t));

    if (cache_size < CACHE_SIZE) {
        strcpy(cache[cache_size].hostname, hostname);
        cache[cache_size].ip = resolved_ip;
        cache_size++;
    }

    concurrent_queries++;
    pthread_mutex_unlock(&lock);
    return 0;
}

