#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    unsigned short RNTI;
    unsigned char CRCFLAG;
    void* extended_information;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct PduNode {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    struct PduNode* next;
} PduNode;

typedef struct {
    PduNode* head;
    PduNode* cacheHead;
    pthread_mutex_t lock;
    int poolSize;
    int cacheSize;
} PDUList;

PDUList* createPDUList(int poolSize, int cacheSize) {
    PDUList* list = (PDUList*)malloc(sizeof(PDUList));
    list->head = NULL;
    list->cacheHead = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->poolSize = poolSize;
    list->cacheSize = cacheSize;
    return list;
}

NFAPI_CRC_INDICATION_PDU_T* generatePDU(PDUList* list) {
    PduNode* node;
    if (list->cacheHead != NULL) {
        node = list->cacheHead;
        list->cacheHead = node->next;
    } else {
        pthread_mutex_lock(&list->lock);
        if (list->head == NULL) {
            // Allocate from pool
            node = (PduNode*)malloc(sizeof(PduNode));
        } else {
            node = list->head;
            list->head = node->next;
        }
        pthread_mutex_unlock(&list->lock);
    }

    // Initialize PDU fields
    node->pdu.RX_UE_INFORMATION_TAG = rand();
    node->pdu.RNTI = (unsigned short)rand();
    node->pdu.CRCFLAG = (unsigned char)(rand() % 256);
    node->pdu.extended_information = NULL; // Optional field

    return &node->pdu;
}

void returnPDU(PDUList* list, NFAPI_CRC_INDICATION_PDU_T* pdu) {
    PduNode* node = (PduNode*)((char*)pdu - offsetof(PduNode, pdu));
    if (list->cacheHead == NULL) {
        pthread_mutex_lock(&list->lock);
        if (list->head == NULL || list->poolSize > 0) {
            node->next = list->head;
            list->head = node;
        }
        pthread_mutex_unlock(&list->lock);
    } else {
        node->next = list->cacheHead;
        list->cacheHead = node;
    }
}

void destroyPDUList(PDUList* list) {
    PduNode* current = list->head;
    while (current != NULL) {
        PduNode* next = current->next;
        free(current);
        current = next;
    }

    pthread_mutex_destroy(&list->lock);
    free(list);
}
