    void (*memory_threshold_callback)(size_t usage);
} PDU_LIST;

int create_pdu_list(PDU_LIST *list, int n) {
    pthread_mutex_lock(&list->mutex);

    for (int i = 0; i < n; i++) {
        list->pdus[i] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!list->pdus[i]) {
            fprintf(stderr, "Memory allocation failed\n");
            pthread_mutex_unlock(&list->mutex);
            return -1;
