        // Populate the PDU with random data
        list->pdus[i]->rx_ue_info.rx_ue_information_tag = rand() % 1000;
        list->pdus[i]->rx_ue_info.rnti = rand() % 256;
        list->pdus[i]->crc_indication.crcflag = rand() % 2;
        list->pdus[i]->rx_power_level = rand() % 30 - 140; // RSSI range: -140 to -10 dBm

        list->total_memory_usage += sizeof(NFAPI_CRC_INDICATION_PDU_T);
        if (list->memory_threshold_callback && list->total_memory_usage > threshold) {
            list->memory_threshold_callback(list->total_memory_usage);
        }
    }

    list->count = n;
    pthread_mutex_unlock(&list->mutex);
    return 0;
}

void free_pdu_list(PDU_LIST *list) {
    for (int i = 0; i < list->count; i++) {
        free(list->pdus[i]);
    }
    memset(list, 0, sizeof(PDU_LIST));
}

void set_memory_threshold_callback(PDU_LIST *list, void (*callback)(size_t usage)) {
    list->memory_threshold_callback = callback;
}

int main() {
    PDU_LIST pdu_list;
    pthread_mutex_init(&pdu_list.mutex, NULL);
    pdu_list.total_memory_usage = 0;

    set_memory_threshold_callback(&pdu_list, [](size_t usage) {
        printf("Memory threshold reached: %zu bytes\n", usage);
    });

    if (create_pdu_list(&pdu_list, MAX_PDUS) != 0) {
        fprintf(stderr, "Failed to create PDU list\n");
        return 1;
    }

    free_pdu_list(&pdu_list);

    pthread_mutex_destroy(&pdu_list.mutex);
    return 0;
}
