// Define a simple hash table for caching configuration data
#define HASH_SIZE 1024

typedef struct config_node {
    LTE_RRC_CU_Transmission_Config_Dedicated_TN config;
    struct config_node *next;
} ConfigNode;

ConfigNode* config_cache[HASH_SIZE] = {NULL};

// Hash function to determine the index in the cache
unsigned int hash_function(int cell_id) {
    return abs(cell_id % HASH_SIZE);
}

// Function to add a configuration to the cache
void add_to_cache(LTE_RRC_CU_Transmission_Config_Dedicated_TN config) {
    unsigned int index = hash_function(config.cell_id);
    ConfigNode *new_node = (ConfigNode *)malloc(sizeof(ConfigNode));
    new_node->config = config;
    new_node->next = config_cache[index];
    config_cache[index] = new_node;
}

// Function to get a configuration from the cache
LTE_RRC_CU_Transmission_Config_Dedicated_TN* get_from_cache(int cell_id) {
    unsigned int index = hash_function(cell_id);
    ConfigNode *current = config_cache[index];
    while (current != NULL) {
        if (current->config.cell_id == cell_id) {
            return &current->config;
        }
        current = current->next;
    }
    return NULL; // Configuration not found in cache
}

