#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <unistd.h>
#include <pthread.h>

#define MAX_CONNECTIONS 1024

typedef struct {
    int client_id;
    struct sockaddr_in socket_params;
    char *message_tags[MAX_CONNECTIONS];
} TCPConnectionConfig;

TCPConnectionConfig *connection_configs = NULL;
int current_connections = 0;
pthread_mutex_t lock;

void initialize_connection_config(int client_id, struct sockaddr_in socket_params) {
    pthread_mutex_lock(&lock);
    if (current_connections >= MAX_CONNECTIONS) {
        fprintf(stderr, "Maximum connections reached\n");
        return;
    }
    TCPConnectionConfig new_config;
    new_config.client_id = client_id;
    new_config.socket_params = socket_params;
    for (int i = 0; i < MAX_CONNECTIONS; i++) {
        new_config.message_tags[i] = NULL;
    }
    if (current_connections == 0) {
        connection_configs = (TCPConnectionConfig *)malloc(sizeof(TCPConnectionConfig) * MAX_CONNECTIONS);
        if (!connection_configs) {
            fprintf(stderr, "Memory allocation failed\n");
            return;
        }
    } else {
        connection_configs = (TCPConnectionConfig *)realloc(connection_configs, sizeof(TCPConnectionConfig) * current_connections + 1);
        if (!connection_configs) {
            fprintf(stderr, "Memory reallocation failed\n");
            return;
        }
    }
    memcpy(&connection_configs[current_connections], &new_config, sizeof(TCPConnectionConfig));
    current_connections++;
    pthread_mutex_unlock(&lock);
}

void update_connection_config(int client_id, struct sockaddr_in socket_params, char *message_tags[]) {
    pthread_mutex_lock(&lock);
    for (int i = 0; i < current_connections; i++) {
        if (connection_configs[i].client_id == client_id) {
            connection_configs[i].socket_params = socket_params;
            for (int j = 0; j < MAX_CONNECTIONS; j++) {
                free(connection_configs[i].message_tags[j]);
                connection_configs[i].message_tags[j] = NULL;
            }
            int j = 0;
            while (message_tags[j]) {
                connection_configs[i].message_tags[j] = strdup(message_tags[j]);
                if (!connection_configs[i].message_tags[j]) {
                    fprintf(stderr, "Memory allocation failed\n");
                    return;
                }
                j++;
            }
            break;
        }
    }
    pthread_mutex_unlock(&lock);
}

void cleanup_connection_configs() {
    pthread_mutex_lock(&lock);
    for (int i = 0; i < current_connections; i++) {
        for (int j = 0; j < MAX_CONNECTIONS; j++) {
            free(connection_configs[i].message_tags[j]);
        }
    }
    free(connection_configs);
    current_connections = 0;
    pthread_mutex_unlock(&lock);
}

int main() {
    pthread_mutex_init(&lock, NULL);

    // Example usage
    struct sockaddr_in socket_params;
    inet_pton(AF_INET, "127.0.0.1", &socket_params.sin_addr);
    socket_params.sin_family = AF_INET;
    socket_params.sin_port = htons(8080);

    char *message_tags[] = {"TAG1", "TAG2", NULL};
    initialize_connection_config(1, socket_params);
    update_connection_config(1, socket_params, message_tags);

    cleanup_connection_configs();

    pthread_mutex_destroy(&lock);

    return 0;
}
