#include <stdlib.h>
#include <string.h>
#include <stdio.h>

#define MAX_PARAMS 1000
#define MAX_VALUE_SIZE 1024

typedef enum {
    CFG_INT,
    CFG_FLOAT,
    CFG_DOUBLE,
    CFG_CHAR_PTR
} cfg_type_t;

typedef struct {
    const char *key;
    union {
        int int_val;
        float float_val;
        double double_val;
        char *char_ptr_val;
    } value;
    cfg_type_t type;
} config_param_t;

typedef struct {
    config_param_t *params;
    int param_count;
} config_storage_t;

config_storage_t *create_config_storage() {
    config_storage_t *storage = (config_storage_t *)malloc(sizeof(config_storage_t));
    if (!storage) return NULL;
    storage->params = (config_param_t *)calloc(MAX_PARAMS, sizeof(config_param_t));
    if (!storage->params) {
        free(storage);
        return NULL;
    }
    storage->param_count = 0;
    return storage;
}

void destroy_config_storage(config_storage_t *storage) {
    for (int i = 0; i < storage->param_count; i++) {
        if (storage->params[i].type == CFG_CHAR_PTR && storage->params[i].value.char_ptr_val) {
            free(storage->params[i].value.char_ptr_val);
        }
    }
    free(storage->params);
    free(storage);
}

int add_config_param(config_storage_t *storage, const char *key, cfg_type_t type, void *value) {
    if (storage->param_count >= MAX_PARAMS) {
        printf("Error: Configuration storage capacity exceeded.\n");
        return -1;
    }
    config_param_t param = { .key = key, .type = type };
    memcpy(&param.value, value, sizeof(union { int int_val; float float_val; double double_val; char *char_ptr_val; }));
    storage->params[storage->param_count++] = param;
    return 0;
}

int get_config_param(config_storage_t *storage, const char *key, cfg_type_t type, void *value) {
    for (int i = 0; i < storage->param_count; i++) {
        if (strcmp(storage->params[i].key, key) == 0 && storage->params[i].type == type) {
            memcpy(value, &storage->params[i].value, sizeof(union { int int_val; float float_val; double double_val; char *char_ptr_val; }));
            return 0;
        }
    }
    printf("Error: Configuration parameter not found or type mismatch.\n");
    return -1;
}

int remove_config_param(config_storage_t *storage, const char *key) {
    for (int i = 0; i < storage->param_count; i++) {
        if (strcmp(storage->params[i].key, key) == 0) {
            if (storage->params[i].type == CFG_CHAR_PTR && storage->params[i].value.char_ptr_val) {
                free(storage->params[i].value.char_ptr_val);
            }
            for (int j = i; j < storage->param_count - 1; j++) {
                storage->params[j] = storage->params[j + 1];
            }
            storage->param_count--;
            return 0;
        }
    }
    printf("Error: Configuration parameter not found.\n");
    return -1;
}

int reset_config_storage(config_storage_t *storage) {
    for (int i = 0; i < storage->param_count; i++) {
        if (storage->params[i].type == CFG_CHAR_PTR && storage->params[i].value.char_ptr_val) {
