typedef struct {
    CURL *handle;
    char *url;
    char *buffer;
} RequestData;

typedef struct {
    RequestData **requests;
    int count;
    int max_count;
    pthread_mutex_t lock;
} RequestQueue;

RequestQueue* create_request_queue(int max_count) {
    RequestQueue *queue = (RequestQueue*) malloc(sizeof(RequestQueue));
    queue->requests = (RequestData**) malloc(max_count * sizeof(RequestData*));
    queue->count = 0;
    queue->max_count = max_count;
    pthread_mutex_init(&queue->lock, NULL);
    return queue;
}

void enqueue_request(RequestQueue *queue, RequestData *request) {
    pthread_mutex_lock(&queue->lock);
    if (queue->count < queue->max_count) {
        queue->requests[queue->count++] = request;
    } else {
        // Handle error: queue is full
    }
    pthread_mutex_unlock(&queue->lock);
}

RequestData* dequeue_request(RequestQueue *queue) {
    RequestData *request = NULL;
    pthread_mutex_lock(&queue->lock);
    if (queue->count > 0) {
        request = queue->requests[--queue->count];
    } else {
        // Handle error: queue is empty
    }
    pthread_mutex_unlock(&queue->lock);
    return request;
}

void free_request(RequestData *request) {
    if (request != NULL) {
        if (request->handle != NULL) curl_easy_cleanup(request->handle);
        if (request->url != NULL) free(request->url);
        if (request->buffer != NULL) free(request->buffer);
        free(request);
    }
}

void* worker_thread(void *arg) {
    RequestQueue *queue = (RequestQueue*) arg;
    while (1) {
        RequestData *request = dequeue_request(queue);
        if (request == NULL) break; // Exit thread
        CURLcode res = curl_easy_perform(request->handle);
        if (res != CURLE_OK) {
            // Handle error: request failed
        }
        free_request(request);
    }
    return NULL;
}

void perform_http_requests(RequestQueue *queue, const char *urls[], int count) {
    pthread_t threads[MAX_CONCURRENCY];
    for (int i = 0; i < MAX_CONCURRENCY && i < count; i++) {
        RequestData *request = (RequestData*) malloc(sizeof(RequestData));
        request->handle = curl_easy_init();
        request->url = strdup(urls[i]);
        request->buffer = NULL;
        curl_easy_setopt(request->handle, CURLOPT_URL, urls[i]);
        curl_easy_setopt(request->handle, CURLOPT_WRITEFUNCTION, NULL);
        enqueue_request(queue, request);
    }
    for (int i = 0; i < MAX_CONCURRENCY; i++) {
        pthread_create(&threads[i], NULL, worker_thread, queue);
    }
    for (int i = 0; i < MAX_CONCURRENCY; i++) {
        pthread_join(threads[i], NULL);
    }
    while (queue->count > 0) {
        RequestData *request = dequeue_request(queue);
        free_request(request);
    }
}

int main() {
    const char *urls[] = {
        "http://example.com",
        "http://example.org",
        // Add more URLs as needed
    };
    int count = sizeof(urls) / sizeof(urls[0]);
    RequestQueue *queue = create_request_queue(MAX_CONCURRENCY);
    perform_http_requests(queue, urls, count);
    free_request_queue(queue);
    return 0;
}

void free_request_queue(RequestQueue *queue) {
    if (queue != NULL) {
        for (int i = 0; i < queue->count; i++) {
            free_request(queue->requests[i]);
        }
        free(queue->requests);
        pthread_mutex_destroy(&queue->lock);
        free(queue);
    }
}
