#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <libcurl/curl.h>
#include <uthash.h>

#define MAX_CONCURRENCY 10
#define MAX_CACHE_SIZE 1000

typedef struct {
    char *key;
    char *value;
    time_t expiration_time;
    UT_hash_handle hh;
} CacheEntry;

CacheEntry *cache = NULL;

void cache_store(const char *key, const char *value, time_t ttl) {
    CacheEntry *entry;
    HASH_FIND_STR(cache, key, entry);
    if (entry == NULL) {
        entry = (CacheEntry *)malloc(sizeof(CacheEntry));
        entry->key = strdup(key);
        HASH_ADD_STR(cache, key, entry);
    }
    free(entry->value);
    entry->value = strdup(value);
    entry->expiration_time = time(NULL) + ttl;
}

char *cache_fetch(const char *key) {
    CacheEntry *entry;
    HASH_FIND_STR(cache, key, entry);
    if (entry != NULL && entry->expiration_time > time(NULL)) {
        return entry->value;
    }
    return NULL;
}

void cache_invalidate(CacheEntry *entry) {
    HASH_DEL(cache, entry);
    free(entry->key);
    free(entry->value);
    free(entry);
}

size_t write_callback(void *contents, size_t size, size_t nmemb, void *userp) {
    size_t totalSize = size * nmemb;
    char **buffer = (char **)userp;
    *buffer = realloc(*buffer, totalSize + 1);
    if (*buffer == NULL) {
        return 0;
    }
    memcpy(*buffer + strlen(*buffer), contents, totalSize);
    (*buffer)[totalSize] = '\0';
    return totalSize;
}

int perform_request(const char *url, char **response) {
    CURL *curl;
    CURLcode res;

    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();
    if (curl) {
        *response = NULL;
        curl_easy_setopt(curl, CURLOPT_URL, url);
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_callback);
        curl_easy_setopt(curl, CURLOPT_WRITEDATA, response);

        res = curl_easy_perform(curl);
        if (res != CURLE_OK) {
            printf("curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
            return -1;
        }

        long http_code = 0;
        curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &http_code);
        if (http_code >= 400) {
            printf("HTTP error: %ld\n", http_code);
            return -1;
        }
    } else {
        printf("Failed to initialize curl.\n");
        return -1;
    }

    curl_easy_cleanup(curl);
    curl_global_cleanup();
    return 0;
}

int main() {
    char *response = NULL;
    perform_request("https://api.example.com/data", &response);
    if (response != NULL) {
        printf("Response: %s\n", response);
        free(response);
    }
    return 0;
}
```

