#define MAX_PARAMS 1000
#define MAX_VALUE_SIZE 1024

typedef enum { INT, FLOAT, DOUBLE, CHAR_PTR } DataType;
typedef union {
    int i;
    float f;
    double d;
    char *s;
} DataValue;

typedef struct {
    char key[MAX_VALUE_SIZE];
    DataType type;
    DataValue value;
} ConfigParam;

typedef struct {
    ConfigParam params[MAX_PARAMS];
    size_t count;
    size_t soft_cap_index;
    pthread_mutex_t mutex;
} ConfigStorage;

void init_config_storage(ConfigStorage *storage) {
    storage->count = 0;
    storage->soft_cap_index = MAX_PARAMS / 2;
    pthread_mutex_init(&storage->mutex, NULL);
}

int add_param(ConfigStorage *storage, const char *key, DataType type, DataValue value) {
    pthread_mutex_lock(&storage->mutex);
    if (storage->count >= MAX_PARAMS) {
        printf("Error: Maximum number of parameters reached\n");
        pthread_mutex_unlock(&storage->mutex);
        return -1;
    }
    if (strlen(key) + 1 > MAX_VALUE_SIZE) {
        printf("Error: Key length exceeds maximum value size\n");
        pthread_mutex_unlock(&storage->mutex);
        return -1;
    }
    if (value.s && strlen(value.s) + 1 > MAX_VALUE_SIZE) {
        printf("Error: String value length exceeds maximum value size\n");
        pthread_mutex_unlock(&storage->mutex);
        return -1;
    }

    strcpy(storage->params[storage->count].key, key);
    storage->params[storage->count].type = type;
    if (type == CHAR_PTR && value.s) {
        storage->params[storage->count].value.s = strdup(value.s);
    } else {
        memcpy(&storage->params[storage->count].value, &value, sizeof(DataValue));
    }
    storage->count++;
    pthread_mutex_unlock(&storage->mutex);
    return 0;
}

// Implement other functions (get_param, remove_param, serialize, deserialize, etc.) here

int main() {
    ConfigStorage config_storage;
    init_config_storage(&config_storage);

    DataValue int_value = { .i = 42 };
    add_param(&config_storage, "example_int", INT, int_value);

    // Implement other operations and tests

    return 0;
}
