    // Allocate memory for the list of PDUs
    NFAPI_CRC_INDICATION_PDU_T* pdus = (NFAPI_CRC_INDICATION_PDU_T*)malloc(numElements * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (pdus == NULL) {
