typedef struct {
    ConnectionState *states;
    int size;
    int capacity;
    pthread_mutex_t lock;
} ConnectionList;

void initConnectionList(ConnectionList *list, int initialCapacity) {
    list->states = (ConnectionState *)malloc(initialCapacity * sizeof(ConnectionState));
    if (!list->states) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }
    list->size = 0;
    list->capacity = initialCapacity;
    pthread_mutex_init(&list->lock, NULL);
}

void freeConnectionList(ConnectionList *list) {
    pthread_mutex_destroy(&list->lock);
    free(list->states);
}

void addOrUpdateConnection(ConnectionList *list, int id, double bandwidth) {
    pthread_mutex_lock(&list->lock);
    if (id >= list->size) {
        if (id >= list->capacity) {
            list->capacity *= 2;
            ConnectionState *newStates = realloc(list->states, list->capacity * sizeof(ConnectionState));
            if (!newStates) {
                perror("Memory reallocation failed");
                exit(EXIT_FAILURE);
            }
            list->states = newStates;
        }
        list->states[id].id = id;
        time(&list->states[id].timestamp);
    }
    list->states[id].bandwidth = bandwidth;
    pthread_mutex_unlock(&list->lock);

    // Log the connection update
    printf("Connection %d updated at timestamp %ld with bandwidth %.2f\n", id, list->states[id].timestamp, list->states[id].bandwidth);
}

