typedef struct Node {
    ConnectionState data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    size_t count;
    size_t capacity;
} ConnectionStateList;

void initialize_connection_state_list(ConnectionStateList* list, size_t initial_capacity) {
    list->head = NULL;
    list->count = 0;
    list->capacity = initial_capacity;
}

Node* create_node(ConnectionState data) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (new_node == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    new_node->data = data;
    new_node->next = NULL;
    return new_node;
}

void add_connection_state(ConnectionStateList* list, ConnectionState data) {
    if (list->count >= list->capacity) {
        list->capacity *= 2; // Double the capacity
        Node** old_nodes = (Node**)realloc(list->head, list->capacity * sizeof(Node*));
        if (old_nodes == NULL) {
            fprintf(stderr, "Memory reallocation failed\n");
            exit(1);
        }
        list->head = old_nodes;
    }

    Node* new_node = create_node(data);
    new_node->next = list->head;
    list->head = new_node;
    list->count++;
}

void log_connection_state(ConnectionState data) {
