ConnectionState* create_connection_list(int num_elements, long seed) {
    ConnectionState* list = (ConnectionState*)malloc(num_elements * sizeof(ConnectionState));
    if (!list) {
        perror("Memory allocation failed");
        return NULL;
    }

    srand(seed);

    for (int i = 0; i < num_elements; i++) {
        list[i].conn_id = i + 1;
        list[i].timestamp = time(NULL);
        list[i].bandwidth_utilization = ((float)rand() / RAND_MAX) * 100.0;
        list[i].priority = rand() % 5 + 1;
        list[i].qos_deadline = list[i].timestamp + (rand() % 3600 + 1);
    }

    return list;
}

void update_connection(ConnectionState* conn, float new_utilization) {
    time_t current_time = time(NULL);
    conn->timestamp = current_time;
    conn->bandwidth_utilization = new_utilization;

    printf("Connection ID: %d, Timestamp: %ld, Bandwidth Utilization: %.2f%%, Priority: %d, QoS Deadline: %ld\n",
           conn->conn_id, conn->timestamp, conn->bandwidth_utilization, conn->priority, conn->qos_deadline);
}

int main() {
    int num_elements = 10;
    long seed = time(NULL);

    ConnectionState* connection_list = create_connection_list(num_elements, seed);

    if (connection_list) {
        for (int i = 0; i < num_elements; i++) {
            update_connection(&connection_list[i], ((float)rand() / RAND_MAX) * 100.0);
        }

        free(connection_list);
    }

    return 0;
}
