    time_t last_activity;
    int duration;
    int auth_level;
    char rbac_permissions[100];
} UserSession;

UserSession** create_session_list(int size, time_t seed) {
    UserSession** session_list = (UserSession**)malloc(size * sizeof(UserSession*));
    for (int i = 0; i < size; i++) {
        session_list[i] = (UserSession*)malloc(sizeof(UserSession));
        srand(time(NULL) + seed + i);
        session_list[i]->id = rand() % 1000;
        time(&session_list[i]->timestamp);
        session_list[i]->last_activity = session_list[i]->timestamp;
        session_list[i]->duration = rand() % (3600 * 24); // Random duration up to 24 hours
        session_list[i]->auth_level = rand() % 5; // Authentication level from 0 to 4
        snprintf(session_list[i]->rbac_permissions, sizeof(session_list[i]->rbac_permissions), "permissions_%d", rand() % 10);
    }
    return session_list;
}

void update_session(UserSession* session) {
    time_t current_time;
    time(&current_time);
    session->last_activity = current_time;
    session->duration = difftime(current_time, session->timestamp);
    // Simulate RBAC adjustments
    snprintf(session->rbac_permissions, sizeof(session->rbac_permissions), "updated_permissions_%d", rand() % 10);
}

void log_session_update(UserSession* session) {
    printf("Updated Session: ID=%d, Timestamp=%ld, Last Activity=%ld, Duration=%ld, Auth Level=%d, RBAC Permissions=%s\n",
           session->id, (long)session->timestamp, (long)session->last_activity, session->duration, session->auth_level, session->rbac_permissions);
}

int main() {
    int size = 5;
    time_t seed = time(NULL);
    UserSession** sessions = create_session_list(size, seed);

    for (int i = 0; i < size; i++) {
        update_session(sessions[i]);
        log_session_update(sessions[i]);
    }

    // Free allocated memory
    for (int i = 0; i < size; i++) {
        free(sessions[i]);
    }
    free(sessions);

    return 0;
}
