#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct TCPConnectionRecord {
    int socketDescriptor;
    time_t connectionTimestamp;
    time_t lastActivityTime;
    double bandwidthUsage;
} TCPConnectionRecord;

typedef struct ConnectionList {
    TCPConnectionRecord *records;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} ConnectionList;

void initConnectionList(ConnectionList *list, size_t initialCapacity) {
    list->records = malloc(initialCapacity * sizeof(TCPConnectionRecord));
    if (!list->records) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    list->capacity = initialCapacity;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);
}

void addTCPConnection(ConnectionList *list, int socketDescriptor, double bandwidthUsage) {
    pthread_mutex_lock(&list->lock);
    if (list->size == list->capacity) {
        size_t newCapacity = list->capacity * 2;
        TCPConnectionRecord *newRecords = realloc(list->records, newCapacity * sizeof(TCPConnectionRecord));
        if (!newRecords) {
            fprintf(stderr, "Memory reallocation failed\n");
            exit(EXIT_FAILURE);
        }
        list->records = newRecords;
        list->capacity = newCapacity;
    }
    TCPConnectionRecord newRecord = {socketDescriptor, time(NULL), time(NULL), bandwidthUsage};
    list->records[list->size++] = newRecord;
    pthread_mutex_unlock(&list->lock);
}

void updateLastActivityTime(ConnectionList *list, int socketDescriptor) {
    pthread_mutex_lock(&list->lock);
    for (size_t i = 0; i < list->size; ++i) {
        if (list->records[i].socketDescriptor == socketDescriptor) {
            list->records[i].lastActivityTime = time(NULL);
            break;
        }
    }
    pthread_mutex_unlock(&list->lock);
}

void updateBandwidthUsage(ConnectionList *list, int socketDescriptor, double newBandwidthUsage) {
    pthread_mutex_lock(&list->lock);
    for (size_t i = 0; i < list->size; ++i) {
        if (list->records[i].socketDescriptor == socketDescriptor) {
            list->records[i].bandwidthUsage = newBandwidthUsage;
            break;
        }
    }
    pthread_mutex_unlock(&list->lock);
}

void logConnectionEvent(ConnectionList *list, int socketDescriptor, const char *eventType) {
    pthread_mutex_lock(&list->lock);
    for (size_t i = 0; i < list->size; ++i) {
        if (list->records[i].socketDescriptor == socketDescriptor) {
            printf("Connection %d - %s at %ld\n", socketDescriptor, eventType, time(NULL));
            break;
        }
    }
