EVP_CIPHER_CTX *initialize_aes_cipher(const char *password) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) return NULL;

    // Derive key using SHA-1
    unsigned char key[32];
    SHA1((unsigned char *)password, strlen(password), key);

    // Set IV and cipher parameters
    unsigned char iv[EVP_MAX_BLOCK_LENGTH];
    if (!RAND_bytes(iv, EVP_MAX_BLOCK_LENGTH)) {
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    if (1 != EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv)) {
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    return ctx;
}

void cleanup_cipher(EVP_CIPHER_CTX *ctx) {
