EVP_CIPHER_CTX *init_aes_cipher(const char *password, unsigned int iv_len) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) return NULL;

    // Derive key using SHA-1
    unsigned char key[EVP_MAX_KEY_LENGTH];
    SHA1((unsigned char *)password, strlen(password), key);

    // Initialize cipher context
    if (1 != EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, NULL)) {
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    // Set IV length (fixed value)
    if (iv_len == 0) iv_len = EVP_CIPHER_iv_length(EVP_aes_256_cbc());

    // Allocate and set IV
    unsigned char *iv = OPENSSL_malloc(iv_len);
    if (!iv) {
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }
    memset(iv, 0, iv_len); // Example: use all zeros for IV

    if (1 != EVP_EncryptInit_ex(ctx, NULL, NULL, key, iv)) {
        OPENSSL_free(iv);
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    // Enable cipher
    if (1 != EVP_EncryptUpdate(ctx, NULL, &iv_len, NULL, 0)) {
        OPENSSL_free(iv);
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    OPENSSL_free(iv);
    return ctx;
}

void cleanup_aes_cipher(EVP_CIPHER_CTX *ctx) {
    if (ctx) {
        EVP_CIPHER_CTX_free(ctx);
    }
}

