#include <openssl/evp.h>
#include <openssl/rand.h>
#include <arpa/inet.h>
#include <stdio.h>
#include <stdlib.h>

// Define constants for AES-256-CBC
#define KEY_SIZE 32
#define IV_SIZE 16

// Function to initialize AES-256-CBC cipher context
EVP_CIPHER_CTX *init_cipher(const char *password) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) return NULL;

    unsigned char key[KEY_SIZE];
    unsigned char iv[IV_SIZE];

    // Derive the encryption key from the password using SHA-1
    if (SHA1((unsigned char *)password, strlen(password), key) != KEY_SIZE) {
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    // Set IV and enable cipher
    if (!RAND_bytes(iv, IV_SIZE) ||
        !EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv)) {
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    return ctx;
}

// Function to clean up and disable the cipher
void cleanup_cipher(EVP_CIPHER_CTX *ctx) {
    if (ctx) {
        EVP_CIPHER_CTX_free(ctx);
    }
}

// Function to perform DNS resolution for a given hostname
int resolve_hostname(const char *hostname, u_char ip[4]) {
    struct addrinfo hints, *res;
    int status;

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET; // Use IPv4
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        fprintf(stderr, "getaddrinfo: %s\n", gai_strerror(status));
        return -1;
    }

    struct sockaddr_in *ipv4 = (struct sockaddr_in *)res->ai_addr;
    memcpy(ip, &(ipv4->sin_addr), 4);

    freeaddrinfo(res);
    return 0;
}

// Function to periodically refresh encryption keys
void refresh_encryption_keys(EVP_CIPHER_CTX **ctx) {
    cleanup_cipher(*ctx);
    *ctx = init_cipher("new_password"); // Replace with actual password logic
}
