#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

typedef struct Packet {
    void* header;
    void* payload;
    time_t timestamp;
    char source_ip[16];
    char destination_ip[16];
    int protocol_type;
    int priority;
    int deadline;
} Packet;

typedef struct PacketQueue {
    Packet** packets;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
    pthread_cond_t not_full;
    pthread_cond_t not_empty;
    int max_memory_usage;
    int current_memory_usage;
} PacketQueue;

PacketQueue* create_packet_queue(size_t initial_capacity, int max_memory_usage) {
    PacketQueue* queue = (PacketQueue*)malloc(sizeof(PacketQueue));
    queue->packets = (Packet**)calloc(initial_capacity, sizeof(Packet*));
    queue->capacity = initial_capacity;
    queue->size = 0;
    pthread_mutex_init(&queue->lock, NULL);
    pthread_cond_init(&queue->not_full, NULL);
    pthread_cond_init(&queue->not_empty, NULL);
    queue->max_memory_usage = max_memory_usage;
    queue->current_memory_usage = 0;
    return queue;
}

void enqueue_packet(PacketQueue* queue, Packet* packet) {
    pthread_mutex_lock(&queue->lock);
    while (queue->size == queue->capacity || queue->current_memory_usage + packet_size > queue->max_memory_usage) {
        pthread_cond_wait(&queue->not_full, &queue->lock);
    }
    queue->packets[queue->size] = packet;
    queue->size++;
    queue->current_memory_usage += packet_size;
    pthread_cond_signal(&queue->not_empty);
    pthread_mutex_unlock(&queue->lock);
}

Packet* dequeue_packet(PacketQueue* queue) {
    Packet* packet = NULL;
    pthread_mutex_lock(&queue->lock);
    while (queue->size == 0) {
        pthread_cond_wait(&queue->not_empty, &queue->lock);
    }
    packet = queue->packets[0];
    for (size_t i = 1; i < queue->size; i++) {
        queue->packets[i - 1] = queue->packets[i];
    }
    queue->size--;
    queue->current_memory_usage -= packet_size;
    pthread_cond_signal(&queue->not_full);
    pthread_mutex_unlock(&queue->lock);
    return packet;
}

void destroy_packet_queue(PacketQueue* queue) {
    for (size_t i = 0; i < queue->size; i++) {
        free(queue->packets[i]);
    }
    free(queue->packets);
    pthread_mutex_destroy(&queue->lock);
    pthread_cond_destroy(&queue->not_full);
    pthread_cond_destroy(&queue->not_empty);
    free(queue);
}
