// Define the NFAPI_CRC_INDICATION_PDU_T structure
typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    char CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Function to create and populate a list of NFAPI_CRC_INDICATION_PDU_T structures
void* create_and_populate_list(int N, int min_tag, int max_tag, int max_size) {
    if (N > max_size) {
        return NULL; // Error: List size exceeds maximum allowed
    }

    NFAPI_CRC_INDICATION_PDU_T** list = (NFAPI_CRC_INDICATION_PDU_T**)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    if (!list) {
        return NULL; // Memory allocation failed
    }

    pthread_mutex_t mutex;
    pthread_mutex_init(&mutex, NULL);

    for (int i = 0; i < N; i++) {
        list[i] = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!list[i]) {
            // Free previously allocated memory
            for (int j = 0; j < i; j++) {
                free(list[j]);
            }
            free(list);
            pthread_mutex_destroy(&mutex);
            return NULL; // Memory allocation failed
        }

        // Initialize the structure with random values within specified ranges
        list[i]->RX_UE_INFORMATION_TAG = rand() % (max_tag - min_tag + 1) + min_tag;
        do {
            list[i]->RNTI = rand() % max_size; // Ensure unique RNTI values
        } while (i > 0 && list[i]->RNTI == list[i-1]->RNTI);
        list[i]->CRC_INDICATION_REL8_TAG = (rand() % 2) ? 'Y' : 'N'; // Randomly set CRCFLAG

        // Log the creation of each structure
        printf("Created NFAPI_CRC_INDICATION_PDU_T with RX_UE_INFORMATION_TAG=%d, RNTI=%d, CRC_INDICATION_REL8_TAG=%c\n",
               list[i]->RX_UE_INFORMATION_TAG, list[i]->RNTI, list[i]->CRC_INDICATION_REL8_TAG);
    }

    // Initialize the mutex for thread-safe operations
    pthread_mutex_lock(&mutex);
    // Perform thread-safe operations here if necessary

    return (void*)list;
}

// Function to free the allocated memory for the list of NFAPI_CRC_INDICATION_PDU_T structures
void free_list(void* list, int N) {
    NFAPI_CRC_INDICATION_PDU_T** ptr = (NFAPI_CRC_INDICATION_PDU_T**)list;

    pthread_mutex_t mutex;
    pthread_mutex_init(&mutex, NULL);
    pthread_mutex_lock(&mutex);

    for (int i = 0; i < N; i++) {
        free(ptr[i]);
        // Log the deletion of each structure
        printf("Deleted NFAPI_CRC_INDICATION_PDU_T with RX_UE_INFORMATION_TAG=%d, RNTI=%d, CRC_INDICATION_REL8_TAG=%c\n",
               ptr[i]->RX_UE_INFORMATION_TAG, ptr[i]->RNTI, ptr[i]->CRC_INDICATION_REL8_TAG);
    }

    free(ptr);
    pthread_mutex_destroy(&mutex);
}

// Example usage of the create_and_populate_list function
