NFAPICRCList* create_crc_list(size_t max_size) {
    NFAPICRCList* list = (NFAPICRCList*)malloc(sizeof(NFAPICRCList));
    if (!list) {
        return NULL;
    }
    list->max_size = max_size;
    list->count = 0;
    list->list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(max_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->list) {
        free(list);
        return NULL;
    }
    pthread_mutex_init(&list->mutex, NULL);
    return list;
}

void destroy_crc_list(NFAPICRCList* list) {
    pthread_mutex_lock(&list->mutex);
    for (size_t i = 0; i < list->count; i++) {
        printf("Deleted NFAPI_CRC_INDICATION_PDU_T with RNTI: %u\n", list->list[i].RNTI);
    }
    free(list->list);
    pthread_mutex_destroy(&list->mutex);
    free(list);
}

int add_crc_indication(NFAPICRCList* list, uint32_t rx_tag, uint32_t rnti, uint8_t crc_flag) {
    pthread_mutex_lock(&list->mutex);
    if (list->count >= list->max_size) {
        pthread_mutex_unlock(&list->mutex);
        return -1; // List is full
    }
    NFAPI_CRC_INDICATION_PDU_T new_record = {rx_tag, rnti, crc_flag};
    list->list[list->count++] = new_record;
    printf("Added NFAPI_CRC_INDICATION_PDU_T with RNTI: %u\n", rnti);
    pthread_mutex_unlock(&list->mutex);
    return 0;
}

int remove_crc_indication(NFAPICRCList* list, uint32_t rnti) {
    pthread_mutex_lock(&list->mutex);
    for (size_t i = 0; i < list->count; i++) {
        if (list->list[i].RNTI == rnti) {
            printf("Removed NFAPI_CRC_INDICATION_PDU_T with RNTI: %u\n", rnti);
            for (size_t j = i + 1; j < list->count; j++) {
                list->list[j - 1] = list->list[j];
            }
            list->count--;
            pthread_mutex_unlock(&list->mutex);
            return 0;
        }
    }
    pthread_mutex_unlock(&list->mutex);
    return -1; // RNTI not found
}

void* periodic_sync(void* arg) {
    NFAPICRCList* list = (NFAPICRCList*)arg;
    // Implement external system synchronization logic here
    printf("Performing periodic data synchronization\n");
    return NULL;
}

int main() {
    NFAPICRCList* crc_list = create_crc_list(MAX_RECORDS);
    if (!crc_list) {
        fprintf(stderr, "Failed to create CRC list\n");
        return 1;
    }

    // Simulate adding and removing records
    add_crc_indication(crc_list, 0x1234, 5678, 1);
    remove_crc_indication(crc_list, 5678);

    destroy_crc_list(crc_list);

    pthread_t sync_thread;
    if (pthread_create(&sync_thread, NULL, periodic_sync, crc_list) != 0) {
        fprintf(stderr, "Failed to create synchronization thread\n");
        return 1;
    }

    pthread_join(sync_thread, NULL);

    return 0;
}
