#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/evp.h>
#include <pthread.h>

#define MAX_RECORDS 1024
#define MIN_KEY 1
#define MAX_KEY 1000

typedef struct {
    int value;
} record;

record records[MAX_RECORDS];
int num_records = 0;
long offsets[MAX_RECORDS];
int keys[MAX_RECORDS];

void* create_cipher(char* cipher_name) {
    EVP_CIPHER* cipher;
    if (strcmp(cipher_name, "ECB") == 0) {
        cipher = EVP_des_ecb();
    } else if (strcmp(cipher_name, "EDE") == 0) {
        cipher = EVP_des_ede3_cbc();
    } else if (strcmp(cipher_name, "CFB") == 0) {
        cipher = EVP_des_cfb128();
    } else if (strcmp(cipher_name, "NULL") == 0) {
        cipher = NULL;
    } else {
        return NULL;
    }
    return (void*)cipher;
}

int validate_records() {
    for (int i = 0; i < num_records; i++) {
        for (int j = i + 1; j < num_records; j++) {
            if (keys[i] == keys[j]) {
                return 0;
            }
            if (offsets[i] < MIN_KEY || offsets[i] > MAX_KEY) {
                return 0;
            }
        }
    }
    return 1;
}

void* create_record(int value, long offset, int key) {
    if (num_records >= MAX_RECORDS) {
        return NULL;
    }
    record rec = {value};
    records[num_records] = rec;
    offsets[num_records] = offset;
    keys[num_records] = key;
    num_records++;
    printf("Record created: value=%d, offset=%ld, key=%d\n", value, offset, key);
    return &records[num_records - 1];
}

void delete_record(void* record_ptr) {
    int index = (record*)record_ptr - records;
    if (index < num_records) {
        printf("Record deleted: value=%d, offset=%ld, key=%d\n", records[index].value, offsets[index], keys[index]);
        for (int i = index; i < num_records - 1; i++) {
            records[i] = records[i + 1];
            offsets[i] = offsets[i + 1];
            keys[i] = keys[i + 1];
        }
        num_records--;
    } else {
        printf("Invalid record pointer\n");
    }
}

int find_largest_value() {
    int max_value = INT_MIN;
    for (int i = 0; i < num_records; i++) {
        if (records[i].value > max_value) {
            max_value = records[i].value;
        }
    }
    return max_value;
}

void* thread_func(void* arg) {
    char* cipher_name = (char*)arg;
    void* cipher = create_cipher(cipher_name);
    if (!cipher) {
        printf("Failed to create cipher\n");
        pthread_exit(NULL);
    }

    record* rec = create_record(123, 456, 789);
    if (!rec) {
        printf("Failed to create record\n");
        EVP_CIPHER_free(cipher);
        pthread_exit(NULL);
    }

    int largest_value = find_largest_value();
    printf("Largest value: %d\n", largest_value);

    delete_record(rec);
    EVP_CIPHER_free(cipher);
    pthread_exit(NULL);
}

int main() {
    pthread_t threads[10];
    for (int i = 0; i < 10; i++) {
        char* cipher_name = "ECB"; // Change this to test other ciphers
        pthread_create(&threads[i], NULL, thread_func, cipher_name);
    }

    for (int i = 0; i < 10; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
