#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_LIST_SIZE 1024
#define LOG_LEVEL_INFO 1
#define LOG_LEVEL_DEBUG 2

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct NFapiCrcIndicationList {
    NFAPI_CRC_INDICATION_PDU_T *items[MAX_LIST_SIZE];
    size_t count;
    pthread_mutex_t lock;
} NFapiCrcIndicationList;

NFapiCrcIndicationList* createNFApiCrcIndicationList() {
    NFapiCrcIndicationList* list = (NFapiCrcIndicationList*)malloc(sizeof(NFapiCrcIndicationList));
    if (!list) return NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->count = 0;
    return list;
}

void destroyNFApiCrcIndicationList(NFapiCrcIndicationList* list) {
    for (size_t i = 0; i < list->count; ++i) {
        free(list->items[i]);
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int addNFApiCrcIndicationPdu(NFapiCrcIndicationList* list, uint32_t rxTag, uint16_t rnti, uint8_t crcFlag) {
    pthread_mutex_lock(&list->lock);

    // Check if the list is full
    if (list->count >= MAX_LIST_SIZE) {
        pthread_mutex_unlock(&list->lock);
        return -1; // List overflow
    }

    // Check for unique RNTI
    for (size_t i = 0; i < list->count; ++i) {
        if (list->items[i]->RNTI == rnti) {
            pthread_mutex_unlock(&list->lock);
            return -2; // Duplicate RNTI
        }
    }

    // Allocate memory for the new item
    NFAPI_CRC_INDICATION_PDU_T* newItem = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!newItem) {
        pthread_mutex_unlock(&list->lock);
        return -3; // Memory allocation failed
    }

    newItem->RX_UE_INFORMATION_TAG = rxTag;
    newItem->RNTI = rnti;
    newItem->CRCFLAG = crcFlag;

    list->items[list->count++] = newItem;
    pthread_mutex_unlock(&list->lock);

    return 0; // Success
}

void logNFApiCrcIndicationListOperation(int level, const char* message) {
    // Implement logging based on the specified level and message
    // Use an existing logging framework for comprehensive audit trails
}

// Example usage:
int main() {
    NFapiCrcIndicationList* list = createNFApiCrcIndicationList();
    if (!list) {
        logNFApiCrcIndicationListOperation(LOG_LEVEL_ERROR, "Failed to create NFAPI CRC Indication List");
        return 1;
    }

    srand(time(NULL));
    for (int i = 0; i < 10; ++i) {
        int result = addNFApiCrcIndicationPdu(list, rand() % 100000, rand() % 4096, rand() % 2);
        if (result != 0) {
            logNFApiCrcIndicationListOperation(LOG_LEVEL_ERROR, "Failed to add NFAPI CRC Indication PDU");
            break;
        }
    }

    destroyNFApiCrcIndicationList(list);
    return 0;
}
