#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    time_t timestamp;
    char type[50];
    char payload[];
} NetworkEvent;

typedef struct {
    NetworkEvent *events;
    size_t count;
    size_t capacity;
} EventArray;

void init_event_array(EventArray *array, size_t initial_capacity) {
    array->events = (NetworkEvent *)malloc(initial_capacity * sizeof(NetworkEvent));
    array->count = 0;
    array->capacity = initial_capacity;
}

void resize_event_array(EventArray *array, size_t new_capacity) {
    NetworkEvent *new_events = (NetworkEvent *)realloc(array->events, new_capacity * sizeof(NetworkEvent));
    if (new_events) {
        array->events = new_events;
        array->capacity = new_capacity;
    }
}

void insert_event(EventArray *array, time_t timestamp, const char *type, const char *payload) {
    if (array->count >= array->capacity) {
        resize_event_array(array, array->capacity * 2);
    }
    NetworkEvent *new_event = &array->events[array->count++];
    new_event->timestamp = timestamp;
    strncpy(new_event->type, type, sizeof(new_event->type) - 1);
    size_t payload_len = strlen(payload) + 1;
    new_event->payload = (char *)malloc(payload_len);
    strcpy(new_event->payload, payload);
}

void delete_event(EventArray *array, size_t index) {
    if (index < array->count) {
        free(array->events[index].payload);
        for (size_t i = index; i < array->count - 1; ++i) {
            array->events[i] = array->events[i + 1];
        }
        array->count--;
    }
}

NetworkEvent *find_event_by_type(EventArray *array, const char *type) {
    for (size_t i = 0; i < array->count; ++i) {
        if (strcmp(array->events[i].type, type) == 0) {
            return &array->events[i];
        }
    }
    return NULL;
}

void serialize_event_array(EventArray *array, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (file) {
        fwrite(&array->count, sizeof(size_t), 1, file);
        for (size_t i = 0; i < array->count; ++i) {
            fwrite(&array->events[i].timestamp, sizeof(time_t), 1, file);
            size_t type_len = strlen(array->events[i].type) + 1;
            fwrite(&type_len, sizeof(size_t), 1, file);
            fwrite(array->events[i].type, 1, type_len, file);
            size_t payload_len = strlen(array->events[i].payload) + 1;
            fwrite(&payload_len, sizeof(size_t), 1, file);
            fwrite(array->events[i].payload, 1, payload_len, file);
        }
        fclose(file);
    }
}

void deserialize_event_array(EventArray *array, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (file) {
        size_t count;
        fread(&count, sizeof(size_t), 1, file);
        resize_event_array(array, count);
        for (size_t i = 0; i < count; ++i) {
            fread(&array->events[i].timestamp, sizeof(time_t), 1, file);
            size_t type_len;
            fread(&type_len, sizeof(size_t), 1, file);
            array->events[i].type = (char *)malloc(type_len);
            fread(array->events[i].type, 1, type_len, file);
            size_t payload_len;
            fread(&payload_len, sizeof(size_t), 1, file);
            array->events[i].payload = (char *)malloc(payload_len);
            fread(array->events[i].payload, 1, payload_len, file);
        }
        fclose(file);
    }
}

void free_event_array(EventArray *array) {
    for (size_t i = 0; i < array->count; ++i) {
        free(array->events[i].payload);
    }
    free(array->events);
}
