#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <arpa/inet.h>
#include <netdb.h>
#include <pthread.h>
#include <time.h>

#define CACHE_SIZE 100
#define MAX_IPS_PER_HOST 5
#define TTL (60 * 60) // Time to live for cache entries in seconds

struct CacheEntry {
    char hostname[NI_MAXHOST];
    struct sockaddr_in ips[MAX_IPS_PER_HOST];
    int ip_count;
    time_t last_accessed;
};

struct Cache {
    struct CacheEntry entries[CACHE_SIZE];
    pthread_mutex_t lock;
};

struct Cache g_cache;

int resolveHostname(const char *hostname, struct sockaddr_in **ips, int *ip_count) {
    // Check cache
    pthread_mutex_lock(&g_cache.lock);
    for (int i = 0; i < CACHE_SIZE; ++i) {
        if (strcmp(g_cache.entries[i].hostname, hostname) == 0 && time(NULL) - g_cache.entries[i].last_accessed <= TTL) {
            memcpy(ips, g_cache.entries[i].ips, sizeof(struct sockaddr_in) * g_cache.entries[i].ip_count);
            *ip_count = g_cache.entries[i].ip_count;
            pthread_mutex_unlock(&g_cache.lock);
            return 0; // Cache hit
        }
    }
    pthread_mutex_unlock(&g_cache.lock);

    // Fallback to system resolver
    struct addrinfo hints, *res;
    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET;
    hints.ai_socktype = SOCK_STREAM;

    int status = getaddrinfo(hostname, NULL, &hints, &res);
    if (status != 0) {
        return -1; // System resolver failed
    }

    *ip_count = 0;
    struct sockaddr_in *new_ips = malloc(sizeof(struct sockaddr_in) * MAX_IPS_PER_HOST);
    if (!new_ips) {
        freeaddrinfo(res);
        return -2; // Memory allocation failed
    }

    for (struct addrinfo *p = res; p != NULL && *ip_count < MAX_IPS_PER_HOST; p = p->ai_next, ++(*ip_count)) {
        if (p->ai_family == AF_INET) {
            new_ips[*ip_count] = *(struct sockaddr_in *)p->ai_addr;
        }
    }

    freeaddrinfo(res);

    // Update cache
    pthread_mutex_lock(&g_cache.lock);
    int next_empty_slot = -1;
    for (int i = 0; i < CACHE_SIZE; ++i) {
        if (next_empty_slot == -1 && g_cache.entries[i].hostname[0] == '\0') {
            next_empty_slot = i;
        }
    }

    if (next_empty_slot != -1) {
        strncpy(g_cache.entries[next_empty_slot].hostname, hostname, NI_MAXHOST);
        memcpy(g_cache.entries[next_empty_slot].ips, new_ips, sizeof(struct sockaddr_in) * (*ip_count));
        g_cache.entries[next_empty_slot].ip_count = *ip_count;
        g_cache.entries[next_empty_slot].last_accessed = time(NULL);
    }
    pthread_mutex_unlock(&g_cache.lock);

    free(new_ips);
    return 0; // DNS resolution successful
}
