#include <stdlib.h>
#include <pthread.h>

typedef struct {
    RX_UE_INFORMATION_TAG ue_info;
    uint16_t rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
    WiFiNetworkConfig config;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pdus;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} PDULinkedList;

PDULinkedList* create_pdu_list(size_t initial_capacity) {
    PDULinkedList *list = malloc(sizeof(PDULinkedList));
    if (list == NULL) {
        return NULL; // Handle memory allocation failure
    }
    list->pdus = malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (list->pdus == NULL) {
        free(list);
        return NULL;
    }
    pthread_mutex_init(&list->lock, NULL);
    list->capacity = initial_capacity;
    list->size = 0;
    return list;
}

void destroy_pdu_list(PDULinkedList *list) {
    if (list != NULL) {
        pthread_mutex_lock(&list->lock);
        free(list->pdus);
        list->pdus = NULL;
        list->capacity = 0;
        list->size = 0;
        pthread_mutex_unlock(&list->lock);
        pthread_mutex_destroy(&list->lock);
        free(list);
    }
}

int add_pdu(PDULinkedList *list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&list->lock);
    if (list->size >= list->capacity) {
        size_t new_capacity = list->capacity == 0 ? 1 : list->capacity * 2;
        void *new_memory = realloc(list->pdus, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (new_memory == NULL) {
            pthread_mutex_unlock(&list->lock);
            return -1; // Handle memory allocation failure
        }
        list->pdus = new_memory;
        list->capacity = new_capacity;
    }
    list->pdus[list->size++] = pdu;
    pthread_mutex_unlock(&list->lock);
    return 0;
}

// Additional functions and error handling can be implemented here
