NFAPI_CRC_INDICATION_PDU_T* generate_NFAPduList(int N, int *cache, int cache_size, int checksum_validation) {
    static int next_rnti = 1;
    static NFAPI_CRC_INDICATION_PDU_T *pdu_list = NULL;
    static size_t total_memory_used = 0;

    if (pdu_list == NULL) {
        pdu_list = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * N);
    }

    srand(time(NULL));
    for (int i = 0; i < N; i++) {
        while (1) {
            int rnti;
            // Implement caching mechanism for RNTI values
            if (cache != NULL && cache_size > 0) {
                // Search in cache first
                int found = 0;
                for (int j = 0; j < cache_size; j++) {
                    if (cache[j] == next_rnti) {
                        rnti = next_rnti;
                        found = 1;
                        break;
                    }
                }
                if (!found) {
                    // If not in cache, add to cache
                    if (cache_size > 0) {
                        cache[0] = next_rnti;
                        for (int j = 1; j < cache_size - 1; j++) {
                            cache[j] = cache[j + 1];
                        }
                    } else {
                        // Cache is full, overwrite the oldest entry
                        cache[cache_size - 1] = next_rnti;
                    }
                }
            } else {
                rnti = next_rnti;
            }

            if (i == 0 || pdu_list[i-1].RNTI != rnti) {
                // Populate the structure with valid values
                pdu_list[i].RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
                pdu_list[i].RNTI = rnti;
                pdu_list[i].CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
                pdu_list[i].CRCFLAG = rand() % 2; // Randomly set CRCFLAG

                total_memory_used += sizeof(NFAPI_CRC_INDICATION_PDU_T);
                if (total_memory_used > MAX_MEMORY_THRESHOLD) {
                    free(pdu_list);
                    pdu_list = NULL;
                    return NULL;
                }

                next_rnti++;
                break;
            }
        }
    }

    if (checksum_validation) {
        // Implement checksum validation logic
    }

    return pdu_list;
}
