    float MEASUREMENT_QUALITY_FACTOR[NR_CELL_MEASUREMENT_DATA_SIZE];
} NR_CELL_MEASUREMENT_RECORD;

typedef struct cell_node {
    NR_CELL_MEASUREMENT_RECORD data;
    struct cell_node* next;
} CELL_NODE;

typedef struct {
    CELL_NODE* head;
    int size;
} CELL_LIST;

void initialize_cell_list(CELL_LIST* list) {
    list->head = NULL;
    list->size = 0;
}

int insert_cell_record(CELL_LIST* list, NR_CELL_MEASUREMENT_RECORD record) {
    CELL_NODE* new_node = (CELL_NODE*)malloc(sizeof(CELL_NODE));
    if (!new_node) return -1; // Memory allocation failure

    new_node->data = record;
    new_node->next = NULL;

    if (list->head == NULL || list->head->data.MEASUREMENT_TIME > record.MEASUREMENT_TIME) {
        new_node->next = list->head;
        list->head = new_node;
    } else {
        CELL_NODE* current = list->head;
        while (current->next != NULL && current->next->data.MEASUREMENT_TIME < record.MEASUREMENT_TIME) {
            current = current->next;
        }
        new_node->next = current->next;
        current->next = new_node;
    }

    list->size++;
    return 0;
}

int delete_cell_record(CELL_LIST* list, int cell_id) {
    CELL_NODE* current = list->head;
    CELL_NODE* previous = NULL;

    while (current != NULL && current->data.CELL_ID != cell_id) {
        previous = current;
        current = current->next;
    }

    if (current == NULL) return -1; // Cell not found

    if (previous == NULL) {
        list->head = current->next;
    } else {
        previous->next = current->next;
    }

    free(current);
    list->size--;
    return 0;
}

NR_CELL_MEASUREMENT_RECORD* find_cell_record(CELL_LIST* list, int cell_id) {
    CELL_NODE* current = list->head;

    while (current != NULL && current->data.CELL_ID != cell_id) {
        current = current->next;
    }

    if (current == NULL) return NULL; // Cell not found

    return &current->data;
}

void destroy_cell_list(CELL_LIST* list) {
    CELL_NODE* current = list->head;
    while (current != NULL) {
        CELL_NODE* temp = current;
        current = current->next;
        free(temp);
    }
    list->head = NULL;
    list->size = 0;
}

void generate_random_cell_record(NR_CELL_MEASUREMENT_RECORD* record) {
    srand(time(NULL));
    record->CELL_ID = rand() % 1000;
    record->MEASUREMENT_TIME = time(NULL);
    for (int i = 0; i < NR_CELL_MEASUREMENT_DATA_SIZE; i++) {
        record->MEASUREMENT_QUALITY_FACTOR[i] = ((float)rand()) / RAND_MAX;
    }
}

