#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define NFAPI_CRC_INDICATION_PDU_T // Assume this is defined elsewhere

typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_info_tag;
    int rnti;
} CRC_INDICATION_REL8_TAG;

typedef struct {
    pthread_mutex_t mutex;
    NFAPI_CRC_INDICATION_PDU_T* array;
    size_t capacity;
    size_t count;
    void* (*allocate)(size_t size);
} DynamicArray;

int initialize_dynamic_array(DynamicArray* da, size_t initial_capacity, void* (*allocator)(size_t)) {
    if (!allocator) return -1; // Null allocator check
    da->mutex = (pthread_mutex_t){};
    pthread_mutex_init(&da->mutex, NULL);
    da->array = (NFAPI_CRC_INDICATION_PDU_T*)allocator(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!da->array) {
        pthread_mutex_destroy(&da->mutex);
        return -2; // Out of memory
    }
    da->capacity = initial_capacity;
    da->count = 0;
    da->allocate = allocator;
    return 0;
}

int populate_dynamic_array(DynamicArray* da, size_t N, RX_UE_INFORMATION_TAG* rx_ue_info_tags, int* rntis) {
    if (!rx_ue_info_tags || !rntis || !da->array) return -1; // Null pointer check

    pthread_mutex_lock(&da->mutex);
    if (N + da->count > da->capacity) {
        size_t new_capacity = (da->capacity * 3) / 2 + N;
        NFAPI_CRC_INDICATION_PDU_T* new_array = (NFAPI_CRC_INDICATION_PDU_T*)da->allocate(new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_array) {
            pthread_mutex_unlock(&da->mutex);
            return -2; // Out of memory
        }
        memcpy(new_array, da->array, da->count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        free(da->array);
        da->array = new_array;
        da->capacity = new_capacity;
    }

    for (size_t i = 0; i < N; ++i) {
        da->array[da->count + i].rx_ue_info_tag = rx_ue_info_tags[i];
        da->array[da->count + i].crc_indication_rel8_tag.rnti = rntis[i];
        // Randomly set CRCFLAG
        da->array[da->count + i].crc_indication_rel8_tag.crcflag = rand() % 2;
    }
    da->count += N;
    pthread_mutex_unlock(&da->mutex);
    return 0;
}

void destroy_dynamic_array(DynamicArray* da) {
    if (!da) return;
    pthread_mutex_lock(&da->mutex);
    free(da->array);
    pthread_mutex_destroy(&da->mutex);
}
