#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_LOG_MESSAGE_LENGTH 256
#define INITIAL_CAPACITY 10

typedef enum {
    SEVERITY_INFO,
    SEVERITY_WARNING,
    SEVERITY_ERROR
} SeverityLevel;

typedef struct LogEvent {
    int event_id;
    SeverityLevel severity_level;
    time_t timestamp;
    char log_message[MAX_LOG_MESSAGE_LENGTH];
} LogEvent;

typedef struct LogCollection {
    LogEvent *events;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} LogCollection;

void log_collection_init(LogCollection *collection) {
    collection->capacity = INITIAL_CAPACITY;
    collection->count = 0;
    collection->events = malloc(collection->capacity * sizeof(LogEvent));
    if (collection->events == NULL) {
        fprintf(stderr, "Memory allocation failed for log collection\n");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_init(&collection->lock, NULL);
}

void log_collection_destroy(LogCollection *collection) {
    pthread_mutex_lock(&collection->lock);
    free(collection->events);
    collection->events = NULL;
    pthread_mutex_unlock(&collection->lock);
    pthread_mutex_destroy(&collection->lock);
}

int log_collection_insert(LogCollection *collection, LogEvent *event) {
    pthread_mutex_lock(&collection->lock);

    if (collection->count >= collection->capacity) {
        size_t new_capacity = collection->capacity * 2;
        LogEvent *new_events = realloc(collection->events, new_capacity * sizeof(LogEvent));
        if (new_events == NULL) {
            fprintf(stderr, "Memory allocation failed for log collection resize\n");
            pthread_mutex_unlock(&collection->lock);
            return -1;
        }
        collection->events = new_events;
        collection->capacity = new_capacity;
    }

    size_t insert_index = collection->count;
    while (insert_index > 0 && collection->events[insert_index - 1].timestamp > event->timestamp) {
        collection->events[insert_index] = collection->events[insert_index - 1];
        insert_index--;
    }
    if (insert_index < collection->count && collection->events[insert_index].event_id == event->event_id) {
        pthread_mutex_unlock(&collection->lock);
        return -2; // Duplicate entry
    }

    memmove(&collection->events[insert_index + 1], &collection->events[insert_index], (collection->count - insert_index) * sizeof(LogEvent));
    collection->events[insert_index] = *event;
    collection->count++;

    pthread_mutex_unlock(&collection->lock);
    return 0;
}

void log_collection_delete(LogCollection *collection, int event_id) {
    pthread_mutex_lock(&collection->lock);

    for (size_t i = 0; i < collection->count; i++) {
        if (collection->events[i].event_id == event_id) {
            memmove(&collection->events[i], &collection->events[i + 1], (collection->count - i - 1) * sizeof(LogEvent));
            collection->count--;
            break;
        }
    }

    pthread_mutex_unlock(&collection->lock);
}

void log_collection_filter(LogCollection *collection, SeverityLevel min_severity, SeverityLevel max_severity,
                            time_t start_timestamp, time_t end_timestamp, LogEvent **filtered_events, size_t *filtered_count) {
    pthread_mutex_lock(&collection->lock);

    *filtered_count = 0;
    for (size_t i = 0; i < collection->count; i++) {
        if (collection->events[i].severity_level >= min_severity && collection->events[i].severity_level <= max_severity &&
            (start_timestamp == 0 || start_timestamp < collection->events[i].timestamp) &&
            (end_timestamp == 0 || collection->events[i].timestamp < end_timestamp)) {
            if (*filtered_count == *collection->capacity) {
                size_t new_capacity = *collection->capacity * 2;
                LogEvent *new_events = realloc(*filtered_events, new_capacity * sizeof(LogEvent));
                if (new_events == NULL) {
                    fprintf(stderr, "Memory allocation failed for filtered log events resize\n");
                    pthread_mutex_unlock(&collection->lock);
                    return;
                }
                *filtered_events = new_events;
                *collection->capacity = new_capacity;
            }
            (*filtered_events)[(*filtered_count)++] = collection->events[i];
        }
    }

    pthread_mutex_unlock(&collection->lock);
}

int main() {
    LogCollection log_collection;
    log_collection_init(&log_collection);

    // Example usage
    LogEvent event1 = {1, SEVERITY_ERROR, time(NULL), "Error occurred"};
    LogEvent event2 = {2, SEVERITY_WARNING, time(NULL) + 3600, "Warning message"};
    log_collection_insert(&log_collection, &event1);
    log_collection_insert(&log_collection, &event2);

    // Filtering events
    LogEvent *filtered_events;
    size_t filtered_count;
    log_collection_filter(&log_collection, SEVERITY_WARNING, SEVERITY_ERROR, 0, 0, &filtered_events, &filtered_count);

    for (size_t i = 0; i < filtered_count; i++) {
        printf("Event ID: %d, Severity: %d, Timestamp: %s, Message: %s\n",
               filtered_events[i].event_id, filtered_events[i].severity_level,
               ctime(&filtered_events[i].timestamp), filtered_events[i].log_message);
    }

    free(filtered_events);
    log_collection_destroy(&log_collection);

    return 0;
}
