// Function to create a new packet header with random values
PacketHeader* create_packet_header(int seed, int packet_count) {
    srand(seed + packet_count);
    PacketHeader *header = (PacketHeader*)malloc(sizeof(PacketHeader));
    if (!header) {
        perror("Failed to allocate memory for packet header");
        return NULL;
    }
    // Simulate random generation of source and destination IPs
    snprintf(header->source_ip, sizeof(header->source_ip), "192.168.%d.%d", rand() % 255, rand() % 255);
    snprintf(header->destination_ip, sizeof(header->destination_ip), "10.0.%d.%d", rand() % 255, rand() % 255);
    header->protocol_type = rand() % 100; // Random protocol type
    header->length = rand() % 1500 + 64; // Random length with minimum of 64 bytes for Ethernet headers

    // Log the creation of the packet header
    pthread_mutex_lock(&log_mutex);
    fprintf(log_file, "Created packet header: Source IP=%s, Destination IP=%s, Protocol Type=%d, Length=%d\n",
            header->source_ip, header->destination_ip, header->protocol_type, header->length);
    fflush(log_file);
    pthread_mutex_unlock(&log_mutex);

    return header;
}

// Function to prioritize packets based on protocol type
PacketHeader* prioritize_packet(PacketHeader *packet, int critical_protocol) {
    if (packet && packet->protocol_type == critical_protocol) {
        // Simulate adding a unique identifier for critical packets
        static int id_counter = 0;
        pthread_mutex_lock(&log_mutex);
        fprintf(log_file, "Prioritized packet with protocol type %d\n", critical_protocol);
        fflush(log_file);
        pthread_mutex_unlock(&log_mutex);
        return packet; // Return the same packet but potentially updated
    }
    return NULL; // Do not process non-critical packets
}

// Function to handle network packets
PacketHeader* process_packet(const char *interface, int size_limit, FILE *log_fd) {
    log_file = log_fd;
    pthread_mutex_lock(&log_mutex);
    fprintf(log_file, "Processing packet on interface %s with size limit %d\n", interface, size_limit);
    fflush(log_file);
    pthread_mutex_unlock(&log_mutex);

    PacketHeader *packet = create_packet_header(42, 1); // Example seed and count
    if (packet) {
        packet = prioritize_packet(packet, 6); // Assuming TCP protocol has type 6
        if (!packet) {
            free(packet);
        }
    }

    return packet;
}

int main() {
    FILE *log_fd = fopen("network_log.txt", "w");
    if (!log_fd) {
        perror("Failed to open log file");
        return EXIT_FAILURE;
    }

    PacketHeader *processed_packet = process_packet("eth0", 1500, log_fd);
    if (processed_packet) {
        printf("Processed packet with unique ID: %d\n", processed_packet->unique_id);
        free(processed_packet);
    } else {
        printf("No critical packet to process.\n");
    }

    fclose(log_fd);
    return EXIT_SUCCESS;
}
