#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct LOG_EVENT {
    int EVENT_ID;
    int SEVERITY_LEVEL;
    time_t TIMESTAMP;
    char* LOG_MESSAGE;
} LOG_EVENT;

typedef struct LOG_NODE {
    LOG_EVENT event;
    struct LOG_NODE* next;
} LOG_NODE;

typedef struct LOG_COLLECTION {
    LOG_NODE* head;
    pthread_mutex_t mutex;
} LOG_COLLECTION;

void log_event_insert(LOG_COLLECTION* collection, int EVENT_ID, int SEVERITY_LEVEL, time_t TIMESTAMP, const char* LOG_MESSAGE) {
    pthread_mutex_lock(&collection->mutex);
    LOG_NODE* new_node = (LOG_NODE*)malloc(sizeof(LOG_NODE));
    if (!new_node) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }
    new_node->event.EVENT_ID = EVENT_ID;
    new_node->event.SEVERITY_LEVEL = SEVERITY_LEVEL;
    new_node->event.TIMESTAMP = TIMESTAMP;
    new_node->event.LOG_MESSAGE = strdup(LOG_MESSAGE);
    new_node->next = NULL;

    if (!collection->head || collection->head->event.TIMESTAMP >= TIMESTAMP) {
        new_node->next = collection->head;
        collection->head = new_node;
    } else {
        LOG_NODE* current = collection->head;
        while (current->next && current->next->event.TIMESTAMP < TIMESTAMP) {
            current = current->next;
        }
        new_node->next = current->next;
        current->next = new_node;
    }
    pthread_mutex_unlock(&collection->mutex);
}

void log_event_delete(LOG_COLLECTION* collection, int EVENT_ID, time_t TIMESTAMP) {
    pthread_mutex_lock(&collection->mutex);
    LOG_NODE* current = collection->head;
    LOG_NODE* previous = NULL;

    while (current) {
        if (current->event.EVENT_ID == EVENT_ID && current->event.TIMESTAMP == TIMESTAMP) {
            if (previous) {
                previous->next = current->next;
            } else {
                collection->head = current->next;
            }
            free(current->event.LOG_MESSAGE);
            free(current);
            break;
        }
        previous = current;
        current = current->next;
    }
    pthread_mutex_unlock(&collection->mutex);
}

LOG_NODE* log_event_retrieve(LOG_COLLECTION* collection, int EVENT_ID) {
    pthread_mutex_lock(&collection->mutex);
    LOG_NODE* current = collection->head;
    while (current) {
        if (current->event.EVENT_ID == EVENT_ID) {
            break;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&collection->mutex);
    return current;
}

void log_event_filter(LOG_COLLECTION* collection, int SEVERITY_LEVEL, time_t start_time, time_t end_time, int inclusive_start, int inclusive_end) {
    pthread_mutex_lock(&collection->mutex);
    LOG_NODE* current = collection->head;
    while (current) {
        if ((inclusive_start ? current->event.TIMESTAMP >= start_time : current->event.TIMESTAMP > start_time) &&
            (inclusive_end ? current->event.TIMESTAMP <= end_time : current->event.TIMESTAMP < end_time) &&
            current->event.SEVERITY_LEVEL == SEVERITY_LEVEL) {
            // Process the event
        }
        current = current->next;
    }
    pthread_mutex_unlock(&collection->mutex);
}

void log_collection_destroy(LOG_COLLECTION* collection) {
    pthread_mutex_lock(&collection->mutex);
    while (collection->head) {
        LOG_NODE* temp = collection->head;
        collection->head = collection->head->next;
        free(temp->event.LOG_MESSAGE);
        free(temp);
    }
    pthread_mutex_unlock(&collection->mutex);
    pthread_mutex_destroy(&collection->mutex);
}
