// Define a structure for network packet headers
typedef struct PacketHeader {
    char sourceIP[16];
    char destinationIP[16];
    int protocolType;
    int packetLength;
    unsigned long uniqueID; // Unique identifier to be appended if criteria met
} PacketHeader;

// Function to dynamically manage network packet headers
PacketHeader* managePacketHeaders(int numHeaders, unsigned int seed) {
    PacketHeader *headers = (PacketHeader *)malloc(numHeaders * sizeof(PacketHeader));
    if (!headers) {
        perror("Memory allocation failed");
        return NULL;
    }

    srand(seed);
    for (int i = 0; i < numHeaders; i++) {
        // Initialize random source and destination IPs
        snprintf(headers[i].sourceIP, 16, "%d.%d.%d.%d", rand() % 256, rand() % 256, rand() % 256, rand() % 256);
        snprintf(headers[i].destinationIP, 16, "%d.%d.%d.%d", rand() % 256, rand() % 256, rand() % 256, rand() % 256);

        // Random protocol type
        headers[i].protocolType = rand() % 10;

        // Random packet length
        headers[i].packetLength = rand() % 1000 + 100;

        // Log creation of each header
        printf("Created header: Source IP=%s, Destination IP=%s, Protocol Type=%d, Packet Length=%d\n",
               headers[i].sourceIP, headers[i].destinationIP, headers[i].protocolType, headers[i].packetLength);
    }

    return headers;
}

// Function to prioritize packets based on specific criteria
PacketHeader* prioritizePacket(PacketHeader *header) {
    if (header->protocolType == 6 || header->protocolType == 17) { // TCP or UDP
        printf("Prioritizing packet with protocol type: %d\n", header->protocolType);
        return header;
    } else {
        printf("Non-critical packet, not prioritized.\n");
        return NULL;
    }
}

// Main function to demonstrate usage
int main() {
    int numHeaders = 5;
    unsigned int seed = time(NULL);

    PacketHeader *headers = managePacketHeaders(numHeaders, seed);
    if (headers) {
        for (int i = 0; i < numHeaders; i++) {
            prioritizePacket(&headers[i]);
        }
        free(headers);
    }

    return 0;
}
```

This code provides a basic structure for managing network packet headers with dynamic memory allocation and logging. It includes functions to create packet headers with random values, prioritize packets based on protocol type, and manage memory efficiently. The code demonstrates the use of structures, random number generation, and basic file I/O for logging purposes.']

