import java.io.IOException;
import java.nio.file.Files;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.logging.Level;
import java.util.logging.Logger;

public class PacketProcessor {

    private static final Logger logger = Logger.getLogger(PacketProcessor.class.getName());
    private final int sizeLimit;
    private final String logFilePath;

    public PacketProcessor(int sizeLimit, String logFilePath) {
        this.sizeLimit = sizeLimit;
        this.logFilePath = logFilePath;
    }

    public Map<String, String> processPacketHeaders(List<String> headers) {
        Map<String, String> hashMap = new ConcurrentHashMap<>();
        int processedCount = 0;
        int skippedCount = 0;

        long startTime = System.currentTimeMillis();

        for (String header : headers) {
            if (header == null || header.isEmpty()) {
                logger.warning("Skipping null or empty header");
                skippedCount++;
                continue;
            }

            try {
                String hash = computeMD5Hash(header);
                hashMap.put(header, hash);
                processedCount++;
            } catch (IOException e) {
                logger.log(Level.SEVERE, "Error processing packet header: " + header, e);
            }
        }

        long endTime = System.currentTimeMillis();
        int totalCount = processedCount + skippedCount;
        double totalProcessingTime = (endTime - startTime) / 1000.0;

        generatePerformanceReport(processedCount, skippedCount, totalProcessingTime);

        return hashMap;
    }

    private String computeMD5Hash(String data) throws IOException {
        MessageDigest digest;
        try {
            digest = MessageDigest.getInstance("MD5");
        } catch (NoSuchAlgorithmException e) {
            throw new IOException("Error computing MD5 hash", e);
        }
        byte[] hashBytes = digest.digest(data.getBytes());
        StringBuilder hexString = new StringBuilder();
        for (byte b : hashBytes) {
            String hex = Integer.toHexString(0xff & b);
            if(hex.length() == 1) hexString.append('0');
            hexString.append(hex);
        }
        return hexString.toString();
    }

    private void generatePerformanceReport(int processedCount, int skippedCount, double totalProcessingTime) {
        logger.info("Processed " + processedCount + " headers");
        logger.info("Skipped " + skippedCount + " headers");
        logger.info("Total processing time: " + totalProcessingTime + " seconds");
    }
}
