['```c
#include <stdlib.h>
#include <time.h>
#include <pthread.h>
#include <sys/time.h>

#define MAX_PATH_LENGTH 256

typedef struct {
    char path[MAX_PATH_LENGTH];
    time_t last_accessed;
    off_t size;
    uint32_t metadata_version;
} FileDescriptorStat;

typedef struct {
    FileDescriptorStat *stats;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} FDStatsCollection;

void init_fd_stats_collection(FDStatsCollection *collection, size_t initial_capacity) {
    collection->capacity = initial_capacity;
    collection->count = 0;
    collection->stats = (FileDescriptorStat *)malloc(initial_capacity * sizeof(FileDescriptorStat));
    if (!collection->stats) {
        perror("Failed to allocate memory for FD stats collection");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_init(&collection->lock, NULL);
}

void free_fd_stats_collection(FDStatsCollection *collection) {
    free(collection->stats);
    pthread_mutex_destroy(&collection->lock);
}

void add_file_descriptor_stat(FDStatsCollection *collection, const char *path, off_t size) {
    pthread_mutex_lock(&collection->lock);
    if (collection->count == collection->capacity) {
        collection->capacity *= 2;
        FileDescriptorStat *new_stats = (FileDescriptorStat *)realloc(collection->stats, collection->capacity * sizeof(FileDescriptorStat));
        if (!new_stats) {
            perror("Failed to reallocate memory for FD stats collection");
            exit(EXIT_FAILURE);
        }
        collection->stats = new_stats;
    }

    struct timeval now;
    gettimeofday(&now, NULL);
    time_t current_time = now.tv_sec;

    strncpy(collection->stats[collection->count].path, path, MAX_PATH_LENGTH - 1);
    collection->stats[collection->count].last_accessed = current_time;
    collection->stats[collection->count].size = size;
    collection->stats[collection->count].metadata_version = rand();

    printf("Added FD stat for %s, last accessed: %ld, size: %ld, metadata version: %u\n",
           path, current_time, size, collection->stats[collection->count].metadata_version);

    collection->count++;
    pthread_mutex_unlock(&collection->lock);
}

void update_file_descriptor_stat(FDStatsCollection *collection, const char *path, off_t new_size) {
    pthread_mutex_lock(&collection->lock);
    for (size_t i = 0; i < collection->count; i++) {
        if (strcmp(collection->stats[i].path, path) == 0) {
            struct timeval now;
            gettimeofday(&now, NULL);
            time_t current_time = now.tv_sec;

            collection->stats[i].last_accessed = current_time;
            collection->stats[i].size = new_size;
            collection->stats[i].metadata_version++;

            printf("Updated FD stat for %s, last accessed: %ld, size: %ld, metadata version: %u\n",
                   path, current_time, new_size, collection->stats[i].metadata_version);

            pthread_mutex_unlock(&collection->lock);
            return;
        }
    }
    pthread_mutex_unlock(&collection->lock);
    printf("FD stat for %s not found\n", path);
}

int main() {
    srand(time(NULL));
    FDStatsCollection fd_stats_collection;
    init_fd_stats_collection(&fd_stats_collection, 10);

    add_file_descriptor_stat(&fd_stats_collection, "/path/to/file1", 1024);
    update_file_descriptor_stat(&fd_stats_collection, "/path/to/file1", 2048);

    free_fd_stats_collection(&fd_stats_collection);
    return 0;
}
