typedef struct {
    int type;
    size_t length;
    unsigned char buffer[];
} DATA_ELEMENT;

typedef struct {
    // Define the fields for RX_UE_INFORMATION_TAG and RNTI here
    int tag;
    int rnti;
} RX_UE_INFORMATION;

typedef struct {
    RX_UE_INFORMATION rx_ue_info;
    int crc_flag;
    DATA_ELEMENT* data_elements;
    size_t num_data_elements;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T** allocate_pdus(size_t n, size_t m) {
    if (n == 0 || m == 0) {
        return NULL;
    }

    if (m > MAX_DATA_ELEMENTS) {
        fprintf(stderr, "Error: M exceeds maximum allowed data elements.\n");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T** pdus = malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    if (pdus == NULL) {
        perror("Memory allocation failed for PDUs.");
        return NULL;
    }

    srand(time(NULL));

    for (size_t i = 0; i < n; ++i) {
        pdus[i] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (pdus[i] == NULL) {
            perror("Memory allocation failed for PDU.");
            // Free previously allocated PDUs
            for (size_t j = 0; j < i; ++j) {
                free(pdus[j]);
            }
            free(pdus);
            return NULL;
        }

        // Initialize RX_UE_INFORMATION and RNTI here, possibly from an external source with retry logic
        pdus[i]->rx_ue_info.tag = rand();
        pdus[i]->rx_ue_info.rnti = rand();

        pdus[i]->crc_flag = (rand() % 2) ? 1 : 0;

        pdus[i]->data_elements = malloc(m * sizeof(DATA_ELEMENT));
        if (pdus[i]->data_elements == NULL) {
            perror("Memory allocation failed for data elements.");
            // Free previously allocated PDUs
            for (size_t j = 0; j <= i; ++j) {
                free(pdus[j]);
            }
            free(pdus);
            return NULL;
        }

        for (size_t j = 0; j < m; ++j) {
            pdus[i]->data_elements[j].type = rand() % 3; // Example type values
            pdus[i]->data_elements[j].length = rand() % 1024; // Random length up to 1KB
            pdus[i]->data_elements[j].buffer = malloc(pdus[i]->data_elements[j].length);
            if (pdus[i]->data_elements[j].buffer == NULL) {
                perror("Memory allocation failed for buffer.");
                // Free previously allocated PDUs and data elements
                for (size_t k = 0; k <= i; ++k) {
                    free(pdus[k]->data_elements);
                    free(pdus[k]);
                }
                free(pdus);
                return NULL;
            }

            // Initialize buffer with random data
            for (size_t k = 0; k < pdus[i]->data_elements[j].length; ++k) {
                pdus[i]->data_elements[j].buffer[k] = rand() % 256;
            }
        }

        pdus[i]->num_data_elements = m;
    }

    return pdus;
}

void free_pdus(NFAPI_CRC_INDICATION_PDU_T** pdus, size_t n) {
    if (pdus == NULL) {
        return;
    }

    for (size_t i = 0; i < n; ++i) {
