typedef struct {
    char path[256];
    time_t last_accessed;
    size_t file_size;
    int metadata_version;
} FileDescriptorStat;

FileDescriptorStat** create_stat_collection(int num_elements, int seed) {
    FileDescriptorStat** collection = malloc(num_elements * sizeof(FileDescriptorStat*));
    if (!collection) {
        perror("Failed to allocate memory for the file descriptor collection");
        return NULL;
    }

    srand(seed);
    for (int i = 0; i < num_elements; i++) {
        collection[i] = malloc(sizeof(FileDescriptorStat));
        if (!collection[i]) {
            perror("Failed to allocate memory for individual file descriptor stat");
            // Clean up previously allocated memory
            for (int j = 0; j < i; j++) {
                free(collection[j]);
            }
            free(collection);
            return NULL;
        }

        snprintf(collection[i]->path, sizeof(collection[i]->path), "/tmp/file%d", i);
        collection[i]->last_accessed = time(NULL) - rand() % (365 * 24 * 60 * 60); // Randomly set within the last year
        collection[i]->file_size = rand() % (1024 * 1024 * 1024); // Random file size up to 1GB
        collection[i]->metadata_version = rand();
    }

    return collection;
}

void free_stat_collection(FileDescriptorStat** collection, int num_elements) {
    for (int i = 0; i < num_elements; i++) {
        if (collection[i]) {
            free(collection[i]);
        }
    }
    free(collection);
}

void log_stat_creation(FileDescriptorStat* stat) {
    printf("Created file descriptor stat: %s, version: %d\n", stat->path, stat->metadata_version);
}

void log_stat_update(FileDescriptorStat* stat) {
    printf("Updated file descriptor stat: %s, version: %d\n", stat->path, stat->metadata_version);
}

int main() {
    int num_elements = 10;
    int seed = time(NULL);

    FileDescriptorStat** collection = create_stat_collection(num_elements, seed);
    if (!collection) {
        return 1;
    }

    // Simulate updating a file descriptor stat
    for (int i = 0; i < num_elements; i++) {
        log_stat_creation(collection[i]);
        collection[i]->metadata_version++;
        log_stat_update(collection[i]);
    }

    free_stat_collection(collection, num_elements);
    return 0;
}
```

