#define MAX_STRUCTURES 10000
#define BUFFER_ADJUSTMENT_INTERVAL 500

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* buffer[MAX_STRUCTURES];
int buffer_size = 0;
pthread_mutex_t buffer_lock = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t buffer_full = PTHREAD_COND_INITIALIZER;

void* background_worker(void* arg) {
    while (1) {
        pthread_mutex_lock(&buffer_lock);
        if (buffer_size < MAX_STRUCTURES / 2) {
            int new_size = buffer_size * 2;
            if (new_size > MAX_STRUCTURES) {
                new_size = MAX_STRUCTURES;
            }
            for (int i = buffer_size; i < new_size; i++) {
                buffer[i] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
            }
            buffer_size = new_size;
        } else if (buffer_size > MAX_STRUCTURES / 2) {
            int new_size = buffer_size / 2;
            for (int i = new_size; i < buffer_size; i++) {
                free(buffer[i]);
                buffer[i] = NULL;
            }
            buffer_size = new_size;
        }
        pthread_cond_signal(&buffer_full);
        pthread_mutex_unlock(&buffer_lock);

        usleep(BUFFER_ADJUSTMENT_INTERVAL * 1000);
    }
    return NULL;
}

NFAPI_CRC_INDICATION_PDU_T* generate_crc_indication_pdu() {
    NFAPI_CRC_INDICATION_PDU_T* pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (pdu == NULL) {
        return NULL;
    }
    pthread_mutex_lock(&buffer_lock);
    while (buffer_size >= MAX_STRUCTURES) {
        pthread_cond_wait(&buffer_full, &buffer_lock);
    }
    buffer[buffer_size++] = pdu;
    pthread_mutex_unlock(&buffer_lock);

    // Populate the structure with random values
    srand(time(NULL));
    pdu->RX_UE_INFORMATION_TAG = rand() % 1000;
    pdu->RNTI = rand() % 256;
    pdu->CRC_INDICATION_REL8_TAG = rand() % 2;

    return pdu;
}

