#define MAX_CONNECTIONS 10000

typedef struct {
    char src_ip[16];
    char dest_ip[16];
    int port;
    time_t packet_timestamp;
} TCPConnectionData;

TCPConnectionData *connection_list[MAX_CONNECTIONS];
int connection_count = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t cond = PTHREAD_COND_INITIALIZER;
size_t buffer_size = MAX_CONNECTIONS * sizeof(TCPConnectionData);
double load_factor = 0.5;

void* monitor_buffer(void* arg) {
    while (1) {
        pthread_mutex_lock(&lock);
        if ((double)connection_count / buffer_size < load_factor) {
            size_t new_size = buffer_size / 2;
            TCPConnectionData *new_list = realloc(connection_list, new_size);
            if (new_list != NULL) {
                connection_list = new_list;
                buffer_size = new_size;
            }
        } else if ((double)connection_count / buffer_size > load_factor * 2) {
            size_t new_size = buffer_size * 2;
            TCPConnectionData *new_list = realloc(connection_list, new_size);
            if (new_list != NULL) {
                connection_list = new_list;
                buffer_size = new_size;
            }
        }
        pthread_mutex_unlock(&lock);
        sleep(1);
    }
    return NULL;
}

int add_connection(const char *src_ip, const char *dest_ip, int port) {
    TCPConnectionData *new_connection = (TCPConnectionData *)malloc(sizeof(TCPConnectionData));
    if (new_connection == NULL) {
        perror("Failed to allocate memory for new connection");
        return -1;
    }
    strcpy(new_connection->src_ip, src_ip);
    strcpy(new_connection->dest_ip, dest_ip);
    new_connection->port = port;
    new_connection->packet_timestamp = time(NULL);

    pthread_mutex_lock(&lock);
    if (connection_count >= MAX_CONNECTIONS) {
        free(new_connection);
        fprintf(stderr, "Connection limit reached\n");
        return -1;
    }
    connection_list[connection_count] = new_connection;
    connection_count++;
    pthread_cond_signal(&cond);
    pthread_mutex_unlock(&lock);

    return 0;
}

void remove_inactive_connections() {
    time_t current_time = time(NULL);
    int inactive_threshold = 60; // 1 minute

    pthread_mutex_lock(&lock);
    for (int i = connection_count - 1; i >= 0; i--) {
        if (current_time - connection_list[i]->packet_timestamp > inactive_threshold) {
            free(connection_list[i]);
            for (int j = i + 1; j < connection_count; j++) {
                connection_list[j - 1] = connection_list[j];
            }
            connection_count--;
        }
    }
    pthread_mutex_unlock(&lock);
}

void* log_errors(void* arg) {
    while (1) {
        // Implement asynchronous logging logic here
        sleep(1);
    }
    return NULL;
}

int main() {
    pthread_t monitor_thread, log_thread;

    pthread_create(&monitor_thread, NULL, monitor_buffer, NULL);
    pthread_create(&log_thread, NULL, log_errors, NULL);

    // Simulate adding connections
    add_connection("192.168.1.1", "10.0.0.1", 80);
    add_connection("192.168.1.2", "10.0.0.2", 443);

    // Simulate removing inactive connections
    sleep(70);
    remove_inactive_connections();

    pthread_join(monitor_thread, NULL);
    pthread_join(log_thread, NULL);

    return 0;
}
```

