#include <stdlib.h>
#include <stdio.h>
#include <time.h>

typedef struct {
    char* path;
    time_t last_accessed;
    size_t file_size;
    int metadata_version;
} FileDescriptorStat;

typedef struct {
    FileDescriptorStat* stats;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
} FileDescriptorCollection;

FileDescriptorCollection* create_collection(size_t initial_capacity) {
    FileDescriptorCollection* collection = (FileDescriptorCollection*)malloc(sizeof(FileDescriptorCollection));
    if (!collection) return NULL;

    collection->stats = (FileDescriptorStat*)calloc(initial_capacity, sizeof(FileDescriptorStat));
    if (!collection->stats) {
        free(collection);
        return NULL;
    }

    collection->size = 0;
    collection->capacity = initial_capacity;
    pthread_mutex_init(&collection->lock, NULL);

    return collection;
}

void destroy_collection(FileDescriptorCollection* collection) {
    for (size_t i = 0; i < collection->size; ++i) {
        free(collection->stats[i].path);
    }
    free(collection->stats);
    pthread_mutex_destroy(&collection->lock);
    free(collection);
}

void add_stat(FileDescriptorCollection* collection, const char* path, time_t last_accessed, size_t file_size, int metadata_version) {
    pthread_mutex_lock(&collection->lock);

    if (collection->size == collection->capacity) {
        FileDescriptorStat* new_stats = (FileDescriptorStat*)realloc(collection->stats, collection->capacity * 2 * sizeof(FileDescriptorStat));
        if (!new_stats) {
            pthread_mutex_unlock(&collection->lock);
            return;
        }
        collection->stats = new_stats;
        collection->capacity *= 2;
    }

    FileDescriptorStat* stat = &collection->stats[collection->size++];
    stat->path = strdup(path);
    stat->last_accessed = last_accessed;
    stat->file_size = file_size;
    stat->metadata_version = metadata_version;

    pthread_mutex_unlock(&collection->lock);
}

void update_stat(FileDescriptorCollection* collection, size_t index, const char* path, time_t last_accessed, size_t file_size, int metadata_version) {
    if (index >= collection->size) return;

    pthread_mutex_lock(&collection->lock);

    FileDescriptorStat* stat = &collection->stats[index];
    free(stat->path);
    stat->path = strdup(path);
    stat->last_accessed = last_accessed;
    stat->file_size = file_size;
    stat->metadata_version = metadata_version;

    pthread_mutex_unlock(&collection->lock);
}

int main() {
    FileDescriptorCollection* collection = create_collection(10);
    if (!collection) return 1;

    add_stat(collection, "/path/to/file", time(NULL), 1024, 1);
    update_stat(collection, 0, "/updated/path/to/file", time(NULL), 2048, 2);

    destroy_collection(collection);

    return 0;
}
