#include <stdlib.h>
#include <pthread.h>

#define MAX_DATA_ELEMENTS 1024

typedef struct {
    int type;
    size_t length;
    unsigned char *buffer;
} DATA_ELEMENT;

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG rx_ue_info_tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
    DATA_ELEMENT data[MAX_DATA_ELEMENTS];
    size_t data_count;
} NFAPI_CRC_INDICATION_PDU_T;

pthread_mutex_t allocation_lock = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t allocation_complete = PTHREAD_COND_INITIALIZER;
int allocation_completed = 0;

NFAPI_CRC_INDICATION_PDU_T* allocate_nfaapi_pdu_list(int N, int M) {
    if (N < 0 || M < 0) {
        fprintf(stderr, "Error: Negative values are not allowed for N or M.\n");
        return NULL;
    }

    if (M > MAX_DATA_ELEMENTS) {
        fprintf(stderr, "Error: Maximum number of data elements per PDU exceeded.\n");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T *list = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list) {
        perror("Memory allocation failed for NFAPI CRC Indication PDU list.");
        return NULL;
    }

    for (int i = 0; i < N; ++i) {
        list[i].data_count = 0;
    }

    pthread_mutex_lock(&allocation_lock);
    allocation_completed = 1;
    pthread_cond_broadcast(&allocation_complete);
    pthread_mutex_unlock(&allocation_lock);

    return list;
}

void *thread_function(void *arg) {
    int thread_id = *(int *)arg;
    NFAPI_CRC_INDICATION_PDU_T *list = allocate_nfaapi_pdu_list(1, 500); // Example values

    if (list) {
        pthread_mutex_lock(&allocation_lock);
        while (!allocation_completed) {
            pthread_cond_wait(&allocation_complete, &allocation_lock);
        }
        pthread_mutex_unlock(&allocation_lock);

        for (int i = 0; i < list->data_count; ++i) {
            // Add data elements to the PDU
            DATA_ELEMENT *new_element = &list->data[i];
            new_element->type = thread_id;
            new_element->length = sizeof(thread_id);
            new_element->buffer = (unsigned char *)&thread_id;
        }

        // Proceed with operations using the list
    }

    return NULL;
}

int main() {
    pthread_t threads[10];
    int thread_ids[10];

    for (int i = 0; i < 10; ++i) {
        thread_ids[i] = i;
        pthread_create(&threads[i], NULL, thread_function, &thread_ids[i]);
    }

    for (int i = 0; i < 10; ++i) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
