#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int client_id;
    int server_id;
    unsigned short connection_flags;
} TCP_CONNECTION_REQUEST_T;

typedef enum {
    TCP_FLAG_ESTABLISHED = 1 << 0,
    TCP_FLAG_FIN_WAIT_1 = 1 << 1,
    TCP_FLAG_FIN_WAIT_2 = 1 << 2,
    TCP_FLAG_CLOSE_WAIT = 1 << 3
} TCP_CONNECTION_FLAGS_T;

TCP_CONNECTION_REQUEST_T* create_connection_requests(int num_elements, unsigned int seed) {
    srand(seed);
    TCP_CONNECTION_REQUEST_T* connections = (TCP_CONNECTION_REQUEST_T*)malloc(num_elements * sizeof(TCP_CONNECTION_REQUEST_T));

    if (connections == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    for (int i = 0; i < num_elements; i++) {
        connections[i].client_id = rand() % 1000 + 1; // Random client ID between 1 and 1000
        connections[i].server_id = rand() % 1000 + 1; // Random server ID between 1 and 1000

        unsigned short flags = 0;
        if (rand() % 2) flags |= TCP_FLAG_ESTABLISHED;
        if (rand() % 2) flags |= TCP_FLAG_FIN_WAIT_1;
        if (rand() % 2) flags |= TCP_FLAG_FIN_WAIT_2;
        if (rand() % 2) flags |= TCP_FLAG_CLOSE_WAIT;

        connections[i].connection_flags = flags;

        printf("Created connection request: Client ID=%d, Server ID=%d, Flags=0x%04X\n", 
               connections[i].client_id, connections[i].server_id, connections[i].connection_flags);
    }

    return connections;
}

void export_connections_to_csv(TCP_CONNECTION_REQUEST_T* connections, int num_elements, const char* filename) {
    FILE* fp = fopen(filename, "w");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open file for writing\n");
        return;
    }

    fprintf(fp, "Client ID,Server ID,Connection Flags\n");
    for (int i = 0; i < num_elements; i++) {
        fprintf(fp, "%d,%d,0x%04X\n", 
               connections[i].client_id, connections[i].server_id, connections[i].connection_flags);
    }

    fclose(fp);
}

int main() {
    int num_elements = 10;
    unsigned int seed = time(NULL);
    TCP_CONNECTION_REQUEST_T* connections = create_connection_requests(num_elements, seed);

    if (connections != NULL) {
        export_connections_to_csv(connections, num_elements, "connection_requests.csv");
        free(connections);
    }

    return 0;
}
