void* compress_and_decompress_thread(void* arg) {
    unsigned char input_buffer[1024];
    unsigned char output_buffer[2048];
    int input_size = sizeof(input_buffer);
    int output_size = sizeof(output_buffer);
    z_stream stream;

    // Initialize compression
    memset(&stream, 0, sizeof(stream));
    deflateInit(&stream, Z_DEFAULT_COMPRESSION);
    stream.next_in = input_buffer;
    stream.avail_in = input_size;
    stream.next_out = output_buffer;
    stream.avail_out = output_size;

    // Compress data
    deflate(&stream, Z_FINISH);
    deflateEnd(&stream);

    // Initialize decompression
    memset(&stream, 0, sizeof(stream));
    inflateInit(&stream);
    stream.next_in = output_buffer;
    stream.avail_in = stream.total_out;
    stream.next_out = input_buffer;
    stream.avail_out = input_size;

    // Decompress data
    inflate(&stream, Z_FINISH);
    inflateEnd(&stream);

    return NULL;
}

