['```java
import java.util.*;
import java.security.MessageDigest;
import java.io.FileWriter;
import java.io.IOException;
import org.apache.logging.log4j.LogManager;
import org.apache.logging.log4j.Logger;

public class PacketProcessor {

    private static final Logger logger = LogManager.getLogger(PacketProcessor.class);
    private MessageDigest md5Digest;

    public PacketProcessor() {
        try {
            md5Digest = MessageDigest.getInstance("MD5");
        } catch (Exception e) {
            throw new RuntimeException("Failed to initialize MD5 Digest", e);
        }
    }

    public Map<String, String> processHeaders(List<String> headers, int sizeLimit, FileWriter logWriter) throws IOException {
        long startTime = System.currentTimeMillis();
        Map<String, String> hashMap = new HashMap<>();
        int processed = 0;
        int skipped = 0;

        for (String header : headers) {
            if (header == null || header.isEmpty()) {
                logger.warn("Skipping empty or null header");
                skipped++;
                continue;
            }

            try {
                byte[] hashBytes = md5Digest.digest(header.getBytes());
                String hash = bytesToHex(hashBytes);
                hashMap.put(header, hash);
                processed++;
            } catch (Exception e) {
                logger.error("Failed to process header: " + header, e);
            }
        }

        logWriter.write("Processed Headers: " + processed + "\n");
        logWriter.write("Skipped Headers: " + skipped + "\n");
        long endTime = System.currentTimeMillis();
        logWriter.write("Total Processing Time: " + (endTime - startTime) + " ms\n");

        return hashMap;
    }

    private String bytesToHex(byte[] hashBytes) {
        StringBuilder hexString = new StringBuilder(32);
        for (byte b : hashBytes) {
            String hex = Integer.toHexString(0xff & b);
            if (hex.length() == 1) hexString.append('0');
            hexString.append(hex);
        }
        return hexString.toString();
    }

    public static void main(String[] args) {
        PacketProcessor processor = new PacketProcessor();
        List<String> headers = Arrays.asList("Header1", "Header2", null, "Header3");
        try (FileWriter logWriter = new FileWriter("packet_processing.log")) {
            Map<String, String> hashes = processor.processHeaders(headers, 100, logWriter);
            System.out.println(hashes);
        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}
