    int ORDER_ID;
    char ORDER_STATUS_T[50];
} CUSTOMER_ORDER_T;

void log_order_creation(int order_id) {
    printf("Order created: %d\n", order_id);
}

int generate_random_order(CUSTOMER_ORDER_T *order) {
    if (rand() % 2 == 0) {
        strcpy(order->ORDER_STATUS_T, "Pending");
    } else {
        strcpy(order->ORDER_STATUS_T, "Completed");
    }
    order->CUSTOMER_ID = rand() % (MAX_ID - MIN_ID + 1) + MIN_ID;
    order->ORDER_ID = rand();
    return 0;
}

int add_order(CUSTOMER_ORDER_T **order_list, int *order_count, int capacity) {
    if (*order_count >= capacity) {
        CUSTOMER_ORDER_T *new_list = realloc(*order_list, (capacity + MAX_ORDERS) * sizeof(CUSTOMER_ORDER_T));
        if (!new_list) return -1;
        *order_list = new_list;
        capacity += MAX_ORDERS;
    }
    CUSTOMER_ORDER_T order;
    if (generate_random_order(&order) == 0) {
        (*order_list)[*order_count] = order;
        log_order_creation(order.ORDER_ID);
        (*order_count)++;
        return 1;
    } else {
        return -1;
    }
}

void export_orders(CUSTOMER_ORDER_T *order_list, int order_count, const char *filename) {
    FILE *file = fopen(filename, "w");
    if (!file) return;
    fprintf(file, "CUSTOMER_ID,ORDER_ID,ORDER_STATUS\n");
    for (int i = 0; i < order_count; i++) {
        fprintf(file, "%d,%d,%s\n", order_list[i].CUSTOMER_ID, order_list[i].ORDER_ID, order_list[i].ORDER_STATUS_T);
    }
    fclose(file);
}

int main() {
    srand(time(NULL));
    CUSTOMER_ORDER_T *order_list = NULL;
    int order_count = 0;
    int capacity = 0;

    while (1) {
        add_order(&order_list, &order_count, capacity);
        if (order_count >= MAX_ORDERS) break;
    }

    export_orders(order_list, order_count, "orders.csv");

    for (int i = 0; i < order_count; i++) {
        free(&order_list[i]);
    }
    free(order_list);

    return 0;
}
