typedef struct {
    pthread_mutex_t lock;
    NFAPI_CRC_INDICATION_PDU_T *pool[MAX_STRUCTS];
    int size;
    int capacity;
} MemoryPool;

MemoryPool pool;

void init_memory_pool() {
    pthread_mutex_init(&pool.lock, NULL);
    pool.capacity = 1024; // Initial capacity
    pool.size = 0;
    for (int i = 0; i < pool.capacity; i++) {
        pool.pool[i] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    }
}

void* allocate_from_pool() {
    pthread_mutex_lock(&pool.lock);
    if (pool.size == pool.capacity) {
        // Resize the pool
        int new_capacity = pool.capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T **new_pool = realloc(pool.pool, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T *));
        if (!new_pool) {
            pthread_mutex_unlock(&pool.lock);
            return NULL; // Memory allocation failed
        }
        pool.capacity = new_capacity;
        for (int i = pool.size; i < pool.capacity; i++) {
            new_pool[i] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        }
        pool.pool = new_pool;
    }
    void *block = pool.pool[pool.size++];
    pthread_mutex_unlock(&pool.lock);
    return block;
}

void free_to_pool(void *block) {
    pthread_mutex_lock(&pool.lock);
    for (int i = 0; i < pool.size; i++) {
        if (pool.pool[i] == block) {
            // Free the block and shift other blocks up
            free(block);
            for (int j = i; j < pool.size - 1; j++) {
                pool.pool[j] = pool.pool[j + 1];
            }
            pool.size--;
            break;
        }
    }
    pthread_mutex_unlock(&pool.lock);
}

