    for (int i = 0; i < N; i++) {
        indications[i].RX_UE_INFORMATION_TAG = /* Initialize RX_UE_INFORMATION_TAG */;
        indications[i].RNTI = /* Initialize RNTI */;
        indications[i].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2; // Randomize CRCFLAG
