xmlNode *parse_xml_with_xpath(const char *xml_data, const char *xpath_expression) {
    xmlDocPtr doc;
    xmlNodeSetPtr nodeset;
    xmlXPathContextPtr xpathCtx;

    if (xmlCheckVersion(2, 7, 6) != 0) {
        fprintf(stderr, "XML library version mismatch!\n");
        return NULL;
    }

    // Parse the XML data
    doc = xmlReadMemory(xml_data, strlen(xml_data), NULL, NULL, 0);
    if (doc == NULL) {
        fprintf(stderr, "Failed to parse XML document\n");
        return NULL;
    }

    xpathCtx = xmlXPathNewContext(doc);
    if (xpathCtx == NULL) {
        fprintf(stderr, "Failed to create XPath context\n");
        xmlFreeDoc(doc);
        return NULL;
    }

    nodeset = xmlXPathEvalExpression(BAD_CAST xpath_expression, xpathCtx);
    if (nodeset != NULL && nodeset->nodeTab[0] != NULL) {
        xmlNode *result_node = nodeset->nodeTab[0];
        xmlXPathFreeResult(nodeset);
        return result_node;
    }

    // Free resources
    xmlXPathFreeContext(xpathCtx);
    xmlFreeDoc(doc);

    return NULL;
}
