public class PokemonReportGenerator {
    private static final Logger logger = LoggerFactory.getLogger(PokemonReportGenerator.class);
    private ConcurrentHashMap<String, String> typeWeaknessesCache = new ConcurrentHashMap<>();
    private ExecutorService executorService = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors());
    private ObjectMapper objectMapper = new ObjectMapper();

    public String generateReports(List<Pokemon> pokemons) {
        try {
            long startTime = System.currentTimeMillis();
            StringBuilder reports = new StringBuilder();
            for (Pokemon pokemon : pokemons) {
                executorService.submit(() -> {
                    try {
                        String report = generateReport(pokemon);
                        synchronized (reports) {
                            reports.append(report).append("\n");
                        }
                    } catch (Exception e) {
                        logger.error("Failed to generate report for Pokemon: " + pokemon.getName(), e);
                    }
                });
            }
            executorService.shutdown();
            executorService.awaitTermination(Long.MAX_VALUE, java.util.concurrent.TimeUnit.NANOSECONDS);
            long endTime = System.currentTimeMillis();
            logger.info("Report generation completed in {} ms", endTime - startTime);
            return reports.toString();
        } catch (Exception e) {
