#include <pthread.h>
#include <semaphore.h>
#include <stdio.h>
#include <stdlib.h>
#include <errno.h>

typedef struct {
    sem_t *sem;
    char name[16];
    int initial_count;
    int timeout;
} ThreadSafeSemaphore;

ThreadSafeSemaphore* create_thread_safe_semaphore(const char* name, int initial_count, int timeout) {
    ThreadSafeSemaphore* ts_sem = malloc(sizeof(ThreadSafeSemaphore));
    if (!ts_sem) {
        perror("Failed to allocate memory for semaphore");
        return NULL;
    }

    sem_t *sem = malloc(sizeof(sem_t));
    if (!sem) {
        perror("Failed to allocate memory for semaphore structure");
        free(ts_sem);
        return NULL;
    }

    int ret = sem_init(sem, 0, initial_count);
    if (ret != 0) {
        perror("Failed to initialize semaphore");
        free(sem);
        free(ts_sem);
        return NULL;
    }

    ts_sem->sem = sem;
    snprintf(ts_sem->name, sizeof(ts_sem->name), "%s", name);
    ts_sem->initial_count = initial_count;
    ts_sem->timeout = timeout;

    return ts_sem;
}

void destroy_thread_safe_semaphore(ThreadSafeSemaphore* ts_sem) {
    if (ts_sem && ts_sem->sem) {
        sem_destroy(ts_sem->sem);
        free(ts_sem->sem);
    }
    free(ts_sem);
}

int initialize_semaphore(ThreadSafeSemaphore* ts_sem, int timeout) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    ts.tv_sec += timeout;

    return sem_timedwait(ts_sem->sem, &ts);
}
```

