#include <unordered_map>
#include <vector>

void mergeVectorsInMap(std::unordered_map<int, std::vector<int>>& map, int key1, int key2) {
    if (map.find(key1) == map.end()) {
        map[key1] = std::move(map[key2]);
        map.erase(key2);
    } else {
        auto& vec1 = map[key1];
        auto& vec2 = map[key2];
        for (auto it = vec2.begin(); it != vec2.end(); ++it) {
            vec1.push_back(*it);
        }
        map.erase(key2);
    }
}
