#include <iostream>
#include <random>
#include <chrono>
#include <thread>
#include <vector>

namespace SimulationMath {
    class RandomGenerator {
    public:
        enum DistributionType {
            Uniform,
            Normal,
            Exponential,
            LogNormal
        };

        RandomGenerator(DistributionType type, unsigned int seed = std::random_device{}(), double min = 0.0, double max = 1.0)
            : dist_type(type), gen(seed) {
            setRange(min, max);
        }

        void setRange(double min, double max) {
            switch (dist_type) {
                case Uniform:
                    uniform_dist = std::uniform_real_distribution<>(min, max);
                    break;
                case Normal:
                    normal_dist = std::normal_distribution<>((min + max) / 2.0, (max - min) / 4.0);
                    break;
                case Exponential:
                    exp_dist = std::exponential_distribution<>((max - min) / 2.0);
                    break;
                case LogNormal:
                    log_norm_dist = std::lognormal_distribution<>(std::log(min + max) / 2.0, (std::log(max) - std::log(min)) / 4.0);
                    break;
            }
        }

        double generate() {
            switch (dist_type) {
                case Uniform:
                    return uniform_dist(gen);
                case Normal:
                    return normal_dist(gen);
                case Exponential:
                    return exp_dist(gen);
                case LogNormal:
                    return log_norm_dist(gen);
                default:
                    throw std::runtime_error("Unknown distribution type");
            }
        }

    private:
        DistributionType dist_type;
        std::mt19937 gen;
        std::uniform_real_distribution<> uniform_dist;
        std::normal_distribution<> normal_dist;
        std::exponential_distribution<> exp_dist;
        std::lognormal_distribution<> log_norm_dist;
    };

    void benchmarkGenerator(RandomGenerator& gen, size_t numSamples) {
        auto start = std::chrono::high_resolution_clock::now();
        for (size_t i = 0; i < numSamples; ++i) {
            gen.generate();
        }
        auto end = std::chrono::high_resolution_clock::now();
        std::cout << "Latency: " << std::chrono::duration_cast<std::chrono::nanoseconds>(end - start).count() / numSamples << " ns" << std::endl;
    }

    void runBenchmark(size_t samplesPerThread, size_t numThreads) {
        RandomGenerator gen(RandomGenerator::Normal);
        std::vector<std::thread> threads(numThreads);
        for (size_t i = 0; i < numThreads; ++i) {
            threads[i] = std::thread(benchmarkGenerator, std::ref(gen), samplesPerThread);
        }
        for (auto& t : threads) {
            t.join();
        }
    }

    int main() {
        runBenchmark(1000000, 4);
        return 0;
    }
