['```csharp
using System;
using System.Data;
using System.Data.SqlClient;

public class DynamicSqlGenerator
{
    public static IDataReader GenerateDynamicQuery(SqlConnection connection, dynamic config, string sort = null, int? page = null, int? pageSize = null)
    {
        try
        {
            using (var command = new SqlCommand())
            {
                command.Connection = connection;
                command.CommandType = CommandType.Text;

                // Construct the base query with selected tables and columns
                var mainTable = config.MainTable;
                var selectColumns = string.Join(", ", config.SelectedColumns);
                command.CommandText = $"SELECT {selectColumns} FROM {mainTable}";

                // Add JOINs based on configuration
                foreach (var join in config.Joins)
                {
                    command.CommandText += $"\nINNER JOIN {join.Table} ON {join.Condition}";
                }

                // Apply filters based on configuration
                if (config.Filters != null && config.Filters.Any())
                {
                    command.CommandText += "\nWHERE " + string.Join(" AND ", config.Filters);
                }

                // Add sorting
                if (!string.IsNullOrEmpty(sort))
                {
                    command.CommandText += $"\nORDER BY {sort}";
                }

                // Apply pagination
                if (page.HasValue && pageSize.HasValue)
                {
                    var offset = (page.Value - 1) * pageSize.Value;
                    command.CommandText += $"\nOFFSET {offset} ROWS FETCH NEXT {pageSize} ROWS ONLY";
                }

                // Execute the query and return the result
                connection.Open();
                return command.ExecuteReader(CommandBehavior.CloseConnection);
            }
        }
        catch (Exception ex)
        {
            // Log or handle exception as needed
            Console.WriteLine($"An error occurred: {ex.Message}");
            throw;
        }
    }
}
```

