    private Random _random = new Random();
    private bool _isRunning = false;

    public WeatherService()
    {
        _httpClient = new HttpClient();
    }

    public async Task StartAsync(int delaySeconds)
    {
        if (!_isRunning)
        {
            await Task.Delay(delaySeconds * 1000);
            _isRunning = true;
            while (_isRunning)
            {
                try
                {
                    var weatherData = await FetchWeatherDataAsync();
                    AdjustLighting(weatherData);
                }
                catch (Exception ex)
                {
                    Console.WriteLine($"Error fetching weather data: {ex.Message}");
                }

                // Random delay between 10 and 60 seconds
                int randomDelay = _random.Next(10, 61);
                await Task.Delay(randomDelay * 1000);
            }
        }
    }

    public void Stop()
    {
        _isRunning = false;
        Console.WriteLine("Service stopped.");
        // Send message to messaging system
    }

    private async Task<string> FetchWeatherDataAsync()
    {
        var response = await _httpClient.GetAsync(_apiUrl);
        response.EnsureSuccessStatusCode();
        return await response.Content.ReadAsStringAsync();
    }

    private void AdjustLighting(string weatherData)
    {
        // Logic to adjust lighting based on weather data
        Console.WriteLine("Adjusting lighting based on weather data.");
    }
}

class Program
{
    static async Task Main(string[] args)
    {
        WeatherService weatherService = new WeatherService();

        while (true)
        {
            int randomDelay = new Random().Next(10, 61);
            await weatherService.StartAsync(randomDelay);

            // Simulate user override for a specific location
            if (_random.Next(2) == 0)
            {
                Console.WriteLine("User override detected. Adjusting lighting manually.");
                weatherService.AdjustLighting("Manually adjusted");
            }

            // Random delay before restarting the service
