#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define INITIAL_CAPACITY 10
#define GROWTH_THRESHOLD 50

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
    clock_t start_time;
    size_t allocation_count;
    size_t successful_allocations;
    double total_allocation_time;
} DynamicArrayT;

void initialize_array(DynamicArrayT *array) {
    array->array = (NFAPI_CRC_INDICATION_PDU_T *)malloc(INITIAL_CAPACITY * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array->array) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    array->capacity = INITIAL_CAPACITY;
    array->count = 0;
    pthread_mutex_init(&array->lock, NULL);
    array->start_time = clock();
    array->allocation_count = 0;
    array->successful_allocations = 0;
    array->total_allocation_time = 0.0;
}

void* add_element_to_array(DynamicArrayT *array) {
    pthread_mutex_lock(&array->lock);
    if (array->count == array->capacity) {
        size_t new_capacity = array->capacity + GROWTH_THRESHOLD;
        NFAPI_CRC_INDICATION_PDU_T *new_array = (NFAPI_CRC_INDICATION_PDU_T *)realloc(array->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_array) {
            fprintf(stderr, "Memory reallocation failed\n");
            exit(EXIT_FAILURE);
        }
        array->array = new_array;
        array->capacity = new_capacity;
    }

    NFAPI_CRC_INDICATION_PDU_T *element = &array->array[array->count++];
    element->RX_UE_INFORMATION_TAG = rand() % 1000; // Example value
    element->RNTI = rand() % 65536; // Example value
    element->crc_indication.CRCFLAG = (rand() % 2) ? TRUE : FALSE; // Randomly set CRCFLAG

    pthread_mutex_unlock(&array->lock);
    return element;
}

void* get_array_stats(DynamicArrayT *array, size_t *total_elements, size_t *successful_allocations, double *average_time) {
    pthread_mutex_lock(&array->lock);
    *total_elements = array->count;
    *successful_allocations = array->successful_allocations;
    if (array->allocation_count > 0) {
        *average_time = ((double)array->total_allocation_time) / array->allocation_count;
    } else {
        *average_time = 0.0;
    }
    pthread_mutex_unlock(&array->lock);
    return NULL;
}

void destroy_array(DynamicArrayT *array) {
    pthread_mutex_lock(&array->lock);
    free(array->array);
    pthread_mutex_destroy(&array->lock);
}
