#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define INITIAL_CAPACITY 10
#define RESIZE_THRESHOLD 80

typedef struct {
    RX_UE_INFORMATION_TAG ue_info;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* array;
    size_t capacity;
    size_t size;
    size_t successful_allocations;
    size_t failed_allocations;
    clock_t total_allocation_time;
    pthread_mutex_t lock;
} DynamicArray;

void init_dynamic_array(DynamicArray* da, size_t initial_capacity) {
    da->array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    da->capacity = initial_capacity;
    da->size = 0;
    da->successful_allocations = 0;
    da->failed_allocations = 0;
    da->total_allocation_time = 0;
    pthread_mutex_init(&da->lock, NULL);
}

void destroy_dynamic_array(DynamicArray* da) {
    free(da->array);
    pthread_mutex_destroy(&da->lock);
}

void resize_dynamic_array(DynamicArray* da) {
    size_t new_capacity = da->capacity * 2;
    NFAPI_CRC_INDICATION_PDU_T* new_array = (NFAPI_CRC_INDICATION_PDU_T*)realloc(da->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (new_array != NULL) {
        da->array = new_array;
        da->capacity = new_capacity;
    }
}

void add_to_dynamic_array(DynamicArray* da) {
    pthread_mutex_lock(&da->lock);
    if (da->size >= da->capacity) {
        resize_dynamic_array(da);
    }
    // Initialize NFAPI_CRC_INDICATION_PDU_T structure with random data
    da->array[da->size].ue_info = generate_ue_info();
    da->array[da->size].rnti = generate_rnti();
    da->array[da->size].crc_indication.crcflag = rand() % 2;
    da->size++;
    pthread_mutex_unlock(&da->lock);
}

void* dynamic_array_thread_function(void* arg) {
    DynamicArray* da = (DynamicArray*)arg;
    while (1) {
        add_to_dynamic_array(da);
        usleep(1000); // Simulate work
    }
    return NULL;
}

int main() {
    srand(time(NULL));
    DynamicArray da;
    init_dynamic_array(&da, INITIAL_CAPACITY);

    pthread_t threads[10];
    for (size_t i = 0; i < 10; i++) {
        pthread_create(&threads[i], NULL, dynamic_array_thread_function, &da);
    }

    for (size_t i = 0; i < 10; i++) {
        pthread_join(threads[i], NULL);
    }

    destroy_dynamic_array(&da);
    return 0;
}
