    if (!manager->cell_array) {
        perror("Failed to allocate memory for cell array");
        free(manager);
        return NULL;
    }
    manager->array_size = M;

    if (pthread_mutex_init(&manager->mutex, NULL) != 0) {
        perror("Failed to initialize mutex");
        free(manager->cell_array);
        free(manager);
        return NULL;
    }

    for (size_t i = 0; i < M; ++i) {
        manager->cell_array[i].CELL_ID = -1;
        manager->cell_array[i].PCI = -1;
        manager->cell_array[i].RSRP = -1;
        manager->cell_array[i].RSRQ = -1;
        manager->cell_array[i].SINR = -1;
    }

    return manager;
}

void update_cell_info(CellInfoManager *manager, size_t index, NR_CELL_INFO_T new_info) {
    pthread_mutex_lock(&manager->mutex);
    if (index >= manager->array_size || new_info.CELL_ID == -1) {
        fprintf(stderr, "Invalid index or uninitialized data provided\n");
        pthread_mutex_unlock(&manager->mutex);
        return;
    }

    manager->cell_array[index] = new_info;
    pthread_mutex_unlock(&manager->mutex);
}

void free_cell_info_manager(CellInfoManager *manager) {
    if (manager) {
        pthread_mutex_destroy(&manager->mutex);
        free(manager->cell_array);
        free(manager);
    }
