using System;
using System.Collections.Generic;
using System.Linq;
using System.Xml.XPath;
using System.Text.RegularExpressions;

public class XmlParser
{
    private static readonly Dictionary<string, XPathDocument> cache = new Dictionary<string, XPathDocument>();
    private static readonly Regex wellFormedXmlRegex = new Regex(@"^<\?xml\s+version=""1\.0""\s+(encoding=""(UTF-8|UTF-16)"")?\?>\s*<[^>]+>[^<]*</[^>]+>\s*$", RegexOptions.Compiled | RegexOptions.IgnoreCase);
    private static readonly object cacheLock = new object();

    public static List<XElement> ParseXmlWithXPath(string xml, string elementName, Func<XElement, bool> filter = null, int maxResults = int.MaxValue, bool enableStreaming = false, XmlLoggers logger = null)
    {
        if (!IsValidXml(xml))
        {
            throw new ArgumentException("Invalid XML format.");
        }

        var doc = GetParsedXmlDocument(xml);
        var namespaceManager = new XmlNamespaceManager(doc.NameTable);

        XPathNavigator navigator = doc.CreateNavigator();
        navigator.MoveToRoot();

        var resultElements = new List<XElement>();
        foreach (XPathNavigator node in navigator.Select($"//{elementName}", namespaceManager))
        {
            if (filter == null || filter(new XElement(node)))
            {
                resultElements.Add(new XElement(node));
                if (resultElements.Count >= maxResults)
                {
                    break;
                }
            }
        }

        return resultElements;
    }

    private static bool IsValidXml(string xml)
    {
        return wellFormedXmlRegex.IsMatch(xml);
    }

    private static XPathDocument GetParsedXmlDocument(string xml)
    {
        lock (cacheLock)
        {
            if (!cache.ContainsKey(xml))
            {
                var settings = new XmlReaderSettings
                {
                    DtdProcessing = DtdProcessing.Prohibit,
                    CheckCharacters = true,
                    CloseInput = true,
                    Encoding = System.Text.Encoding.GetEncoding("UTF-8"),
                    IgnoreWhitespace = true
                };

                using (var reader = XmlReader.Create(new StringReader(xml), settings))
                {
                    cache[xml] = new XPathDocument(reader);
                }
            }

            return cache[xml];
        }
    }
}

public static class XmlLoggers
{
    public static void LogError(string message)
    {
        // Implement logging logic here, respecting the current log level.
    }

    public static bool IsLoggingEnabled()
    {
        // Return true if logging is enabled based on the current log level.
        return true;
    }
}
