class UserHandler {
    private $database;
    private $logger;
    private $rateLimiter;

    public function __construct($database, $logger, $rateLimiter) {
        $this->database = $database;
        $this->logger = $logger;
        $this->rateLimiter = $rateLimiter;
    }

    public function handleRequest($requestMethod, $id, $data) {
        if (!$this->rateLimiter->allowRequest($_SERVER['REMOTE_ADDR'])) {
            http_response_code(429);
            echo json_encode(['error' => 'Too many requests']);
            return;
        }

        $transactionId = uniqid();
        $timestamp = time();
        $userIp = $_SERVER['REMOTE_ADDR'];

        try {
            $this->database->beginTransaction();

            if ($requestMethod === 'PUT') {
                $validationResult = $this->validate($data);
                if ($validationResult !== true) {
                    throw new Exception('Validation failed: ' . json_encode($validationResult));
                }

                $userId = intval($id);
                $sql = "UPDATE users SET name=:name, email=:email, password=:password WHERE id=:id";
                $stmt = $this->database->prepare($sql);
                $stmt->execute([
                    ':name' => $data['name'],
                    ':email' => $data['email'],
                    ':password' => password_hash($data['password'], PASSWORD_DEFAULT),
                    ':id' => $userId
                ]);
            } elseif ($requestMethod === 'DELETE') {
                $userId = intval($id);
                $sql = "DELETE FROM users WHERE id=:id";
                $stmt = $this->database->prepare($sql);
                $stmt->execute([
                    ':id' => $userId
                ]);
            }

            $this->database->commit();
            $this->logAction($transactionId, $timestamp, $userIp, $requestMethod, $data);

            if ($requestMethod === 'PUT') {
                $this->notifyUser('update', $data['email']);
            } elseif ($requestMethod === 'DELETE') {
                $this->notifyUser('delete', $id);
            }

            http_response_code(200);
            echo json_encode(['message' => 'Operation successful']);
        } catch (Exception $e) {
            $this->database->rollBack();
            $this->logAction($transactionId, $timestamp, $userIp, $requestMethod, $data, ['error' => $e->getMessage()]);
            http_response_code(500);
            echo json_encode(['error' => 'Internal server error']);
        }
    }

    private function validate($data) {
        // Implement validation logic here
        return true;
    }

    private function logAction($transactionId, $timestamp, $userIp, $requestMethod, $data, $extra = []) {
        $logData = [
            'transaction_id' => $transactionId,
            'timestamp' => $timestamp,
            'user_ip' => $userIp,
