import java.io.*;
import java.util.HashMap;
import java.util.Map;

public class StateLoader {
    private static final Map<String, MoSTState> cache = new HashMap<>();
    private static final int MAX_CACHE_SIZE = 100;
    private static final String[] ALLOWED_DIRECTORIES = {"C:\\allowed\\dir", "/another/allowed/dir"};

    public static synchronized MoSTState loadState(String filePath) {
        if (!isPathAllowed(filePath)) {
            logError("Invalid file path: " + filePath);
            return null;
        }

        if (cache.containsKey(filePath)) {
            return cache.get(filePath);
        }

        try (ObjectInputStream ois = new ObjectInputStream(new FileInputStream(filePath))) {
            MoSTState state = (MoSTState) ois.readObject();
            if (state instanceof MoSTState && isStateUpToDate(state)) {
                addToCache(filePath, state);
                return state;
            } else {
                logWarning("Outdated or invalid state loaded from: " + filePath);
                return null;
            }
        } catch (FileNotFoundException e) {
            logError("File not found: " + filePath, e);
        } catch (IOException | ClassNotFoundException e) {
            logError("Failed to read object from file: " + filePath, e);
        }

        return null;
    }

    private static boolean isPathAllowed(String filePath) {
        for (String allowedDir : ALLOWED_DIRECTORIES) {
            if (filePath.startsWith(allowedDir)) {
                return true;
            }
        }
        return false;
    }

    private static boolean isStateUpToDate(MoSTState state) {
        long currentTime = System.currentTimeMillis();
        return (currentTime - state.getTimestamp()) <= 24 * 60 * 60 * 1000; // Check if within last 24 hours
    }

    private static void addToCache(String filePath, MoSTState state) {
        if (cache.size() >= MAX_CACHE_SIZE) {
            String oldestKey = null;
            long oldestTime = Long.MAX_VALUE;
            for (Map.Entry<String, MoSTState> entry : cache.entrySet()) {
                if (entry.getValue().getTimestamp() < oldestTime) {
                    oldestKey = entry.getKey();
                    oldestTime = entry.getValue().getTimestamp();
                }
            }
            cache.remove(oldestKey);
        }
        cache.put(filePath, state);
    }

    private static void logError(String message) {
        System.err.println("ERROR: " + message);
    }

    private static void logError(String message, Exception e) {
        System.err.println("ERROR: " + message);
        e.printStackTrace();
    }

    private static void logWarning(String message) {
        System.out.println("WARNING: " + message);
    }
}
