// JavaScript code for asynchronous file reading with error handling and efficient memory usage
async function readFilesInDirectory(directoryPath) {
  try {
    const files = await fs.promises.readdir(directoryPath);
    const results = {};

    for (const file of files) {
      const filePath = path.join(directoryPath, file);
      const stats = await fs.promises.stat(filePath);

      if (stats.isFile()) {
        const content = await fs.promises.readFile(filePath, 'utf8');
        results[file] = {
          content,
          size: stats.size,
          lastModified: stats.mtimeMs
        };
      } else if (stats.isDirectory()) {
        // Handle directory contents as needed
      }
    }

    return results;
  } catch (error) {
    console.error('Error reading files:', error);
    throw error;
  }
}

// Example usage:
readFilesInDirectory('/path/to/directory')
  .then(files => console.log(files))
  .catch(error => console.error('Failed to read files:', error));
