// C code for a simple DNS resolver registry manager with multi-threading support
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int sid;
    int timeout;
    int cache_expiration;
    char* queried_domains[1024];
} DNS_RESOLVER;

DNS_RESOLVER* createResolver(int sid, int timeout, int cache_expiration) {
    DNS_RESOLVER* resolver = (DNS_RESOLVER*)malloc(sizeof(DNS_RESOLVER));
    if (resolver == NULL) {
        perror("Memory allocation failed");
        return NULL;
    }
    resolver->sid = sid;
    resolver->timeout = timeout;
    resolver->cache_expiration = cache_expiration;
    memset(resolver->queried_domains, 0, sizeof(resolver->queried_domains));
    pthread_mutex_init(&resolver->lock, NULL);
    return resolver;
}

void freeResolver(DNS_RESOLVER* resolver) {
    pthread_mutex_destroy(&resolver->lock);
    free(resolver);
}

// Example usage:
int main() {
    DNS_RESOLVER* resolver = createResolver(1, 5000, 3600);
    if (resolver != NULL) {
        // Use the resolver
        freeResolver(resolver);
    }
    return 0;
}
