// C code for a simple memory pool implementation to manage buffer allocations efficiently
#include <stdio.h>
#include <stdlib.h>

typedef struct {
    size_t block_size;
    int num_blocks;
    void* blocks[1024];
} MEMORY_POOL;

MEMORY_POOL* createMemoryPool(size_t block_size, int num_blocks) {
    MEMORY_POOL* pool = (MEMORY_POOL*)malloc(sizeof(MEMORY_POOL));
    if (pool == NULL) {
        perror("Memory allocation failed");
        return NULL;
    }
    pool->block_size = block_size;
    pool->num_blocks = num_blocks;
    for (int i = 0; i < num_blocks; i++) {
        pool->blocks[i] = malloc(block_size);
        if (pool->blocks[i] == NULL) {
            perror("Memory allocation failed");
            return NULL;
        }
    }
    return pool;
}

void freeMemoryPool(MEMORY_POOL* pool) {
    for (int i = 0; i < pool->num_blocks; i++) {
        free(pool->blocks[i]);
    }
    free(pool);
}

// Example usage:
int main() {
    MEMORY_POOL* pool = createMemoryPool(1024, 100);
    if (pool != NULL) {
        // Use the memory pool
        freeMemoryPool(pool);
    }
    return 0;
}
