import com.typesafe.config.ConfigFactory;

public class FinancialTransactionProcessor {
    public static void main(String[] args) {
        if (args.length == 0) {
            System.out.println("Please specify a mode (A, B, or C)");
            return;
        }

        String mode = args[0];
        ActorSystem system = ActorSystem.create("FinancialTransactionProcessing", ConfigFactory.load());
        Materializer materializer = Materializer.createMaterializer(system);

        switch (mode) {
            case "A":
                FixedNumberOfTransactionsProcessor.process(system, materializer);
                break;
            case "B":
                OnDemandTransactionProcessor.process(system, materializer);
                break;
            case "C":
                ContinuousStreamTransactionProcessor.stream(system, materializer);
                break;
            default:
                System.out.println("Invalid mode. Please specify A, B, or C");
        }
    }
}
