async function runModuleTests(moduleName, tests, isOptional) {
    const results = {
        passed: 0,
        failed: 0,
        errors: []
    };

    for (let i = 0; i < tests.length; i++) {
        const testFunction = tests[i];
        const skipTest = isOptional[i] && process.argv.includes('--skipOptional');

        if (skipTest) {
            console.log(`Skipping optional test: ${testFunction.name}`);
            continue;
        }

        try {
            const module = await import(moduleName);
            const start_time = performance.now();

            await testFunction(module);

            const duration = performance.now() - start_time;
            results.passed++;
            console.log(`Passed test: ${testFunction.name} in ${duration.toFixed(2)}ms`);
        } catch (error) {
            blueslip.reset();
            results.failed++;
            results.errors.push({ test: tests[i].name, error });
            console.error(`Failed test: ${tests[i].name}`);
        }
    }

    return results;
}
