async function renderFooter(components) {
  const container = document.createElement('footer');

  for (const component of components) {
    if (!component.id || !component.className) continue;

    const element = document.createElement(component.tag || 'div');
    element.id = component.id;
    element.className = component.className;

    if (component.content) {
      if (typeof component.content === 'string') {
        element.textContent = component.content;
      } else if (component.content instanceof Promise) {
        try {
          const asyncContent = await component.content;
          element.textContent = asyncContent;
        } catch (error) {
          console.error('Error fetching content for', component.id, error);
          element.textContent = 'Error loading content';
        }
      }
    }

    if (component.onClick) {
      element.addEventListener('click', component.onClick);
    }

    if (component.visible !== false) {
      container.appendChild(element);
    }
  }

  return container.outerHTML;
}

