["```javascript
const { Buffer } = require('buffer');

function copyBufferChunks(chunks, offset, length) {
  if (!Array.isArray(chunks) || !Number.isInteger(offset) || !Number.isInteger(length)) {
    throw new Error('Invalid input parameters');
  }

  const targetBuffer = Buffer.allocUnsafe(length);
  let bytesRead = 0;

  for (let i = 0; i < chunks.length && bytesRead < length; ++i) {
    if (!(chunks[i] instanceof Buffer)) {
      throw new Error('Non-buffer chunk detected');
    }
    const bytesToCopy = Math.min(chunks[i].length, length - bytesRead);
    chunks[i].copy(targetBuffer, bytesRead, 0, bytesToCopy);
    bytesRead += bytesToCopy;
  }

  if (bytesRead !== length) {
    return targetBuffer.slice(0, bytesRead);
  }

  return targetBuffer;
}
