class DOMTraverser {
  constructor() {
    this.cache = new Map();
    this.maxDepth = 50;
  }

  traverse(element, selector, depth = 0) {
    if (depth > this.maxDepth) return [];

    if (!this.cache.has(element)) {
      const result = [];
      for (let i = 0; i < element.childNodes.length; i++) {
        const child = element.childNodes[i];
        if (child.nodeType === 1) {
          if (child.matches(selector)) {
            result.push(child);
          }
          result.push(...this.traverse(child, selector, depth + 1));
        }
      }
      this.cache.set(element, result);
    }

    return [...this.cache.get(element)].filter(el => el.matches(selector));
  }

  updateCache() {
    // Implement logic to update the cache based on DOM changes
    // For example, if a new element is added, add it to the cache
    // If an existing element is removed or modified, remove/update it from the cache
  }
}

// Usage
