["```javascript
class ModuleLoader {
    constructor() {
        this.modules = {};
        this.loadQueue = [];
        this.dependencies = new Map();
    }

    registerModule(moduleName, modulePath) {
        if (!this.modules[moduleName]) {
            this.modules[moduleName] = { path: modulePath, dependencies: [], loaded: false };
        }
    }

    setDependencies(moduleName, dependencies) {
        this.dependencies.set(moduleName, dependencies);
    }

    loadModule(moduleName) {
        const module = this.modules[moduleName];
        if (!module.loaded) {
            module.loading = true;
            fetch(module.path)
                .then(response => response.text())
                .then(scriptContent => {
                    const script = document.createElement('script');
                    script.textContent = `(${scriptContent})()`;
                    document.head.appendChild(script);
                    script.onload = () => {
                        module.loaded = true;
                        this.executeDependencies(moduleName);
                    };
                    script.onerror = () => {
                        console.error(`Failed to load module: ${moduleName}`);
                    };
                })
                .catch(error => {
                    console.error(`Error loading module ${moduleName}:`, error);
                });
        }
    }

    executeModule(moduleName) {
        if (this.modules[moduleName].loaded && !this.modules[moduleName].executed) {
            this.modules[moduleName].executed = true;
            // Assuming the module exports a function named 'init'
            this.modules[moduleName].init();
        }
    }

    executeDependencies(moduleName) {
        const dependencies = this.dependencies.get(moduleName);
        if (dependencies && dependencies.length > 0) {
            dependencies.forEach(dependency => {
                this.loadModule(dependency);
            });
            this.executeModule(moduleName);
        } else {
            this.executeModule(moduleName);
        }
    }

    loadAllModules() {
        Object.keys(this.modules).forEach(moduleName => this.loadModule(moduleName));
    }
}

// Usage
const loader = new ModuleLoader();
loader.registerModule('moduleA', 'path/to/moduleA.js');
loader.registerModule('moduleB', 'path/to/moduleB.js');
loader.setDependencies('moduleA', ['dependencyX']);
loader.setDependencies('moduleB', ['moduleA', 'dependencyY']);

loader.loadAllModules();
```

This code snippet provides a basic implementation of a JavaScript module loader that dynamically loads and executes modules based on their dependencies. It uses asynchronous loading with `fetch` to ensure the main thread is not blocked. The loader handles module registration, dependency management, and execution, including error handling for missing or failed modules."]

