import java.util.*;
import java.util.concurrent.*;
import com.fasterxml.jackson.databind.*;

public class TransactionProcessor {
    private PriorityQueue<Transaction> queue = new PriorityBlockingQueue<>();
    private Map<String, Function<JsonNode, Transaction>> factoryRegistry = new HashMap<>();

    public void addTransaction(Transaction transaction) {
        long startTime = System.nanoTime();
        queue.add(transaction);
        processQueue();
        long endTime = System.nanoTime();
        System.out.println("Transaction processed in " + (endTime - startTime) + " ns");
    }

    private void processQueue() {
        while (!queue.isEmpty()) {
            Transaction transaction = queue.poll();
            // Process the transaction
            if (transaction.getAmount() > 1000) {
                System.out.println(transaction.getId() + " is high-value");
            } else {
                System.out.println(transaction.getId() + " is low-value");
            }
        }
    }

    public void addFactory(String id, Function<JsonNode, Transaction> factory) {
        factoryRegistry.put(id, factory);
    }

    public Transaction createTransaction(String id, String json) throws IOException {
        ObjectMapper mapper = new ObjectMapper();
        JsonNode node = mapper.readTree(json);
        return factoryRegistry.get(id).apply(node);
    }
}

class Transaction {
    private String id;
    private double amount;

    public Transaction(String id, double amount) {
        this.id = id;
        this.amount = amount;
    }

    public String getId() {
        return id;
    }

    public double getAmount() {
        return amount;
    }
}
