import java.io.IOException;
import java.net.InetSocketAddress;
import java.nio.ByteBuffer;
import java.nio.channels.SelectionKey;
import java.nio.channels.Selector;
import java.nio.channels.ServerSocketChannel;
import java.nio.channels.SocketChannel;
import java.util.Iterator;
import java.util.Set;

public class SecureServer {

    private final int port;
    private final int maxConnections;
    private Selector selector;
    private ServerSocketChannel serverSocketChannel;
    private int activeConnections = 0;

    public SecureServer(int port, int maxConnections) {
        this.port = port;
        this.maxConnections = maxConnections;
    }

    public void start() throws IOException {
        selector = Selector.open();
        serverSocketChannel = ServerSocketChannel.open();
        serverSocketChannel.socket().bind(new InetSocketAddress(port));
        serverSocketChannel.configureBlocking(false);
        serverSocketChannel.register(selector, SelectionKey.OP_ACCEPT);

        while (true) {
            selector.select(1000); // Timeout of 1 second
            Set<SelectionKey> selectedKeys = selector.selectedKeys();
            Iterator<SelectionKey> keyIterator = selectedKeys.iterator();

            while (keyIterator.hasNext()) {
                SelectionKey key = keyIterator.next();

                if (!key.isValid()) {
                    continue;
                }

                if (key.isAcceptable()) {
                    acceptConnection(key);
                } else if (key.isReadable()) {
                    readMessage(key);
                }

                keyIterator.remove();
            }
        }
    }

    private void acceptConnection(SelectionKey key) throws IOException {
        ServerSocketChannel serverSocket = (ServerSocketChannel) key.channel();
        SocketChannel clientChannel = serverSocket.accept();
        clientChannel.configureBlocking(false);

        if (activeConnections < maxConnections) {
            clientChannel.register(selector, SelectionKey.OP_READ);
            activeConnections++;
            logConnection("Connected", clientChannel.getRemoteAddress());
        } else {
            rejectConnection(clientChannel);
        }
    }

    private void readMessage(SelectionKey key) throws IOException {
        SocketChannel clientChannel = (SocketChannel) key.channel();
        ByteBuffer buffer = ByteBuffer.allocate(1024);
        int bytesRead = clientChannel.read(buffer);

        if (bytesRead == -1) {
            closeConnection(clientChannel);
            return;
        }

        buffer.flip();
        byte[] data = new byte[buffer.remaining()];
        buffer.get(data);
        String message = new String(data);

        handleMessage(message, clientChannel);
    }

    private void handleMessage(String message, SocketChannel clientChannel) {
        // Process the message and possibly prioritize it based on importance
        int priority = 5; // Default priority if not specified

        try {
            // Simulate some processing time
            Thread.sleep(100);

            logConnection("Processed", clientChannel.getRemoteAddress());
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            logError(e);
        }
    }

    private void rejectConnection(SocketChannel clientChannel) throws IOException {
        clientChannel.close();
        logConnection("Rejected", clientChannel.getRemoteAddress());
    }

    private void closeConnection(SocketChannel clientChannel) throws IOException {
        clientChannel.close();
        activeConnections--;
        logConnection("Disconnected", clientChannel.getRemoteAddress());
    }

    private void logConnection(String action, Object address) {
        System.out.println(action + " connection from " + address);
    }

    private void logError(Exception e) {
        System.err.println("Error: " + e.getMessage());
    }

    public static void main(String[] args) {
        try {
            SecureServer server = new SecureServer(8080, 1000);
            server.start();
        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}
