const express = require('express');
const fs = require('fs');
const path = require('path');
const crypto = require('crypto');

const app = express();
const PORT = process.env.PORT || 3000;

// Set environment variables
app.use(express.json());
app.use((req, res, next) => {
    const env = req.headers['x-env'] || 'development';
    const configPath = path.join(__dirname, `config/${env}.json`);

    if (!fs.existsSync(configPath)) {
        return res.status(500).send('Configuration file not found');
    }

    fs.readFile(configPath, (err, data) => {
        if (err) {
            return res.status(500).send('Failed to read configuration file');
        }

        const config = JSON.parse(data);

        // Validate and sanitize environment variables
        req.envConfig = {};
        for (const key in config) {
            if (config.hasOwnProperty(key)) {
                req.envConfig[key] = crypto.createHash('sha256').update(config[key]).digest('hex');
            }
        }

        next();
    });
});

// Custom module resolver
function loadModule(moduleName, callback) {
    const modulePath = path.join(__dirname, 'modules', moduleName);

    fs.stat(modulePath, (err, stats) => {
        if (err || !stats.isDirectory()) {
            return callback(new Error('Module not found'), null);
        }

        require(modulePath)(callback);
    });
}

// Load services using configuration
app.use((req, res, next) => {
    const services = req.envConfig.services;

    for (const service in services) {
        if (services.hasOwnProperty(service)) {
            loadModule(services[service], (err, module) => {
                if (err) {
                    return res.status(500).send('Failed to load module');
                }

                // Register the module with the application
                req.app.locals[service] = module;
            });
        }
    }

    next();
});

// Health check endpoint
app.get('/health', (req, res) => {
    const services = req.envConfig.services;
    const status = {};

    for (const service in services) {
        if (services.hasOwnProperty(service)) {
            const module = req.app.locals[service];

            if (module && module.isHealthy()) {
                status[service] = 'up';
            } else {
                status[service] = 'down';
            }
        }
    }

    res.json(status);
});

// Fallback mechanism for configuration file
app.use((req, res, next) => {
    const configPath = path.join(__dirname, `config/fallback.json`);

    if (!fs.existsSync(configPath)) {
        return res.status(500).send('Fallback configuration file not found');
    }

    fs.readFile(configPath, (err, data) => {
        if (err) {
            return res.status(500).send('Failed to read fallback configuration file');
        }

        const config = JSON.parse(data);

        // Validate and sanitize environment variables
        req.fallbackEnvConfig = {};
        for (const key in config) {
            if (config.hasOwnProperty(key)) {
                req.fallbackEnvConfig[key] = crypto.createHash('sha256').update(config[key]).digest('hex');
            }
        }

        next();
    });
});

// Cache mechanism for configuration file
app.use((req, res, next) => {
    const cachePath = path.join(__dirname, 'cache', `${req.envConfig.version}.json`);

    if (fs.existsSync(cachePath)) {
        fs.readFile(cachePath, (err, data) => {
            if (!err) {
                req.envConfig = JSON.parse(data);
                return next();
            }
        });
    }

    // Fallback to reading from disk
    const configPath = path.join(__dirname, `config/${req.envConfig.version}.json`);

    fs.readFile(configPath, (err, data) => {
        if (!err) {
            req.envConfig = JSON.parse(data);
        }

        next();
    });
});

// Scale horizontally by using asynchronous operations
app.get('/data', async (req, res) => {
    const module = req.app.locals.dataService;

    try {
        const data = await module.fetchData();
        res.json(data);
    } catch (err) {
        return res.status(500).send('Failed to fetch data');
    }
});

app.listen(PORT, () => {
    console.log(`Server is running on port ${PORT}`);
});
