struct MediaPlayer {
    config: Config,
    audio_player: AudioPlayer,
    video_player: VideoPlayer,
}

impl MediaPlayer {
    fn new(config: Config) -> Self {
        MediaPlayer {
            config,
            audio_player: AudioPlayer::new(config.clone()),
            video_player: VideoPlayer::new(config.clone()),
        }
    }

    async fn play(&self, media_source: MediaSource) -> Result<(), Error> {
        let (tx, mut rx) = mpsc::channel(10);

        task::spawn(async move {
            match media_source {
                MediaSource::Audio(path) => self.audio_player.play(path).await,
                MediaSource::Video(path) => self.video_player.play(path).await,
                MediaSource::Mixed(path) => {
                    let audio_path = path.clone();
                    let video_path = path.clone();

                    tokio::join!(
                        task::spawn(async move {
                            self.audio_player.play(audio_path).await
                        }),
                        task::spawn(async move {
                            self.video_player.play(video_path).await
                        })
                    );
                }
            }

            tx.send(()).unwrap();
        });

        while let Some(_) = rx.recv().await {
            // Handle playback interruption and resume logic here
        }

        Ok(())
    }
}

