        $status = $statuses[$index];
        $retryCount = 0;

        do {
            try {
                $connection = connectToDatabase($clinicId); // Implement this function to get a database connection for the given clinic
                $transactionStarted = false;

                if ($connection->inTransaction()) {
                    $transactionStarted = true;
                } else {
                    $connection->beginTransaction();
                }

                updateClinicRecord($connection, $clinicId, $status, $userId, $clientIp);

                if ($transactionStarted) {
                    $connection->commit();
                } else {
                    $connection->commitTransaction(); // Implement this function to commit the transaction
                }

                $success[$clinicId] = true;
                break; // Exit loop on successful update
            } catch (Exception $e) {
                $retryCount++;
                if ($retryCount > $maxRetries) {
                    $success[$clinicId] = false;
                    error_log("Failed to update clinic ID {$clinicId} after {$maxRetries} retries: " . $e->getMessage());
                    break; // Exit loop on failure
                }

                usleep($retryDelay * 1000); // Sleep for retry delay before next attempt
            } finally {
                if ($connection && $connection->inTransaction()) {
                    $connection->rollBack(); // Ensure transaction is rolled back in case of exception or retry limit reached
                }
            }
        } while ($retryCount <= $maxRetries);
