    private $httpClient;
    private $entityManager;
    private $redisClient;
    private $logger;

    public function __construct(
        HttpClient $httpClient,
        EntityManager $entityManager,
        Redis $redisClient,
        LoggerInterface $logger
    ) {
        $this->httpClient = $httpClient;
        $this->entityManager = $entityManager;
        $this->redisClient = $redisClient;
        $this->logger = $logger;
    }

    public function processTransaction(array $transactionData): void {
        // Validate input data
        if (!isset($transactionData['amount'], $transactionData['currency'], $transactionData['merchantId'], $transactionData['customerId'])) {
            $this->logger->error('Invalid transaction data', ['data' => $transactionData]);
            return;
        }

        $orderId = $transactionData['orderId'] ?? null;

        // Check for duplicate transactions
        if ($this->redisClient->exists($orderId)) {
            $this->logger->info('Duplicate transaction detected', ['orderId' => $orderId]);
            return;
        }

        try {
            // Send transaction to payment gateway
            $response = $this->httpClient->request(
                'POST',
                'https://api.paymentgateway.com/transaction',
                [
                    'json' => $transactionData,
                    'timeout' => 5.0
                ]
            );

            $paymentGatewayResponse = json_decode($response->getBody(), true);

            // Store transaction details in database
            $this->entityManager->persist(
                new TransactionEntity(
                    orderId: $orderId,
                    amount: $transactionData['amount'],
                    currency: $transactionData['currency'],
                    merchantId: $transactionData['merchantId'],
                    customerId: $transactionData['customerId'],
                    paymentStatus: $paymentGatewayResponse['status']
                )
            );
            $this->entityManager->flush();

            // Cache transaction for 24 hours
            $this->redisClient->setex($orderId, 86400, 'processed');

            // Send confirmation emails
            $this->sendConfirmationEmails($transactionData, $paymentGatewayResponse['status']);

        } catch (\Exception $e) {
            $this->logger->error('Error processing transaction', ['exception' => $e]);
        }
    }

    private function sendConfirmationEmails(array $transactionData, string $paymentStatus): void {
        // Logic to send confirmation emails to merchant and customer
        // ...
    }
}
