class NetworkClient {
public:
    void sendRequest(const std::string& url, const std::string& params) {
        // Simulate sending an HTTP GET request
        std::cout << "Sending request to: " << url << "?params=" << params << std::endl;
    }
};

class RateLimiter {
private:
    std::mutex mtx;
    std::unordered_map<std::thread::id, std::chrono::time_point<std::chrono::system_clock>> lastRequestTime;
    const int maxRequestsPerMinute = 5;

public:
    bool canMakeRequest() {
        std::lock_guard<std::mutex> lock(mtx);
        auto now = std::chrono::system_clock::now();
        if (lastRequestTime.empty()) {
            lastRequestTime[std::this_thread::get_id()] = now;
            return true;
        }
        auto& time = lastRequestTime[std::this_thread::get_id()];
        if (time + std::chrono::minutes(1) <= now || lastRequestTime.size() < maxRequestsPerMinute) {
            time = now;
            return true;
        }
        return false;
    }

    void requestCompleted() {
        std::lock_guard<std::mutex> lock(mtx);
        lastRequestTime.erase(std::this_thread::get_id());
    }
};

class UserProfileSession {
private:
    NetworkClient client;
    RateLimiter rateLimiter;

public:
    void dispatchNetworkRequest(const std::string& userId, const std::string& params) {
        if (!rateLimiter.canMakeRequest()) {
            std::cout << "Rate limit exceeded. Request not sent." << std::endl;
            return;
        }
        client.sendRequest("https://api.example.com/user/" + userId, params);
        rateLimiter.requestCompleted();
    }
};

int main() {
    UserProfileSession session;
    std::vector<std::thread> threads;

    for (int i = 0; i < 10; ++i) {
        threads.emplace_back([&session]() {
            for (int j = 0; j < 3; ++j) {
                session.dispatchNetworkRequest("user" + std::to_string(j), "details=true");
                std::this_thread::sleep_for(std::chrono::milliseconds(100));
            }
        });
    }

    for (auto& thread : threads) {
        thread.join();
    }

    return 0;
}
