function robustAsyncAggregation(numbers, initialValue, reducerCallback) {
    return new Promise((resolve, reject) => {
        let accumulator = initialValue;

        numbers.reduce(async (accPromise, num) => {
            try {
                const currentAcc = await accPromise;
                accumulator = await reducerCallback(currentAcc, num);
            } catch (error) {
                reject(error);
            }
        }, Promise.resolve(accumulator))
        .then(() => resolve(accumulator))
        .catch(reject);
    });
}

// Example usage:
const numbers = [1, 2, 3, 4, 5];
const initialValue = 0;
const reducerCallback = (acc, num) => {
    return new Promise((resolve) => {
        setTimeout(() => resolve(acc + num), 100); // Simulate async operation
    });
};

robustAsyncAggregation(numbers, initialValue, reducerCallback)
    .then(result => console.log('Final result:', result))
    .catch(error => console.error('Error:', error));
