}

// Function to handle memory cleanup
void cleanup_crypto_library(CryptoLibrary *lib) {
    EVP_CIPHER_CTX_free(lib->aes_ctx);
    EVP_CIPHER_CTX_free(lib->camellia_ctx);
    EVP_MD_CTX_free(lib->md5_ctx);
    EVP_MD_CTX_free(lib->sha_ctx);
    RSA_free(lib->rsa_key);
    free(lib);
}

// Thread-safe logging function
void log_crypto_operation(const char *operation, int success, const char *error_code) {
    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);
    pthread_mutex_lock(&lock);

    time_t current_time = time(NULL);
    struct tm *timeinfo = localtime(&current_time);
    printf("[%s] %s: %s\n", asctime(timeinfo), operation, success ? "Success" : error_code);

    pthread_mutex_unlock(&lock);
}

// Example usage
int main() {
    CryptoLibrary *lib = init_crypto_library(1); // Use hardware acceleration if available

    unsigned char key[AES_BLOCK_SIZE], iv[AES_BLOCK_SIZE];
    memset(key, 0x00, AES_BLOCK_SIZE);
    memset(iv, 0x00, AES_BLOCK_SIZE);

    unsigned char plaintext[] = "Hello, World!";
    unsigned char ciphertext[sizeof(plaintext)];
    unsigned char decryptedtext[sizeof(plaintext)];

    if (aes_encrypt(lib, plaintext, sizeof(plaintext), ciphertext)) {
        printf("Encryption successful.\n");
    } else {
        printf("Encryption failed.\n");
    }

    if (aes_decrypt(lib, ciphertext, sizeof(ciphertext), decryptedtext)) {
        printf("Decryption successful: %s\n", decryptedtext);
    } else {
        printf("Decryption failed.\n");
    }

    cleanup_crypto_library(lib);

    return 0;
}
```

This code provides a basic structure for integrating various cryptographic primitives into a modular library using OpenSSL. It includes functions for AES encryption and decryption, MD5 hashing, SHA-1 hashing, RSA signing, and RSA verification. The `init_crypto_library` function initializes the cryptographic context, while the `cleanup_crypto_library` function cleans up resources. The `log_crypto_operation` function provides a thread-safe logging mechanism.

Please note that this is a simplified example and does not include error handling for every operation, which should be added in a production environment. Additionally, the code assumes certain OpenSSL functions are available and does not handle hardware acceleration explicitly.']

