import java.io.*;
import java.util.concurrent.*;
import java.lang.management.*;

public class ProcessManager {
    private ExecutorService executor;
    private Map<String, Future<?>> processMap;

    public ProcessManager(int poolSize) {
        this.executor = Executors.newFixedThreadPool(poolSize);
        this.processMap = new ConcurrentHashMap<>();
    }

    public void executeCommand(String command, String[] envp, File dir) throws InterruptedException, IOException {
        ProcessBuilder pb = new ProcessBuilder(command.split(" "));
        pb.environment().putAll(System.getenv());
        if (envp != null) {
            for (String env : envp) {
                String[] pair = env.split("=");
                pb.environment().put(pair[0], pair[1]);
            }
        }
        pb.directory(dir);
        Process process = pb.start();

        Future<?> future = executor.submit(() -> {
            try (
                BufferedReader in = new BufferedReader(new InputStreamReader(process.getInputStream()));
                BufferedWriter out = new BufferedWriter(new FileWriter(getLogFilePath(command)))
            ) {
                String line;
                while ((line = in.readLine()) != null) {
                    out.write(line);
                    out.newLine();
                }
            } catch (IOException e) {
                e.printStackTrace();
            }

            try (
                BufferedReader errorIn = new BufferedReader(new InputStreamReader(process.getErrorStream()));
                BufferedWriter errorOut = new BufferedWriter(new FileWriter(getErrorLogFilePath(command)))
            ) {
                String line;
                while ((line = errorIn.readLine()) != null) {
                    errorOut.write(line);
                    errorOut.newLine();
                }
            } catch (IOException e) {
                e.printStackTrace();
            }

            try {
                int exitCode = process.waitFor();
                System.out.println("Process exited with code " + exitCode);
            } catch (InterruptedException e) {
                process.destroy();
                System.out.println("Process interrupted");
            }
        });

        processMap.put(command, future);
    }

    public void interruptProcess(String command) {
        Future<?> future = processMap.get(command);
        if (future != null && !future.isDone()) {
            future.cancel(true);
            System.out.println("Interrupted process: " + command);
        } else {
            System.out.println("No running process found for: " + command);
        }
    }

    private String getLogFilePath(String command) {
        return "logs/" + command.replace(" ", "_") + ".log";
    }

    private String getErrorLogFilePath(String command) {
        return "errors/" + command.replace(" ", "_") + "_error.log";
    }

    public void shutdown() {
        executor.shutdown();
        try {
            if (!executor.awaitTermination(60, TimeUnit.SECONDS)) {
                executor.shutdownNow();
            }
        } catch (InterruptedException e) {
            executor.shutdownNow();
        }
    }

    public static void main(String[] args) throws InterruptedException, IOException {
        ProcessManager manager = new ProcessManager(5);
        manager.executeCommand("ls -la", null, new File("/home"));
        // Add more commands as needed
        manager.shutdown();
    }
}
