enum StatusCode {
    SUCCESS,
    INVALID_JSON,
    MISSING_FIELDS,
    ACCESS_TOKEN_ERROR,
    EXPIRES_IN_ERROR,
    TOKEN_TYPE_ERROR,
    REFRESH_TOKEN_ERROR,
    STRING_LENGTH_ERROR
};

int validate_access_token(const char *token) {
    if (token == NULL || token[0] == '\0' || !isalnum(token[0])) {
        return ACCESS_TOKEN_ERROR;
    }
    return SUCCESS;
}

int validate_expires_in(long expires_in) {
    // Placeholder for overflow check
    if (expires_in <= 0) {
        return EXPIRES_IN_ERROR;
    }
    return SUCCESS;
}

int validate_token_type(const char *token_type, const char *expected_type) {
    if (strncasecmp(token_type, expected_type, strlen(expected_type)) != 0) {
        return TOKEN_TYPE_ERROR;
    }
    return SUCCESS;
}

int validate_refresh_token(const char *refresh_token) {
    uuid_t uuid;
    int ret = uuid_parse(refresh_token, uuid);
    if (ret != 0 || uuid[6] & 0xf0 != 0xd0) {
        return REFRESH_TOKEN_ERROR;
    }
    return SUCCESS;
}

int validate_json(const char *json_string, char **access_token, long *expires_in, char **token_type, char **refresh_token) {
    // Placeholder for JSON parsing and validation logic
    // This is a simplified example
    if (sscanf(json_string, "{\"access_token\":\"%[^,]\", \"expires_in\":%ld, \"token_type\":\"%s\", \"refresh_token\":\"%s\"}",
               access_token, expires_in, token_type, refresh_token) != 4) {
        return INVALID_JSON;
    }
    return SUCCESS;
}

enum StatusCode process_oauth2_token(const char *json_string, char **error_message) {
    if (json_string == NULL || strlen(json_string) > 1024) {
        *error_message = "Invalid JSON string";
        return STRING_LENGTH_ERROR;
    }

    char *access_token, *token_type, *refresh_token;
    long expires_in;

    int json_status = validate_json(json_string, &access_token, &expires_in, &token_type, &refresh_token);
    if (json_status != SUCCESS) {
        *error_message = "Malformed JSON object";
        return json_status;
    }

    int access_token_status = validate_access_token(access_token);
    if (access_token_status != SUCCESS) {
        *error_message = "Invalid access token format";
        return access_token_status;
    }

    int expires_in_status = validate_expires_in(expires_in);
    if (expires_in_status != SUCCESS) {
        *error_message = "Invalid expires in value";
        return expires_in_status;
    }

    int token_type_status = validate_token_type(token_type, "Bearer");
    if (token_type_status != SUCCESS) {
        *error_message = "Token type must be Bearer";
        return token_type_status;
    }

    if (refresh_token != NULL && strlen(refresh_token) > 1024) {
        *error_message = "Refresh token exceeds maximum length";
        return STRING_LENGTH_ERROR;
    }

    int refresh_token_status = validate_refresh_token(refresh_token);
    if (refresh_token_status != SUCCESS) {
        *error_message = "Invalid refresh token format";
        return refresh_token_status;
    }

    *error_message = NULL;
    return SUCCESS;
}
