public class DecryptionHelper
{
    public static string DecryptMessage(string base64EncodedEncryptedMessage, byte[] key, byte[] iv)
    {
        using (TripleDES des = TripleDES.Create())
        {
            des.Key = key;
            des.IV = iv;
            des.Mode = CipherMode.CBC;
            des.Padding = PaddingMode.PKCS7;

            using (MemoryStream msDecrypt = new MemoryStream(Convert.FromBase64String(base64EncodedEncryptedMessage)))
            {
                using (CryptoStream csDecrypt = new CryptoStream(msDecrypt, des.CreateDecryptor(), CryptoStreamMode.Read))
