public class SecureMessagingManager
{
    private readonly byte[] _key;
    private readonly byte[] _iv;
    private readonly ILogger _logger;

    public SecureMessagingManager(byte[] key, byte[] iv, ILogger logger)
    {
        _key = key;
        _iv = iv;
        _logger = logger ?? throw new ArgumentNullException(nameof(logger));
    }

    public byte[] Encrypt(string plainText, PaddingMode paddingMode)
    {
        using (Aes aesAlg = Aes.Create())
        {
            aesAlg.Key = _key;
            aesAlg.IV = _iv;
            aesAlg.Padding = paddingMode;

            ICryptoTransform encryptor = aesAlg.CreateEncryptor(aesAlg.Key, aesAlg.IV);

            using (MemoryStream msEncrypt = new MemoryStream())
            {
                using (CryptoStream csEncrypt = new CryptoStream(msEncrypt, encryptor, CryptoStreamMode.Write))
                {
                    using (StreamWriter swEncrypt = new StreamWriter(csEncrypt))
                    {
                        swEncrypt.Write(plainText);
                    }
                    return msEncrypt.ToArray();
                }
            }
        }
    }

    public string Decrypt(byte[] cipherText, PaddingMode paddingMode)
    {
        try
        {
            using (Aes aesAlg = Aes.Create())
            {
                aesAlg.Key = _key;
                aesAlg.IV = _iv;
                aesAlg.Padding = paddingMode;

                ICryptoTransform decryptor = aesAlg.CreateDecryptor(aesAlg.Key, aesAlg.IV);

                using (MemoryStream msDecrypt = new MemoryStream(cipherText))
                {
                    using (CryptoStream csDecrypt = new CryptoStream(msDecrypt, decryptor, CryptoStreamMode.Read))
                    {
                        using (StreamReader srDecrypt = new StreamReader(csDecrypt))
                        {
                            string decryptedData = srDecrypt.ReadToEnd();
                            _logger.Log("Decryption successful", LogLevel.Success);
                            return decryptedData;
                        }
                    }
                }
            }
        }
        catch (Exception ex)
        {
            _logger.Log($"Decryption failed: {ex.Message}", LogLevel.Error);
            throw;
        }
    }

