using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using Newtonsoft.Json;

public class DataProcessor
{
    private const string CacheFilePath = "dataCache.json";
    private static Dictionary<int, CustomData> cache = new Dictionary<int, CustomData>();

    public static List<CustomData> LoadAndDeserialize(string filePath)
    {
        try
        {
            // Check if data is available in cache
            if (File.Exists(CacheFilePath))
            {
                var cachedData = File.ReadAllText(CacheFilePath);
                cache = JsonConvert.DeserializeObject<Dictionary<int, CustomData>>(cachedData);
                return cache.Values.ToList();
            }

            // Read and deserialize from file
            using (var reader = new BinaryReader(File.Open(filePath, FileMode.Open)))
            {
                List<CustomData> data = new List<CustomData>();
                while (reader.BaseStream.Position < reader.BaseStream.Length)
                {
                    CustomData item = DeserializeItem(reader);
                    data.Add(item);
                    cache[item.Id] = item;
                }
                return data;
            }
        }
        catch (Exception ex)
        {
            // Handle exceptions gracefully
            Console.WriteLine($"Error loading or deserializing data: {ex.Message}");
            return new List<CustomData>();
        }
    }

    private static CustomData DeserializeItem(BinaryReader reader)
    {
        // Deserialize a single item from the binary stream
        int id = reader.ReadInt32();
        string name = reader.ReadString();
        double value = reader.ReadDouble();
        return new CustomData { Id = id, Name = name, Value = value };
    }
}

public class CustomData
{
    public int Id { get; set; }
    public string Name { get; set; }
    public double Value { get; set; }

    // Implement necessary constructors and overrides for Equals and GetHashCode if needed
}
```

