import java.io.*;
import java.net.URL;
import javax.script.ScriptEngine;
import javax.script.ScriptEngineManager;
import javax.script.ScriptException;

public class DeserializationAndJavaScriptExecutor {

    private static final Cache<String, Object> deserializationCache = new Cache<>();

    public static <T> T deserialize(byte[] data) throws CustomDeserializationException {
        try {
            if (deserializationCache.containsKey(data)) {
                return (T) deserializationCache.get(data);
            }
            ByteArrayInputStream bis = new ByteArrayInputStream(data);
            ObjectInputStream ois = new ObjectInputStream(bis);
            T obj = (T) ois.readObject();
            ois.close();
            bis.close();
            deserializationCache.put(data, obj);
            return obj;
        } catch (IOException | ClassNotFoundException e) {
            throw new CustomDeserializationException("Error during deserialization", e);
        }
    }

    public static void executeJavaScript(String filePath) throws CustomJavaScriptExecutionException {
        try {
            ScriptEngineManager manager = new ScriptEngineManager();
            ScriptEngine engine = manager.getEngineByName("javascript");
            URL fileUrl = DeserializationAndJavaScriptExecutor.class.getResource(filePath);
            if (fileUrl == null) {
                throw new CustomJavaScriptExecutionException("File not found: " + filePath);
            }
            engine.eval(new FileReader(fileUrl.getFile()));
        } catch (ScriptException e) {
            throw new CustomJavaScriptExecutionException("Error during JavaScript execution", e);
        }
    }

    static class Cache<K, V> {
        private final java.util.Map<K, V> cache = new java.util.HashMap<>();

        public void put(K key, V value) {
            cache.put(key, value);
        }

        public boolean containsKey(K key) {
            return cache.containsKey(key);
        }

        public V get(K key) {
            return cache.get(key);
        }
    }

    static class CustomDeserializationException extends RuntimeException {
        public CustomDeserializationException(String message, Throwable cause) {
            super(message, cause);
        }
    }

    static class CustomJavaScriptExecutionException extends RuntimeException {
        public CustomJavaScriptExecutionException(String message, Throwable cause) {
            super(message, cause);
        }
    }
}
