use std::env;
use std::fs::{self, DirBuilder};
use std::path::{Path, PathBuf};
use tokio::task;

async fn create_config_directory(
    home_dir: Option<PathBuf>,
    env_var_name: &str,
    config_dir_name: &str,
) -> Result<(), Box<dyn std::error::Error>> {
    let home_dir = match home_dir.or_else(|| dirs_next::home_dir()) {
        Some(path) => path,
        None => return Err("Failed to get user home directory".into()),
    };

    let config_path = home_dir.join(config_dir_name);
    if config_path.exists() {
        if env::var(env_var_name).is_ok() {
            log::info!("Configuration directory already exists and environment variable is set.");
            return Ok(());
        } else {
            env::set_var(env_var_name, config_path);
            log::info!("Environment variable {} set to existing configuration directory.", env_var_name);
            return Ok(());
        }
    }

    let mut builder = DirBuilder::new();
    builder.recursive(true);

    match builder.create(&config_path).await {
        Ok(_) => {
            env::set_var(env_var_name, config_path);
            log::info!("Configuration directory created successfully and environment variable set.");
            Ok(())
        }
        Err(e) if e.kind() == std::io::ErrorKind::AlreadyExists => {
            let retry_count = 5;
            for i in 0..retry_count {
                tokio::time::sleep(std::time::Duration::from_secs(2u64.pow(i))).await;
                if fs::try_exists(&config_path).await? {
                    env::set_var(env_var_name, config_path);
                    log::info!("Configuration directory created successfully and environment variable set.");
                    return Ok(());
                }
            }
            Err("Failed to create configuration directory after retries".into())
        }
        Err(e) => Err(format!("Failed to create configuration directory: {}", e).into()),
    }
}

#[tokio::main]
async fn main() {
    if let Err(e) = create_config_directory(None, "CONFIG_DIR", "config").await {
        log::error!("Error creating configuration directory: {}", e);
    }
}
```

