#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define INITIAL_CAPACITY 10
#define GROWTH_FACTOR 2
#define RESIDENCY_TRACKING_ENABLED 0

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* data;
    size_t capacity;
    size_t size;
    size_t successful_allocations;
    size_t failed_allocations;
    clock_t total_allocation_time;
    pthread_mutex_t mutex;
#if RESIDENCY_TRACKING_ENABLED
    // Add residency tracking fields here
#endif
} DynamicArray;

DynamicArray* create_dynamic_array() {
    DynamicArray* array = (DynamicArray*)malloc(sizeof(DynamicArray));
    if (array == NULL) {
        return NULL;
    }
    array->data = (NFAPI_CRC_INDICATION_PDU_T*)calloc(INITIAL_CAPACITY, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (array->data == NULL) {
        free(array);
        return NULL;
    }
    array->capacity = INITIAL_CAPACITY;
    array->size = 0;
    array->successful_allocations = 0;
    array->failed_allocations = 0;
    array->total_allocation_time = 0;
    pthread_mutex_init(&array->mutex, NULL);
#if RESIDENCY_TRACKING_ENABLED
    // Initialize residency tracking fields here
#endif
    return array;
}

void destroy_dynamic_array(DynamicArray* array) {
    if (array != NULL) {
        free(array->data);
        pthread_mutex_destroy(&array->mutex);
        free(array);
    }
}

int add_element_to_array(DynamicArray* array, NFAPI_CRC_INDICATION_PDU_T element) {
    pthread_mutex_lock(&array->mutex);
    if (array->size >= array->capacity) {
        size_t new_capacity = array->capacity * GROWTH_FACTOR;
        NFAPI_CRC_INDICATION_PDU_T* new_data = (NFAPI_CRC_INDICATION_PDU_T*)realloc(array->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (new_data == NULL) {
            pthread_mutex_unlock(&array->mutex);
            return -1;
        }
        array->data = new_data;
        array->capacity = new_capacity;
    }
    array->data[array->size++] = element;
    pthread_mutex_unlock(&array->mutex);
    return 0;
}

void get_array_stats(DynamicArray* array, size_t* total_elements, size_t* successful_allocations, size_t* failed_allocations) {
    *total_elements = array->size;
    *successful_allocations = array->successful_allocations;
    *failed_allocations = array->failed_allocations;
}

#if RESIDENCY_TRACKING_ENABLED
// Implement residency tracking functions here
#endif
