int current_size = 0;
pthread_mutex_t pdus_mutex = PTHREAD_MUTEX_INITIALIZER;

void generate_pdu(NFAPI_CRC_INDICATION_PDU_T **pdu) {
    // Generate a valid NFAPI_CRC_INDICATION_PDU_T structure
    *pdu = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    (*pdu)->RNTI = rand() % 1024; // Example random RNTI generation
    (*pdu)->CRCFLAG = rand() % 2; // Randomly set CRCFLAG
}

void add_pdu_to_list() {
    pthread_mutex_lock(&pdus_mutex);
    if (current_size < MAX_STRUCTURES) {
        generate_pdu(&pdus[current_size]);
        current_size++;
    }
    pthread_mutex_unlock(&pdus_mutex);
}

void process_batch() {
    for (int i = 0; i < BATCH_SIZE && current_size > 0; i++) {
        // Process each PDU in the batch
        NFAPI_CRC_INDICATION_PDU_T *pdu = pdus[current_size - 1];
        // Perform necessary operations with pdu
        free(pdu);
        current_size--;
    }
}

void *batch_processor_thread(void *arg) {
    while (1) {
        process_batch();
        sleep(1); // Pause for a second between batches
    }
    return NULL;
}

int main() {
    pthread_t processor_thread;
    srand(time(NULL)); // Seed the random number generator

    // Create and start the batch processing thread
    if (pthread_create(&processor_thread, NULL, batch_processor_thread, NULL) != 0) {
        perror("Failed to create thread");
        return EXIT_FAILURE;
    }

    // Simulate adding PDUs to the list
    for (int i = 0; i < MAX_STRUCTURES; i++) {
        add_pdu_to_list();
    }

    // Wait for the processor thread to finish
    pthread_join(processor_thread, NULL);

    return EXIT_SUCCESS;
}
