        if (pthread_mutex_unlock(&mutex) != 0) {
            free(pdu_data);
            log_message("Error: Failed to unlock mutex");
            return -5;
        }
    }

    *pdus = (NFAPI_CRC_INDICATION_PDU_T*)pdu_data;
    pthread_mutex_destroy(&mutex);
    log_message("Info: Memory allocation and initialization successful");
