// Function to add a neighbor to a node
void add_neighbor(NODE* node, NODE* neighbor) {
    node->neighbor_count++;
    node->neighbors = (NODE**)realloc(node->neighbors, node->neighbor_count * sizeof(NODE*));
    node->neighbors[node->neighbor_count - 1] = neighbor;
}

// Function to initialize the network topology
NODE** init_network(int num_nodes, int max_neighbors_per_node) {
    NODE** nodes = (NODE**)malloc(num_nodes * sizeof(NODE*));
    for (int i = 0; i < num_nodes; i++) {
        nodes[i] = create_node(i);
    }
    // Randomly connect nodes based on the number of neighbors per node
    srand(time(NULL)); // Seed for random numbers
    for (int i = 0; i < num_nodes; i++) {
        int count = rand() % max_neighbors_per_node + 1;
        for (int j = 0; j < count; j++) {
            int neighbor_id = rand() % num_nodes;
            if (neighbor_id != i && !is_neighbor(nodes[i], nodes[neighbor_id])) {
                add_neighbor(nodes[i], nodes[neighbor_id]);
                add_neighbor(nodes[neighbor_id], nodes[i]); // Assuming undirected graph
            }
        }
    }
    return nodes;
}

// Helper function to check if two nodes are neighbors
int is_neighbor(NODE* node1, NODE* node2) {
    for (int i = 0; i < node1->neighbor_count; i++) {
