#define MAX_UE_COUNT 10000

typedef struct {
    int ue_id;
    int rssi;
    float snr;
} LTEPHY_NTF_RXUEINFO_TAG;

LTEPHY_NTF_RXUEINFO_TAG *ue_list[MAX_UE_COUNT];
int ue_count = 0;
pthread_mutex_t ue_mutex;

void initialize_ue_list() {
    pthread_mutex_lock(&ue_mutex);
    for (int i = 0; i < MAX_UE_COUNT; i++) {
        LTEPHY_NTF_RXUEINFO_TAG *ue_info = malloc(sizeof(LTEPHY_NTF_RXUEINFO_TAG));
        if (ue_info) {
            ue_info->ue_id = i;
            ue_info->rssi = rand() % 100;
            ue_info->snr = ((float)(rand() % 20)) + 10.0;
            ue_list[i] = ue_info;
            ue_count++;
        }
    }
    pthread_mutex_unlock(&ue_mutex);
}

void *update_ue_info(void *arg) {
    int delay_ms = *(int *)arg;
    while (1) {
        pthread_mutex_lock(&ue_mutex);
        for (int i = 0; i < ue_count; i++) {
            if (ue_list[i]) {
                ue_list[i]->rssi = rand() % 100;
                ue_list[i]->snr = ((float)(rand() % 20)) + 10.0;
            }
        }
        pthread_mutex_unlock(&ue_mutex);
        usleep(delay_ms * 1000);
    }
    return NULL;
}

int main() {
    srand(time(NULL));
    pthread_t update_thread;

    pthread_mutex_init(&ue_mutex, NULL);
    initialize_ue_list();

    int update_delay = 5000; // 5 seconds
    pthread_create(&update_thread, NULL, update_ue_info, &update_delay);

    while (1) {
        pthread_mutex_lock(&ue_mutex);
        for (int i = 0; i < ue_count; i++) {
            if (ue_list[i]) {
                printf("UE ID: %d, RSSI: %d, SNR: %.2f\n", ue_list[i]->ue_id, ue_list[i]->rssi, ue_list[i]->snr);
            }
        }
        pthread_mutex_unlock(&ue_mutex);
        sleep(1);
    }

    pthread_join(update_thread, NULL);
    pthread_mutex_destroy(&ue_mutex);

    for (int i = 0; i < MAX_UE_COUNT; i++) {
        free(ue_list[i]);
    }

    return 0;
}
