#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_ENTRIES 10000
#define GROWTH_FACTOR 2

typedef struct {
    int ue_id;
    char rx_channel_info[50];
    int rssi;
    int snr;
} LTEPHY_NTF_RXUEINFO_TAG;

typedef struct {
    LTEPHY_NTF_RXUEINFO_TAG *array;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} DynamicArray;

void initializeDynamicArray(DynamicArray *arr, size_t initial_capacity) {
    arr->array = (LPHY_NTF_RXUEINFO_TAG *)malloc(initial_capacity * sizeof(LTEPHY_NTF_RXUEINFO_TAG));
    if (arr->array == NULL) {
        perror("Failed to allocate memory for dynamic array");
        exit(EXIT_FAILURE);
    }
    arr->capacity = initial_capacity;
    arr->size = 0;
    pthread_mutex_init(&arr->mutex, NULL);
}

void resizeDynamicArray(DynamicArray *arr) {
    size_t new_capacity = arr->capacity * GROWTH_FACTOR;
    LTEPHY_NTF_RXUEINFO_TAG *new_array = (LPHY_NTF_RXUEINFO_TAG *)realloc(arr->array, new_capacity * sizeof(LTEPHY_NTF_RXUEINFO_TAG));
    if (new_array == NULL) {
        perror("Failed to reallocate memory for dynamic array");
        exit(EXIT_FAILURE);
    }
    arr->array = new_array;
    arr->capacity = new_capacity;
}

void addEntry(DynamicArray *arr, int ue_id, const char *rx_channel_info) {
    pthread_mutex_lock(&arr->mutex);
    if (arr->size >= MAX_ENTRIES) {
        fprintf(stderr, "Maximum number of entries reached\n");
        pthread_mutex_unlock(&arr->mutex);
        return;
    }
    if (arr->size == arr->capacity) {
        resizeDynamicArray(arr);
    }
    LTEPHY_NTF_RXUEINFO_TAG *entry = &arr->array[arr->size++];
    entry->ue_id = ue_id;
    strncpy(entry->rx_channel_info, rx_channel_info, sizeof(entry->rx_channel_info) - 1);
    entry->rssi = rand() % 100; // Random value between 0 and 99
    entry->snr = rand() % 20;  // Random value between 0 and 19
    pthread_mutex_unlock(&arr->mutex);
}

void freeDynamicArray(DynamicArray *arr) {
    pthread_mutex_destroy(&arr->mutex);
    free(arr->array);
}
