        if (!*output_buffer || strlen(*output_buffer) + max_length > output_buffer_size) {
            return "Output buffer overflow";
        }
        strcpy(*output_buffer, input);
        strncat(*output_buffer, &termination_char, 1);
        return NULL;
    }

    char *output = malloc(max_length);
    if (!output) return "Memory allocation failed";

    snprintf(output, max_length, "%s%c", input, termination_char);
    *output_buffer = output;
    return NULL;
}
