#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_RNTI 1024
#define INITIAL_POOL_SIZE 16

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct RNTIPool {
    int pool[MAX_RNTI];
    int size;
    pthread_mutex_t lock;
} RNTIPool;

RNTIPool rntiPool = {{0}, 0, PTHREAD_MUTEX_INITIALIZER};

NFAPI_CRC_INDICATION_PDU_T* createNFAPICRCIndication(int N) {
    if (N <= 0) return NULL;

    NFAPI_CRC_INDICATION_PDU_T* list = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list) return NULL;

    pthread_mutex_lock(&rntiPool.lock);
    int availableRNTIs = MAX_RNTI - rntiPool.size;
    if (N > availableRNTIs) {
        pthread_mutex_unlock(&rntiPool.lock);
        free(list);
        return NULL; // Insufficient RNTIs available
    }

    for (int i = 0; i < N; ++i) {
        list[i].RX_UE_INFORMATION_TAG = rand() % MAX_RNTI;
        while (1) {
            int rnti = rand() % MAX_RNTI;
            int found = 0;
            for (int j = 0; j < rntiPool.size; ++j) {
                if (rntiPool.pool[j] == rnti) {
                    found = 1;
                    break;
                }
            }
            if (!found) {
                list[i].RNTI = rnti;
                rntiPool.pool[rntiPool.size++] = rnti;
                break;
            }
        }

        // Simulate CRCFLAG validation according to protocol standards
        list[i].CRCFLAG = rand() % 2; // Example: Randomly set to 0 or 1
    }

    pthread_mutex_unlock(&rntiPool.lock);
    return list;
}

void freeNFAPICRCIndication(NFAPI_CRC_INDICATION_PDU_T* list, int N) {
    if (list) {
        free(list);
    }
}
