int fs_manager_create(FILE_SYSTEM_MANAGER_T* manager, size_t initial_size) {
    if (manager == NULL || initial_size == 0) return -1;

    manager->files = (FILE_SYSTEM_OBJECT_T**)malloc(initial_size * sizeof(FILE_SYSTEM_OBJECT_T*));
    manager->directories = (DIRECTORY_ENTRY_T**)malloc(initial_size * sizeof(DIRECTORY_ENTRY_T*));

    if (manager->files == NULL || manager->directories == NULL) {
        free(manager->files);
        free(manager->directories);
        return -1;
    }

    manager->file_count = 0;
    manager->directory_count = 0;
    manager->max_files = initial_size;
    manager->max_directories = initial_size;

    return 0;
}

int fs_manager_add_file(FILE_SYSTEM_MANAGER_T* manager, char* file_name, long file_size, int access_mode) {
    if (manager == NULL || file_name == NULL) return -1;

    if (manager->file_count >= manager->max_files) {
        // Resize the array
        FILE_SYSTEM_OBJECT_T** new_files = realloc(manager->files, manager->max_files * 2 * sizeof(FILE_SYSTEM_OBJECT_T*));
        if (new_files == NULL) return -1;
        manager->files = new_files;
        manager->max_files *= 2;
    }

    manager->files[manager->file_count] = (FILE_SYSTEM_OBJECT_T*)malloc(sizeof(FILE_SYSTEM_OBJECT_T));
    if (manager->files[manager->file_count] == NULL) return -1;

    manager->files[manager->file_count]->file_name = strdup(file_name);
    manager->files[manager->file_count]->file_size = file_size;
    manager->files[manager->file_count]->access_mode = access_mode;
    time(&manager->files[manager->file_count]->modification_time);

    // Calculate checksum here

    manager->file_count++;
    return 0;
}

