#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define NUM_UEs 1000
#define RSSI_MIN -120
#define RSSI_MAX -80
#define SNR_MIN -15
#define SNR_MAX 15

typedef struct {
    int ue_id;
    int rx_channel_info[4];
} LTEPHY_NTF_RXUEINFO_TAG;

LTEPHY_NTF_RXUEINFO_TAG *ue_list = NULL;
pthread_mutex_t list_lock;
int initialized = 0;

void initialize_ue_list() {
    pthread_mutex_lock(&list_lock);
    if (!initialized) {
        ue_list = (LTEPHY_NTF_RXUEINFO_TAG *)malloc(NUM_UEs * sizeof(LTEPHY_NTF_RXUEINFO_TAG));
        if (ue_list == NULL) {
            fprintf(stderr, "Memory allocation failed\n");
            return;
        }
        srand(time(NULL));
        for (int i = 0; i < NUM_UEs; i++) {
            ue_list[i].ue_id = i + 1;
            for (int j = 0; j < 4; j++) {
                ue_list[i].rx_channel_info[j] = rand() % (RSSI_MAX - RSSI_MIN + 1) + RSSI_MIN;
            }
        }
        initialized = 1;
    }
    pthread_mutex_unlock(&list_lock);
}

void update_ue_list(LTEPHY_NTF_RXUEINFO_TAG *new_data, int num_updates) {
    pthread_mutex_lock(&list_lock);
    for (int i = 0; i < num_updates && i < NUM_UEs; i++) {
        ue_list[i] = new_data[i];
    }
    pthread_mutex_unlock(&list_lock);
}

void* update_thread(void *arg) {
