typedef struct {
    char username[256];
    char email[256];
    char phone_number[16];
    char roles[3][64];
} UserProfile;

static const char* role_mapping[] = {"admin", "user", "guest"};

int validate_and_process_json(const char* json_str, int mode, UserProfile** profiles, int* count) {
    cJSON* root = cJSON_Parse(json_str);
    if (!root || !cJSON_IsArray(root)) {
        return -1;
    }

    *count = cJSON_GetArraySize(root);
    *profiles = (UserProfile*)malloc(*count * sizeof(UserProfile));
    if (!*profiles) {
        cJSON_Delete(root);
        return -2;
    }

    for (int i = 0; i < *count; ++i) {
        UserProfile* profile = &(*profiles)[i];
        cJSON* user = cJSON_GetArrayItem(root, i);

        // Parse and validate each field
        if (cJSON_IsObject(user)) {
            cJSON* username = cJSON_GetObjectItemCaseSensitive(user, "username");
            if (!cJSON_IsString(username) || !username->valuestring) return -3;
            strcpy(profile->username, username->valuestring);

            cJSON* email = cJSON_GetObjectItemCaseSensitive(user, "email");
            if (cJSON_IsString(email) && email->valuestring) {
                // Validate and normalize email
                strncpy(profile->email, email->valuestring, sizeof(profile->email));
            } else return -3;

            cJSON* phone_number = cJSON_GetObjectItemCaseSensitive(user, "phone_number");
            if (cJSON_IsString(phone_number) && phone_number->valuestring) {
                // Normalize phone number
                strncpy(profile->phone_number, phone_number->valuestring, sizeof(profile->phone_number));
            } else return -3;

            cJSON* roles = cJSON_GetObjectItemCaseSensitive(user, "roles");
            if (cJSON_IsArray(roles)) {
                int role_count = cJSON_GetArraySize(roles);
                for (int j = 0; j < role_count && j < 3; ++j) {
                    cJSON* role_item = cJSON_GetArrayItem(roles, j);
                    if (cJSON_IsString(role_item)) {
                        const char* role_name = role_item->valuestring;
                        int mapped_role_index = -1;
                        for (int k = 0; k < sizeof(role_mapping) / sizeof(role_mapping[0]); ++k) {
                            if (strcmp(role_name, role_mapping[k]) == 0) {
                                mapped_role_index = k;
                                break;
                            }
                        }
                        if (mapped_role_index != -1) {
                            strcpy(profile->roles[j], role_mapping[mapped_role_index]);
                        } else {
                            return -3;
                        }
                    } else {
                        return -3;
                    }
                }
            } else return -3;

            // Transform data based on mode
            switch (mode) {
                case 0: // Lowercase
                    for (int j = 0; profile->username[j]; ++j) profile->username[j] = tolower(profile->username[j]);
                    for (int j = 0; profile->email[j]; ++j) profile->email[j] = tolower(profile->email[j]);
                    for (int j = 0; profile->phone_number[j]; ++j) profile->phone_number[j] = tolower(profile->phone_number[j]);
                    for (int j = 0; j < 3 && profile->roles[j][0]; ++j) {
                        for (int k = 0; profile->roles[j][k]; ++k) profile->roles[j][k] = tolower(profile->roles[j][k]);
                    }
                    break;
                case 1: // Uppercase
                    for (int j = 0; profile->username[j]; ++j) profile->username[j] = toupper(profile->username[j]);
                    for (int j = 0; profile->email[j]; ++j) profile->email[j] = toupper(profile->email[j]);
                    for (int j = 0; profile->phone_number[j]; ++j) profile->phone_number[j] = toupper(profile->phone_number[j]);
                    for (int j = 0; j < 3 && profile->roles[j][0]; ++j) {
                        for (int k = 0; profile->roles[j][k]; ++k) profile->roles[j][k] = toupper(profile->roles[j][k]);
                    }
                    break;
                case 2: // Slug
                    // Implement slug transformation logic here
                    break;
            }
        } else return -3;
    }

    cJSON_Delete(root);
    return 0;
}
