#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>

#define MAX_UE 1000
#define RETRY_COUNT 5

typedef struct LTEPHY_NTF_RXUEINFO_TAG {
    int ue_id;
    int rx_channel_info;
} LTEPHY_NTF_RXUEINFO_TAG;

LTEPHY_NTF_RXUEINFO_TAG *ue_list[MAX_UE];
sem_t pool_lock;
pthread_mutex_t list_mutex;

void init_memory_pool() {
    sem_init(&pool_lock, 0, 1);
}

void* allocate_memory(int size) {
    void* ptr = malloc(size);
    if (!ptr) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

void deallocate_memory(void* ptr) {
    free(ptr);
}

LTEPHY_NTF_RXUEINFO_TAG* get_ue_info(int ue_id) {
    pthread_mutex_lock(&list_mutex);
    for (int i = 0; i < MAX_UE; i++) {
        if (ue_list[i] && ue_list[i]->ue_id == ue_id) {
            pthread_mutex_unlock(&list_mutex);
            return ue_list[i];
        }
    }
    pthread_mutex_unlock(&list_mutex);
    return NULL;
}

void update_ue_info(int ue_id, int rx_channel_info) {
    pthread_mutex_lock(&list_mutex);
    for (int i = 0; i < MAX_UE; i++) {
        if (ue_list[i] && ue_list[i]->ue_id == ue_id) {
            ue_list[i]->rx_channel_info = rx_channel_info;
            break;
        }
    }
    pthread_mutex_unlock(&list_mutex);
}

void* memory_allocator(void* arg) {
    int *size = (int *)arg;
    void* ptr = allocate_memory(*size);
    sem_wait(&pool_lock);
    deallocate_memory(ptr);
    sem_post(&pool_lock);
    return NULL;
}

void add_new_ue(int ue_id, int rx_channel_info) {
    if (get_ue_info(ue_id)) return;

    pthread_mutex_lock(&list_mutex);
    for (int i = 0; i < MAX_UE; i++) {
        if (!ue_list[i]) {
            ue_list[i] = allocate_memory(sizeof(LTEPHY_NTF_RXUEINFO_TAG));
            ue_list[i]->ue_id = ue_id;
            ue_list[i]->rx_channel_info = rx_channel_info;
            break;
        }
    }
    pthread_mutex_unlock(&list_mutex);
}

void remove_ue(int ue_id) {
    pthread_mutex_lock(&list_mutex);
    for (int i = 0; i < MAX_UE; i++) {
        if (ue_list[i] && ue_list[i]->ue_id == ue_id) {
            free(ue_list[i]);
            ue_list[i] = NULL;
            break;
        }
    }
    pthread_mutex_unlock(&list_mutex);
}

void* update_data_source(void* arg) {
    int *retry_count = (int *)arg;

    for (int i = 0; i < RETRY_COUNT; i++) {
        if (/* check external data source availability */) {
            // Update UE information from external data source
            break;
        } else {
            printf("Retry %d: External data source unavailable\n", i + 1);
        }
    }

    return NULL;
}

void* health_check(void* arg) {
    while (1) {
        // Perform non-intrusive health checks on external services
        sleep(60); // Check every minute
    }

    return NULL;
}

int main() {
    init_memory_pool();
    pthread_mutex_init(&list_mutex, NULL);

    pthread_t memory_thread[5];
    int sizes[] = {1024, 2048, 3072, 4096, 5120};

    for (int i = 0; i < 5; i++) {
        pthread_create(&memory_thread[i], NULL, memory_allocator, &sizes[i]);
    }

    for (int i = 0; i < 5; i++) {
        pthread_join(memory_thread[i], NULL);
    }

    return 0;
}
