int dns_resolve(const char *hostname, u_char *ip_address) {
    struct in_addr addr;
    int status = getaddrinfo(hostname, NULL, NULL, &result);

    if (status != 0) {
        herror("getaddrinfo");
        return -1; // Error during DNS resolution
