#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_UE_ID 1000000
#define INITIAL_LIST_SIZE 1024

typedef struct LTEPHY_NTF_RXUEINFO_TAG {
    int ue_id;
    int rssi;
    int snr;
} LTEPHY_NTF_RXUEINFO_TAG;

typedef struct ListNode {
    LTEPHY_NTF_RXUEINFO_TAG data;
    struct ListNode* next;
} ListNode;

typedef struct {
    ListNode* head;
    pthread_mutex_t lock;
    size_t count;
} UEList;

void initialize_list(UEList* list) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->count = 0;
}

void destroy_list(UEList* list) {
    ListNode* current = list->head;
    while (current != NULL) {
        ListNode* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
}

int add_ue(UEList* list, int ue_id) {
    pthread_mutex_lock(&list->lock);
    ListNode* new_node = (ListNode*)malloc(sizeof(ListNode));
    if (new_node == NULL) {
        pthread_mutex_unlock(&list->lock);
        return -1; // Memory allocation failed
    }
    new_node->data.ue_id = ue_id;
    new_node->data.rssi = rand() % 100; // Simulate random RSSI value
    new_node->data.snr = rand() % 50;   // Simulate random SNR value
    new_node->next = list->head;
    list->head = new_node;
    list->count++;
    pthread_mutex_unlock(&list->lock);
    return 0;
}

int get_stats(UEList* list, double* avg_rssi, double* avg_snr) {
    int total_rssi = 0, total_snr = 0;
    pthread_mutex_lock(&list->lock);
    ListNode* current = list->head;
    while (current != NULL) {
        total_rssi += current->data.rssi;
        total_snr += current->data.snr;
        current = current->next;
    }
    if (list->count > 0) {
        *avg_rssi = (double)total_rssi / list->count;
        *avg_snr = (double)total_snr / list->count;
    } else {
        pthread_mutex_unlock(&list->lock);
        return -1; // List is empty
    }
    pthread_mutex_unlock(&list->lock);
    return 0;
}

int main() {
    srand(time(NULL));
    UEList list;
    initialize_list(&list);

    for (int i = 0; i < MAX_UE_ID; i++) {
        add_ue(&list, i);
    }

    double avg_rssi, avg_snr;
    if (get_stats(&list, &avg_rssi, &avg_snr) == 0) {
        printf("Average RSSI: %.2f\n", avg_rssi);
        printf("Average SNR: %.2f\n", avg_snr);
    }

    destroy_list(&list);
    return 0;
}
