    size_t count;
    size_t capacity;
    int *cache_indices;
    size_t cache_count;
    size_t cache_capacity;
} LTEPHY_UE_LIST;

LTEPHY_UE_LIST* init_UE_list() {
    LTEPHY_UE_LIST* list = (LTEPHY_UE_LIST*)malloc(sizeof(LTEPHY_UE_LIST));
    if (!list) return NULL;
    list->list = (LPHY_NTF_RXUEINFO_TAG*)calloc(MAX_UE, sizeof(LTEPHY_NTF_RXUEINFO_TAG));
    list->count = 0;
    list->capacity = MAX_UE;
    list->cache_indices = (int*)calloc(CACHE_SIZE, sizeof(int));
    list->cache_count = 0;
    list->cache_capacity = CACHE_SIZE;
    return list;
}

void free_UE_list(LTEPHY_UE_LIST* list) {
    if (!list) return;
    free(list->list);
    list->list = NULL;
    free(list->cache_indices);
    list->cache_indices = NULL;
    free(list);
}

int add_UE_entry(LTEPHY_UE_LIST* list, int ue_id, int rssi, int snr) {
    if (list->count >= list->capacity) return -1; // Overflow
    LTEPHY_NTF_RXUEINFO_TAG entry = {ue_id, rssi, snr};
    list->list[list->count++] = entry;
    return 0;
}

void resize_cache(LTEPHY_UE_LIST* list) {
    if (list->cache_count >= list->cache_capacity) {
        int* new_cache_indices = (int*)realloc(list->cache_indices, sizeof(int) * list->cache_capacity * 2);
        if (!new_cache_indices) return; // Memory allocation failed
        list->cache_indices = new_cache_indices;
        list->cache_capacity *= 2;
    }
    list->cache_indices[list->cache_count++] = list->count - 1;
}

