pthread_mutex_t lock;

void initialize_list() {
    pthread_mutex_init(&lock, NULL);
}

NFAPI_CRC_INDICATION_PDU_T* create_struct() {
    NFAPI_CRC_INDICATION_PDU_T* new_struct = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (new_struct == NULL) {
        perror("Failed to allocate memory for NFAPI_CRC_INDICATION_PDU_T");
        return NULL;
    }
    pthread_mutex_lock(&lock);
    if (count >= MAX_STRUCTS) {
        pthread_mutex_unlock(&lock);
        free(new_struct);
        printf("Maximum number of structures reached.\n");
        return NULL;
    }
    list[count++] = new_struct;
    pthread_mutex_unlock(&lock);
    return new_struct;
}

void destroy_list() {
    for (int i = 0; i < count; i++) {
        free(list[i]);
    }
    count = 0;
    pthread_mutex_destroy(&lock);
}

