typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned short RNTI;
    unsigned char CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

void handleDynamicNFAPIListWithEncryptionAndHashing(int listSize) {
    NFAPI_CRC_INDICATION_PDU_T *list = (NFAPI_CRC_INDICATION_PDU_T *)malloc(listSize * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (list == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }

    // Initialize and configure EVP_CIPHER structure
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    const EVP_CIPHER *cipher = EVP_aes_256_cbc();
    unsigned char key[32] = {0}; // Example key
    unsigned char iv[16] = {0};  // Example IV

    if (EVP_EncryptInit_ex(ctx, cipher, NULL, key, iv) != 1) {
        fprintf(stderr, "Failed to initialize encryption context\n");
        free(list);
        EVP_CIPHER_CTX_free(ctx);
        return;
    }

    // Populate and encrypt data
    for (int i = 0; i < listSize; i++) {
        list[i].RX_UE_INFORMATION_TAG = i;
        list[i].RNTI = i * 100;
        list[i].CRCFLAG = rand() % 2;

        if (EVP_EncryptUpdate(ctx, list + i, &i, list + i, sizeof(NFAPI_CRC_INDICATION_PDU_T)) != 1) {
            fprintf(stderr, "Failed to encrypt data\n");
            free(list);
            EVP_CIPHER_CTX_free(ctx);
            return;
        }
    }

    // Finalize encryption
    int finalLen;
    if (EVP_EncryptFinal_ex(ctx, list + listSize, &finalLen) != 1) {
        fprintf(stderr, "Failed to finalize encryption\n");
        free(list);
        EVP_CIPHER_CTX_free(ctx);
        return;
    }

    // Perform other operations...

    // Clean up
    free(list);
    EVP_CIPHER_CTX_free(ctx);
}

