#define MAX_ELEMENTS 100
#define MEMORY_LIMIT_PER_ELEMENT 10240 // 10 KB

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
} UE_INFO;

typedef struct {
    UE_INFO *ue_info;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* allocate_nfaipdu_list(int N) {
    if (N > MAX_ELEMENTS) {
        fprintf(stderr, "Error: Maximum of %d elements allowed.\n", MAX_ELEMENTS);
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T *list = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list) {
        perror("Memory allocation failed");
        return NULL;
    }

    for (int i = 0; i < N; i++) {
        list[i].ue_info = malloc(sizeof(UE_INFO));
        if (!list[i].ue_info) {
            fprintf(stderr, "Error: Memory allocation failed for UE info.\n");
            // Free previously allocated memory
            for (int j = 0; j < i; j++) {
                free(list[j].ue_info);
            }
            free(list);
            return NULL;
        }
    }

    pthread_mutex_t mutex;
    if (pthread_mutex_init(&mutex, NULL) != 0) {
        fprintf(stderr, "Error: Mutex initialization failed.\n");
        // Free previously allocated memory
        for (int j = 0; j < N; j++) {
            free(list[j].ue_info);
        }
        free(list);
        return NULL;
    }

    srand(time(NULL));
    for (int i = 0; i < N; i++) {
        list[i].ue_info->RX_UE_INFORMATION_TAG = rand();
        list[i].ue_info->RNTI = rand() % 65536;
        list[i].CRCFLAG = rand() % 2;
    }

    return list;
}

void free_nfaipdu_list(NFAPI_CRC_INDICATION_PDU_T *list, int N) {
    for (int i = 0; i < N; i++) {
        free(list[i].ue_info);
    }
    pthread_mutex_destroy(&mutex);
    free(list);
}

void serialize_nfaipdu_list(NFAPI_CRC_INDICATION_PDU_T *list, int N, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) {
        perror("Failed to open file for writing");
        return;
    }

    fwrite(list, sizeof(NFAPI_CRC_INDICATION_PDU_T), N, file);
    fclose(file);
}

int deserialize_nfaipdu_list(NFAPI_CRC_INDICATION_PDU_T **list, int *N, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        perror("Failed to open file for reading");
        return -1;
    }

    fseek(file, 0, SEEK_END);
    long size = ftell(file);
    rewind(file);

    *N = size / sizeof(NFAPI_CRC_INDICATION_PDU_T);
    if (*N > MAX_ELEMENTS) {
        fprintf(stderr, "Error: Maximum of %d elements allowed.\n", MAX_ELEMENTS);
        fclose(file);
        return -1;
    }

    *list = malloc(*N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!*list) {
        perror("Memory allocation failed");
        fclose(file);
        return -1;
    }

    fread(*list, sizeof(NFAPI_CRC_INDICATION_PDU_T), *N, file);
    fclose(file);

    pthread_mutex_t mutex;
    if (pthread_mutex_init(&mutex, NULL) != 0) {
        fprintf(stderr, "Error: Mutex initialization failed.\n");
        free(*list);
        return -1;
    }

    return 0;
}
