#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_ELEMENTS 1000
#define MAX_MEMORY_PER_ELEMENT 10240 // 10 KB

typedef struct {
    int RX_UE_INFORMATION_TAG;
    unsigned short RNTI;
    struct {
        unsigned char CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *elements[MAX_ELEMENTS];
    int count;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool* create_memory_pool() {
    MemoryPool *pool = (MemoryPool*)malloc(sizeof(MemoryPool));
    if (!pool) {
        perror("Failed to allocate memory for memory pool");
        return NULL;
    }
    memset(pool, 0, sizeof(MemoryPool));
    pthread_mutex_init(&pool->lock, NULL);
    return pool;
}

void destroy_memory_pool(MemoryPool *pool) {
    for (int i = 0; i < pool->count; i++) {
        free(pool->elements[i]);
    }
    pthread_mutex_destroy(&pool->lock);
    free(pool);
}

NFAPI_CRC_INDICATION_PDU_T* allocate_element(MemoryPool *pool) {
    NFAPI_CRC_INDICATION_PDU_T *element = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!element) {
        perror("Failed to allocate memory for element");
        return NULL;
    }
    pthread_mutex_lock(&pool->lock);
    pool->elements[pool->count++] = element;
    pthread_mutex_unlock(&pool->lock);
    return element;
}

void serialize_memory_pool(MemoryPool *pool, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) {
        perror("Failed to open file for writing");
        return;
    }
    fwrite(pool, sizeof(MemoryPool), 1, file);
    for (int i = 0; i < pool->count; i++) {
        fwrite(pool->elements[i], sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
    }
    fclose(file);
}

MemoryPool* deserialize_memory_pool(const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        perror("Failed to open file for reading");
        return NULL;
    }
    MemoryPool *pool = (MemoryPool*)malloc(sizeof(MemoryPool));
    if (!pool) {
        fclose(file);
        perror("Failed to allocate memory for memory pool");
        return NULL;
    }
    memset(pool, 0, sizeof(MemoryPool));
    pthread_mutex_init(&pool->lock, NULL);
    fread(pool, sizeof(MemoryPool), 1, file);
    for (int i = 0; i < pool->count; i++) {
        pool->elements[i] = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!pool->elements[i]) {
            perror("Failed to allocate memory for element");
            destroy_memory_pool(pool);
            fclose(file);
            return NULL;
        }
        fread(pool->elements[i], sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
    }
    fclose(file);
    return pool;
}
