} NFAPI_CRC_INDICATION_PDU_T;

// Function to generate a list of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T* generatePDUs(int numElements, int seed) {
    if (numElements <= 0) return NULL;

    // Allocate memory for the list of PDUs
    NFAPI_CRC_INDICATION_PDU_T* pdus = malloc(numElements * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdus) {
        printf("Memory allocation failed\n");
        return NULL;
    }

    // Seed the random number generator
    srand(seed);

    // Populate the list with valid RX_UE_INFORMATION_TAG, RNTI, and CRC_INDICATION_REL8_TAG values
    for (int i = 0; i < numElements; i++) {
        pdus[i].rx_ue_info_tag = generateRandomRXUEInfoTag();
        pdus[i].rnti = generateRandomRNTI();
        pdus[i].crc_indication_rel8_tag = generateRandomCRCIndicator();
    }

    return pdus;
}

// Function to validate the integrity of the generated PDUs
int validatePDUs(NFAPI_CRC_INDICATION_PDU_T* pdus, int numElements) {
    for (int i = 0; i < numElements; i++) {
        if (!isValidRXUEInfoTag(pdus[i].rx_ue_info_tag)) return 0;
        if (!isValidRNTI(pdus[i].rnti)) return 0;
        if (!isValidCRCIndicator(pdus[i].crc_indication_rel8_tag)) return 0;
    }
    return 1;
}

// Function to export the generated list of PDUs to an external storage format
void exportPDUs(NFAPI_CRC_INDICATION_PDU_T* pdus, int numElements, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) {
        printf("Failed to open file for writing\n");
        return;
    }

    // Write the number of PDUs and each PDU to the file
    fwrite(&numElements, sizeof(int), 1, file);
    fwrite(pdus, sizeof(NFAPI_CRC_INDICATION_PDU_T), numElements, file);

    fclose(file);
}

// Function to handle errors gracefully
void handleError(int errorCode) {
    switch (errorCode) {
        case 1:
            printf("Memory allocation failed\n");
            break;
        case 2:
            printf("Invalid RX_UE_INFORMATION_TAG\n");
            break;
        case 3:
            printf("Invalid RNTI\n");
            break;
        case 4:
            printf("Invalid CRC_INDICATION_REL8_TAG\n");
            break;
        default:
            printf("Unknown error\n");
            break;
    }
}

// Main function to demonstrate the usage of the generatePDUs, validatePDUs, and exportPDUs functions
int main() {
    int numElements = 100;
    int seed = time(NULL);
    NFAPI_CRC_INDICATION_PDU_T* pdus = generatePDUs(numElements, seed);

    if (pdus) {
        if (validatePDUs(pdus, numElements)) {
            exportPDUs(pdus, numElements, "output.bin");
        } else {
            handleError(3);
        }
        free(pdus);
    } else {
        handleError(1);
    }

    return 0;
}
