#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_CRC_INDICATION_PDUS 1000
#define RESOURCE_LIMIT_ERROR "Resource limit exceeded"
#define ALLOCATION_SUCCESS "Allocation successful"
#define ALLOCATION_FAILURE "Memory allocation failed"

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef enum {
    LOG_ERROR,
    LOG_INFO
} LogLevel;

typedef struct {
    LogLevel level;
    char* message;
} LogEntry;

LogEntry logBuffer[MAX_CRC_INDICATION_PDUS];
int logIndex = 0;
pthread_mutex_t logMutex = PTHREAD_MUTEX_INITIALIZER;

void logMessage(LogLevel level, const char* format, ...) {
    va_list args;
    va_start(args, format);

    if (logIndex < MAX_CRC_INDICATION_PDUS) {
        pthread_mutex_lock(&logMutex);
        logBuffer[logIndex].level = level;
        vsnprintf(logBuffer[logIndex].message, sizeof(logBuffer[logIndex].message), format, args);
        logIndex++;
        pthread_mutex_unlock(&logMutex);
    }
}

NFAPI_CRC_INDICATION_PDU_T* allocateNFAPIPDUs(int N, size_t maxMemory) {
    static size_t totalAllocated = 0;
    size_t requiredMemory = N * sizeof(NFAPI_CRC_INDICATION_PDU_T);

    if (requiredMemory + totalAllocated > maxMemory) {
        logMessage(LOG_ERROR, RESOURCE_LIMIT_ERROR);
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* pdus = (NFAPI_CRC_INDICATION_PDU_T*)malloc(requiredMemory);
    if (pdus == NULL) {
        logMessage(LOG_ERROR, ALLOCATION_FAILURE);
        return NULL;
    }

    totalAllocated += requiredMemory;
    logMessage(LOG_INFO, ALLOCATION_SUCCESS);

    for (int i = 0; i < N; i++) {
