void* safe_malloc(size_t size, const char* file, int line) {
    void* ptr = malloc(size);
    if (!ptr) {
        fprintf(stderr, "Memory allocation failed at %s:%d\n", file, line);
    }
    return ptr;
}

NFAPI_CRC_INDICATION_PDU_T** create_pdus(int N, size_t max_memory, FILE* log_file) {
    if (N > MAX_PDUS) {
        fprintf(stderr, "Too many PDUs requested. Maximum allowed is %d.\n", MAX_PDUS);
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T** pdu_list = safe_malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T*), __FILE__, __LINE__);
    if (!pdu_list) {
        return NULL;
    }

    size_t total_memory = 0;
    for (int i = 0; i < N; i++) {
        pdu_list[i] = safe_malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T), __FILE__, __LINE__);
        if (!pdu_list[i]) {
            fprintf(stderr, "Memory allocation failed at %s:%d\n", __FILE__, __LINE__);
            for (int j = 0; j < i; j++) {
                free(pdu_list[j]);
            }
            free(pdu_list);
            return NULL;
        }

        total_memory += sizeof(NFAPI_CRC_INDICATION_PDU_T);
        if (total_memory > max_memory) {
            fprintf(stderr, "Memory limit exceeded. Total memory used: %zu bytes\n", total_memory);
            for (int j = 0; j <= i; j++) {
                free(pdu_list[j]);
            }
            free(pdu_list);
            return NULL;
