#include <stdlib.h>
#include <pthread.h>

#define MAX_PDUS 100

typedef struct PDU {
    uint8_t data[MAX_PDUS];
    size_t size;
    int priority;
} PDU;

typedef struct MAC_EContext {
    uint64_t mac_entity_id;
    void* rlc_entity; // Placeholder for RLC entity reference
    PDU pending_pdus[MAX_PDUS];
    int pdu_count;
    pthread_mutex_t mutex;
} MAC_EContext;

MAC_EContext* create_mac_e_context(uint64_t mac_entity_id) {
    MAC_EContext* context = (MAC_EContext*)malloc(sizeof(MAC_EContext));
    if (!context) return NULL;
    context->mac_entity_id = mac_entity_id;
    context->rlc_entity = NULL;
    context->pdu_count = 0;
    pthread_mutex_init(&context->mutex, NULL);
    return context;
}

void destroy_mac_e_context(MAC_EContext* context) {
    pthread_mutex_destroy(&context->mutex);
    free(context);
}

int add_pdu(MAC_EContext* context, PDU pdu) {
    pthread_mutex_lock(&context->mutex);
    if (context->pdu_count >= MAX_PDUS) {
        pthread_mutex_unlock(&context->mutex);
        return -1; // Overflow
    }
    context->pending_pdus[context->pdu_count++] = pdu;
    pthread_mutex_unlock(&context->mutex);
    return 0;
}

PDU* get_highest_priority_pdu(MAC_EContext* context) {
    pthread_mutex_lock(&context->mutex);
    if (context->pdu_count == 0) {
        pthread_mutex_unlock(&context->mutex);
        return NULL; // No PDUs
    }
    int highest_index = 0;
    for (int i = 1; i < context->pdu_count; ++i) {
        if (context->pending_pdus[i].priority > context->pending_pdus[highest_index].priority) {
            highest_index = i;
        }
    }
    PDU* pdu = &context->pending_pdus[highest_index];
    pthread_mutex_unlock(&context->mutex);
    return pdu;
}

// Additional functions for updating contexts and integrating with external signaling system can be added here.
