import hashlib
import os
import concurrent.futures
from tqdm import tqdm

def calculate_md5(file_path):
    hash_md5 = hashlib.md5()
    with open(file_path, "rb") as f:
        for chunk in iter(lambda: f.read(4096), b""):
            hash_md5.update(chunk)
    return hash_md5.hexdigest()

def process_files(directory):
    file_paths = [os.path.join(directory, f) for f in os.listdir(directory) if os.path.isfile(os.path.join(directory, f))]

    with concurrent.futures.ThreadPoolExecutor() as executor:
        results = list(tqdm(executor.map(calculate_md5, file_paths), total=len(file_paths)))

    return results

if __name__ == "__main__":
    directory_path = "path/to/large/files"
    md5_hashes = process_files(directory_path)
    print(md5_hashes)
