// Custom pool-based allocator structure
typedef struct {
    size_t block_size;
    size_t max_blocks;
    void *free_list;
} PoolAllocator;

// Initialize the custom pool-based allocator
void init_pool_allocator(PoolAllocator *allocator, size_t block_size, size_t max_blocks) {
    allocator->block_size = block_size;
    allocator->max_blocks = max_blocks;
    allocator->free_list = malloc(max_blocks * block_size);
}

// Allocate memory from the custom pool
void* allocate_from_pool(PoolAllocator *allocator) {
    if (allocator->free_list == NULL) return NULL;

    void *block = allocator->free_list;
    allocator->free_list = *(void**)block; // Update free list pointer

    return block;
}

// Free memory back to the custom pool
void free_to_pool(PoolAllocator *allocator, void *block) {
    if (allocator->free_list == NULL) {
        allocator->free_list = block;
        *((void**)block) = NULL;
    } else {
        *((void**)block) = allocator->free_list;
        allocator->free_list = block;
    }
}

// Function to dynamically allocate memory for NFAPI_L2_PDU structures
NFAPI_L2_PDU* allocate_nfaapi_l2_pdu_array(size_t n, PoolAllocator *allocator) {
    if (n > allocator->max_blocks) return NULL;

    NFAPI_L2_PDU *array = allocate_from_pool(allocator);
    if (array == NULL) return NULL;

    for (size_t i = 0; i < n; i++) {
        array[i].mac_pdu = create_mac_pdu();
        array[i].l2_header = create_l2_header();
