LTE_ENB_RRC_INST_T** allocate_lte_rrc_inst(int num_elements, size_t max_memory_usage, LOG_LEVEL* log_level) {
    LTE_ENB_RRC_INST_T** array = (LTE_ENB_RRC_INST_T**)malloc(num_elements * sizeof(LTE_ENB_RRC_INST_T*));
    if (!array) {
        log_message(LOG_LEVEL_ERROR, "Memory allocation failed");
        *log_level = LOG_LEVEL_ERROR;
        return NULL;
    }

    size_t total_memory_used = 0;
    for (int i = 0; i < num_elements; i++) {
        LTE_ENB_RRC_INST_T* inst = (LTE_ENB_RRC_INST_T*)malloc(sizeof(LTE_ENB_RRC_INST_T));
        if (!inst) {
            log_message(LOG_LEVEL_ERROR, "Memory allocation failed");
            *log_level = LOG_LEVEL_ERROR;
            for (int j = 0; j < i; j++) {
                free(array[j]);
            }
            free(array);
            return NULL;
        }

        inst->s_tmsi = MIN_S_TMSI + rand() % (MAX_S_TMSI - MIN_S_TMSI + 1);
        inst->c_rnti = MIN_C_RNTI + rand() % (MAX_C_RNTI - MIN_C_RNTI + 1);

        array[i] = inst;
        total_memory_used += sizeof(LTE_ENB_RRC_INST_T);

        if (total_memory_used > max_memory_usage) {
            log_message(LOG_LEVEL_WARNING, "Memory usage exceeds limit");
            *log_level = LOG_LEVEL_WARNING;
            for (int j = 0; j <= i; j++) {
                free(array[j]);
            }
            free(array);
            return NULL;
        }
    }

    *log_level = LOG_LEVEL_INFO;
    log_message(LOG_LEVEL_INFO, "Memory allocation successful");
    return array;
}

void free_lte_rrc_inst(LTE_ENB_RRC_INST_T** array, int num_elements) {
    for (int i = 0; i < num_elements; i++) {
        free(array[i]);
    }
    free(array);
}
