typedef struct State {
    int data;
    struct State* next;
} State;

typedef struct StateList {
    State* head;
    State* tail;
    size_t count;
    size_t capacity;
    pthread_mutex_t mutex;
} StateList;

StateList* create_state_list(int* states, size_t num_states, const void* fsa, int last_state, size_t max_capacity, bool clear_current) {
    StateList* list = (StateList*)malloc(sizeof(StateList));
    if (!list) return NULL;

    pthread_mutex_init(&list->mutex, NULL);
    list->head = NULL;
    list->tail = NULL;
    list->count = 0;
    list->capacity = max_capacity;

    if (clear_current) {
        // Implement clearing the current state list if necessary
    }

    for (size_t i = 0; i < num_states && list->count < list->capacity; ++i) {
        State* new_state = (State*)malloc(sizeof(State));
        if (!new_state) {
            free_state_list(list);
            return NULL;
        }
        new_state->data = states[i];
        new_state->next = NULL;

        pthread_mutex_lock(&list->mutex);
        if (list->head == NULL) {
            list->head = new_state;
        } else {
            list->tail->next = new_state;
        }
        list->tail = new_state;
        ++list->count;
        pthread_mutex_unlock(&list->mutex);
    }

    return list;
}

void free_state_list(StateList* list) {
    if (list == NULL) return;

    State* current = list->head;
    while (current != NULL) {
        State* next = current->next;
        free(current);
        current = next;
    }

    pthread_mutex_destroy(&list->mutex);
    free(list);
}

bool serialize_state_list(StateList* list, FILE* file) {
    if (list == NULL || file == NULL) return false;

    fwrite(&list->count, sizeof(size_t), 1, file);
    fwrite(&list->capacity, sizeof(size_t), 1, file);

    State* current = list->head;
    while (current != NULL) {
        fwrite(&current->data, sizeof(int), 1, file);
        current = current->next;
    }

    return true;
}

StateList* deserialize_state_list(FILE* file) {
    if (file == NULL) return NULL;

    StateList* list = (StateList*)malloc(sizeof(StateList));
    if (!list) return NULL;

    pthread_mutex_init(&list->mutex, NULL);
    list->head = NULL;
    list->tail = NULL;
    list->count = 0;
    list->capacity = 0;

    size_t count, capacity;
    if (fread(&count, sizeof(size_t), 1, file) != 1 ||
        fread(&capacity, sizeof(size_t), 1, file) != 1) {
        free_state_list(list);
        return NULL;
    }

    list->capacity = capacity;

    for (size_t i = 0; i < count; ++i) {
        State* new_state = (State*)malloc(sizeof(State));
        if (!new_state) {
            free_state_list(list);
            return NULL;
        }
        if (fread(&new_state->data, sizeof(int), 1, file) != 1) {
            free(new_state);
            free_state_list(list);
            return NULL;
        }
        new_state->next = NULL;

        pthread_mutex_lock(&list->mutex);
        if (list->head == NULL) {
            list->head = new_state;
        } else {
            list->tail->next = new_state;
        }
        list->tail = new_state;
        ++list->count;
        pthread_mutex_unlock(&list->mutex);
