public class AesCbcDecryption {
    public static byte[] DecryptCiphertext(byte[] ciphertext, byte[] key, byte[] iv, CipherMode mode) {
        using (Aes aes = Aes.Create()) {
            aes.Key = key;
            aes.IV = iv;
            aes.Mode = mode;

            ICryptoTransform decryptor = aes.CreateDecryptor(aes.Key, aes.IV);

            using (MemoryStream msDecrypt = new MemoryStream(ciphertext)) {
                using (CryptoStream csDecrypt = new CryptoStream(msDecrypt, decryptor, CryptoStreamMode.Read)) {
                    byte[] plaintext = new byte[ciphertext.Length];
                    int bytesRead = csDecrypt.Read(plaintext, 0, plaintext.Length);
                    Array.Resize(ref plaintext, bytesRead); // Resize array to actual size
                    return plaintext;
                }
            }
        }
    }
}
