// Memory pool structure
typedef struct MemoryPool {
    void* blocks;
    size_t block_size;
    size_t num_blocks;
    pthread_mutex_t lock;
} MemoryPool;

// Function to initialize the memory pool
MemoryPool* init_memory_pool(size_t block_size, size_t num_blocks) {
    MemoryPool* pool = (MemoryPool*)malloc(sizeof(MemoryPool));
    if (!pool) return NULL;

    pool->blocks = malloc(block_size * num_blocks);
    if (!pool->blocks) {
        free(pool);
        return NULL;
    }

    pool->block_size = block_size;
    pool->num_blocks = num_blocks;
    pthread_mutex_init(&pool->lock, NULL);

    return pool;
}

// Function to allocate memory from the pool
void* mem_pool_alloc(MemoryPool* pool) {
    void* block = NULL;
    pthread_mutex_lock(&pool->lock);
    if (pool->blocks) {
        block = pool->blocks;
        pool->blocks = NULL; // Take the first block and mark the pool as empty
    }
    pthread_mutex_unlock(&pool->lock);
    return block;
}

// Function to free memory back to the pool
void mem_pool_free(MemoryPool* pool, void* block) {
    pthread_mutex_lock(&pool->lock);
    if (block == pool->blocks) {
        // Reuse the first block in the pool
    } else {
        // Add block to a linked list or another data structure for later reuse
    }
    pthread_mutex_unlock(&pool->lock);
}

// Function to create and manage LTE_PDCP_PDU_T structures
LTE_PDCP_PDU_T** create_lte_pdcp_pdu_array(int num_sgw, MemoryPool* pool) {
    LTE_PDCP_PDU_T** array = (LTE_PDCP_PDU_T**)mem_pool_alloc(pool);
    if (!array) return NULL;

    for (int i = 0; i < num_sgw; ++i) {
        array[i] = (LTE_PDCP_PDU_T*)mem_pool_alloc(pool);
        if (!array[i]) {
            // Handle memory allocation failure
            mem_pool_free(pool, array);
            return NULL;
        }

        // Initialize LTE_PDCP_PDU_T structure
        array[i]->PDCP_SN = rand();
        array[i]->PDCP_SDU_LENGTH = rand() % 1024;
        array[i]->PDCP_SEQ_NUMBER = rand() % 65536;

        int num_crc_indications = rand() % 10;
        array[i]->crc_indications = (NFAPI_CRC_INDICATION_PDU_T*)mem_pool_alloc(pool);
        if (!array[i]->crc_indications) {
            // Handle memory allocation failure
            for (int j = 0; j < i; ++j) mem_pool_free(pool, array[j]);
            mem_pool_free(pool, array);
            return NULL;
        }

        for (int j = 0; j < num_crc_indications; ++j) {
            // Initialize NFAPI_CRC_INDICATION_PDU_T structure
            snprintf(array[i]->crc_indications[j].RX_UE_INFORMATION_TAG, 256, "Tag_%d", rand());
            array[i]->crc_indications[j].RNTI = rand() % 1024;
            array[i]->crc_indications[j].CRC_INDICATION_REL8_TAG = (rand() % 2) ? 'Y' : 'N';
        }
    }

    return array;
}

// Function to clean up and deallocate resources
void cleanup(LTE_PDCP_PDU_T** array, int num_sgw, MemoryPool* pool) {
    for (int i = 0; i < num_sgw; ++i) {
        mem_pool_free(pool, array[i]->crc_indications);
        mem_pool_free(pool, array[i]);
    }
    mem_pool_free(pool, array);
}

// Example usage
int main() {
    MemoryPool* pool = init_memory_pool(sizeof(LTE_PDCP_PDU_T), 100);
    if (!pool) return -1;

    int num_sgw = 5;
    LTE_PDCP_PDU_T** array = create_lte_pdcp_pdu_array(num_sgw, pool);
    if (array) {
        // Use the array
        cleanup(array, num_sgw, pool);
    }

    pthread_mutex_destroy(&pool->lock);
    free(pool);

    return 0;
}
```

