#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define N 1000 // Example number of entries

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void populate_array(NFAPI_CRC_INDICATION_PDU_T *array, int num_entries) {
    if (array == NULL || num_entries <= 0) return;

    pthread_mutex_lock(&mutex);
    srand(time(NULL));

    for (int i = 0; i < num_entries; ++i) {
        array[i].RX_UE_INFORMATION_TAG = rand();
        array[i].RNTI = rand() % 65536;
        array[i].CRC_INDICATION_REL8_TAG = rand() % 256;
        array[i].CRCFLAG = rand() % 2; // Binary flag
    }

    pthread_mutex_unlock(&mutex);
}

void validate_array(NFAPI_CRC_INDICATION_PDU_T *array, int num_entries) {
    if (array == NULL || num_entries <= 0) return;

    pthread_mutex_lock(&mutex);

    for (int i = 1; i < num_entries; ++i) {
        if (array[i].RX_UE_INFORMATION_TAG != array[i - 1].RX_UE_INFORMATION_TAG ||
            array[i].RNTI != array[i - 1].RNTI ||
            array[i].CRC_INDICATION_REL8_TAG != array[i - 1].CRC_INDICATION_REL8_TAG) {
            // Handle inconsistency, e.g., log error
        }
    }

    pthread_mutex_unlock(&mutex);
}

int main() {
    NFAPI_CRC_INDICATION_PDU_T *array = (NFAPI_CRC_INDICATION_PDU_T *)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (array == NULL) {
        // Handle memory allocation failure
        return 1;
    }

    populate_array(array, N);
    validate_array(array, N);

    free(array);

    return 0;
}
```

