typedef struct {
    bool is_enabled;
    time_t last_cache_update;
    char **cached_entries;
    int cache_size;
} DNS_CACHE_T;

DNS_CACHE_T dns_cache = {false, 0, NULL, 0};

int secureNetworkCommunicationHandler(const char* hostname, size_t size_limit, int mode, bool enable_dns_caching, int num_sgw_instances) {
    if (enable_dns_caching && !dns_cache.is_enabled) {
        // Initialize DNS cache
        dns_cache.cached_entries = (char**)malloc(10 * sizeof(char*));
        dns_cache.cache_size = 10;
        dns_cache.is_enabled = true;
    }

    // Perform DNS resolution with rate-limiting and caching
    if (!dns_cache.is_enabled || time(NULL) - dns_cache.last_cache_update > DNS_CACHE_DURATION) {
        struct addrinfo hints, *res, *p;
        int status;

        memset(&hints, 0, sizeof hints);
        hints.ai_family = AF_UNSPEC; // AF_INET or AF_INET6 to force version
        hints.ai_socktype = SOCK_STREAM;

        if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
            fprintf(stderr, "getaddrinfo error: %s\n", gai_strerror(status));
            return -1;
        }

        for (p = res; p != NULL; p = p->ai_next) {
            void *addr;
            char ipstr[INET6_ADDRSTRLEN];

            // get the pointer to the address itself,
            // different fields in IPv4 and IPv6:
            if (p->ai_family == AF_INET) { // IPv4
                struct sockaddr_in *ipv4 = (struct sockaddr_in *)p->ai_addr;
                addr = &(ipv4->sin_addr);
            } else { // IPv6
                struct sockaddr_in6 *ipv6 = (struct sockaddr_in6 *)p->ai_addr;
                addr = &(ipv6->sin6_addr);
            }

            // convert the IP to a string and print it:
            inet_ntop(p->ai_family, addr, ipstr, sizeof ipstr);
            printf("  %s\n", ipstr);

            freeaddrinfo(res); // all done with this structure
        }
    } else {
        for (int i = 0; i < dns_cache.cache_size; i++) {
            if (strcmp(dns_cache.cached_entries[i], hostname) == 0) {
                printf("Using cached DNS entry: %s\n", dns_cache.cached_entries[i]);
                break;
            }
        }
    }

    // Initialize encryption based on the specified mode
    EVP_CIPHER *cipher = NULL;
    switch (mode) {
        case ECB:
            cipher = EVP_aes_256_ecb();
            break;
        case EDE:
            cipher = EVP_aes_256_cbc();
            break;
        case EDE3:
            cipher = EVP_aes_192_cbc();
            break;
        case CFB:
            cipher = EVP_aes_128_cfb128();
            break;
        default:
            fprintf(stderr, "Unsupported encryption mode\n");
            return -1;
    }

    // Process the string and check length
    char *processed_string = NULL;
    if (strlen(hostname) < size_limit) {
        processed_string = strdup(hostname);
        strncat(processed_string, "/", 1);
    } else {
        printf("String exceeds size limit\n");
