LTEPHY_NTF_RXUEINFO_TAG* init_and_populate_list(int initial_states[], size_t state_count, FSA fsa, int max_entries) {
    if (initial_states == NULL || fsa == NULL) {
        log_error("Invalid input pointers");
        return NULL;
    }

    LTEPHY_NTF_RXUEINFO_TAG** list = (LTEPHY_NTF_RXUEINFO_TAG**)malloc(max_entries * sizeof(LTEPHY_NTF_RXUEINFO_TAG*));
    if (list == NULL) {
        log_error("Memory allocation failed");
        return NULL;
    }

    size_t capacity = INITIAL_CAPACITY;
    size_t count = 0;

    for (size_t i = 0; i < state_count && count < max_entries; ++i) {
        LTEPHY_NTF_RXUEINFO_TAG* entry = (LTEPHY_NTF_RXUEINFO_TAG*)malloc(sizeof(LTEPHY_NTF_RXUEINFO_TAG));
        if (entry == NULL) {
            log_error("Memory allocation failed for entry");
            free_list(list, count);
            return NULL;
        }
        entry->ue_id = initial_states[i];
        entry->rssi = generate_random_rssi();
        entry->snr = generate_random_snr();
        entry->next = list[count - 1]; // Link to the previous entry
        list[count++] = entry;

        if (count == capacity) {
            capacity *= GROWTH_FACTOR;
            LTEPHY_NTF_RXUEINFO_TAG** new_list = (LTEPHY_NTF_RXUEINFO_TAG**)realloc(list, capacity * sizeof(LTEPHY_NTF_RXUEINFO_TAG*));
            if (new_list == NULL) {
                log_error("Memory reallocation failed");
                free_list(list, count);
                return NULL;
            }
            list = new_list;
        }

        // Apply FSA transition rules and manage dependencies
        apply_fsa_rules(entry, fsa);
    }

    LTEPHY_NTF_RXUEINFO_TAG* head = (LTEPHY_NTF_RXUEINFO_TAG*)malloc(sizeof(LTEPHY_NTF_RXUEINFO_TAG));
    if (head == NULL) {
        log_error("Memory allocation failed for head");
        free_list(list, count);
        return NULL;
    }
    head->ue_id = -1; // Sentinel value
    head->rssi = 0;
    head->snr = 0;
    head->next = list[0];

    return head;
}

void free_list(LTEPHY_NTF_RXUEINFO_TAG** list, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        free(list[i]);
    }
    free(list);
}
