typedef struct NetworkConnectionList {
    NETWORK_CONNECTION_T *connection;
    struct NetworkConnectionList *next;
} NetworkConnectionList;

NetworkDeviceList* createNetworkDevices(int num_devices, char **device_names, char **ip_addresses) {
    if (num_devices <= 0 || device_names == NULL || ip_addresses == NULL) {
        return NULL;
    }

    NetworkDeviceList *head = NULL;
    NetworkDeviceList *current = NULL;

    for (int i = 0; i < num_devices; i++) {
        NetworkDeviceList *new_device = malloc(sizeof(NetworkDeviceList));
        if (new_device == NULL) {
            // Handle memory allocation failure
            return head;
        }

        new_device->device = malloc(sizeof(NETWORK_DEVICE_T));
        if (new_device->device == NULL) {
            free(new_device);
            // Handle memory allocation failure
            return head;
        }

        strncpy(new_device->device->DEVICE_NAME, device_names[i], sizeof(new_device->device->DEVICE_NAME));
        strncpy(new_device->device->IP_ADDRESS, ip_addresses[i], sizeof(new_device->device->IP_ADDRESS));

        // Initialize other fields
        new_device->device->PORT_NUMBER = 0;
        strcpy(new_device->device->STATUS, "Online");
        new_device->device->LAST_CONNECTION_TIME = time(NULL);

        new_device->next = NULL;

        if (head == NULL) {
            head = new_device;
        } else {
            current->next = new_device;
        }

        current = new_device;
    }

    return head;
}

