    NetworkDeviceList *devices = createNetworkDevices(2, device_names, ip_addresses);

    // Clean up allocated memory
    while (devices != NULL) {
        NetworkDeviceList *temp = devices;
        free(temp->device);
        devices = temp->next;
        free(temp);
    }

    return 0;
}
