    if (de->file_objects == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        free(de);
        return NULL;
    }
    de->count = 0;
    de->capacity = initial_capacity;
    return de;
}

void add_file_to_directory(DIRECTORY_ENTRY_T* de, FILE_SYSTEM_OBJECT_T file_object) {
    if (de->count == de->capacity) {
        size_t new_capacity = de->capacity * 2;
