    while (1) {
        // Simulate network monitoring logic here
        double sample = simulate_network_sample(interface_id);
        pthread_mutex_lock(&log_mutex);
        fprintf(data->log_file, "Interface %d Sample: %.2f\n", interface_id, sample);
        pthread_mutex_unlock(&log_mutex);

        cache[cache_index++] = sample;
