#include <stdbool.h>
#include <pthread.h>

typedef struct StateNode {
    int state;
    struct StateNode* next;
} StateNode;

typedef struct {
    StateNode* head;
    StateNode* tail;
    pthread_mutex_t lock;
    bool is_locked;
    int size;
} ResizableLinkedList;

ResizableLinkedList* create_resizable_linked_list() {
    ResizableLinkedList* list = (ResizableLinkedList*)malloc(sizeof(ResizableLinkedList));
    if (!list) return NULL;
    list->head = list->tail = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->is_locked = false;
    list->size = 0;
    return list;
}

void destroy_resizable_linked_list(ResizableLinkedList* list) {
    StateNode* current = list->head;
    while (current) {
        StateNode* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

bool lock_resizable_linked_list(ResizableLinkedList* list) {
    if (pthread_mutex_lock(&list->lock)) return false;
    list->is_locked = true;
    return true;
}

void unlock_resizable_linked_list(ResizableLinkedList* list) {
    list->is_locked = false;
    pthread_mutex_unlock(&list->lock);
}

void insert_state_into_list(ResizableLinkedList* list, int state) {
    StateNode* new_node = (StateNode*)malloc(sizeof(StateNode));
    if (!new_node) return;
    new_node->state = state;
    new_node->next = NULL;

    lock_resizable_linked_list(list);
    if (!list->head) {
        list->head = list->tail = new_node;
    } else {
        list->tail->next = new_node;
        list->tail = new_node;
    }
    list->size++;
    unlock_resizable_linked_list(list);
}

ResizableLinkedList* update_state_list(int* states, int num_states, void* fsa, int last_state, int max_capacity, bool clear_current) {
    ResizableLinkedList* list = create_resizable_linked_list();
    if (!list) return NULL;

    if (clear_current) {
        destroy_resizable_linked_list(list);
        list = create_resizable_linked_list();
        if (!list) return NULL;
    }

    for (int i = 0; i < num_states; i++) {
        insert_state_into_list(list, states[i]);
    }

    // Additional logic to handle external data sources and error handling can be added here

    return list;
}

// Function to serialize the state list
void* serialize_state_list(ResizableLinkedList* list) {
    // Logic to serialize the state list into a compact format
