#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <pthread.h>

typedef struct State {
    int id;
    // other state attributes
} State;

typedef struct StateList {
    State** states;
    int size;
    int capacity;
    pthread_mutex_t mutex;
} StateList;

StateList* create_state_list(int* states, int num_states, FSA* fsa, int last_state, int max_capacity, bool clear) {
    StateList* list = (StateList*)malloc(sizeof(StateList));
    if (!list) return NULL;

    pthread_mutex_init(&list->mutex, NULL);
    list->states = (State**)malloc(max_capacity * sizeof(State*));
    if (!list->states) {
        free(list);
        return NULL;
    }
    list->size = 0;
    list->capacity = max_capacity;

    if (clear) {
        for (int i = 0; i < last_state; i++) {
            list->states[i] = NULL;
        }
    }

    // Populate the state list with valid states from the FSA
    for (int i = 0; i < num_states; i++) {
        int state_id = states[i];
        if (state_id >= 0 && state_id < last_state) {
            State* new_state = create_state(fsa, state_id);
            if (!new_state) {
                free_state_list(list);
                return NULL;
            }
            list->states[state_id] = new_state;
            list->size++;
        }
    }

    return list;
}

void free_state_list(StateList* list) {
    pthread_mutex_lock(&list->mutex);
    for (int i = 0; i < list->size; i++) {
        if (list->states[i]) {
            free_state(list->states[i]);
        }
    }
    pthread_mutex_unlock(&list->mutex);

    free(list->states);
    pthread_mutex_destroy(&list->mutex);
    free(list);
}

State* create_state(FSA* fsa, int state_id) {
    State* state = (State*)malloc(sizeof(State));
    if (!state) return NULL;

    // Initialize state based on the FSA
    state->id = state_id;
    // other initialization code

    return state;
