} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

Node* create_node(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (new_node != NULL) {
        new_node->data = data;
        new_node->next = NULL;
    }
    return new_node;
}

void free_list(Node** head) {
    Node* current = *head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    *head = NULL;
}

NFAPI_CRC_INDICATION_PDU_T generate_random_pdu() {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    // Populate pdu with random values for ue_info_tag, rnti, and crcflag
    return pdu;
}

Node* create_list(int N) {
    Node* head = NULL;
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    for (int i = 0; i < N; ++i) {
        pthread_mutex_lock(&mutex);
        Node* new_node = create_node(generate_random_pdu());
        if (new_node == NULL) {
            free_list(&head);
            pthread_mutex_unlock(&mutex);
            return NULL;
        }
        new_node->next = head;
        head = new_node;
        pthread_mutex_unlock(&mutex);
    }

    pthread_mutex_destroy(&mutex);
    return head;
}

int main() {
    int N = 10000;
    Node* list = create_list(N);
    if (list != NULL) {
        // Use the list
