    std::atomic<int> filesTransferred;

public:
    void start(const std::vector<FileOperation>& operations) {
        for (const auto& operation : operations) {
            if (operation.is_upload) {
                threads.emplace_back(&CloudStorageManager::uploadFile, this, operation.source_path, operation.destination_path);
            } else {
                threads.emplace_back(&CloudStorageManager::downloadFile, this, operation.source_path, operation.destination_path);
            }
        }

        for (auto& thread : threads) {
            if (thread.joinable()) {
                thread.join();
            }
        }

        std::cout << "Total files transferred: " << filesTransferred.load() << std::endl;
    }

    void uploadFile(const std::string& localPath, const std::string& remotePath) {
        // Simulate file upload
        std::this_thread::sleep_for(std::chrono::seconds(1));
        filesTransferred.fetch_add(1);
        progressMutex.lock();
        std::cout << "Uploaded: " << remotePath << std::endl;
        progressMutex.unlock();
    }

    void downloadFile(const std::string& remotePath, const std::string& localPath) {
        // Simulate file download
        std::this_thread::sleep_for(std::chrono::seconds(1));
        filesTransferred.fetch_add(1);
        progressMutex.lock();
        std::cout << "Downloaded: " << localPath << std::endl;
        progressMutex.unlock();
    }
};

