#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_SETTINGS 100
#define MAX_SETTING_SIZE 1024

typedef struct ConfigSetting {
    int priority;
    char data[MAX_SETTING_SIZE];
    struct ConfigSetting *prev, *next;
} ConfigSetting;

typedef struct ConfigList {
    ConfigSetting *head, *tail;
    size_t size;
    pthread_mutex_t lock;
    size_t total_size;
} ConfigList;

int validate_setting(const char *data) {
    // Implement validation logic here
    return 0; // Return 0 if valid, non-zero if invalid
}

void log_change(ConfigSetting *setting, const char *action) {
    // Implement logging mechanism here
}

ConfigSetting* insert_config(ConfigList *list, int priority, const char *data) {
    pthread_mutex_lock(&list->lock);

    if (list->size >= MAX_SETTINGS) {
        ConfigSetting *least_recent = list->tail;
        remove_config(list, least_recent);
        list->total_size -= strlen(least_recent->data);
        free(least_recent);
    }

    ConfigSetting *new_setting = (ConfigSetting*)malloc(sizeof(ConfigSetting));
    if (!new_setting) {
        pthread_mutex_unlock(&list->lock);
        return NULL;
    }

    new_setting->priority = priority;
    strncpy(new_setting->data, data, MAX_SETTING_SIZE - 1);
    new_setting->data[MAX_SETTING_SIZE - 1] = '\0';
    list->total_size += strlen(new_setting->data);

    if (list->size == 0 || priority > list->head->priority) {
        insert_at_head(list, new_setting);
    } else {
        insert_after(list, find_by_priority(list, priority), new_setting);
    }

    pthread_mutex_unlock(&list->lock);
    return new_setting;
}

void remove_config(ConfigList *list, ConfigSetting *setting) {
    pthread_mutex_lock(&list->lock);

    if (setting == list->head) {
        list->head = setting->next;
    }
    if (setting == list->tail) {
        list->tail = setting->prev;
    }

    if (setting->prev) {
        setting->prev->next = setting->next;
    }
    if (setting->next) {
        setting->next->prev = setting->prev;
    }

    list->size--;
    list->total_size -= strlen(setting->data);
    free(setting);

    pthread_mutex_unlock(&list->lock);
}

void insert_at_head(ConfigList *list, ConfigSetting *new_setting) {
    new_setting->prev = NULL;
    new_setting->next = list->head;
    if (list->head) {
        list->head->prev = new_setting;
    }
    list->head = new_setting;
    if (!list->tail) {
        list->tail = new_setting;
    }
    list->size++;
}

void insert_after(ConfigList *list, ConfigSetting *before, ConfigSetting *new_setting) {
    new_setting->next = before->next;
    new_setting->prev = before;
    if (before->next) {
        before->next->prev = new_setting;
    } else {
        list->tail = new_setting;
    }
    before->next = new_setting;
    list->size++;
}

ConfigSetting* find_by_priority(ConfigList *list, int priority) {
    ConfigSetting *current = list->head;
    while (current && current->priority != priority) {
        current = current->next;
    }
    return current;
}

void serialize_list(ConfigList *list, const char *filename) {
    FILE *file = fopen(filename, "w");
    if (!file) return;

    pthread_mutex_lock(&list->lock);

    ConfigSetting *current = list->head;
    while (current) {
        fprintf(file, "%d %s\n", current->priority, current->data);
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);

    fclose(file);
}

int deserialize_list(ConfigList *list, const char *filename) {
    FILE *file = fopen(filename, "r");
    if (!file) return -1;

    ConfigSetting *current = NULL;
    int priority;
    char data[MAX_SETTING_SIZE];

    pthread_mutex_lock(&list->lock);

    while (fscanf(file, "%d %s", &priority, data) != EOF) {
        current = insert_config(list, priority, data);
        if (!current) {
            pthread_mutex_unlock(&list->lock);
            fclose(file);
            return -1;
        }
    }

    pthread_mutex_unlock(&list->lock);

    fclose(file);
    return 0;
}
```

