            transformAndValidate(json);

            if (mode == ProcessingMode::ModeA && ++currentWindow >= windowSize) {
                currentWindow = 0;
                adjustProcessingWindow();
            }

            spdlog::info("Processed line: {}", line);
        } catch (const std::exception& e) {
            spdlog::error("Failed to process line: {}, Error: {}", line, e.what());
            handleFailure(line, e.what());
