    }
};

int main(int argc, char* argv[]) {
    if (argc < 2) {
        spdlog::error("Usage: {} <file_path> [mode] [window_size]", argv[0]);
        return 1;
    }

    std::string filePath = argv[1];
    ProcessingMode mode = ProcessingMode::ModeA; // Default mode
    int windowSize = 1000; // Default window size

    if (argc >= 3) {
        if (argv[2] == "B") {
            mode = ProcessingMode::ModeB;
        } else if (argv[2] == "C") {
            mode = ProcessingMode::ModeC;
        }
    }

