    NFAPI_RX_FRAME_T *frames;
    size_t count;
    size_t max_size;
    pthread_mutex_t lock;
} FRAME_LIST;

void init_frame_list(FRAME_LIST *list, size_t initial_size) {
    list->frames = (NFAPI_RX_FRAME_T *)malloc(initial_size * sizeof(NFAPI_RX_FRAME_T));
    list->count = 0;
    list->max_size = initial_size;
    pthread_mutex_init(&list->lock, NULL);
}

void destroy_frame_list(FRAME_LIST *list) {
    free(list->frames);
    pthread_mutex_destroy(&list->lock);
}

int add_frame_to_list(FRAME_LIST *list, NFAPI_RX_FRAME_T frame) {
    pthread_mutex_lock(&list->lock);
    if (list->count >= list->max_size) {
        size_t new_size = list->max_size * 2;
        NFAPI_RX_FRAME_T *new_frames = realloc(list->frames, new_size * sizeof(NFAPI_RX_FRAME_T));
        if (!new_frames) {
            pthread_mutex_unlock(&list->lock);
            return -1; // Memory allocation failed
        }
        list->frames = new_frames;
        list->max_size = new_size;
    }
    list->frames[list->count++] = frame;
    pthread_mutex_unlock(&list->lock);
    return 0;
}

