            options->delimiter = "custom";
        } else if (strcmp(argv[i], "-o") == 0 && i + 1 < argc) {
            options->output_file = argv[++i];
        } else if (strcmp(argv[i], "--encrypt") == 0 && i + 1 < argc) {
            options->encryption_key = argv[++i];
        } else if (strcmp(argv[i], "--stats") == 0) {
