        pthread_mutex_unlock(&entries_lock);
        return -1;
    }
    entries[entry_count] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!entries[entry_count]) {
        pthread_mutex_unlock(&entries_lock);
        return -1;
    }
