FrameList* create_frame_list(int max_size) {
    FrameList *list = (FrameList *)malloc(sizeof(FrameList));
    if (!list) {
        perror("Failed to allocate memory for frame list");
        return NULL;
    }
    list->frames = (FrameData **)malloc(max_size * sizeof(FrameData *));
    if (!list->frames) {
        free(list);
        perror("Failed to allocate memory for frame pointers");
        return NULL;
    }
    memset(list->frames, 0, max_size * sizeof(FrameData *));
    list->count = 0;
    list->max_size = max_size;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void destroy_frame_list(FrameList *list) {
    for (int i = 0; i < list->count; ++i) {
        free(list->frames[i]);
    }
    free(list->frames);
    free(list);
}

int add_frame_to_list(FrameList *list, FrameData *frame) {
    pthread_mutex_lock(&list->lock);
    if (list->count >= list->max_size) {
        pthread_mutex_unlock(&list->lock);
        fprintf(stderr, "Frame list is full\n");
        return -1;
    }
    list->frames[list->count++] = frame;
    pthread_mutex_unlock(&list->lock);
    return 0;
}

