import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.HashMap;
import java.util.Map;

public class BatchHashProcessor {
    private static final int BATCH_SIZE = 10000;
    private static final String CACHE_KEY_PREFIX = "hash_";

    public Map<String, String> processBatch(String[] inputStrings) throws NoSuchAlgorithmException {
        MessageDigest md = MessageDigest.getInstance("MD5");
        Map<String, String> hashCache = new HashMap<>();
        Map<String, String> result = new HashMap<>();

        for (String input : inputStrings) {
            if (!hashCache.containsKey(input)) {
                byte[] messageDigest = md.digest(input.getBytes());
                StringBuilder hexString = new StringBuilder();
                for (byte b : messageDigest) {
                    String hex = Integer.toHexString(0xff & b);
                    if(hex.length() == 1) hexString.append('0');
                    hexString.append(hex);
                }
                hashCache.put(CACHE_KEY_PREFIX + input, hexString.toString());
            }
            result.put(input, hashCache.get(CACHE_KEY_PREFIX + input));
        }

        return result;
    }

    public static void main(String[] args) {
        BatchHashProcessor processor = new BatchHashProcessor();
        String[] inputStrings = {"string1", "string2", /* ... */};

        try {
            Map<String, String> hashes = processor.processBatch(inputStrings);
            System.out.println(hashes);
        } catch (NoSuchAlgorithmException e) {
            e.printStackTrace();
        }
    }
}
