    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    unsigned char CRCFLAG;
    time_t timestamp;
    struct NFAPI_CRC_INDICATION_PDU_T* next;
} NFAPI_CRC_INDICATION_PDU_T;

pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;

NFAPI_CRC_INDICATION_PDU_T* create_linked_list(int N) {
    if (N > MAX_ELEMENTS || sizeof(NFAPI_CRC_INDICATION_PDU_T) * N > MAX_MEM_USAGE) {
        fprintf(stderr, "Error: Invalid input or memory limit exceeded.\n");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* head = NULL;
    NFAPI_CRC_INDICATION_PDU_T** current = &head;

    for (int i = 0; i < N; i++) {
        *current = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (*current == NULL) {
            fprintf(stderr, "Error: Out of memory.\n");
            return head;
        }

        pthread_mutex_lock(&list_mutex);
        (*current)->RX_UE_INFORMATION_TAG = rand() % 1000; // Example range
        (*current)->RNTI = rand() % 1000; // Example range
        (*current)->CRC_INDICATION_REL8_TAG = rand() % 1000; // Example range
        (*current)->CRCFLAG = (unsigned char)(rand() % 256);
        (*current)->timestamp = time(NULL);
        pthread_mutex_unlock(&list_mutex);

        (*current)->next = NULL;
        current = &(*current)->next;
    }

    return head;
}

// Example usage
int main() {
    srand(time(0));
    NFAPI_CRC_INDICATION_PDU_T* list = create_linked_list(5);
    // Process the list...
    free(list); // Remember to free the allocated memory
    return 0;
}
