    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
    int crcflag;
    struct NFAPI_CRC_INDICATION_PDU *next;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *head;
    NFAPI_CRC_INDICATION_PDU_T *tail;
    size_t current_size;
    pthread_mutex_t mutex;
} CRC_LIST_T;

void init_crc_list(CRC_LIST_T *list) {
    list->head = NULL;
    list->tail = NULL;
    list->current_size = 0;
    pthread_mutex_init(&list->mutex, NULL);
}

int insert_to_crc_list(CRC_LIST_T *list) {
    if (list->current_size >= MAX_ELEMENTS) {
        log_error("CRC List is full");
        return -1;
    }

    NFAPI_CRC_INDICATION_PDU_T *new_node = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_node) {
        log_error("Failed to allocate memory for new CRC node");
        return -1;
    }

    // Initialize new node with random data
    new_node->ue_info = generate_random_UE_INFO();
    new_node->rnti = generate_random_RNTI();
    new_node->crc_indication = generate_random_CRC_INDICATION();
    new_node->crcflag = rand() % 2; // Randomly set CRCFLAG to 0 or 1
    new_node->next = NULL;

    pthread_mutex_lock(&list->mutex);
    if (list->tail) {
        list->tail->next = new_node;
    } else {
        list->head = new_node;
    }
    list->tail = new_node;
    list->current_size++;
    pthread_mutex_unlock(&list->mutex);

    return 0;
}

void *crc_thread_func(void *arg) {
    CRC_LIST_T *list = (CRC_LIST_T *)arg;

    for (int i = 0; i < 1000; i++) { // Example of thread work
        if (insert_to_crc_list(list) != 0) {
            break;
        }
    }

    return NULL;
}

int main() {
    srand(time(NULL));
    CRC_LIST_T list;
    init_crc_list(&list);

    pthread_t threads[10];
    for (int i = 0; i < 10; i++) {
        if (pthread_create(&threads[i], NULL, crc_thread_func, &list) != 0) {
            log_error("Failed to create thread");
            return -1;
        }
    }

    for (int i = 0; i < 10; i++) {
        pthread_join(threads[i], NULL);
    }

    log_info("CRC List created with %zu elements", list.current_size);

    // Clean up
    NFAPI_CRC_INDICATION_PDU_T *current = list.head;
    while (current) {
        NFAPI_CRC_INDICATION_PDU_T *next = current->next;
        free(current);
        current = next;
    }

    pthread_mutex_destroy(&list.mutex);

    return 0;
}
