import reactor.core.publisher.Flux;
import java.security.MessageDigest;
import java.util.concurrent.ConcurrentHashMap;

public class HashBatchProcessor {
    private ConcurrentHashMap<String, String> cache;
    private MessageDigest digest;
    private int cacheSize;
    private double evictionThreshold;
    private int retryLimit;

    public HashBatchProcessor(int cacheSize, double evictionThreshold, int retryLimit) throws Exception {
        this.cache = new ConcurrentHashMap<>(cacheSize);
        this.digest = MessageDigest.getInstance("SHA-256");
        this.cacheSize = cacheSize;
        this.evictionThreshold = evictionThreshold;
        this.retryLimit = retryLimit;
    }

    public Flux<String> processBatch(Flux<String> inputStrings) {
        return inputStrings.flatMap(s -> {
            if (cache.containsKey(s)) {
                return Flux.just(cache.get(s));
            } else {
                return Flux.fromCallable(() -> hashString(s))
                           .retry(retryLimit)
                           .onErrorResume(e -> {
                               logError(s, e);
                               return Flux.empty();
                           })
                           .doOnNext(hash -> cache.putIfAbsent(s, hash));
            }
        }).flatMap(this::logHash);
    }

    private String hashString(String input) {
        byte[] encodedhash = digest.digest(input.getBytes());
        return bytesToHex(encodedhash);
    }

    private String bytesToHex(byte[] bytes) {
        StringBuilder hexString = new StringBuilder();
        for (byte b : bytes) {
            String hex = Integer.toHexString(0xff & b);
            if(hex.length() == 1) hexString.append('0');
            hexString.append(hex);
        }
        return hexString.toString();
    }

    private void logError(String input, Throwable e) {
        // Log error details to console or centralized logging service
    }

    private Flux<String> logHash(String hash) {
        // Log successful hash computation details to console or centralized logging service
        return Flux.just(hash);
    }
}
```

This code snippet provides a basic structure for the `HashBatchProcessor` class, which uses Project Reactor's reactive programming model to handle batch processing of input strings and generate their SHA-256 hashes. The class utilizes a thread-safe `ConcurrentHashMap` as a cache to store previously computed hashes, implementing an LRU eviction policy based on a configurable threshold. Error handling is implemented using `onErrorResume`, and detailed error information is logged. The actual hash computation and logging details are left for implementation based on specific requirements and logging frameworks in use.']

