#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    Node* tail;
    pthread_mutex_t mutex;
} List;

void init_list(List* list) {
    list->head = NULL;
    list->tail = NULL;
    pthread_mutex_init(&list->mutex, NULL);
}

void free_list(List* list) {
    pthread_mutex_lock(&list->mutex);
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_unlock(&list->mutex);
    pthread_mutex_destroy(&list->mutex);
}

NFAPI_CRC_INDICATION_PDU_T generate_random_pdu() {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    srand(time(NULL));
    pdu.RX_UE_INFORMATION_TAG = rand();
    pdu.RNTI = (uint16_t)rand();
    pdu.CRC_INDICATION_REL8_TAG = (uint8_t)(rand() % 2);
    return pdu;
}

void add_to_list(List* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&list->mutex);
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (new_node == NULL) {
        perror("Failed to allocate memory for new node");
        return;
    }
    new_node->data = pdu;
    new_node->next = NULL;

    if (list->head == NULL) {
        list->head = new_node;
        list->tail = new_node;
    } else {
        list->tail->next = new_node;
        list->tail = new_node;
    }
    pthread_mutex_unlock(&list->mutex);
}

void remove_from_list(List* list, uint32_t RX_UE_INFORMATION_TAG) {
    pthread_mutex_lock(&list->mutex);
    Node* current = list->head;
    Node* previous = NULL;

    while (current != NULL && current->data.RX_UE_INFORMATION_TAG != RX_UE_INFORMATION_TAG) {
        previous = current;
        current = current->next;
    }

    if (current == NULL) {
        pthread_mutex_unlock(&list->mutex);
        return; // Tag not found
    }

    if (previous == NULL) {
        list->head = current->next;
    } else {
        previous->next = current->next;
    }

    free(current);
    pthread_mutex_unlock(&list->mutex);
}

void* thread_function(void* arg) {
    List* list = (List*)arg;
    for (int i = 0; i < 1000; i++) {
        NFAPI_CRC_INDICATION_PDU_T pdu = generate_random_pdu();
        add_to_list(list, pdu);

        // Simulate some processing time
        usleep(500);
    }
    return NULL;
}

int main() {
    List list;
    init_list(&list);

    pthread_t threads[10];
    for (int i = 0; i < 10; i++) {
        pthread_create(&threads[i], NULL, thread_function, &list);
    }

    for (int i = 0; i < 10; i++) {
        pthread_join(threads[i], NULL);
    }

    free_list(&list);

    return 0;
}
