#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_FILES 10

void printManPage() {
    printf("Usage: program_name [--manpage] [-cs] -o output_file [-l limit_output_lines] file1 [file2 ...]\n");
}

int processFile(const char *filename, int caseSensitive, const char *outputFile, int limitLines) {
    FILE *input = fopen(filename, "r");
    if (!input) {
        perror("Error opening file");
        return 1;
    }

    FILE *output = fopen(outputFile, "a");
    if (!output) {
        perror("Error opening output file");
        fclose(input);
        return 1;
    }

    char buffer[1024];
    int lineCount = 0;

    while (fgets(buffer, sizeof(buffer), input)) {
        if (lineCount >= limitLines) break;

        if (!caseSensitive) {
            for (char *c = buffer; *c; c++) *c = tolower(*c);
        }

        // Process the line and write to output
        fputs(buffer, output);
        lineCount++;
    }

    fclose(input);
    fclose(output);
    return 0;
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        printManPage();
        return 1;
    }

    int caseSensitive = 1;
    const char *outputFile = "default_output.txt";
    int limitLines = -1;
    char *files[MAX_FILES] = { NULL };
    int fileCount = 0;

    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "--manpage") == 0) {
            printManPage();
            return 0;
        } else if (strcmp(argv[i], "-cs") == 0) {
            caseSensitive = 0;
        } else if (strcmp(argv[i], "-o") == 0 && i + 1 < argc) {
            outputFile = argv[++i];
        } else if (strcmp(argv[i], "-l") == 0 && i + 1 < argc) {
            limitLines = atoi(argv[++i]);
        } else if (fileCount < MAX_FILES) {
            files[fileCount++] = argv[i];
        }
    }

    for (int i = 0; i < fileCount; i++) {
        processFile(files[i], caseSensitive, outputFile, limitLines);
    }

    return 0;
}
