use std::collections::HashMap;
use tokio::{task, time};
use rand::Rng;

#[derive(Debug)]
struct NFAPI_CRC_INDICATION_PDU_T {
    rx_ue_information_tag: String,
    rnti: u16,
    crc_indication_rel8_tag: CRC_INDICATION_REL8_TAG,
}

#[derive(Debug)]
struct CRC_INDICATION_REL8_TAG {
    crcflag: bool,
}

async fn generate_pdu(n: usize) -> Vec<NFAPI_CRC_INDICATION_PDU_T> {
    let mut pdus = Vec::new();
    for _ in 0..n {
        let rx_ue_information_tag = String::from("UE_INFO");
        let rnti: u16 = rand::thread_rng().gen_range(1..1000);
        let crcflag = rand::thread_rng().gen();
        pdus.push(NFAPI_CRC_INDICATION_PDU_T {
            rx_ue_information_tag,
            rnti,
            crc_indication_rel8_tag: CRC_INDICATION_REL8_TAG { crcflag },
        });
    }
    pdus
}

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    let args: Vec<String> = std::env::args().collect();
    if args.len() < 2 {
        eprintln!("Usage: {} <N>", args[0]);
        return Ok(());
    }

    let n = args[1].parse::<usize>()?;
    let mut cache: HashMap<usize, Vec<NFAPI_CRC_INDICATION_PDU_T>> = HashMap::new();

    loop {
        if !cache.contains_key(&n) {
            cache.insert(n, task::spawn(generate_pdu(n)).await?);
        }

        for pdu in &cache[&n] {
            println!("{:?}", pdu);
        }

        time::sleep(time::Duration::from_secs(10)).await;
    }
}
