#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    // Define structure members
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct LinkedListNode {
    NFAPI_CRC_INDICATION_PDU_T *data;
    struct LinkedListNode *next;
} LinkedListNode;

LinkedListNode* generateNFAPIList(int N, pthread_mutex_t *mutex) {
    LinkedListNode *head = NULL;
    pthread_mutex_lock(mutex);

    for (int i = 0; i < N; ++i) {
        NFAPI_CRC_INDICATION_PDU_T *newData = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!newData) {
            log_error("Memory allocation failed");
            pthread_mutex_unlock(mutex);
            cleanList(head, mutex);
            return NULL;
        }

        // Initialize newData members
        time_t seed = time(NULL);
        srand(seed + i); // Seed for pseudo-random generator

        // Set CRCFLAG based on pseudo-random generator
        if (rand() % 2 == 0) {
            newData->CRCFLAG = 1; // Example flag set logic
        } else {
            newData->CRCFLAG = 0;
        }

        LinkedListNode *newNode = malloc(sizeof(LinkedListNode));
        if (!newNode) {
            log_error("Memory allocation failed");
            free(newData);
            pthread_mutex_unlock(mutex);
            cleanList(head, mutex);
            return NULL;
        }

        newNode->data = newData;
        newNode->next = head;
        head = newNode;
    }

    pthread_mutex_unlock(mutex);
    return head;
}

void cleanList(LinkedListNode *head, pthread_mutex_t *mutex) {
    pthread_mutex_lock(mutex);
    LinkedListNode *current = head;
    while (current) {
        LinkedListNode *temp = current;
        current = current->next;
        free(temp->data);
        free(temp);
    }
    pthread_mutex_unlock(mutex);
}

// Example usage
int main() {
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    int N = 10000;
    LinkedListNode *head = generateNFAPIList(N, &mutex);

    if (head) {
        // Process the list
        cleanList(head, &mutex);
    }

    return 0;
}
