#include <time.h>

#define MAX_ENTRIES 10000
#define MAX_MEMORY_USAGE 500 * 1024 * 1024 // 500 MB

typedef struct {
    int rnti;
    int crc_flag;
} RX_UE_INFORMATION_TAG;

typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_info_tag;
    int rnti;
    int crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

pthread_mutex_t memory_lock = PTHREAD_MUTEX_INITIALIZER;
size_t current_memory_usage = 0;

NFAPI_CRC_INDICATION_PDU_T* generate_nfaapi_pdus(int n, RX_UE_INFORMATION_TAG* ue_info_tags, int num_ue_info_tags) {
    if (n > MAX_ENTRIES) {
        // Handle error: too many entries
        return NULL;
    }

    size_t required_memory = n * sizeof(NFAPI_CRC_INDICATION_PDU_T);
    if (current_memory_usage + required_memory > MAX_MEMORY_USAGE) {
        // Handle error: memory limit exceeded
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* pdus = malloc(required_memory);
    if (!pdus) {
        // Handle error: memory allocation failed
        return NULL;
    }

    pthread_mutex_lock(&memory_lock);

    for (int i = 0; i < n; ++i) {
        int random_index = rand() % num_ue_info_tags;
        pdus[i].rx_ue_info_tag = ue_info_tags[random_index];
        pdus[i].rnti = pdus[i].rx_ue_info_tag.rnti;
        pdus[i].crc_indication_rel8_tag = rand();
    }

    current_memory_usage += required_memory;

    pthread_mutex_unlock(&memory_lock);

    return pdus;
}

void free_nfaapi_pdus(NFAPI_CRC_INDICATION_PDU_T* pdus, int n) {
    if (pdus) {
        pthread_mutex_lock(&memory_lock);
        current_memory_usage -= n * sizeof(NFAPI_CRC_INDICATION_PDU_T);
        pthread_mutex_unlock(&memory_lock);

        free(pdus);
    }
}
