HashTable* createHashTable(int initialCapacity, unsigned long (*hashFunction)(const UserProfile*)) {
    HashTable* table = (HashTable*)malloc(sizeof(HashTable));
    if (!table) return NULL;

    table->buckets = (HashTableNode**)calloc(initialCapacity, sizeof(HashTableNode*));
    if (!table->buckets) {
        free(table);
        return NULL;
    }

    table->size = 0;
    table->capacity = initialCapacity;
    // Initialize synchronization mechanism

    return table;
}

void destroyHashTable(HashTable* table) {
    for (int i = 0; i < table->capacity; ++i) {
        HashTableNode* node = table->buckets[i];
        while (node) {
            HashTableNode* next = node->next;
            free(node);
            node = next;
        }
    }
    free(table->buckets);
    free(table);
}

unsigned long hashFunction(const UserProfile* userProfile, int capacity) {
    // Implement a good hash function
    return (userProfile->age * 31 + *(int*)userProfile->name) % capacity;
}

void insertUserProfile(HashTable* table, const UserProfile* userProfile) {
    unsigned long index = hashFunction(userProfile, table->capacity);
    HashTableNode* newNode = (HashTableNode*)malloc(sizeof(HashTableNode));
    if (!newNode) return;

    memcpy(&newNode->data, userProfile, sizeof(UserProfile));
    newNode->next = table->buckets[index];
    table->buckets[index] = newNode;
    ++table->size;

    // Handle collisions and growth
}

// Add other functions for managing the hash table as per requirements

int main() {
    // Example usage of the hash table
    UserProfile user1 = {"Alice", 30};
    UserProfile user2 = {"Bob", 25};

    HashTable* table = createHashTable(16, &hashFunction);
    if (table) {
        insertUserProfile(table, &user1);
        insertUserProfile(table, &user2);

        // Use the hash table as needed

        destroyHashTable(table);
    }

    return 0;
}
