use tokio::net::{TcpListener, TcpStream};
use tokio::io::{AsyncReadExt, AsyncWriteExt};
use std::env;
use serde_json::{Value, from_str};
use reqwest;

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    let args: Vec<String> = env::args().collect();
    if args.len() < 3 {
        eprintln!("Usage: {} mode port", args[0]);
        return Ok(());
    }

    let mode = &args[1];
    let port = args[2].parse::<u16>()?;
    let listener = TcpListener::bind(format!("0.0.0.0:{}", port)).await?;

    println!("Server listening on port {}", port);

    loop {
        let (stream, addr) = listener.accept().await?;
        tokio::spawn(handle_connection(stream, mode));
    }
}

async fn handle_connection(mut stream: TcpStream, mode: &str) {
    let mut buffer = [0; 1024];
    match stream.read(&mut buffer).await {
        Ok(n) if n == 0 => return,
        Ok(n) => {
            let request = String::from_utf8_lossy(&buffer[..n]);
            process_request(request, mode).await;
        }
        Err(_) => {
            eprintln!("Failed to read from stream");
        }
    }
}

async fn process_request(request: String, mode: &str) {
    if let Ok(json_value) = from_str(&request) {
        match json_value["type"].as_str() {
            Some("auth") => handle_auth_token(json_value).await,
            _ => eprintln!("Unsupported request type"),
        }
    } else {
        eprintln!("Invalid JSON payload");
    }
}

async fn handle_auth_token(payload: Value) {
    let token = payload["token"].as_str().unwrap_or_default();
    match validate_token(token).await {
        Ok(true) => execute_action(payload),
        Ok(false) => eprintln!("Token invalid"),
        Err(_) => eprintln!("Failed to validate token"),
    }
}

async fn validate_token(token: &str) -> Result<bool, reqwest::Error> {
    let client = reqwest::Client::new();
    let response = client.get("https://auth-service.com/validate")
        .query(&[("token", token)])
        .send()
        .await?
        .text()
        .await?;

    Ok(response == "valid")
}

fn execute_action(payload: Value) {
    // Implement action execution logic here
    println!("Executing action for payload: {:?}", payload);
}
```

