#define MAX_ENTRIES 10000
#define BURST_SIZE 50000
#define LOG_FILE "nfaapi_crc_indication.log"

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* crc_indications[MAX_ENTRIES];
int entry_count = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t cond_var = PTHREAD_COND_INITIALIZER;

void log_message(const char* message) {
    FILE* log_file = fopen(LOG_FILE, "a");
    if (log_file != NULL) {
        fprintf(log_file, "%s\n", message);
        fclose(log_file);
    }
}

NFAPI_CRC_INDICATION_PDU_T* create_crc_indication(uint32_t ue_info_tag, uint16_t rnti, uint8_t crc_flag) {
    NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (pdu != NULL) {
        pdu->RX_UE_INFORMATION_TAG = ue_info_tag;
        pdu->RNTI = rnti;
        pdu->CRC_INDICATION_REL8_TAG = crc_flag;
    }
    return pdu;
}

void* background_worker(void* arg) {
    while (1) {
        pthread_mutex_lock(&mutex);
        if (entry_count > 0 && entry_count < MAX_ENTRIES / 2) {
            for (int i = 0; i < entry_count / 2; i++) {
                free(crc_indications[i]);
                crc_indications[i] = NULL;
            }
            entry_count /= 2;
            log_message("Buffer utilization adjusted, memory freed.");
        } else if (entry_count == MAX_ENTRIES) {
            pthread_cond_signal(&cond_var);
        }
        pthread_mutex_unlock(&mutex);

        // Sleep for a while before next adjustment
        sleep(5);
    }
    return NULL;
}

void generate_crc_indications(int num_entries) {
    pthread_t worker_thread;
    pthread_create(&worker_thread, NULL, background_worker, NULL);

    srand(time(NULL));
    for (int i = 0; i < num_entries; i++) {
        uint32_t ue_info_tag = rand() % 1000000;
        uint16_t rnti = rand() % 4095;
        uint8_t crc_flag = rand() % 2;

        pthread_mutex_lock(&mutex);
        while (entry_count == MAX_ENTRIES) {
            pthread_cond_wait(&cond_var, &mutex);
        }

        NFAPI_CRC_INDICATION_PDU_T* pdu = create_crc_indication(ue_info_tag, rnti, crc_flag);
        if (pdu != NULL) {
            crc_indications[entry_count++] = pdu;
        }
        pthread_mutex_unlock(&mutex);

        // Simulate network latency
        sleep(rand() % 2);
    }

    pthread_join(worker_thread, NULL);
}

int main() {
    generate_crc_indications(BURST_SIZE);
    log_message("CRC indications generated successfully.");
    return 0;
}
