                crc_indication_rel8_tag: crcflag,
            });
        }
        pdus
    }

    async fn handle_crc_pdus(&self, mut rx: mpsc::Receiver<NFAPI_CRC_INDICATION_PDU_T>) {
        while let Some(pdu) = rx.recv().await {
            // Simulate processing the PDU
            println!("{:?}", pdu);
        }
    }
}

