#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

// Define the structure for user profile
typedef struct {
    char name[100];
    char email[100];
    char phone[20];
    char preferences[256];
    time_t last_login;
    char *social_media_accounts;
} UserProfile;

// Define a node in the linked list for storing profiles
typedef struct ProfileNode {
    UserProfile profile;
    struct ProfileNode *next;
} ProfileNode;

// Define a hash table for quick access and caching
#define TABLE_SIZE 1000
ProfileNode* hash_table[TABLE_SIZE];

// Mutex for thread safety
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to calculate hash key based on email domain
unsigned int get_hash_key(const char *email) {
    unsigned int hash = 5381;
    int c;
    while ((c = *email++)) {
        hash = ((hash << 5) + hash) + c; /* hash * 33 + c */
    }
    return hash % TABLE_SIZE;
}

// Function to insert a user profile into the database
void insert_profile(UserProfile profile) {
    pthread_mutex_lock(&mutex);
    unsigned int key = get_hash_key(profile.email);
    ProfileNode *new_node = (ProfileNode *)malloc(sizeof(ProfileNode));
    new_node->profile = profile;
    new_node->next = hash_table[key];
    hash_table[key] = new_node;
    pthread_mutex_unlock(&mutex);
}

// Function to delete a user profile from the database
void delete_profile(const char *email) {
    pthread_mutex_lock(&mutex);
    unsigned int key = get_hash_key(email);
    ProfileNode *current = hash_table[key];
    ProfileNode *previous = NULL;

    while (current != NULL) {
        if (strcmp(current->profile.email, email) == 0) {
            if (previous == NULL) {
                hash_table[key] = current->next;
            } else {
                previous->next = current->next;
            }
            free(current);
            pthread_mutex_unlock(&mutex);
            return;
        }
        previous = current;
        current = current->next;
    }
    pthread_mutex_unlock(&mutex);
}

// Function to retrieve a user profile from the database
UserProfile* get_profile(const char *email) {
    unsigned int key = get_hash_key(email);
    ProfileNode *current = hash_table[key];

    while (current != NULL) {
        if (strcmp(current->profile.email, email) == 0) {
            pthread_mutex_lock(&mutex);
            UserProfile *profile_copy = malloc(sizeof(UserProfile));
            memcpy(profile_copy, &current->profile, sizeof(UserProfile));
            profile_copy->social_media_accounts = strdup(current->profile.social_media_accounts);
            pthread_mutex_unlock(&mutex);
            return profile_copy;
        }
        current = current->next;
    }

    pthread_mutex_lock(&mutex);
    UserProfile *not_found_profile = NULL;
    pthread_mutex_unlock(&mutex);
    return not_found_profile;
}

// Function to update a user profile and trigger notifications
void update_profile(UserProfile new_profile) {
    delete_profile(new_profile.email); // Assuming updates overwrite old profiles
    insert_profile(new_profile);
    // Trigger notification logic here
}

// Command-line interface functions (not implemented in this snippet)

int main() {
    // Example usage of the database management functions
    UserProfile user1 = {"John Doe", "john.doe@example.com", "1234567890", "News, Tech", time(NULL), NULL};
    insert_profile(user1);

    UserProfile *retrieved_user = get_profile("john.doe@example.com");
    if (retrieved_user != NULL) {
        printf("Retrieved User: %s\n", retrieved_user->name);
        free(retrieved_user->social_media_accounts); // Don't forget to free dynamically allocated strings
        free(retrieved_user);
    }

    return 0;
}
