#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_ENTRIES 10000

typedef struct {
    int rx_ue_information_tag;
    int rnti;
    int crc_indication_rel8_tag;
    int crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* pdu_list[MAX_ENTRIES];
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void initialize_pdu(int index) {
    pthread_mutex_lock(&mutex);
    if (index < 0 || index >= MAX_ENTRIES) {
        fprintf(stderr, "Invalid index: %d\n", index);
        return;
    }
    pdu_list[index] = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu_list[index]) {
        perror("Memory allocation failed");
        pthread_mutex_unlock(&mutex);
        return;
    }
    srand(time(NULL));
    pdu_list[index]->rx_ue_information_tag = rand();
    pdu_list[index]->rnti = rand() % 65536;
    pdu_list[index]->crc_indication_rel8_tag = rand();
    pdu_list[index]->crcflag = rand() % 2; // Randomly set CRCFLAG
    printf("PDU created at index %d\n", index);
    pthread_mutex_unlock(&mutex);
}

void free_pdu(int index) {
    pthread_mutex_lock(&mutex);
    if (index < 0 || index >= MAX_ENTRIES || !pdu_list[index]) {
        fprintf(stderr, "Invalid index: %d\n", index);
        pthread_mutex_unlock(&mutex);
        return;
    }
    free(pdu_list[index]);
    pdu_list[index] = NULL;
    printf("PDU freed at index %d\n", index);
    pthread_mutex_unlock(&mutex);
}

void export_pdus_to_file() {
    FILE* file = fopen("pdus.txt", "w");
    if (!file) {
        perror("Failed to open file for writing");
        return;
    }
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < MAX_ENTRIES; i++) {
        if (pdu_list[i]) {
            fprintf(file, "%d %d %d %d\n", pdu_list[i]->rx_ue_information_tag, pdu_list[i]->rnti,
                    pdu_list[i]->crc_indication_rel8_tag, pdu_list[i]->crcflag);
        }
    }
    pthread_mutex_unlock(&mutex);
    fclose(file);
    printf("PDUs exported to file 'pdus.txt'\n");
}

int main() {
    for (int i = 0; i < MAX_ENTRIES; i++) {
        initialize_pdu(i);
    }

    // Simulate freeing some PDUs
    free_pdu(5);
    free_pdu(10);

    export_pdus_to_file();

    return 0;
}
