        return NULL;
    }

    printf("Enter %d integers:\n", num_integers);
    for (int i = 0; i < num_integers; i++) {
        scanf("%d", &integers[i]);
    }

    int largest = find_largest_integer(integers, num_integers);
    printf("Largest integer: %d\n", largest);

    EVP_CIPHER *cipher;
    printf("Choose a cipher (1: ECB, 2: EDE, 3: EDE3, 4: CFB, 5: Null): ");
    int choice;
    scanf("%d", &choice);
    switch (choice) {
        case 1:
            cipher = EVP_aes_128_ecb();
            break;
        case 2:
            cipher = EVP_aes_128_cbc(); // Note: CFB is not EDE
            break;
        case 3:
            cipher = EVP_aes_128_cbc(); // Note: CFB is not EDE3
            break;
        case 4:
            cipher = EVP_aes_128_cfb();
            break;
        case 5:
            cipher = NULL;
            break;
        default:
            printf("Invalid choice\n");
            free(integers);
            return NULL;
    }

    free(integers);
    return cipher;
}

int find_largest_integer(int *array, int size) {
    int max = array[0];
    for (int i = 1; i < size; i++) {
        if (array[i] > max) {
            max = array[i];
        }
    }
    return max;
}
