#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <semaphore.h>

// Define the structure for a user profile
typedef struct {
    char name[100];
    char email[100];
    char phone_number[20];
    char preferences[256];
    char last_login_date[20];
    char social_media_accounts[512];
} UserProfile;

// Define the structure for a node in the distributed database
typedef struct Node {
    UserProfile profile;
    struct Node* next;
} Node;

// Define the structure for the distributed database
typedef struct {
    Node* head;
    sem_t lock;
} DistributedDatabase;

// Initialize the distributed database
void init_distributed_database(DistributedDatabase* db) {
    db->head = NULL;
    sem_init(&db->lock, 0, 1);
}

// Insert a user profile into the distributed database
void insert_profile(DistributedDatabase* db, UserProfile profile) {
    sem_wait(&db->lock);
    Node* new_node = (Node*)malloc(sizeof(Node));
    strcpy(new_node->profile.name, profile.name);
    strcpy(new_node->profile.email, profile.email);
    strcpy(new_node->profile.phone_number, profile.phone_number);
    strcpy(new_node->profile.preferences, profile.preferences);
    strcpy(new_node->profile.last_login_date, profile.last_login_date);
    strcpy(new_node->profile.social_media_accounts, profile.social_media_accounts);
    new_node->next = db->head;
    db->head = new_node;
    sem_post(&db->lock);
}

// Delete a user profile from the distributed database
void delete_profile(DistributedDatabase* db, char* email) {
    sem_wait(&db->lock);
    Node* current = db->head;
    Node* previous = NULL;
    while (current != NULL && strcmp(current->profile.email, email) != 0) {
        previous = current;
        current = current->next;
    }
    if (current == NULL) {
        sem_post(&db->lock);
        return;
    }
    if (previous == NULL) {
        db->head = current->next;
    } else {
        previous->next = current->next;
    }
    free(current);
    sem_post(&db->lock);
}

// Retrieve a user profile from the distributed database
UserProfile* retrieve_profile(DistributedDatabase* db, char* email) {
    sem_wait(&db->lock);
    Node* current = db->head;
    while (current != NULL && strcmp(current->profile.email, email) != 0) {
        current = current->next;
    }
    if (current == NULL) {
        UserProfile* result = malloc(sizeof(UserProfile));
        strcpy(result->name, "");
        strcpy(result->email, "");
        strcpy(result->phone_number, "");
        strcpy(result->preferences, "");
        strcpy(result->last_login_date, "");
        strcpy(result->social_media_accounts, "");
        sem_post(&db->lock);
        return result;
    }
    UserProfile* result = malloc(sizeof(UserProfile));
    strcpy(result->name, current->profile.name);
    strcpy(result->email, current->profile.email);
    strcpy(result->phone_number, current->profile.phone_number);
    strcpy(result->preferences, current->profile.preferences);
    strcpy(result->last_login_date, current->profile.last_login_date);
    strcpy(result->social_media_accounts, current->profile.social_media_accounts);
    sem_post(&db->lock);
    return result;
}

// Update a user profile in the distributed database
void update_profile(DistributedDatabase* db, UserProfile new_profile) {
    sem_wait(&db->lock);
    Node* current = db->head;
    while (current != NULL && strcmp(current->profile.email, new_profile.email) != 0) {
        current = current->next;
    }
    if (current != NULL) {
        strcpy(current->profile.name, new_profile.name);
        strcpy(current->profile.phone_number, new_profile.phone_number);
        strcpy(current->profile.preferences, new_profile.preferences);
        strcpy(current->profile.last_login_date, new_profile.last_login_date);
        strcpy(current->profile.social_media_accounts, new_profile.social_media_accounts);
    }
    sem_post(&db->lock);
}

// Free the memory allocated for the distributed database
void free_distributed_database(DistributedDatabase* db) {
    Node* current = db->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    sem_destroy(&db->lock);
}
