#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <pthread.h>

#define MAX_INPUT_FILES 10
#define DEFAULT_CHUNK_SIZE 4096

typedef struct {
    char *filename;
    int chunk_size;
    int case_sensitive;
    FILE *output_file;
    int limit_output_lines;
    int line_count;
} FileTask;

void *process_file(void *arg) {
    FileTask *task = (FileTask *)arg;
    FILE *input_file = fopen(task->filename, "r");
    if (!input_file) {
        perror("Failed to open file");
        return NULL;
    }

    char buffer[task->chunk_size];
    size_t bytes_read;

    while ((bytes_read = fread(buffer, 1, task->chunk_size, input_file)) > 0) {
        for (size_t i = 0; i < bytes_read; i++) {
            if (task->limit_output_lines && task->line_count >= task->limit_output_lines) break;
            // Process each character or line based on requirements
            printf("%c", buffer[i]);
            if (buffer[i] == '\n') task->line_count++;
        }
    }

    fclose(input_file);
    return NULL;
}

int main(int argc, char *argv[]) {
    int input_files[MAX_INPUT_FILES];
    int file_count = 0;
    int chunk_size = DEFAULT_CHUNK_SIZE;
    int case_sensitive = 0;
    FILE *output_file = stdout;
    int limit_output_lines = INT_MAX;

    // Parse command line arguments
    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "--manpage") == 0) {
            printf("Usage: %s [options] input_file [input_file...]\n", argv[0]);
            printf("Options:\n");
            printf("  --manpage     Show this help message\n");
            printf("  -cs           Case-sensitive search\n");
            printf("  -o output_file Output file for results\n");
            printf("  -l limit_output_lines Limit the number of lines printed\n");
            return 0;
        } else if (strcmp(argv[i], "-cs") == 0) {
            case_sensitive = 1;
        } else if (strcmp(argv[i], "-o") == 0 && i + 1 < argc) {
            output_file = fopen(argv[++i], "w");
            if (!output_file) {
                perror("Failed to open output file");
                return 1;
            }
        } else if (strcmp(argv[i], "-l") == 0 && i + 1 < argc) {
            limit_output_lines = atoi(argv[++i]);
        } else if (file_count < MAX_INPUT_FILES) {
            input_files[file_count++] = i;
        } else {
            fprintf(stderr, "Too many input files\n");
            return 1;
        }
    }

    if (!file_count) {
        printf("No input file specified. Use --manpage for help.\n");
        return 0;
    }

    pthread_t threads[MAX_INPUT_FILES];
    FileTask tasks[MAX_INPUT_FILES];

    for (int i = 0; i < file_count; i++) {
        memset(&tasks[i], 0, sizeof(FileTask));
        tasks[i].filename = argv[input_files[i]];
        tasks[i].chunk_size = chunk_size;
        tasks[i].case_sensitive = case_sensitive;
        tasks[i].output_file = output_file;
        tasks[i].limit_output_lines = limit_output_lines;

        if (pthread_create(&threads[i], NULL, process_file, &tasks[i]) != 0) {
            perror("Failed to create thread");
            return 1;
        }
    }

    for (int i = 0; i < file_count; i++) {
        pthread_join(threads[i], NULL);
    }

    if (output_file != stdout) fclose(output_file);

    return 0;
}
