#define MAX_FILENAME_LENGTH 256

void generateRandomString(char *str, size_t length) {
    static const char charset[] = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
    for (size_t i = 0; i < length; ++i) {
        str[i] = charset[rand() % (sizeof(charset) - 1)];
    }
    str[length] = '\0';
}

int generateSequenceNumber() {
    static int sequence_number = 0;
    return ++sequence_number;
}

char* getTimestamp() {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y%m%d%H%M%S", tm_info);
    return strdup(timestamp);
}

void modifyFilename(char *filename) {
    if (strlen(filename) >= MAX_FILENAME_LENGTH - 16) {
        fprintf(stderr, "Filename too long\n");
        return;
    }

    char new_filename[MAX_FILENAME_LENGTH];
    int sequence = generateSequenceNumber();
    char timestamp[20] = getTimestamp();
    char random_string[8];
    generateRandomString(random_string, 8);

    snprintf(new_filename, sizeof(new_filename), "%s_%d_%s_%s", filename, sequence, timestamp, random_string);
    printf("Original: %s\nNew: %s\n", filename, new_filename);
}

int main() {
    srand(time(NULL));
    char filename[] = "example.txt";
    modifyFilename(filename);

    return 0;
}
