            case 'd':
                if (optarg && strlen(optarg) == 1) {
                    config.delimiter = optarg[0];
                } else {
                    log_error("Invalid delimiter specified");
                    return EXIT_FAILURE;
                }
                break;
            case '?':
                print_usage();
                return EXIT_FAILURE;
        }
    }

    if (optind >= argc) {
        print_usage();
        return EXIT_FAILURE;
    }

    pthread_t threads[argc - optind];
    for (int i = optind; i < argc; i++) {
        config.input_file = argv[i];
        if (pthread_create(&threads[i - optind], NULL, process_file, &config) != 0) {
            log_error("Failed to create thread");
            return EXIT_FAILURE;
        }
    }

    for (int i = 0; i < argc - optind; i++) {
        pthread_join(threads[i], NULL);
    }

    // Additional cleanup and logging

    return EXIT_SUCCESS;
}
```

