#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define INITIAL_LIST_SIZE 10
#define RESIZE_THRESHOLD 5

typedef struct {
    RX_UE_INFORMATION_TAG ue_info;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
    time_t timestamp;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* data;
    size_t used;
    size_t size;
    pthread_mutex_t lock;
} DynamicList;

void init_list(DynamicList *list) {
    list->data = (NFAPI_CRC_INDICATION_PDU_T*)malloc(INITIAL_LIST_SIZE * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    list->used = 0;
    list->size = INITIAL_LIST_SIZE;
    pthread_mutex_init(&list->lock, NULL);
}

void free_list(DynamicList *list) {
    pthread_mutex_lock(&list->lock);
    free(list->data);
    pthread_mutex_unlock(&list->lock);
}

NFAPI_CRC_INDICATION_PDU_T* add_item(DynamicList *list) {
    if (list->used == list->size) {
        size_t new_size = list->size + RESIZE_THRESHOLD;
        NFAPI_CRC_INDICATION_PDU_T* new_data = (NFAPI_CRC_INDICATION_PDU_T*)realloc(list->data, new_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_data) {
            perror("Failed to resize list");
            return NULL;
        }
        list->data = new_data;
        list->size = new_size;
    }

    NFAPI_CRC_INDICATION_PDU_T* item = &list->data[list->used];
    pthread_mutex_lock(&list->lock);
    item->ue_info = get_rx_ue_information_tag(); // Function to fetch UE info
    item->rnti = generate_unique_rnti(list);  // Function to generate unique RNTI, ensuring no consecutive same RNTI
    item->crc_indication.crcflag = rand() % 2; // Randomly set CRCFLAG
    item->timestamp = time(NULL);
    list->used++;
    pthread_mutex_unlock(&list->lock);

    return item;
}

void* scheduler_thread(void *arg) {
    DynamicList *list = (DynamicList*)arg;
    while (1) {
        NFAPI_CRC_INDICATION_PDU_T* item = add_item(list);
        if (!item) break;

        // Process the item
        process_item(item);  // Function to process the added item

        sleep(1); // Sleep for a second before adding the next item
    }
    return NULL;
}

int main() {
    srand(time(NULL));
    DynamicList list;
    init_list(&list);

    pthread_t thread_id;
    if (pthread_create(&thread_id, NULL, scheduler_thread, &list) != 0) {
        perror("Failed to create scheduler thread");
        free_list(&list);
        return EXIT_FAILURE;
    }

    // Wait for the scheduler thread to finish
    pthread_join(thread_id, NULL);

    free_list(&list);
    return EXIT_SUCCESS;
}
