void init_nfa_pi_crc_list(NFAPI_CRC_LIST *list, size_t initial_capacity) {
    list->capacity = initial_capacity;
    list->size = 0;
    list->data = (NFAPI_CRC_INDICATION_PDU_T *)malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
}

void free_nfa_pi_crc_list(NFAPI_CRC_LIST *list) {
    free(list->data);
}

void resize_nfa_pi_crc_list(NFAPI_CRC_LIST *list, size_t new_capacity) {
    NFAPI_CRC_INDICATION_PDU_T *new_data = (NFAPI_CRC_INDICATION_PDU_T *)realloc(list->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (new_data != NULL) {
        list->data = new_data;
        list->capacity = new_capacity;
    }
}

void add_nfa_pi_crc_indication(NFAPI_CRC_LIST *list, NFAPI_CRC_INDICATION_PDU_T indication) {
    if (list->size >= list->capacity) {
        resize_nfa_pi_crc_list(list, list->capacity * 2);
    }
    list->data[list->size++] = indication;
}

NFAPI_CRC_INDICATION_PDU_T get_last_nfa_pi_crc_indication(NFAPI_CRC_LIST *list, size_t n) {
    if (n >= list->size) {
        return list->data[list->size - 1];
    }
    return list->data[list->size - n - 1];
}

