fn generate_nfaapi_structs(n: u32) -> Vec<NFAPI_CRC_INDICATION_PDU_T> {
    let mut rng = rand::thread_rng();
    (0..n).map(|_| NFAPI_CRC_INDICATION_PDU_T {
        rx_ue_information_tag: RX_UE_INFORMATION_TAG::default(),
        rnti: rng.gen(),
        crc_indication_rel8_tag: CRC_INDICATION_REL8_TAG { crcflag: rng.gen() },
    }).collect()
}

fn find_max_value(numbers: &[u32]) -> u32 {
    *numbers.iter().max().unwrap_or(&0)
}

#[tokio::main]
async fn main() -> io::Result<()> {
    let args: Vec<String> = env::args().collect();
    if args.len() < 2 {
        eprintln!("Usage: {} <number_of_structs>", args[0]);
        return Ok(());
    }

    let n = args[1].parse::<u32>().expect("Please provide a valid number");
    let nfaapi_structs = task::spawn_blocking(|| generate_nfaapi_structs(n)).await.unwrap();

    println!("Generated NFAPI structs: {:?}", nfaapi_structs);

    let mut numbers = Vec::new();
    io::stdin().lock().lines()
        .take_while(|line| line.as_ref().is_ok())
        .map(|line| line.expect("Failed to read line"))
        .filter_map(|line| line.parse::<u32>().ok())
        .for_each(|num| numbers.push(num));

    if !numbers.is_empty() {
        let max_value = task::spawn_blocking(|| find_max_value(&numbers)).await.unwrap();
        println!("Largest integer: {}", max_value);
    } else {
        eprintln!("No integers provided");
    }

    Ok(())
}
