    size_t measurementCount;
    size_t maxMeasurements;
    pthread_mutex_t mutex;
} LTE_PHY_RX_FRAME_T;

LTE_PHY_RX_FRAME_T* lte_phy_rx_frame_init(size_t maxMeasurements) {
    LTE_PHY_RX_FRAME_T *frame = (LTE_PHY_RX_FRAME_T*)malloc(sizeof(LTE_PHY_RX_FRAME_T));
    if (frame == NULL) return NULL;

    frame->snrMeasurements = (SNRMeasurement*)calloc(maxMeasurements, sizeof(SNRMeasurement));
    if (frame->snrMeasurements == NULL) {
        free(frame);
        return NULL;
    }

    frame->measurementCount = 0;
    frame->maxMeasurements = maxMeasurements;
    pthread_mutex_init(&frame->mutex, NULL);

    return frame;
}

void lte_phy_rx_frame_add_measurement(LTE_PHY_RX_FRAME_T *frame, SNRMeasurement measurement) {
    pthread_mutex_lock(&frame->mutex);
    if (frame->measurementCount < frame->maxMeasurements) {
        frame->snrMeasurements[frame->measurementCount] = measurement;
        frame->measurementCount++;
    }
    pthread_mutex_unlock(&frame->mutex);
}

void lte_phy_rx_frame_remove_measurement(LTE_PHY_RX_FRAME_T *frame, size_t index) {
    pthread_mutex_lock(&frame->mutex);
    if (index < frame->measurementCount) {
        for (size_t i = index; i < frame->measurementCount - 1; i++) {
            frame->snrMeasurements[i] = frame->snrMeasurements[i + 1];
        }
        frame->measurementCount--;
    }
    pthread_mutex_unlock(&frame->mutex);
}

SNRMeasurement* lte_phy_rx_frame_get_measurement(LTE_PHY_RX_FRAME_T *frame, size_t index) {
    if (index < frame->measurementCount) {
        return &frame->snrMeasurements[index];
    } else {
        return NULL;
    }
}

void lte_phy_rx_frame_destroy(LTE_PHY_RX_FRAME_T *frame) {
    pthread_mutex_lock(&frame->mutex);
    free(frame->snrMeasurements);
    frame->snrMeasurements = NULL;
    pthread_mutex_unlock(&frame->mutex);
    pthread_mutex_destroy(&frame->mutex);
    free(frame);
}
