#include <time.h>

#define MAX_CONNECTIONS 1000
#define ROLLING_WINDOW_SIZE 10
#define SLIDING_WINDOW_SIZE 50

typedef struct {
    TCP_CONNECTION_ID connection_id;
    SOURCE_IP source_ip;
    DESTINATION_IP destination_ip;
    SOURCE_PORT source_port;
    DESTINATION_PORT destination_port;
    uint8_t SYN_FLAG;
    uint8_t ACK_FLAG;
    time_t timestamp;
} TCP_CONNECTION_RECORD_T;

TCP_CONNECTION_RECORD_T* tcp_connection_list = NULL;
int list_size = 0;
int current_index = 0;

void initialize_tcp_connection_list() {
    tcp_connection_list = (TCP_CONNECTION_RECORD_T*)malloc(MAX_CONNECTIONS * sizeof(TCP_CONNECTION_RECORD_T));
}

void add_tcp_connection_record(TCP_CONNECTION_ID connection_id, SOURCE_IP source_ip, DESTINATION_IP destination_ip, SOURCE_PORT source_port, DESTINATION_PORT destination_port) {
    TCP_CONNECTION_RECORD_T new_record;
    new_record.connection_id = connection_id;
    new_record.source_ip = source_ip;
    new_record.destination_ip = destination_ip;
    new_record.source_port = source_port;
    new_record.destination_port = destination_port;
    new_record.SYN_FLAG = rand() % 2;
    new_record.ACK_FLAG = rand() % 2;
    new_record.timestamp = time(NULL);

    // Ensure no two consecutive connections have the same ID
    while (list_size > 0 && tcp_connection_list[(current_index + list_size - 1) % MAX_CONNECTIONS].connection_id == connection_id) {
        connection_id = rand();
    }

    // Ensure no two records in rolling window have the same flag combination
    for (int i = 0; i < ROLLING_WINDOW_SIZE; i++) {
        int index = (current_index + list_size - ROLLING_WINDOW_SIZE + i) % MAX_CONNECTIONS;
        if (tcp_connection_list[index].SYN_FLAG == new_record.SYN_FLAG && tcp_connection_list[index].ACK_FLAG == new_record.ACK_FLAG) {
            connection_id = rand();
            break;
        }
    }

    tcp_connection_list[(current_index + list_size) % MAX_CONNECTIONS] = new_record;
    list_size++;
}

void resize_tcp_connection_list() {
    TCP_CONNECTION_RECORD_T* new_list = (TCP_CONNECTION_RECORD_T*)malloc(MAX_CONNECTIONS * 2 * sizeof(TCP_CONNECTION_RECORD_T));
    if (new_list == NULL) {
        return; // Memory allocation failed, handle error
    }

    for (int i = 0; i < list_size; i++) {
        new_list[i] = tcp_connection_list[(current_index + i) % MAX_CONNECTIONS];
    }

    free(tcp_connection_list);
    tcp_connection_list = new_list;
    current_index = 0;
    MAX_CONNECTIONS *= 2;
}

void log_error(const char* message) {
    // Log error to file or console
}

void log_performance_metric(const char* metric, double value) {
    // Log performance metric to file or dashboard
}

void graceful_shutdown() {
    free(tcp_connection_list);
}

// Other functions and integration points can be added here
