#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    TCP_CONNECTION_ID id;
    IP SOURCE_IP;
    IP DESTINATION_IP;
    PORT SOURCE_PORT;
    PORT DESTINATION_PORT;
    uint8_t SYN_FLAG;
    uint8_t ACK_FLAG;
    time_t timestamp;
} TCP_CONNECTION_RECORD_T;

typedef struct tcp_connection_list {
    TCP_CONNECTION_RECORD_T *records;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
} TCP_CONNECTION_LIST_T;

void initialize_tcp_connection_list(TCP_CONNECTION_LIST_T *list, size_t initial_capacity) {
    list->records = malloc(initial_capacity * sizeof(TCP_CONNECTION_RECORD_T));
    list->capacity = initial_capacity;
    list->count = 0;
    pthread_mutex_init(&list->mutex, NULL);
}

void resize_tcp_connection_list(TCP_CONNECTION_LIST_T *list) {
    size_t new_capacity = list->capacity * 2;
    TCP_CONNECTION_RECORD_T *new_records = realloc(list->records, new_capacity * sizeof(TCP_CONNECTION_RECORD_T));
    if (new_records) {
        list->records = new_records;
        list->capacity = new_capacity;
    }
}

void add_tcp_connection_record(TCP_CONNECTION_LIST_T *list, const TCP_CONNECTION_RECORD_T *record) {
    pthread_mutex_lock(&list->mutex);
    if (list->count >= list->capacity) {
        resize_tcp_connection_list(list);
    }
    list->records[list->count++] = *record;
    pthread_mutex_unlock(&list->mutex);
}

void free_tcp_connection_list(TCP_CONNECTION_LIST_T *list) {
    pthread_mutex_destroy(&list->mutex);
    free(list->records);
}
