#define INITIAL_LIST_SIZE 100
#define RESIZE_THRESHOLD 75

NFAPI_CRC_INDICATION_PDU_T* crc_list = NULL;
int list_size = 0;
int current_index = 0;

void resize_list() {
    if (current_index >= list_size * RESIZE_THRESHOLD / 100) {
        int new_size = list_size * 2;
        NFAPI_CRC_INDICATION_PDU_T* new_list = realloc(crc_list, new_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (new_list == NULL) {
            // Handle memory allocation failure
            return;
        }
        crc_list = new_list;
        list_size = new_size;
    }
}

void add_crc_indication() {
    resize_list();
    if (current_index >= list_size) {
        return; // List is full, cannot add more items
    }

    NFAPI_CRC_INDICATION_PDU_T* entry = &crc_list[current_index];
    entry->RX_UE_INFORMATION_TAG = get_current_ue_info(); // Fetch from external data source
    do {
        entry->RNTI = generate_random_rnti(); // Generate unique RNTI
    } while (current_index > 0 && crc_list[current_index - 1].RNTI == entry->RNTI); // Ensure no consecutive duplicates
    entry->CRC_INDICATION_REL8_TAG = get_current_crc_value(); // Fetch from external data source
    entry->CRCFLAG = rand() % 2; // Randomly set CRCFLAG
    entry->timestamp = time(NULL);

    current_index++;
}

void initialize_network_processing_framework() {
    srand(time(NULL));
    crc_list = malloc(INITIAL_LIST_SIZE * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (crc_list == NULL) {
        // Handle memory allocation failure
        return;
    }
    list_size = INITIAL_LIST_SIZE;
}

void cleanup_network_processing_framework() {
    free(crc_list);
}
