        case ALG_SHA256:
            ctx->md_ctx = EVP_MD_CTX_new();
            if (!EVP_DigestInit_ex(ctx->md_ctx, EVP_sha256(), NULL)) {
                fprintf(stderr, "Error initializing SHA-256\n");
                goto cleanup;
            }
            break;
        case ALG_RSA:
            // Initialize RSA key pair
            ctx->rsa = RSA_new();
            if (!ctx->rsa) {
                fprintf(stderr, "Error creating RSA context\n");
                goto cleanup;
            }
