            break;
        default:
            fprintf(stderr, "Unsupported algorithm\n");
            goto cleanup;
    }

    return ctx;

cleanup:
    if (ctx->cipher_ctx) EVP_CIPHER_CTX_free(ctx->cipher_ctx);
    if (ctx->md_ctx) EVP_MD_CTX_free(ctx->md_ctx);
    if (ctx->rsa) RSA_free(ctx->rsa);
    free(ctx);
    return NULL;
