void secure_library_init() {
    // Initialize OpenSSL library
    if (SSL_library_init() != 1) {
        fprintf(stderr, "Failed to initialize SSL library\n");
        exit(EXIT_FAILURE);
    }

    // Add AES block cipher
    if (!EVP_add_cipher(EVP_aes_256_cbc())) {
        fprintf(stderr, "Failed to add AES cipher\n");
        exit(EXIT_FAILURE);
    }

    // Add Camellia block cipher
    if (!EVP_add_cipher(EVP_camellia_256_ecb())) {
        fprintf(stderr, "Failed to add Camellia cipher\n");
        exit(EXIT_FAILURE);
    }

    // Add MD5 digest
    if (!EVP_add_digest(EVP_md5())) {
        fprintf(stderr, "Failed to add MD5 digest\n");
        exit(EXIT_FAILURE);
    }

    // Add SHA1 digest
    if (!EVP_add_digest(EVP_sha1())) {
        fprintf(stderr, "Failed to add SHA1 digest\n");
        exit(EXIT_FAILURE);
    }

    // Add RSA with SHA1
    if (!EVP_add_cipher(EVP_RSA_PKCS1_PADDING)) {
        fprintf(stderr, "Failed to add RSA padding\n");
        exit(EXIT_FAILURE);
    }

    // Alias for MD5
    if (!EVP_add_digest_alias("MD5", "md5")) {
        fprintf(stderr, "Failed to create MD5 alias\n");
        exit(EXIT_FAILURE);
    }

    // Alias for SHA1
    if (!EVP_add_digest_alias("SHA1", "sha1")) {
        fprintf(stderr, "Failed to create SHA1 alias\n");
        exit(EXIT_FAILURE);
    }
}
