#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_STRUCTURES 1000
#define RESIZE_THRESHOLD 800

typedef struct {
    int RNTI;
    int CRCFLAG;
    time_t timestamp;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T *crc_list = NULL;
int list_size = 0;
int max_size = MAX_STRUCTURES;

void resize_list() {
    max_size *= 2;
    crc_list = realloc(crc_list, max_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
}

NFAPI_CRC_INDICATION_PDU_T* get_new_structure(int RNTI) {
    NFAPI_CRC_INDICATION_PDU_T *new_struct = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    new_struct->RNTI = RNTI;
    new_struct->CRCFLAG = rand() % 2; // Randomly set CRCFLAG
    new_struct->timestamp = time(NULL);
    return new_struct;
}

void add_structure(int RNTI) {
    if (list_size >= max_size * 0.8)
        resize_list();

    NFAPI_CRC_INDICATION_PDU_T *new_struct = get_new_structure(RNTI);
    crc_list[list_size++] = *new_struct;

    free(new_struct); // Free the temporary structure
}

int check_duplicate_RNTI(int RNTI) {
    for (int i = 0; i < list_size; i++) {
        if (crc_list[i].RNTI == RNTI)
            return 1;
    }
    return 0;
}

void process_network_data() {
    // Simulate fetching UE information and RNTI values from external sources
    int RNTI = rand() % 1000;

    if (!check_duplicate_RNTI(RNTI)) {
        add_structure(RNTI);
    } else {
        printf("Duplicate RNTI detected: %d\n", RNTI);
    }
}

int main() {
    srand(time(NULL));

    // Simulate periodic execution of the function
    for (int i = 0; i < 1000; i++) {
        process_network_data();
    }

    free(crc_list);

    return 0;
}
