    pthread_mutex_init(&array->mutex, NULL);
    clock_gettime(CLOCK_MONOTONIC, &array->start_time);
    array->total_allocations = 0;
    array->successful_allocations = 0;
    array->average_allocation_time = 0;
}

void* resize_array(void *arg) {
    DynamicArray *array = (DynamicArray *)arg;
    pthread_mutex_lock(&array->mutex);
    if (array->size >= ARRAY_THRESHOLD && array->capacity < MAX_CAPACITY) {
        array->capacity *= 2;
        array->array = realloc(array->array, array->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    }
    pthread_mutex_unlock(&array->mutex);
    return NULL;
}

void add_element_to_array(DynamicArray *array) {
    pthread_mutex_lock(&array->mutex);
    if (array->size == array->capacity) {
        pthread_t thread;
        pthread_create(&thread, NULL, resize_array, array);
        pthread_join(thread, NULL);
    }
    NFAPI_CRC_INDICATION_PDU_T new_element = { /* initialize with valid values */ };
    array->array[array->size++] = new_element;
    pthread_mutex_unlock(&array->mutex);
}

void print_statistics(DynamicArray *array) {
    double current_time;
    clock_gettime(CLOCK_MONOTONIC, &current_time);
    array->average_allocation_time = ((current_time - array->start_time.tv_sec) / (array->total_allocations + 1)) * 1e9;
    printf("Total Allocations: %zu\n", array->total_allocations);
    printf("Successful Allocations: %zu\n", array->successful_allocations);
    printf("Average Allocation Time: %.2f ns\n", array->average_allocation_time);
}

void cleanup(DynamicArray *array) {
    pthread_mutex_destroy(&array->mutex);
    free(array->array);
}
