public class SecureCryptoManager : IDisposable
{
    private int minValue;
    private int maxValue;
    private static readonly RNGCryptoServiceProvider rng = new RNGCryptoServiceProvider();

    public SecureCryptoManager(int minValue, int maxValue)
    {
        if (minValue > maxValue)
        {
            throw new ArgumentOutOfRangeException(nameof(minValue), "Min value must be less than or equal to max value.");
        }
        this.minValue = minValue;
        this.maxValue = maxValue;
    }

    public void Dispose()
    {
        rng.Dispose();
    }

    public float GenerateRandomFloat(float min, float max)
    {
        byte[] randomBytes = new byte[4];
        rng.GetBytes(randomBytes);
        return BitConverter.ToSingle(randomBytes, 0) * (max - min) + min;
    }

    public int GenerateRandomInt(int min, int max)
    {
        byte[] randomBytes = new byte[4];
        rng.GetBytes(randomBytes);
        return BitConverter.ToInt32(randomBytes, 0) % (max - min + 1) + min;
    }

    public bool ValidateOAuth2Token(string tokenResponseJson)
    {
        JObject tokenResponse = JObject.Parse(tokenResponseJson);
        if (!tokenResponse.ContainsKey("access_token") ||
            !tokenResponse.ContainsKey("expires_in") ||
            !tokenResponse.ContainsKey("token_type"))
        {
            return false;
        }
        string tokenType = (string)tokenResponse["token_type"];
        int expiresIn = 0;
        if (!int.TryParse((string)tokenResponse["expires_in"], out expires_in) || expires_in <= 0)
        {
            return false;
        }
        return tokenType == "Bearer";
    }

    public override string ToString()
    {
        return $"Range: {minValue}-{maxValue}";
    }

