#include <stdlib.h>
#include <pthread.h>
#include <stdio.h>

#define MAX_ENTRIES 10000
#define CONCURRENCY_LIMIT 5

typedef struct {
    // Define the structure members based on NFAPI_CRC_INDICATION_PDU_T
    int RX_UE_INFORMATION_TAG;
    unsigned short RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    void *memory_pool;
    size_t pool_size;
    size_t used_memory;
    pthread_mutex_t mutex;
} MemoryPool;

MemoryPool memory_pool;

void initialize_memory_pool(size_t size) {
    memory_pool.memory_pool = malloc(size);
    memory_pool.pool_size = size;
    memory_pool.used_memory = 0;
    pthread_mutex_init(&memory_pool.mutex, NULL);
}

void *allocate_from_pool(size_t size) {
    void *ptr;
    pthread_mutex_lock(&memory_pool.mutex);
    if (memory_pool.used_memory + size > memory_pool.pool_size) {
        printf("Memory allocation failed: Insufficient pool size\n");
        ptr = NULL;
    } else {
        ptr = (char *)memory_pool.memory_pool + memory_pool.used_memory;
        memory_pool.used_memory += size;
    }
    pthread_mutex_unlock(&memory_pool.mutex);
    return ptr;
}

NFAPI_CRC_INDICATION_PDU_T *allocate_and_initialize_entries(int N) {
    if (N <= 0 || N > MAX_ENTRIES) {
        printf("Invalid number of entries: %d\n", N);
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T *entries = allocate_from_pool(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (entries == NULL) {
        return NULL;
    }

    for (int i = 0; i < N; i++) {
        entries[i].RX_UE_INFORMATION_TAG = rand();
        entries[i].RNTI = rand() % 65536;
        entries[i].CRC_INDICATION_REL8_TAG = rand();
        entries[i].CRCFLAG = rand() % 2; // Randomly set to either 0 or 1
    }

    return entries;
}

void free_entries(NFAPI_CRC_INDICATION_PDU_T *entries) {
    pthread_mutex_lock(&memory_pool.mutex);
    memory_pool.used_memory -= N * sizeof(NFAPI_CRC_INDICATION_PDU_T);
    pthread_mutex_unlock(&memory_pool.mutex);
    // Optionally zero out the memory if needed for security
}

int main() {
    initialize_memory_pool(1024 * 1024 * 10); // Initialize memory pool of 10MB

    int N = 5; // Example number of entries
    NFAPI_CRC_INDICATION_PDU_T *entries = allocate_and_initialize_entries(N);
    if (entries == NULL) {
        printf("Failed to allocate and initialize entries\n");
    } else {
        // Use the allocated entries
        free_entries(entries);
    }

    return 0;
}
