typedef struct {
    char ip_address[16];
    int port;
    int connection_status;
    time_t connection_timestamp;
} TCP_CONNECTION_RECORD_T;

typedef struct {
    TCP_CONNECTION_RECORD_T *records;
    size_t capacity;
    size_t count;
} TCP_CONNECTION_LIST_T;

void initialize_tcp_connection_list(TCP_CONNECTION_LIST_T *list, size_t initial_capacity) {
    list->records = malloc(initial_capacity * sizeof(TCP_CONNECTION_RECORD_T));
    list->capacity = initial_capacity;
    list->count = 0;
}

void destroy_tcp_connection_list(TCP_CONNECTION_LIST_T *list) {
    free(list->records);
}

int add_tcp_connection(TCP_CONNECTION_LIST_T *list, const char *ip_address, int port, int connection_status) {
    if (list->count == list->capacity) {
        size_t new_capacity = list->capacity * 2;
        TCP_CONNECTION_RECORD_T *new_records = realloc(list->records, new_capacity * sizeof(TCP_CONNECTION_RECORD_T));
        if (!new_records) return -1; // Memory allocation failed
        list->records = new_records;
        list->capacity = new_capacity;
    }

    for (size_t i = 0; i < list->count; ++i) {
        if (strcmp(list->records[i].ip_address, ip_address) == 0 && list->records[i].port == port) {
            return -1; // Duplicate IP and PORT
        }
    }

    strcpy(list->records[list->count].ip_address, ip_address);
    list->records[list->count].port = port;
    list->records[list->count].connection_status = connection_status;
    list->records[list->count].connection_timestamp = time(NULL);
    ++list->count;

    return 0;
}

int update_tcp_connection_status(TCP_CONNECTION_LIST_T *list, const char *ip_address, int port, int new_status) {
    for (size_t i = 0; i < list->count; ++i) {
        if (strcmp(list->records[i].ip_address, ip_address) == 0 && list->records[i].port == port) {
            list->records[i].connection_status = new_status;
            list->records[i].connection_timestamp = time(NULL);
            return 0;
        }
    }

    return -1; // Connection not found
}

void resize_tcp_connection_list(TCP_CONNECTION_LIST_T *list, size_t new_capacity) {
    TCP_CONNECTION_RECORD_T *new_records = realloc(list->records, new_capacity * sizeof(TCP_CONNECTION_RECORD_T));
    if (new_records) {
        list->records = new_records;
        list->capacity = new_capacity;
    }
}

