typedef struct DynamicList {
    NFAPI_L1_EVENT_PDU_T* data;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
} DynamicList;

DynamicList* dynamic_list_create(size_t initial_capacity) {
    DynamicList* list = (DynamicList*)malloc(sizeof(DynamicList));
    if (!list) return NULL;

    list->data = (NFAPI_L1_EVENT_PDU_T*)malloc(initial_capacity * sizeof(NFAPI_L1_EVENT_PDU_T));
    if (!list->data) {
        free(list);
        return NULL;
    }

    list->capacity = initial_capacity;
    list->size = 0;
    pthread_mutex_init(&list->mutex, NULL);
    pthread_cond_init(&list->cond, NULL);

    return list;
}

void dynamic_list_destroy(DynamicList* list) {
    pthread_mutex_lock(&list->mutex);
    free(list->data);
    pthread_mutex_unlock(&list->mutex);
    pthread_mutex_destroy(&list->mutex);
    pthread_cond_destroy(&list->cond);
    free(list);
}

int dynamic_list_add(DynamicList* list, NFAPI_L1_EVENT_PDU_T pdu) {
    pthread_mutex_lock(&list->mutex);

    if (list->size >= list->capacity) {
        size_t new_capacity = list->capacity * 2;
        NFAPI_L1_EVENT_PDU_T* new_data = (NFAPI_L1_EVENT_PDU_T*)realloc(list->data, new_capacity * sizeof(NFAPI_L1_EVENT_PDU_T));
        if (!new_data) {
            pthread_mutex_unlock(&list->mutex);
            return -1;
        }
        list->data = new_data;
        list->capacity = new_capacity;
    }

    list->data[list->size++] = pdu;
    pthread_cond_signal(&list->cond);

    pthread_mutex_unlock(&list->mutex);
    return 0;
}

int dynamic_list_remove(DynamicList* list, NFAPI_L1_EVENT_PDU_T* pdu) {
    pthread_mutex_lock(&list->mutex);

    for (size_t i = 0; i < list->size; ++i) {
        if (memcmp(&list->data[i], pdu, sizeof(NFAPI_L1_EVENT_PDU_T)) == 0) {
            for (size_t j = i + 1; j < list->size; ++j) {
                list->data[j - 1] = list->data[j];
            }
            --list->size;
            pthread_cond_signal(&list->cond);
            pthread_mutex_unlock(&list->mutex);
            return 0;
        }
    }

    pthread_mutex_unlock(&list->mutex);
    return -1;
}

void* message_queue_processor(void* arg) {
    DynamicList* list = (DynamicList*)arg;

    while (1) {
        NFAPI_L1_EVENT_PDU_T pdu;

        pthread_mutex_lock(&list->mutex);
        while (list->size == 0) {
            pthread_cond_wait(&list->cond, &list->mutex);
