int validate_username(const char *username) {
    if (strlen(username) < MIN_USERNAME_LENGTH || strlen(username) > MAX_USERNAME_LENGTH) return 0;
    if (isdigit(username[0])) return 0;
    for (int i = 0; username[i]; i++) {
        if (!isalnum(username[i]) && username[i] != '-' && username[i] != '_') return 0;
    }
    // Username is valid
    return 1;
}

int validate_email(const char *email) {
    // Regex validation for email
    // Simplified check for demonstration purposes
    if (strlen(email) > strlen(EMAIL_REGEX)) return 0;
    for (int i = 0; email[i]; i++) {
        if (!isalnum(email[i]) && email[i] != '.' && email[i] != '@' && email[i] != '-') return 0;
    }
    // Email is valid
    return 1;
}

int validate_phone(const char *phone) {
    // Regex validation for phone number
    // Simplified check for demonstration purposes
    if (strlen(phone) > strlen(PHONE_REGEX)) return 0;
    for (int i = 0; phone[i]; i++) {
        if (!isdigit(phone[i]) && phone[i] != '+' && phone[i] != '-' && phone[i] != ' ') return 0;
    }
