    if (!validate_username(profile->username)) return 0;
    if (!profile->dob || !profile->email || !profile->phone) return 0;
    if (strlen(profile->preferred_categories[0]) == 0) return 0;

    // Validate personal information fields
    if (!validate_email(profile->email) || !validate_phone(profile->phone)) return 0;

    // Further validation logic for preferences can be added here

    // All validations passed
    return 1;
}

