#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_CONNECTIONS 1000
#define SLIDING_WINDOW_SIZE 50
#define ROLLING_WINDOW_SIZE 10

typedef struct {
    int id;
    char source_ip[16];
    char destination_ip[16];
    int source_port;
    int destination_port;
    int syn_flag;
    int ack_flag;
    time_t timestamp;
} TCP_CONNECTION_RECORD_T;

TCP_CONNECTION_RECORD_T *connection_list[MAX_CONNECTIONS];
int connection_count = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

int generate_random_id() {
    return rand() % MAX_CONNECTIONS;
}

int is_valid_id(int id) {
    for (int i = 0; i < connection_count; i++) {
        if (connection_list[i]->id == id) {
            return 0;
        }
    }
    return 1;
}

void generate_flags(int *syn_flag, int *ack_flag) {
    *syn_flag = rand() % 2;
    *ack_flag = rand() % 2;
}

int is_valid_flag_combination(int syn_flag, int ack_flag, TCP_CONNECTION_RECORD_T **window) {
    for (int i = 0; i < ROLLING_WINDOW_SIZE; i++) {
        if (window[i]->syn_flag == syn_flag && window[i]->ack_flag == ack_flag) {
            return 0;
        }
    }
    return 1;
}

void add_connection(TCP_CONNECTION_RECORD_T *new_record) {
    pthread_mutex_lock(&lock);
    if (connection_count < MAX_CONNECTIONS) {
        connection_list[connection_count] = new_record;
        connection_count++;
    } else {
        // Handle error: max connections reached
    }
    pthread_mutex_unlock(&lock);
}

void *network_traffic_analysis(void *arg) {
    while (1) {
        // Fetch data from external sources and validate checksum
        TCP_CONNECTION_RECORD_T *new_record = malloc(sizeof(TCP_CONNECTION_RECORD_T));
        new_record->id = generate_random_id();
        while (!is_valid_id(new_record->id)) {
            new_record->id = generate_random_id();
        }
        time(&new_record->timestamp);

        // Generate flags and validate flag combination
        int syn_flag, ack_flag;
        generate_flags(&syn_flag, &ack_flag);
        TCP_CONNECTION_RECORD_T *rolling_window[ROLLING_WINDOW_SIZE];
        for (int i = 0; i < ROLLING_WINDOW_SIZE; i++) {
            rolling_window[i] = connection_list[(connection_count - 1 - i + MAX_CONNECTIONS) % MAX_CONNECTIONS];
        }
        while (!is_valid_flag_combination(syn_flag, ack_flag, rolling_window)) {
            generate_flags(&syn_flag, &ack_flag);
        }
        new_record->syn_flag = syn_flag;
        new_record->ack_flag = ack_flag;

        // Add connection to list
        add_connection(new_record);

        // Sleep for specified interval
        sleep(1);
    }
}

int main() {
    pthread_t thread_id;
    pthread_create(&thread_id, NULL, network_traffic_analysis, NULL);
    pthread_join(thread_id, NULL);
    return 0;
}
