#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_CONNECTIONS 1024
#define RESIZE_THRESHOLD 0.75

typedef struct {
    char ip_address[16];
    int port;
} TCP_CONNECTION_RECORD_T;

typedef struct {
    TCP_CONNECTION_RECORD_T *records;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} TCP_CONNECTION_LIST_T;

int hash(const char *ip_address, int port) {
    return (hash(ip_address) + port) % capacity;
}

TCP_CONNECTION_LIST_T* tcp_connection_list_init(size_t initial_capacity) {
    TCP_CONNECTION_LIST_T *list = malloc(sizeof(TCP_CONNECTION_LIST_T));
    list->records = calloc(initial_capacity, sizeof(TCP_CONNECTION_RECORD_T));
    list->capacity = initial_capacity;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void tcp_connection_list_resize(TCP_CONNECTION_LIST_T *list) {
    size_t new_capacity = list->capacity * 2;
    TCP_CONNECTION_RECORD_T *new_records = calloc(new_capacity, sizeof(TCP_CONNECTION_RECORD_T));
    for (size_t i = 0; i < list->size; ++i) {
        // Rehash and insert into the new array
    }
    free(list->records);
    list->records = new_records;
    list->capacity = new_capacity;
}

int tcp_connection_list_add(TCP_CONNECTION_LIST_T *list, const char *ip_address, int port) {
    pthread_mutex_lock(&list->lock);
    if (list->size >= list->capacity * RESIZE_THRESHOLD) {
        tcp_connection_list_resize(list);
    }
    size_t index = hash(ip_address, port);
    while (strcmp(list->records[index].ip_address, ip_address) == 0 && list->records[index].port == port) {
        index = (index + 1) % list->capacity;
    }
    strcpy(list->records[index].ip_address, ip_address);
    list->records[index].port = port;
    ++list->size;
    pthread_mutex_unlock(&list->lock);
    return 0;
}

void tcp_connection_list_destroy(TCP_CONNECTION_LIST_T *list) {
    free(list->records);
    pthread_mutex_destroy(&list->lock);
    free(list);
}
```

