NFAPI_CRC_INDICATION_PDU_T structures[MAX_STRUCTURES];
int structure_count = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
NFAPI_CRC_INDICATION_PDU_T log[MAX_LOG_SIZE];
int log_index = 0;

void add_to_log(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pthread_mutex_lock(&lock);
    if (log_index >= MAX_LOG_SIZE) {
        log_index = 0; // Roll over the log
    }
    memcpy(&log[log_index], pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    log_index++;
    pthread_mutex_unlock(&lock);
}

NFAPI_CRC_INDICATION_PDU_T* create_and_populate_pdu_list(int N) {
    if (structure_count + N > MAX_STRUCTURES) {
        // Resize the array dynamically
        structures = realloc(structures, (structure_count + N) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    }

    pthread_mutex_lock(&lock);
    for (int i = 0; i < N; i++) {
        structures[structure_count].rnti = rand() % 1024; // Assuming RNTI is a 10-bit value
        while (i > 0 && structures[structure_count].rnti == structures[structure_count - 1].rnti) {
            structures[structure_count].rnti = rand() % 1024;
        }
        structures[structure_count].crcFlag = rand() % 2; // Randomly set CRCFLAG
        structures[structure_count].timestamp = time(NULL);
        add_to_log(&structures[structure_count]);
        structure_count++;
    }
    pthread_mutex_unlock(&lock);

    return structures;
}
