#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_PACKETS 1024

typedef enum {
    TCP,
    UDP,
    ICMP,
    DHCP
} PacketType;

typedef struct {
    PacketType type;
    int urgency_level;
    // Other packet data members
} NetworkPacket;

typedef struct {
    NetworkPacket *buffer[MAX_PACKETS];
    int head, tail, size;
    pthread_mutex_t mutex;
    pthread_cond_t not_full, not_empty;
} PacketQueue;

void init_packet_queue(PacketQueue *queue) {
    queue->head = queue->tail = 0;
    queue->size = 0;
    pthread_mutex_init(&queue->mutex, NULL);
    pthread_cond_init(&queue->not_full, NULL);
    pthread_cond_init(&queue->not_empty, NULL);
}

void enqueue_packet(PacketQueue *queue, NetworkPacket *packet) {
    pthread_mutex_lock(&queue->mutex);
    while (queue->size == MAX_PACKETS) {
        pthread_cond_wait(&queue->not_full, &queue->mutex);
    }
    queue->buffer[queue->tail] = packet;
    queue->tail = (queue->tail + 1) % MAX_PACKETS;
    queue->size++;
    if (queue->size == 1) {
        pthread_cond_signal(&queue->not_empty);
    }
    pthread_mutex_unlock(&queue->mutex);
}

NetworkPacket* dequeue_packet(PacketQueue *queue) {
    NetworkPacket *packet = NULL;
    pthread_mutex_lock(&queue->mutex);
    while (queue->size == 0) {
        pthread_cond_wait(&queue->not_empty, &queue->mutex);
    }
    packet = queue->buffer[queue->head];
    queue->head = (queue->head + 1) % MAX_PACKETS;
    queue->size--;
    if (queue->size == MAX_PACKETS - 1) {
        pthread_cond_signal(&queue->not_full);
    }
    pthread_mutex_unlock(&queue->mutex);
    return packet;
}

void process_packet(NetworkPacket *packet) {
    // Placeholder for packet processing logic
    printf("Processing packet of type %d with urgency level %d\n", packet->type, packet->urgency_level);
}

void* packet_processor(void *arg) {
    PacketQueue *queue = (PacketQueue *)arg;
    while (1) {
        NetworkPacket *packet = dequeue_packet(queue);
        process_packet(packet);
        // Free the packet or re-enqueue it based on processing result
    }
    return NULL;
}

int main() {
    PacketQueue queue;
    init_packet_queue(&queue);

    pthread_t processor_thread;
    pthread_create(&processor_thread, NULL, packet_processor, &queue);

    // Simulate adding packets to the queue
    for (int i = 0; i < MAX_PACKETS; i++) {
        NetworkPacket *packet = (NetworkPacket *)malloc(sizeof(NetworkPacket));
        packet->type = i % 4;
        packet->urgency_level = rand() % 3;
        enqueue_packet(&queue, packet);
    }

    pthread_join(processor_thread, NULL);

    return 0;
}
