        entries[current_entry].CRC_INDICATION_REL8_TAG = rand() % 100 + 1;
        entries[current_entry].CRCFLAG = rand() % 2; // Randomly set to 0 or 1
        current_entry++;
    }
    pthread_mutex_unlock(&mutex);
    return NULL;
