void validate_entries() {
    for (int i = 1; i < MAX_ENTRIES; i++) {
        if (entries[i].RX_UE_INFORMATION_TAG != entries[i - 1].RX_UE_INFORMATION_TAG) {
            printf("Inconsistency found between entry %d and %d\n", i, i - 1);
        }
    }
