} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_L1_EVENT_PDU_T *l1_events[MAX_PDUS];
    NFAPI_CRC_INDICATION_PDU_T *crc_indications[MAX_PDUS];
    int size;
