    if (manager->size < MAX_PDUS) {
        manager->l1_events[manager->size++] = event;
        printf("L1 Event added: phy_tag=%d, tx_power_level=%d, rf_state_tag=%d\n",
               event->phy_event_tag, event->tx_power_level, event->rf_state_change_indication_tag);
    } else {
        printf("Error: PDU manager list is full\n");
    }
    pthread_mutex_unlock(&manager->mutex);
}

void add_crc_indication(PduManager *manager, NFAPI_CRC_INDICATION_PDU_T *crc) {
    pthread_mutex_lock(&manager->mutex);
    if (manager->size < MAX_PDUS) {
        manager->crc_indications[manager->size++] = crc;
        printf("CRC Indication added: rx_tag=%d, rnti=%d, crc_flag=%d\n",
               crc->rx_ue_information_tag, crc->rnti, crc->crc_indication_rel8_tag);
    } else {
        printf("Error: PDU manager list is full\n");
    }
    pthread_mutex_unlock(&manager->mutex);
}

void process_pdus(PduManager *manager) {
    for (int i = 0; i < manager->size; ++i) {
        // Simulate processing
        printf("Processing L1 Event: phy_tag=%d, tx_power_level=%d, rf_state_tag=%d\n",
               manager->l1_events[i]->phy_event_tag,
               manager->l1_events[i]->tx_power_level,
               manager->l1_events[i]->rf_state_change_indication_tag);
        printf("Processing CRC Indication: rx_tag=%d, rnti=%d, crc_flag=%d\n",
