#define MAX_ENTRIES 10000

typedef struct {
    uint32_t rx_ue_information_tag;
    uint16_t rnti;
    bool crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T *nfa_pi_pdu_list = NULL;
pthread_mutex_t nfa_pi_mutex = PTHREAD_MUTEX_INITIALIZER;
int current_entries = 0;

void initialize_nfa_pi() {
    nfa_pi_pdu_list = (NFAPI_CRC_INDICATION_PDU_T *)malloc(MAX_ENTRIES * sizeof(NFAPI_CRC_INDICATION_PDU_T));
}

void cleanup_nfa_pi() {
    pthread_mutex_lock(&nfa_pi_mutex);
    free(nfa_pi_pdu_list);
    nfa_pi_pdu_list = NULL;
    current_entries = 0;
    pthread_mutex_unlock(&nfa_pi_mutex);
}

int add_entry(uint32_t rx_tag, uint16_t rnti) {
    pthread_mutex_lock(&nfa_pi_mutex);
    if (current_entries >= MAX_ENTRIES) {
        pthread_mutex_unlock(&nfa_pi_mutex);
        return -1; // List is full
    }

    NFAPI_CRC_INDICATION_PDU_T *entry = &nfa_pi_pdu_list[current_entries];
    entry->rx_ue_information_tag = rx_tag;
    entry->rnti = rnti;
    entry->crc_indication_rel8_tag = rand() % 2; // Randomly set CRC flag

    current_entries++;
    pthread_mutex_unlock(&nfa_pi_mutex);

    return 0;
}

int remove_entry(uint32_t rx_tag) {
    pthread_mutex_lock(&nfa_pi_mutex);
    for (int i = 0; i < current_entries; i++) {
        if (nfa_pi_pdu_list[i].rx_ue_information_tag == rx_tag) {
            // Shift elements to fill the gap
            for (int j = i; j < current_entries - 1; j++) {
                nfa_pi_pdu_list[j] = nfa_pi_pdu_list[j + 1];
            }
            current_entries--;
            pthread_mutex_unlock(&nfa_pi_mutex);
            return 0;
        }
    }
    pthread_mutex_unlock(&nfa_pi_mutex);
    return -1; // Entry not found
}

void *data_source_thread(void *arg) {
    while (1) {
        // Simulate fetching data from external source
        uint32_t rx_tag = rand() % 1000;
        uint16_t rnti = rand() % 1024;

        if (add_entry(rx_tag, rnti) == -1) {
            printf("Failed to add entry\n");
        }

        // Simulate varying intervals
        sleep(rand() % 5);
    }
}

int main() {
    initialize_nfa_pi();

    pthread_t data_source_tid;
    pthread_create(&data_source_tid, NULL, data_source_thread, NULL);

    pthread_join(data_source_tid, NULL);

    cleanup_nfa_pi();
    return 0;
}
