// Define the user profile structure
typedef struct {
    char name[100];
    char email[100];
    char phone_number[20];
    // Add other preferences and last login date fields here
} UserProfile;

// Define a linked list node for storing user profiles
typedef struct ProfileNode {
    UserProfile profile;
    struct ProfileNode* next;
} ProfileNode;

// Define the distributed database structure
typedef struct DistributedDB {
    pthread_mutex_t lock;
    ProfileNode* head;
    // Add caching structures and replication mechanisms here
} DistributedDB;

// Function to insert a new user profile into the database
void insert_profile(DistributedDB* db, UserProfile* new_profile) {
    pthread_mutex_lock(&db->lock);
    ProfileNode* new_node = (ProfileNode*)malloc(sizeof(ProfileNode));
    memcpy(&new_node->profile, new_profile, sizeof(UserProfile));
    new_node->next = db->head;
    db->head = new_node;
    pthread_mutex_unlock(&db->lock);
}

// Function to delete a user profile from the database
void delete_profile(DistributedDB* db, char* email) {
    pthread_mutex_lock(&db->lock);
    ProfileNode* current = db->head;
    ProfileNode* previous = NULL;
    while (current != NULL && strcmp(current->profile.email, email) != 0) {
        previous = current;
        current = current->next;
    }
    if (current != NULL) {
        if (previous == NULL) {
            db->head = current->next;
        } else {
            previous->next = current->next;
        }
        free(current);
    }
    pthread_mutex_unlock(&db->lock);
}

// Function to retrieve a user profile from the database
UserProfile* get_profile(DistributedDB* db, char* email) {
    pthread_mutex_lock(&db->lock);
    ProfileNode* current = db->head;
    while (current != NULL && strcmp(current->profile.email, email) != 0) {
        current = current->next;
    }
    if (current != NULL) {
        UserProfile* profile_copy = (UserProfile*)malloc(sizeof(UserProfile));
        memcpy(profile_copy, &current->profile, sizeof(UserProfile));
        pthread_mutex_unlock(&db->lock);
        return profile_copy;
    } else {
        pthread_mutex_unlock(&db->lock);
        return NULL;
    }
}

// Function to update a user profile in the database
void update_profile(DistributedDB* db, UserProfile* updated_profile) {
    pthread_mutex_lock(&db->lock);
    ProfileNode* current = db->head;
    while (current != NULL && strcmp(current->profile.email, updated_profile->email) != 0) {
        current = current->next;
    }
    if (current != NULL) {
        memcpy(&current->profile, updated_profile, sizeof(UserProfile));
    }
    pthread_mutex_unlock(&db->lock);
}

// Function to list all user profiles in the database
void list_profiles(DistributedDB* db) {
    pthread_mutex_lock(&db->lock);
    ProfileNode* current = db->head;
    while (current != NULL) {
        printf("Name: %s, Email: %s, Phone Number: %s\n", current->profile.name, current->profile.email, current->profile.phone_number);
        current = current->next;
    }
    pthread_mutex_unlock(&db->lock);
}

// Command-line interface for managing profiles
void cli(DistributedDB* db) {
    char command[10];
    while (1) {
        printf("Enter a command: ");
        scanf("%s", command);
        if (strcmp(command, "add") == 0) {
            UserProfile new_profile;
            // Prompt user to enter profile details
            insert_profile(db, &new_profile);
        } else if (strcmp(command, "delete") == 0) {
            char email[100];
            // Prompt user to enter email address
            delete_profile(db, email);
        } else if (strcmp(command, "update") == 0) {
            UserProfile updated_profile;
            // Prompt user to enter profile details
            update_profile(db, &updated_profile);
        } else if (strcmp(command, "list") == 0) {
            list_profiles(db);
        } else if (strcmp(command, "exit") == 0) {
            break;
        } else {
            printf("Invalid command. Try again.\n");
        }
    }
}

int main() {
    DistributedDB db;
    pthread_mutex_init(&db.lock, NULL);
    db.head = NULL;

    cli(&db);

    pthread_mutex_destroy(&db.lock);
    return 0;
}
