#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_KEY_LENGTH 128
#define MAX_VALUE_LENGTH 256
#define CONFIG_FILE "network_service.conf"

void display_usage() {
    printf("Usage: network_service_config --help | --list | --add <key> <value> | --remove <key>\n");
}

int parse_arguments(int argc, char *argv[], char **action, char **key, char **value) {
    if (argc == 2 && strcmp(argv[1], "--help") == 0) {
        *action = "help";
    } else if (argc == 2 && strcmp(argv[1], "--list") == 0) {
        *action = "list";
    } else if (argc == 4 && strcmp(argv[1], "--add") == 0) {
        *action = "add";
        *key = argv[2];
        *value = argv[3];
    } else if (argc == 3 && strcmp(argv[1], "--remove") == 0) {
        *action = "remove";
        *key = argv[2];
    } else {
        return -1;
    }
    return 0;
}

void list_configurations() {
    FILE *file = fopen(CONFIG_FILE, "r");
    if (file == NULL) {
        perror("Failed to open configuration file for reading");
        return;
    }

    char key[MAX_KEY_LENGTH];
    char value[MAX_VALUE_LENGTH];
    while (fscanf(file, "%127[^=]=%255[^\n]\n", key, value) != EOF) {
        printf("%s=%s\n", key, value);
    }

    fclose(file);
}

void add_configuration(const char *key, const char *value) {
    FILE *file = fopen(CONFIG_FILE, "a");
    if (file == NULL) {
        perror("Failed to open configuration file for appending");
        return;
    }

    fprintf(file, "%s=%s\n", key, value);
    fclose(file);
}

void remove_configuration(const char *key) {
    FILE *old_file = fopen(CONFIG_FILE, "r");
    if (old_file == NULL) {
        perror("Failed to open configuration file for reading");
        return;
    }

    FILE *new_file = fopen("temp_config.conf", "w");
    if (new_file == NULL) {
        perror("Failed to create temporary file");
        fclose(old_file);
        return;
    }

    char line[512];
    char key_to_remove[MAX_KEY_LENGTH];
    strcpy(key_to_remove, key);

    while (fgets(line, sizeof(line), old_file)) {
        if (!strstr(line, key_to_remove)) {
            fputs(line, new_file);
        }
    }

    fclose(old_file);
    fclose(new_file);

    if (remove(CONFIG_FILE) != 0 || rename("temp_config.conf", CONFIG_FILE) != 0) {
        perror("Failed to replace configuration file");
    }
}

int main(int argc, char *argv[]) {
    char *action = NULL;
    char *key = NULL;
    char *value = NULL;

    if (parse_arguments(argc, argv, &action, &key, &value) != 0) {
        display_usage();
        return 1;
    }

    if (strcmp(action, "help") == 0) {
        display_usage();
    } else if (strcmp(action, "list") == 0) {
        list_configurations();
    } else if (strcmp(action, "add") == 0) {
        add_configuration(key, value);
    } else if (strcmp(action, "remove") == 0) {
        remove_configuration(key);
    }

    return 0;
}
