use tokio::net::TcpStream;
use reqwest::Client;
use std::collections::VecDeque;
use rand::{thread_rng, Rng};
use std::time::{Duration, Instant};

#[derive(Debug)]
struct NFAPI_CRC_INDICATION_PDU_T {
    rx_ue_information_tag: String,
    rnti: u16,
    crc_indication_rel8_tag: bool,
}

async fn fetch_ue_info(client: &Client) -> Result<String, reqwest::Error> {
    // Simulate fetching UE information
    client.get("https://api.example.com/ueinfo").send().await?.text().await
}

async fn generate_pdu() -> NFAPI_CRC_INDICATION_PDU_T {
    let ue_info = fetch_ue_info(&Client::new()).await.unwrap();
    let rnti: u16 = thread_rng().gen_range(0..=4095);
    NFAPI_CRC_INDICATION_PDU_T {
        rx_ue_information_tag: ue_info,
        rnti,
        crc_indication_rel8_tag: thread_rng().gen(),
    }
}

async fn handle_pdu(pdu: NFAPI_CRC_INDICATION_PDU_T) {
    // Simulate handling the PDU
    println!("Handling PDU with RNTI: {}", pdu.rnti);
}

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    let args: Vec<String> = std::env::args().collect();
    if args.len() < 2 {
        eprintln!("Usage: {} <N>", args[0]);
        return Ok(());
    }

    let n: u32 = args[1].parse()?;
    let mut queue: VecDeque<NFAPI_CRC_INDICATION_PDU_T> = VecDeque::new();
    let client = Client::new();

    let start_time = Instant::now();
    let mut retry_count = 0;
    let mut backoff = Duration::from_millis(1);

    while (Instant::now() - start_time).as_secs_f64() * n as f64 < 10_000 {
        if queue.len() < n as usize {
            let pdu = generate_pdu().await;
            queue.push_back(pdu);
        }

        if !queue.is_empty() {
            if let Some(pdu) = queue.pop_front() {
                tokio::spawn(async move {
                    handle_pdu(pdu).await;
                });
            }
        }

        if queue.len() == 0 && retry_count < 5 {
            tokio::time::sleep(backoff).await;
            retry_count += 1;
            backoff *= 2;
        } else {
            retry_count = 0;
            backoff = Duration::from_millis(1);
        }

        tokio::time::sleep(Duration::from_millis(1)).await;
    }

    Ok(())
}
