use tokio::task;
use reqwest::Client;
use std::{collections::HashMap, sync::Mutex};
use rand::{thread_rng, Rng};
use serde_json::json;

#[derive(Debug)]
struct NFAPI_CRC_INDICATION_PDU_T {
    rx_ue_information_tag: String,
    rnti: u16,
    crc_indication_rel8_tag: String,
    crcflag: bool,
    timestamp: f64,
}

async fn fetch_ue_info(api_url: &str) -> Result<String, reqwest::Error> {
    Client::new().get(api_url).send().await?.text().await
}

async fn generate_structures(api_url: &str, threshold: usize) -> Vec<NFAPI_CRC_INDICATION_PDU_T> {
    let mut structures = Vec::new();
    let mut rng = thread_rng();
    let client = Client::new();

    loop {
        if structures.len() >= threshold {
            break;
        }

        let ue_info = fetch_ue_info(api_url).await.unwrap();
        let rnti: u16 = rng.gen_range(0..65535);
        let crcflag = rng.gen_bool(0.5);

        let new_struct = NFAPI_CRC_INDICATION_PDU_T {
            rx_ue_information_tag: "UE_INFO".to_string(),
            rnti,
            crc_indication_rel8_tag: "CRC_REL8".to_string(),
            crcflag,
            timestamp: chrono::Utc::now().timestamp_millis() as f64,
        };

        structures.push(new_struct);
    }

    structures
}

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    let args: Vec<String> = std::env::args().collect();
    if args.len() < 2 {
        eprintln!("Usage: {} <api_url>", args[0]);
        return Ok(());
    }

    let api_url = &args[1];
    let threshold = 10_000;

    let structures = generate_structures(api_url, threshold).await?;
    println!("{:?}", structures);

    Ok(())
}
