#define MAX_LIST_SIZE 5000
#define MAX_MEMORY_USAGE 2 * 1024 * 1024 // 2 MB

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG ue_info;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_tag;
    int crc_flag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct LinkedList {
    Node* head;
    size_t size;
    pthread_mutex_t mutex;
} LinkedList;

LinkedList* create_list() {
    LinkedList* list = (LinkedList*)malloc(sizeof(LinkedList));
    if (!list) return NULL;
    list->head = NULL;
    list->size = 0;
    pthread_mutex_init(&list->mutex, NULL);
    return list;
}

void destroy_list(LinkedList* list) {
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->mutex);
    free(list);
}

Node* create_node(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* node = (Node*)malloc(sizeof(Node));
    if (!node) return NULL;
    node->data = data;
    node->next = NULL;
    return node;
}

int insert_node(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&list->mutex);
    if (list->size >= MAX_LIST_SIZE || list->size > 10000) {
        pthread_mutex_unlock(&list->mutex);
        return -1; // List overflow
    }
    Node* new_node = create_node(data);
    if (!new_node) {
        pthread_mutex_unlock(&list->mutex);
        return -2; // Memory allocation failed
    }
    if (list->head == NULL) {
        list->head = new_node;
    } else {
        Node* current = list->head;
        while (current->next) {
            current = current->next;
        }
        current->next = new_node;
    }
    list->size++;
    pthread_mutex_unlock(&list->mutex);
    return 0;
}

void prune_list(LinkedList* list) {
    pthread_mutex_lock(&list->mutex);
    if (list->size <= MAX_LIST_SIZE) {
        pthread_mutex_unlock(&list->mutex);
        return;
    }
    Node* current = list->head;
    size_t count = 1;
    while (current && count < list->size - MAX_LIST_SIZE + 1) {
        Node* next = current->next;
        free(current);
        current = next;
        count++;
    }
    list->head = current;
    list->size -= count;
    pthread_mutex_unlock(&list->mutex);
}

// Additional functions for database persistence, caching, logging, and inter-process communication would go here

int main() {
    srand(time(NULL));
    LinkedList* list = create_list();
    if (!list) return -1;

    // Example usage
    NFAPI_CRC_INDICATION_PDU_T data;
    // Populate data with valid values
    for (size_t i = 0; i < MAX_LIST_SIZE * 2; i++) {
        insert_node(list, data);
    }

    prune_list(list);

    destroy_list(list);
    return 0;
}
