typedef struct TFT {
    int id;
    // Other TFT fields
    struct TFT *next;
} TFT;

typedef struct NetworkEntityManagement {
    char ueIdentity[100];
    void *sessionContext; // Placeholder for session context
    TFT *tftList;
    pthread_mutex_t mutex;
} NetworkEntityManagement;

NetworkEntityManagement* createNEM(const char *ueIdentity, void *sessionContext) {
    NetworkEntityManagement *nem = (NetworkEntityManagement *)malloc(sizeof(NetworkEntityManagement));
    if (!nem) return NULL;

    nem->tftList = NULL;
    pthread_mutex_init(&nem->mutex, NULL);

    snprintf(nem->ueIdentity, sizeof(nem->ueIdentity), "%s", ueIdentity);
    nem->sessionContext = sessionContext;

    return nem;
}

void destroyNEM(NetworkEntityManagement *nem) {
    TFT *tft, *temp;
    pthread_mutex_lock(&nem->mutex);
    for (tft = nem->tftList; tft != NULL; ) {
        temp = tft;
        tft = tft->next;
        free(temp);
    }
    pthread_mutex_unlock(&nem->mutex);
    pthread_mutex_destroy(&nem->mutex);
    free(nem);
}

int addTFT(NetworkEntityManagement *nem, int tftId) {
    TFT *newTFT = (TFT *)malloc(sizeof(TFT));
    if (!newTFT) return -1;

    newTFT->id = tftId;
    newTFT->next = NULL;

    pthread_mutex_lock(&nem->mutex);
    newTFT->next = nem->tftList;
    nem->tftList = newTFT;
    pthread_mutex_unlock(&nem->mutex);

    return 0;
}

void removeTFT(NetworkEntityManagement *nem, int tftId) {
    TFT *tft, *prev;
    pthread_mutex_lock(&nem->mutex);
    for (tft = nem->tftList, prev = NULL; tft != NULL; prev = tft, tft = tft->next) {
        if (tft->id == tftId) {
            if (prev) prev->next = tft->next;
            else nem->tftList = tft->next;
            free(tft);
            break;
        }
    }
    pthread_mutex_unlock(&nem->mutex);
}
