// Initialize NEM entity
NemEntity* initializeNemEntity(char* ueIdentity, void* sessionContext) {
    NemEntity* nem = (NemEntity*)malloc(sizeof(NemEntity));
    if (nem == NULL) {
        return NULL; // Handle memory allocation failure
    }
    nem->ueIdentity = strdup(ueIdentity);
    nem->sessionContext = sessionContext;
    nem->tftListHead = NULL;
    pthread_mutex_init(&nem->mutex, NULL);
    return nem;
}

// Add TFT to NEM entity
void addTftToNemEntity(NemEntity* nem, int tftId) {
    pthread_mutex_lock(&nem->mutex);
    TrafficFlowTemplate* newTft = (TrafficFlowTemplate*)malloc(sizeof(TrafficFlowTemplate));
    if (newTft == NULL) {
        pthread_mutex_unlock(&nem->mutex);
        return; // Handle memory allocation failure
    }
    newTft->tftId = tftId;
    newTft->next = nem->tftListHead;
    nem->tftListHead = newTft;
    pthread_mutex_unlock(&nem->mutex);
}

// Remove TFT from NEM entity
void removeTftFromNemEntity(NemEntity* nem, int tftId) {
    pthread_mutex_lock(&nem->mutex);
    TrafficFlowTemplate* current = nem->tftListHead;
    TrafficFlowTemplate* prev = NULL;

    while (current != NULL) {
        if (current->tftId == tftId) {
            if (prev == NULL) {
                nem->tftListHead = current->next;
            } else {
                prev->next = current->next;
            }
            free(current);
            break;
        }
        prev = current;
        current = current->next;
    }
    pthread_mutex_unlock(&nem->mutex);
}

// Free NEM entity resources
void freeNemEntity(NemEntity* nem) {
    TrafficFlowTemplate* currentTft = nem->tftListHead;
    while (currentTft != NULL) {
        TrafficFlowTemplate* nextTft = currentTft->next;
        free(currentTft);
        currentTft = nextTft;
    }
    pthread_mutex_destroy(&nem->mutex);
    free(nem);
}
