#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>

#define MAX_ENTRIES 10000
#define MIN_N 1
#define MAX_N 50

typedef struct {
    RX_UE_INFORMATION_TAG ue_info;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_ind;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *entries;
    size_t allocated_size;
    size_t used_size;
    pthread_mutex_t lock;
} MemoryPool;

void init_memory_pool(MemoryPool *pool, size_t initial_size) {
    pool->entries = (NFAPI_CRC_INDICATION_PDU_T *)malloc(initial_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pool->entries) {
        perror("Failed to allocate memory for memory pool");
        exit(EXIT_FAILURE);
    }
    pool->allocated_size = initial_size;
    pool->used_size = 0;
    pthread_mutex_init(&pool->lock, NULL);
}

NFAPI_CRC_INDICATION_PDU_T *allocate_entry(MemoryPool *pool) {
    NFAPI_CRC_INDICATION_PDU_T *entry = NULL;
    pthread_mutex_lock(&pool->lock);
    if (pool->used_size < pool->allocated_size) {
        entry = &pool->entries[pool->used_size++];
    } else {
        size_t new_size = pool->allocated_size * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_entries = (NFAPI_CRC_INDICATION_PDU_T *)realloc(pool->entries, new_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_entries) {
            perror("Failed to reallocate memory for memory pool");
            exit(EXIT_FAILURE);
        }
        pool->entries = new_entries;
        pool->allocated_size = new_size;
        entry = &pool->entries[pool->used_size++];
    }
    pthread_mutex_unlock(&pool->lock);
    return entry;
}

void free_memory_pool(MemoryPool *pool) {
    pthread_mutex_lock(&pool->lock);
    free(pool->entries);
    pool->entries = NULL;
    pool->allocated_size = 0;
    pool->used_size = 0;
    pthread_mutex_unlock(&pool->lock);
    pthread_mutex_destroy(&pool->lock);
}

NFAPI_CRC_INDICATION_PDU_T *create_entries(size_t N) {
    if (N < MIN_N || N > MAX_N) {
        fprintf(stderr, "Invalid number of entries. Must be between %zu and %zu\n", MIN_N, MAX_N);
        return NULL;
    }

    MemoryPool pool;
    init_memory_pool(&pool, 10); // Initial allocation size

    for (size_t i = 0; i < N; ++i) {
        NFAPI_CRC_INDICATION_PDU_T *entry = allocate_entry(&pool);
        if (!entry) {
            fprintf(stderr, "Failed to allocate entry %zu\n", i);
            free_memory_pool(&pool);
            return NULL;
        }

        // Initialize entries here
        memset(entry, 0, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    }

    return pool.entries;
}

// Example usage:
int main() {
    size_t N = 15; // User input
    NFAPI_CRC_INDICATION_PDU_T *entries = create_entries(N);
    if (entries) {
        printf("Successfully allocated %zu entries\n", N);
        free_memory_pool(&pool); // Free memory when done
    }
    return 0;
}
```

