import io.netty.channel.ChannelHandlerContext;
import io.netty.channel.SimpleChannelInboundHandler;
import io.netty.handler.codec.http.DefaultFullHttpResponse;
import io.netty.handler.codec.http.FullHttpRequest;
import io.netty.handler.codec.http.FullHttpResponse;
import io.netty.handler.codec.http.HttpHeaders;
import io.netty.handler.codec.http.HttpMethod;
import io.netty.handler.codec.http.HttpResponseStatus;
import io.netty.handler.codec.http.HttpVersion;

import java.util.Random;

public class RequestRouter extends SimpleChannelInboundHandler<FullHttpRequest> {
    private final String[] serviceInstances;
    private final Random random = new Random();

    public RequestRouter(String[] serviceInstances) {
        this.serviceInstances = serviceInstances;
    }

    @Override
    protected void channelRead0(ChannelHandlerContext ctx, FullHttpRequest request) throws Exception {
        if (request.method() == HttpMethod.GET && "/cache".equals(request.uri())) {
            // Simulate caching response
            FullHttpResponse response = new DefaultFullHttpResponse(HttpVersion.HTTP_1_1, HttpResponseStatus.OK);
            HttpHeaders.setHeader(response, "Content-Type", "application/json");
            response.content().writeBytes("{\"message\":\"Cached Data\"}".getBytes());
            ctx.writeAndFlush(response);
        } else {
            // Route request to a random service instance
            String targetInstance = serviceInstances[random.nextInt(serviceInstances.length)];
            System.out.println("Routing to: " + targetInstance);
            // Logic to forward the request to the target service instance
            FullHttpResponse response = new DefaultFullHttpResponse(HttpVersion.HTTP_1_1, HttpResponseStatus.OK);
            HttpHeaders.setHeader(response, "Content-Type", "application/json");
            response.content().writeBytes("{\"message\":\"Response from " + targetInstance + "\"}".getBytes());
            ctx.writeAndFlush(response);
        }
    }

    @Override
    public void exceptionCaught(ChannelHandlerContext ctx, Throwable cause) throws Exception {
        cause.printStackTrace();
        ctx.close();
    }
}
