#define MAX_CONNECTIONS 1000
#define ROLLING_WINDOW_SIZE 10
#define SLIDING_WINDOW_SIZE 50

typedef struct TCP_CONNECTION_RECORD_T {
    int connection_id;
    char source_ip[16];
    char destination_ip[16];
    int source_port;
    int destination_port;
    int syn_flag;
    int ack_flag;
    time_t timestamp;
} TCP_CONNECTION_RECORD_T;

TCP_CONNECTION_RECORD_T connection_list[MAX_CONNECTIONS];
int current_index = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void generate_connection_record(TCP_CONNECTION_RECORD_T *record) {
    record->connection_id = rand() % MAX_CONNECTIONS;
    sprintf(record->source_ip, "%d.%d.%d.%d", rand() % 256, rand() % 256, rand() % 256, rand() % 256);
    sprintf(record->destination_ip, "%d.%d.%d.%d", rand() % 256, rand() % 256, rand() % 256, rand() % 256);
    record->source_port = rand() % 65535;
    record->destination_port = rand() % 65535;
    record->syn_flag = rand() % 2;
    record->ack_flag = rand() % 2;
    time(&record->timestamp);
}

int is_valid_record(TCP_CONNECTION_RECORD_T *record, TCP_CONNECTION_RECORD_T *last_records) {
    for (int i = 0; i < ROLLING_WINDOW_SIZE; i++) {
        if (record->connection_id == last_records[i].connection_id ||
            (record->syn_flag == last_records[i].syn_flag && record->ack_flag == last_records[i].ack_flag)) {
            return 0;
        }
    }
    return 1;
}

void add_connection_record(TCP_CONNECTION_RECORD_T *record) {
    pthread_mutex_lock(&lock);
    if (current_index >= MAX_CONNECTIONS) {
        current_index = 0; // Implement caching mechanism here
    }
    connection_list[current_index] = *record;
    current_index++;
    pthread_mutex_unlock(&lock);
}

void* manage_connection_list(void* arg) {
    TCP_CONNECTION_RECORD_T new_record;
    TCP_CONNECTION_RECORD_T last_records[ROLLING_WINDOW_SIZE] = {0};

    while (1) {
        generate_connection_record(&new_record);

        if (is_valid_record(&new_record, last_records)) {
            add_connection_record(&new_record);
        }

        memcpy(last_records, &connection_list[current_index - ROLLING_WINDOW_SIZE], sizeof(TCP_CONNECTION_RECORD_T) * ROLLING_WINDOW_SIZE);

        sleep(1); // Adjust interval as needed
    }

    return NULL;
}

int main() {
    pthread_t thread;

    if (pthread_create(&thread, NULL, manage_connection_list, NULL) != 0) {
        perror("Failed to create thread");
        exit(EXIT_FAILURE);
    }

    pthread_join(thread, NULL);

    return 0;
}
