#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_PACKETS 1000
#define DEFAULT_BUFFER_SIZE 4096

typedef struct {
    void* data;
    int size;
    int priority;
} Packet;

typedef struct {
    Packet* buffer;
    int capacity;
    int count;
    pthread_mutex_t lock;
    pthread_cond_t watermark_condition;
} BufferPool;

void initialize_buffer_pool(BufferPool* pool, int initial_size) {
    pool->buffer = (Packet*)malloc(initial_size * sizeof(Packet));
    if (pool->buffer == NULL) {
        fprintf(stderr, "Failed to allocate buffer pool\n");
        exit(1);
    }
    pool->capacity = initial_size;
    pool->count = 0;
    pthread_mutex_init(&pool->lock, NULL);
    pthread_cond_init(&pool->watermark_condition, NULL);
}

void resize_buffer_pool(BufferPool* pool) {
    int new_capacity = pool->capacity * 2;
    Packet* new_buffer = (Packet*)realloc(pool->buffer, new_capacity * sizeof(Packet));
    if (new_buffer == NULL) {
        fprintf(stderr, "Failed to reallocate buffer pool\n");
        exit(1);
    }
    pool->buffer = new_buffer;
    pool->capacity = new_capacity;
}

void enqueue_packet(BufferPool* pool, Packet packet, int priority) {
    pthread_mutex_lock(&pool->lock);
    while (pool->count >= pool->capacity) {
        pthread_cond_wait(&pool->watermark_condition, &pool->lock);
    }
    pool->buffer[pool->count++] = packet;
    pthread_mutex_unlock(&pool->lock);
    pthread_cond_signal(&pool->watermark_condition);
}

Packet dequeue_packet(BufferPool* pool) {
    Packet packet = {NULL, 0, 0};
    pthread_mutex_lock(&pool->lock);
    while (pool->count == 0) {
        pthread_cond_wait(&pool->watermark_condition, &pool->lock);
    }
    packet = pool->buffer[--pool->count];
    pthread_mutex_unlock(&pool->lock);
    pthread_cond_signal(&pool->watermark_condition);
    return packet;
}

void* packet_processor(void* arg) {
    BufferPool* pool = (BufferPool*)arg;
    Packet packet;
    clock_t start, end;
    double cpu_time_used;

    while (1) {
        packet = dequeue_packet(pool);
        if (packet.data == NULL && packet.size == 0 && packet.priority == 0) break; // Poison pill

        start = clock();
        // Process the packet
        end = clock();
        cpu_time_used = ((double)(end - start)) / CLOCKS_PER_SEC;

        printf("Processed packet in %f seconds\n", cpu_time_used);
    }

    return NULL;
}

int main() {
    BufferPool pool;
    pthread_t threads[MAX_PACKETS];
    int i;

    initialize_buffer_pool(&pool, 10);

    for (i = 0; i < MAX_PACKETS; i++) {
        pthread_create(&threads[i], NULL, packet_processor, &pool);
    }

    // Enqueue packets
    Packet test_packet = {NULL, 1024, 1};
    enqueue_packet(&pool, test_packet, 1);

    // Gracefully shutdown
    for (i = 0; i < MAX_PACKETS; i++) {
        Packet poison_pill = {NULL, 0, 0};
        enqueue_packet(&pool, poison_pill, 0);
        pthread_join(threads[i], NULL);
    }

    free(pool.buffer);
    pthread_mutex_destroy(&pool.lock);
    pthread_cond_destroy(&pool.watermark_condition);

    return 0;
}
