#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_ENTRIES 10000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T crc_pool[MAX_ENTRIES];
int pool_index = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void* populate_crc_array(void* arg) {
    int num_entries = *(int*)arg;

    for (int i = 0; i < num_entries; i++) {
        pthread_mutex_lock(&mutex);

        if (pool_index >= MAX_ENTRIES) {
            printf("Memory pool exhausted.\n");
            pthread_mutex_unlock(&mutex);
            break;
        }

        crc_pool[pool_index].RX_UE_INFORMATION_TAG = rand() % 1000;
        crc_pool[pool_index].RNTI = rand() % 256;
        crc_pool[pool_index].CRC_INDICATION_REL8_TAG = rand() % 2;

        pool_index++;

        pthread_mutex_unlock(&mutex);
    }

    return NULL;
}

int main() {
    srand(time(NULL));

    int num_entries = 100; // Example number of entries
    pthread_t thread_ids[num_entries];

    for (int i = 0; i < num_entries; i++) {
        if (pthread_create(&thread_ids[i], NULL, populate_crc_array, &num_entries) != 0) {
            printf("Failed to create thread %d\n", i);
            return 1;
        }
    }

    for (int i = 0; i < num_entries; i++) {
        pthread_join(thread_ids[i], NULL);
    }

    // Example validation logic
    for (int i = 1; i < pool_index; i++) {
        if (crc_pool[i].CRC_INDICATION_REL8_TAG != crc_pool[i - 1].CRC_INDICATION_REL8_TAG) {
            printf("Inconsistency found at entry %d\n", i);
        }
    }

    return 0;
}
