import configparser
import threading

def sort_and_extract_sequence_number(file_path):
    config = configparser.ConfigParser()
    try:
        config.read(file_path)
        lines = sorted(config.sections())
        last_line = lines[-1]
        sequence_number = int(last_line.split('_')[1])
        return sequence_number
    except Exception as e:
        print(f"Error processing file {file_path}: {e}")
        return None

def process_files_in_parallel(file_paths, max_threads=4):
    threads = []
    results = []

    for file_path in file_paths:
        thread = threading.Thread(target=sort_and_extract_sequence_number, args=(file_path,))
        threads.append(thread)
        thread.start()

    for thread in threads:
        thread.join()
        result = sort_and_extract_sequence_number(thread.name)
        if result is not None:
            results.append(result)

    return results
```

