    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* generate_crc_indications(int n, int *total_allocated, pthread_mutex_t *mutex) {
    NFAPI_CRC_INDICATION_PDU_T *head = NULL, *current = NULL;
    pthread_mutex_lock(mutex);

    for (int i = 0; i < n; i++) {
        NFAPI_CRC_INDICATION_PDU_T *new_node = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_node) {
            if (head != NULL) {
                free_list(head);
            }
            pthread_mutex_unlock(mutex);
            return NULL;
        }

        // Populate the new node with valid values
        new_node->tag = generate_rx_ue_information_tag();
        new_node->rnti = generate_rnti();
        new_node->crc_indication.crcflag = rand() % 2; // Randomly set CRCFLAG

        if (head == NULL) {
            head = new_node;
            current = new_node;
        } else {
            current->next = new_node;
            current = new_node;
        }
    }

    *total_allocated = n;
    pthread_mutex_unlock(mutex);
    return head;
}

void free_list(NFAPI_CRC_INDICATION_PDU_T *head) {
    NFAPI_CRC_INDICATION_PDU_T *current = head, *next;

    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }
}
