typedef struct ConfigEntry {
    char* key;
    char* value;
} ConfigEntry;

typedef struct NETWORK_CONNECTION_RECORD {
    int CONNECTION_ID;
    char SOURCE_IP[16];
    char DESTINATION_IP[16];
    int PORT;
    char STATUS[20];
} NETWORK_CONNECTION_RECORD;

typedef struct SERVICE_REQUEST_LOGS {
    char REQUEST_TIMESTAMP[20];
    char SERVICE_NAME[50];
    char ACTION[20];
    char STATUS[20];
    int ERROR_CODE;
} SERVICE_REQUEST_LOGS;

typedef struct CacheNode {
    ConfigEntry entry;
    struct CacheNode* next;
} CacheNode;

typedef struct {
    pthread_rwlock_t lock;
    CacheNode* head;
    size_t capacity;
    size_t size;
} ConfigCache;

ConfigCache* create_config_cache(size_t max_capacity) {
    ConfigCache* cache = (ConfigCache*)malloc(sizeof(ConfigCache));
    if (!cache) return NULL;

    pthread_rwlock_init(&cache->lock, NULL);
    cache->head = NULL;
    cache->capacity = max_capacity;
    cache->size = 0;

    return cache;
}

void destroy_config_cache(ConfigCache* cache) {
    CacheNode* current = cache->head;
    while (current) {
        CacheNode* next = current->next;
        free(current->entry.key);
        free(current->entry.value);
        free(current);
        current = next;
    }
    pthread_rwlock_destroy(&cache->lock);
    free(cache);
}

int insert_config_entry(ConfigCache* cache, const char* key, const char* value) {
    if (cache->size >= cache->capacity) return -1; // Cache full

    CacheNode* newNode = (CacheNode*)malloc(sizeof(CacheNode));
    if (!newNode) return -1;

    newNode->entry.key = strdup(key);
    newNode->entry.value = strdup(value);
    newNode->next = NULL;

    pthread_rwlock_wrlock(&cache->lock);
    newNode->next = cache->head;
    cache->head = newNode;
    cache->size++;
    pthread_rwlock_unlock(&cache->lock);

    return 0;
}

// Add more functions as needed for querying, updating, and exporting the cache

int main() {
    ConfigCache* cache = create_config_cache(1024);
    if (!cache) {
        fprintf(stderr, "Failed to create config cache\n");
        return 1;
    }

    // Example usage
    insert_config_entry(cache, "setting1", "value1");

    // Clean up
    destroy_config_cache(cache);

    return 0;
}
