#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_ENTRIES 10000
#define CONCURRENT_THREADS 5

typedef struct {
    RX_UE_INFORMATION_TAG ue_info;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_flag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pool;
    int size;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool pool;

void init_pool(int size) {
    if (size > MAX_ENTRIES) {
        fprintf(stderr, "Error: Pool size exceeds maximum limit.\n");
        exit(EXIT_FAILURE);
    }
    pool.pool = malloc(size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pool.size = size;
    pthread_mutex_init(&pool.lock, NULL);
}

NFAPI_CRC_INDICATION_PDU_T* allocate_entry() {
    NFAPI_CRC_INDICATION_PDU_T *entry = NULL;
    pthread_mutex_lock(&pool.lock);
    if (pool.size > 0) {
        entry = pool.pool + pool.size - 1;
        pool.size--;
    }
    pthread_mutex_unlock(&pool.lock);
    return entry;
}

void free_entry(NFAPI_CRC_INDICATION_PDU_T *entry) {
    pthread_mutex_lock(&pool.lock);
    if (entry >= pool.pool && entry < pool.pool + MAX_ENTRIES) {
        pool.size++;
    } else {
        fprintf(stderr, "Error: Attempted to free invalid memory.\n");
    }
    pthread_mutex_unlock(&pool.lock);
}

NFAPI_CRC_INDICATION_PDU_T* create_headers(int N, int num_headers, unsigned int seed) {
    if (N < 0) {
        fprintf(stderr, "Error: Negative value for N is not allowed.\n");
        return NULL;
    }

    init_pool(num_headers * N);
    srand(seed);

    for (int i = 0; i < N; i++) {
        NFAPI_CRC_INDICATION_PDU_T *entry = allocate_entry();
        if (!entry) {
            fprintf(stderr, "Error: Failed to allocate memory.\n");
            // Clean up allocated entries before exiting
            while (pool.pool + pool.size < pool.pool + MAX_ENTRIES) {
                free_entry(pool.pool + pool.size);
            }
            exit(EXIT_FAILURE);
        }
        // Initialize entry fields here
        entry->ue_info = ...;
        entry->rnti = ...;
        entry->crc_flag = rand() % 2; // Randomly set CRC flag
    }

    return pool.pool;
}

NFAPI_CRC_INDICATION_PDU_T* process_packet(const char *network_interface, size_t size_limit, FILE *log_fd) {
    if (size_limit <= 0) {
        fprintf(stderr, "Error: Invalid size limit.\n");
        return NULL;
    }

    // Process packet logic here
    NFAPI_CRC_INDICATION_PDU_T *new_packet = allocate_entry();
    if (!new_packet) {
        fprintf(stderr, "Error: Failed to allocate memory for new packet.\n");
        return NULL;
    }
    // Initialize new packet fields here

    // Log creation of new packet
    fprintf(log_fd, "New packet created with unique ID: %p\n", (void*)new_packet);

    return new_packet;
