#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_CONNECTIONS 100000
#define INITIAL_CAPACITY 1024

typedef struct TCP_CONNECTION_RECORD_T {
    char IP_ADDRESS[45];
    int PORT;
    // Add other necessary fields here
} TCP_CONNECTION_RECORD_T;

typedef struct ConnectionRecordNode {
    TCP_CONNECTION_RECORD_T record;
    struct ConnectionRecordNode* next;
} ConnectionRecordNode;

typedef struct ConnectionList {
    ConnectionRecordNode** buckets;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
} ConnectionList;

ConnectionList* createConnectionList() {
    ConnectionList* list = (ConnectionList*)malloc(sizeof(ConnectionList));
    if (!list) return NULL;

    list->capacity = INITIAL_CAPACITY;
    list->count = 0;
    list->buckets = (ConnectionRecordNode**)calloc(list->capacity, sizeof(ConnectionRecordNode*));
    if (!list->buckets) {
        free(list);
        return NULL;
    }

    pthread_mutex_init(&list->mutex, NULL);

    return list;
}

void destroyConnectionList(ConnectionList* list) {
    for (size_t i = 0; i < list->capacity; ++i) {
        ConnectionRecordNode* node = list->buckets[i];
        while (node) {
            ConnectionRecordNode* next = node->next;
            free(node);
            node = next;
        }
    }

    free(list->buckets);
    pthread_mutex_destroy(&list->mutex);
    free(list);
}

size_t hash(const char* IP_ADDRESS, int PORT, size_t capacity) {
    size_t hash = 0;
    for (size_t i = 0; IP_ADDRESS[i]; ++i) {
        hash = (hash * 31 + IP_ADDRESS[i]) % capacity;
    }
    hash = (hash * 31 + PORT) % capacity;

    return hash;
}

int contains(ConnectionList* list, const char* IP_ADDRESS, int PORT) {
    pthread_mutex_lock(&list->mutex);

    size_t index = hash(IP_ADDRESS, PORT, list->capacity);
    ConnectionRecordNode* node = list->buckets[index];

    while (node) {
        if (strcmp(node->record.IP_ADDRESS, IP_ADDRESS) == 0 && node->record.PORT == PORT) {
            pthread_mutex_unlock(&list->mutex);
            return 1;
        }
        node = node->next;
    }

    pthread_mutex_unlock(&list->mutex);
    return 0;
}

int addConnection(ConnectionList* list, const TCP_CONNECTION_RECORD_T* record) {
    pthread_mutex_lock(&list->mutex);

    if (list->count >= list->capacity * 3 / 4) {
        size_t new_capacity = list->capacity * 2;
        ConnectionRecordNode** new_buckets = (ConnectionRecordNode**)calloc(new_capacity, sizeof(ConnectionRecordNode*));
        if (!new_buckets) {
            pthread_mutex_unlock(&list->mutex);
            return -1;
        }

        for (size_t i = 0; i < list->capacity; ++i) {
            ConnectionRecordNode* node = list->buckets[i];
            while (node) {
                ConnectionRecordNode* next = node->next;

                size_t new_index = hash(node->record.IP_ADDRESS, node->record.PORT, new_capacity);
                node->next = new_buckets[new_index];
                new_buckets[new_index] = node;

                node = next;
            }
        }

        free(list->buckets);
        list->buckets = new_buckets;
        list->capacity = new_capacity;
    }

    size_t index = hash(record->IP_ADDRESS, record->PORT, list->capacity);
    ConnectionRecordNode* new_node = (ConnectionRecordNode*)malloc(sizeof(ConnectionRecordNode));
    if (!new_node) {
        pthread_mutex_unlock(&list->mutex);
        return -1;
    }

    memcpy(&new_node->record, record, sizeof(TCP_CONNECTION_RECORD_T));
    new_node->next = list->buckets[index];
    list->buckets[index] = new_node;

    list->count++;

    pthread_mutex_unlock(&list->mutex);

    return 0;
}

int removeConnection(ConnectionList* list, const char* IP_ADDRESS, int PORT) {
    pthread_mutex_lock(&list->mutex);

    size_t index = hash(IP_ADDRESS, PORT, list->capacity);
    ConnectionRecordNode** head = &list->buckets[index];
    ConnectionRecordNode* node = *head;

    while (node) {
        if (strcmp(node->record.IP_ADDRESS, IP_ADDRESS) == 0 && node->record.PORT == PORT) {
            *head = node->next;
            free(node);
            list->count--;
            pthread_mutex_unlock(&list->mutex);
            return 0;
        }
        head = &node->next;
        node = node->next;
    }

    pthread_mutex_unlock(&list->mutex);
    return -1;
}
