    size_t num_blocks;
    void* blocks;
} MemoryPool;

MemoryPool* create_memory_pool(size_t block_size, size_t num_blocks) {
    MemoryPool* pool = (MemoryPool*)malloc(sizeof(MemoryPool));
    if (!pool) return NULL;

    pool->block_size = block_size;
    pool->num_blocks = num_blocks;
    pool->blocks = malloc(block_size * num_blocks);
    if (!pool->blocks) {
        free(pool);
        return NULL;
    }

    return pool;
}

void destroy_memory_pool(MemoryPool* pool) {
    if (pool) {
        free(pool->blocks);
        free(pool);
    }
}

void* allocate_from_pool(MemoryPool* pool) {
    // Simple round-robin allocation for demonstration
    static size_t next_index = 0;
    void* block = ((char*)pool->blocks) + next_index * pool->block_size;
    next_index = (next_index + 1) % pool->num_blocks;
    return block;
}

CUSTOM_EVENT_PDU_T* generate_event_list(size_t num_events, MemoryPool* pool) {
    CUSTOM_EVENT_PDU_T* head = NULL;
    size_t count = 0;

    for (size_t i = 0; i < num_events; ++i) {
        CUSTOM_EVENT_PDU_T* event = (CUSTOM_EVENT_PDU_T*)allocate_from_pool(pool);
        if (!event) break;

        // Initialize the event structure
        event->tag = rand();
        snprintf(event->type, sizeof(event->type), "Event%d", i % 10); // Example type
        event->timestamp = time(NULL);

        // Link into the list
        if (head == NULL) {
            head = event;
        } else {
            CUSTOM_EVENT_PDU_T* current = head;
            while (current->next != NULL) {
                current = current->next;
            }
            current->next = event;
        }

        ++count;
    }

    return head, count;
}
