void addFrameToList(FrameList *list, NFAPI_RX_FRAME_T *frame, int RNTI) {
    pthread_mutex_lock(&list->lock);
    if (list->count < MAX_FRAMES && findFrameByRNTI(list, RNTI) == -1) {
        list->elements[list->count].RNTI = RNTI;
        list->elements[list->count].frame = frame;
        list->count++;
    }
    pthread_mutex_unlock(&list->lock);
}

int findFrameByRNTI(FrameList *list, int RNTI) {
    for (int i = 0; i < list->count; i++) {
        if (list->elements[i].RNTI == RNTI) {
            return i;
        }
    }
    return -1;
}

void freeFrameList(FrameList *list) {
    pthread_mutex_lock(&list->lock);
    for (int i = 0; i < list->count; i++) {
        free(list->elements[i].frame);
    }
