['```python
import hashlib
import os
import queue
import threading
from time import time

def calculate_md5(file_path):
    hasher = hashlib.md5()
    with open(file_path, 'rb') as file:
        for chunk in iter(lambda: file.read(4096), b""):
            hasher.update(chunk)
    return hasher.hexdigest()

def thread_safe_queue():
    q = queue.Queue()
    lock = threading.Lock()

    def enqueue(item):
        with lock:
            q.put(item)

    def dequeue():
        with lock:
            return q.get()

    def is_empty():
        with lock:
            return q.empty()

    return enqueue, dequeue, is_empty

def concurrent_hashing(file_paths, num_threads=4):
    start_time = time()
    enqueue, dequeue, is_empty = thread_safe_queue()

    def worker():
        while True:
            file_path = dequeue()
            if file_path is None:
                break
            print(f"Hashing {file_path}...")
            md5_hash = calculate_md5(file_path)
            print(f"{file_path} MD5: {md5_hash}")
            # Log start and completion times here

    threads = [threading.Thread(target=worker) for _ in range(num_threads)]
    for thread in threads:
        thread.start()

    for file_path in file_paths:
        enqueue(file_path)

    while not is_empty():
        pass

    for _ in range(num_threads):
        enqueue(None)

    for thread in threads:
        thread.join()

    end_time = time()
    print(f"Total hashing time: {end_time - start_time} seconds")

if __name__ == "__main__":
    file_paths = ["large_file1.txt", "large_file2.txt", "large_file3.txt"]
    concurrent_hashing(file_paths)
```

This code snippet defines a function `calculate_md5` to calculate the MD5 hash of a single file, a `thread_safe_queue` function to create a thread-safe queue for managing file paths, and a `concurrent_hashing` function to concurrently hash multiple files using multiple threads. The `concurrent_hashing` function starts multiple worker threads, each handling a file path from the queue, until all files are processed.

To use this code, simply call the `concurrent_hashing` function with a list of file paths. The function will print the MD5 hash of each file and log the start and completion times to the console. You can adjust the number of threads by changing the `num_threads` parameter in the function call.

This implementation demonstrates efficient concurrent processing, handling of large files, and thread safety using a queue. It provides a simple way to extend the functionality to include progress indicators, priority-based file processing, and integration with external dependencies as needed.']

