# Import necessary libraries
from flask import Flask, request, jsonify
import redis
import csv
import json
import datetime

# Initialize Flask app and Redis client
app = Flask(__name__)
cache = redis.StrictRedis(host='localhost', port=6379, db=0)

# User profile data structure
profile_schema = {
    "personal_info": {"type": "dict"},
    "preferences": {"type": "list"},
    "last_login_date": {"type": "date"},
    "social_media_accounts": {"type": "list"}
}

# Database operations

def add_profile(profile_id, profile_data):
    if cache.exists(profile_id):
        return "Profile already exists", 400
    cache.set(profile_id, json.dumps(profile_data))
    return "Profile added successfully", 201

def update_profile(profile_id, updates):
    existing_profile = cache.get(profile_id)
    if not existing_profile:
        return "Profile does not exist", 404
    profile_data = json.loads(existing_profile)
    for key, value in updates.items():
        if key in profile_schema and isinstance(value, profile_schema[key]["type"]):
            profile_data[key] = value
    cache.set(profile_id, json.dumps(profile_data))
    return "Profile updated successfully", 200

def delete_profile(profile_id):
    if not cache.exists(profile_id):
        return "Profile does not exist", 404
    cache.delete(profile_id)
    return "Profile deleted successfully", 200

def get_profile(profile_id):
    profile_data = cache.get(profile_id)
    if not profile_data:
        return "Profile does not exist", 404
    return jsonify(json.loads(profile_data)), 200

# Command-line interface (simulated using Flask routes)

@app.route('/profile', methods=['POST'])
def add_profile_route():
    data = request.json
    return add_profile(data['profile_id'], data['profile_data'])

@app.route('/profile/<profile_id>', methods=['PUT'])
def update_profile_route(profile_id):
    updates = request.json
    return update_profile(profile_id, updates)

@app.route('/profile/<profile_id>', methods=['DELETE'])
def delete_profile_route(profile_id):
    return delete_profile(profile_id)

@app.route('/profile/<profile_id>', methods=['GET'])
def get_profile_route(profile_id):
    return get_profile(profile_id)

if __name__ == '__main__':
    app.run(debug=True)
```

