bool validate_oauth2_token(const char *json_str) {
    json_error_t error;
    json_t *root = json_loads(json_str, 0, &error);
    if (!root) {
        fprintf(stderr, "Failed to parse JSON: %s\n", error.text);
        return false;
    }

    const char *access_token = json_string_value(json_object_get(root, "access_token"));
    if (access_token == NULL) {
        fprintf(stderr, "Missing 'access_token' field\n");
        json_decref(root);
        return false;
    }

    int expires_in = json_integer_value(json_object_get(root, "expires_in"));
    if (!json_is_number(json_object_get(root, "expires_in")) || expires_in <= 0) {
        fprintf(stderr, "Invalid 'expires_in' field\n");
        json_decref(root);
        return false;
    }

    const char *token_type = json_string_value(json_object_get(root, "token_type"));
    if (token_type == NULL || strcmp(token_type, "Bearer") != 0) {
        fprintf(stderr, "Invalid 'token_type' field\n");
        json_decref(root);
        return false;
    }

    const char *refresh_token = json_string_value(json_object_get(root, "refresh_token"));
    // Optionally check for refresh_token if present

    json_decref(root);
    return true;
}
