#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_STRUCTURES 1000000

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct MemoryPool {
    NFAPI_CRC_INDICATION_PDU_T pool[MAX_STRUCTURES];
    int next_index;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool* create_memory_pool() {
    MemoryPool* pool = (MemoryPool*)malloc(sizeof(MemoryPool));
    if (!pool) return NULL;
    pool->next_index = 0;
    pthread_mutex_init(&pool->lock, NULL);
    return pool;
}

NFAPI_CRC_INDICATION_PDU_T* allocate_struct(MemoryPool* pool) {
    pthread_mutex_lock(&pool->lock);
    if (pool->next_index >= MAX_STRUCTURES) {
        pthread_mutex_unlock(&pool->lock);
        return NULL; // Pool is full
    }
    NFAPI_CRC_INDICATION_PDU_T* pdu = &pool->pool[pool->next_index++];
    pthread_mutex_unlock(&pool->lock);
    return pdu;
}

void free_struct(MemoryPool* pool, NFAPI_CRC_INDICATION_PDU_T* pdu) {
    int index = (int)(pdu - pool->pool);
    if (index < 0 || index >= MAX_STRUCTURES) return; // Invalid index
    pthread_mutex_lock(&pool->lock);
    pool->next_index--;
    pthread_mutex_unlock(&pool->lock);
}

void populate_struct(NFAPI_CRC_INDICATION_PDU_T* pdu, int RX_UE_INFORMATION_TAG, int RNTI, int CRC_INDICATION_REL8_TAG) {
    pdu->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    pdu->RNTI = RNTI;
    pdu->CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
}

NFAPI_CRC_INDICATION_PDU_T** create_and_populate_list(int N, MemoryPool* pool) {
    if (N > MAX_STRUCTURES) return NULL; // Requested more structures than the pool can hold
    NFAPI_CRC_INDICATION_PDU_T** list = (NFAPI_CRC_INDICATION_PDU_T**)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    if (!list) return NULL;

    srand(time(NULL)); // Seed for random number generation

    for (int i = 0; i < N; i++) {
        list[i] = allocate_struct(pool);
        if (!list[i]) {
            free(list);
            return NULL; // Failed to allocate memory
        }
        populate_struct(list[i], rand() % 100, rand() % 256, rand() % 2);
    }

    return list;
}

void destroy_list(NFAPI_CRC_INDICATION_PDU_T** list, int N, MemoryPool* pool) {
    for (int i = 0; i < N; i++) {
        free_struct(pool, list[i]);
    }
    free(list);
}
