typedef struct {
    int PACKET_COUNT;
    long BYTES_TRANSMITTED;
    int ERROR_COUNT;
} TrafficStats;

typedef struct MemoryPoolNode {
    TrafficStats stats;
    struct MemoryPoolNode *next;
} MemoryPoolNode;

MemoryPoolNode *memoryPoolHead = NULL;
int memoryPoolSize = 0;

pthread_mutex_t poolMutex = PTHREAD_MUTEX_INITIALIZER;

TrafficStats* allocateTrafficStats() {
    pthread_mutex_lock(&poolMutex);
    if (memoryPoolHead == NULL) {
        memoryPoolHead = (MemoryPoolNode *)malloc(sizeof(MemoryPoolNode));
        if (memoryPoolHead == NULL) {
            perror("Failed to allocate memory for memory pool");
            pthread_mutex_unlock(&poolMutex);
            return NULL;
        }
        memoryPoolHead->next = NULL;
    }
    MemoryPoolNode *node = memoryPoolHead;
    memoryPoolHead = node->next;
    memoryPoolSize--;
    pthread_mutex_unlock(&poolMutex);

    // Initialize the stats
    node->stats.PACKET_COUNT = 0;
    node->stats.BYTES_TRANSMITTED = 0;
    node->stats.ERROR_COUNT = 0;

    return &node->stats;
}

void deallocateTrafficStats(TrafficStats *stats) {
    pthread_mutex_lock(&poolMutex);
    MemoryPoolNode *node = (MemoryPoolNode *)stats;
    node->next = memoryPoolHead;
    memoryPoolHead = node;
    memoryPoolSize++;
    pthread_mutex_unlock(&poolMutex);
}

void updateTrafficStats(TrafficStats *stats, int packets, long bytes, int errors) {
    stats->PACKET_COUNT += packets;
    stats->BYTES_TRANSMITTED += bytes;
    stats->ERROR_COUNT += errors;
}

void printTrafficStats(const TrafficStats *stats) {
    printf("Packet Count: %d\n", stats->PACKET_COUNT);
    printf("Bytes Transmitted: %ld\n", stats->BYTES_TRANSMITTED);
    printf("Error Count: %d\n", stats->ERROR_COUNT);
}
