// Function to populate the NFAPI_CRC_INDICATION_PDU_T array
NFAPI_CRC_INDICATION_PDU_T* populateNfaApiPduArray(int size, int indices[], int indexCount) {
    if (size <= 0 || !indices || indexCount <= 0) {
        fprintf(stderr, "Invalid input parameters\n");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    int uniqueRntis[size];
    memset(uniqueRntis, 0, sizeof(uniqueRntis));

    for (int i = 0; i < indexCount; i++) {
        int idx = indices[i];
        if (idx < 0 || idx >= size) {
            fprintf(stderr, "Invalid index: %d\n", idx);
            free(array);
            return NULL;
        }

        while (uniqueRntis[idx]) {
            idx = generateUniqueIdentifier() % size; // Ensure uniqueness
        }
        uniqueRntis[idx] = 1;

        array[idx].RX_UE_INFORMATION_TAG = generateUniqueIdentifier();
        array[idx].RNTI = generateUniqueIdentifier(); // Ensure uniqueness
        array[idx].CRC_INDICATION_REL8_TAG = generateUniqueIdentifier(); // Implement as needed
    }

    return array;
}

