    NFAPI_CRC_INDICATION_PDU_T* pduArray = populateNfaApiPduArray(10, indices, sizeof(indices) / sizeof(indices[0]));
    if (pduArray) {
        // Process the populated array
        free(pduArray);
    }
    return 0;
}
