use tokio::sync::{mpsc, RwLock};
use std::collections::HashMap;
use std::time::Instant;

struct Transaction {
    id: u64,
    amount: f64,
}

enum Operation {
    Filter(f64),
    Aggregate,
    Transform(String),
}

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    let (tx, mut rx) = mpsc::channel(32);
    let cache: RwLock<HashMap<u64, Transaction>> = RwLock::new(HashMap::new());

    tokio::spawn(async move {
        while let Some(operation) = rx.recv().await {
            match operation {
                Operation::Filter(min_amount) => filter_transactions(&cache, min_amount).await,
                Operation::Aggregate => aggregate_transactions(&cache).await,
                Operation::Transform(transform_type) => transform_transactions(&cache, transform_type).await,
            }
        }
    });

    // Simulate receiving operations from the command line
    tx.send(Operation::Filter(100.0)).await?;
    tx.send(Operation::Aggregate).await?;
    tx.send(Operation::Transform("uppercase".to_string())).await?;

    Ok(())
}

async fn filter_transactions(cache: &RwLock<HashMap<u64, Transaction>>, min_amount: f64) {
    let cache = cache.read().await;
    let filtered: Vec<&Transaction> = cache.values().filter(|t| t.amount >= min_amount).collect();
    println!("Filtered Transactions: {:?}", filtered);
}

async fn aggregate_transactions(cache: &RwLock<HashMap<u64, Transaction>>) {
    let cache = cache.read().await;
    let sum: f64 = cache.values().map(|t| t.amount).sum();
    println!("Total Amount: {}", sum);
}

async fn transform_transactions(cache: &RwLock<HashMap<u64, Transaction>>, transform_type: String) {
    let mut cache = cache.write().await;
    for transaction in cache.values_mut() {
        match transform_type.as_str() {
            "uppercase" => transaction.id += 1,
            _ => {}
        }
    }
    println!("Transformed Transactions: {:?}", cache);
}
