typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* entries;
    size_t allocated_size;
    size_t used_size;
    pthread_mutex_t mutex;
} CrcIndicationList;

CrcIndicationList* create_crc_indication_list() {
    CrcIndicationList* list = malloc(sizeof(CrcIndicationList));
    if (list == NULL) return NULL;

    list->entries = (NFAPI_CRC_INDICATION_PDU_T*)posix_memalign((void**)&list->entries, 4096, sizeof(NFAPI_CRC_INDICATION_PDU_T) * MAX_ENTRIES);
    if (list->entries == NULL) {
        free(list);
        return NULL;
    }

    list->allocated_size = MAX_ENTRIES;
    list->used_size = 0;
    pthread_mutex_init(&list->mutex, NULL);

    return list;
}

void destroy_crc_indication_list(CrcIndicationList* list) {
    if (list == NULL) return;

    free(list->entries);
    pthread_mutex_destroy(&list->mutex);
    free(list);
}

int add_entry_to_list(CrcIndicationList* list, NFAPI_CRC_INDICATION_PDU_T entry) {
    if (list == NULL || list->used_size >= MAX_ENTRIES) return -1;

    pthread_mutex_lock(&list->mutex);
    list->entries[list->used_size++] = entry;
    pthread_mutex_unlock(&list->mutex);

    return 0;
}

int get_entry_from_list(CrcIndicationList* list, size_t index, NFAPI_CRC_INDICATION_PDU_T* entry) {
    if (list == NULL || index >= list->used_size || entry == NULL) return -1;

    pthread_mutex_lock(&list->mutex);
    *entry = list->entries[index];
    pthread_mutex_unlock(&list->mutex);

    return 0;
}
