typedef struct {
    int TX_POWER;
    int RX_QUALITY;
    float CHANNEL利用率;
} NFAPI_STATS_PDU_T;

// Function to process NFPAPI statistics and generate a summary report
void processNFPAPIStatistics(NFAPI_STATS_PDU_T *stats, int count) {
    if (count == 0) return; // Handle empty input

    // Initialize variables for averaging
    int totalTX_POWER = 0;
    int maxRX_QUALITY = stats[0].RX_QUALITY;
    float minCHANNEL利用率 = stats[0].CHANNEL利用率;

    // Loop through the array to process each entry
    for (int i = 0; i < count; i++) {
        totalTX_POWER += stats[i].TX_POWER;
        if (stats[i].RX_QUALITY > maxRX_QUALITY) {
            maxRX_QUALITY = stats[i].RX_QUALITY;
        }
        if (stats[i].CHANNEL利用率 < minCHANNEL利用率) {
            minCHANNEL利用率 = stats[i].CHANNEL利用率;
        }
    }

    // Calculate average TX_POWER
    float avgTX_POWER = totalTX_POWER / count;

    // Print the summary report
    printf("Summary Report:\n");
    printf("Average TX Power: %d\n", (int)avgTX_POWER);
    printf("Maximum RX Quality: %d\n", maxRX_QUALITY);
    printf("Minimum CHANNEL利用率: %.2f\n", minCHANNEL利用率);
}

// Example usage
int main() {
    NFAPI_STATS_PDU_T stats[] = {
        {10, 95, 85.5},
        {12, 97, 83.2},
        {8, 94, 86.7}
    };
    int count = sizeof(stats) / sizeof(stats[0]);

    processNFPAPIStatistics(stats, count);

    return 0;
}
