    list->elements = (NFAPI_CRC_INDICATION_PDU_T *)malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->elements) {
        return -1; // Memory allocation failed
    }
    list->capacity = initial_capacity;
    list->count = 0;
    pthread_mutex_init(&list->mutex, NULL);
    return 0;
}

int nfaapi_crc_list_add(NFAPI_CRC_LIST_T *list, RX_UE_INFORMATION_TAG ue_info_tag, RNTI rnti, CRC_INDICATION_REL8_TAG crc_indication_rel8_tag) {
