        list->capacity *= 2;
    }

    for (size_t i = list->count; i > 0 && i >= list->count - W + 1; --i) {
        if (list->elements[i].rnti == rnti) {
            pthread_mutex_unlock(&list->mutex);
            return -2; // Duplicate RNTI within sliding window
        }
    }

    list->elements[list->count].ue_info_tag = ue_info_tag;
    list->elements[list->count].rnti = rnti;
    list->elements[list->count].crc_indication_rel8_tag = crc_indication_rel8_tag;
    list->elements[list->count].crcflag = rand(); // Random CRCFLAG

    pthread_mutex_unlock(&list->mutex);
    return 0;
}

void nfaapi_crc_list_free(NFAPI_CRC_LIST_T *list) {
    free(list->elements);
    pthread_mutex_destroy(&list->mutex);
