int initialize_user_context(ContextManager *manager, int M, int **out_of_bounds_ids, int *out_of_bounds_count) {
    if (M > MAX_M) {
        fprintf(stderr, "Error: M exceeds system limits.\n");
        return -1;
    }

    manager->cache_size = 0;

    for (int i = 0; i < M; ++i) {
