            }
            continue;
        }

        UEContext *ctx = (UEContext *)malloc(sizeof(UEContext));
        initialize_context(ctx, identifier, rand(), rand());

        manager->cache[manager->cache_size++] = ctx;

        // Cache mechanism
        if (manager->cache_size >= NR_UE_CONTEXT_MANAGEMENT_STRUCTURES) {
            fprintf(stderr, "Warning: Cache full. Context reinitialization may occur.\n");
        }
    }

    return 0;
}

void free_context_manager(ContextManager *manager) {
    for (int i = 0; i < manager->cache_size; ++i) {
        free(manager->cache[i]);
    }
}

