    pthread_cond_t cond = PTHREAD_COND_INITIALIZER;

    int rntiPool[1024] = {0};
    int poolSize = 0;

    srand(time(NULL));

    for (int i = 0; i < N; i++) {
        if (poolSize == W) {
            // Simulate RNTI re-use after sliding window
            pthread_mutex_lock(&mutex);
            while (poolSize == W && !pthread_cond_wait(&cond, &mutex)) {}
            pthread_mutex_unlock(&mutex);
        }

        int rnti = rand() % 1024;
