typedef struct {
    time_t timestamp;
    float temperature;
    int quality_flag;
} TEMPERATURE_RECORD_T;

typedef struct {
    TEMPERATURE_RECORD_T records[MAX_RECORDS];
    int count;
} TemperatureCache;

TemperatureCache cache = { .count = 0 };

int add_to_cache(TEMPERATURE_RECORD_T record) {
    if (cache.count < CACHE_SIZE) {
        cache.records[cache.count++] = record;
        return 1;
    }
    return 0;
}

void process_temperature_data() {
    float sum = 0.0f, max_temp = -273.15f;
    int count = 0;

    while (1) {
        TEMPERATURE_RECORD_T record;
        if (scanf("%ld %f %d", &record.timestamp, &record.temperature, &record.quality_flag) != 3) {
            break;
        }

        if (record.temperature > max_temp) {
            max_temp = record.temperature;
        }
        sum += record.temperature;
        count++;

        if (record.quality_flag == 1) {
            add_to_cache(record);
        }
    }

    printf("Average Temperature: %.2f\n", sum / count);
    printf("Maximum Temperature: %.2f\n", max_temp);
}

int main() {
    process_temperature_data();
    return 0;
}
