class CryptoThreadSafeStateList {
public:
    CryptoThreadSafeStateList(int* states, int numStates, FSA* fsa, int lastState, int maxCapacity, bool clearList, bool updateWhenAvailable);
    ~CryptoThreadSafeStateList();

    void Serialize(const std::string& filename);
    void Deserialize(const std::string& filename);

    void AddState(int state);
    bool RemoveState(int state);

    float GetRandomFloat(float minValue, float maxValue);
    int GetRandomInt(int minValue, int maxValue);

    bool ValidateOAuth2TokenResponse(const std::string& tokenResponse);

    EVP_CIPHER* GetCipher(EVP_CIPHER_ID cipherId);

private:
    std::vector<int> stateList;
    std::mutex mutex;
    std::condition_variable cv;
    FSA* fsa;
    int lastState;
    int maxCapacity;
    bool clearList;
    bool updateWhenAvailable;

    void RetryFetchData();
};

CryptoThreadSafeStateList::CryptoThreadSafeStateList(int* states, int numStates, FSA* fsa, int lastState, int maxCapacity, bool clearList, bool updateWhenAvailable)
    : stateList(states, states + numStates), fsa(fsa), lastState(lastState), maxCapacity(maxCapacity), clearList(clearList), updateWhenAvailable(updateWhenAvailable) {
    if (clearList) stateList.clear();
}

CryptoThreadSafeStateList::~CryptoThreadSafeStateList() {
    // Clean up resources
}

void CryptoThreadSafeStateList::Serialize(const std::string& filename) {
    // Serialize the state list to a file
}

void CryptoThreadSafeStateList::Deserialize(const std::string& filename) {
    // Deserialize the state list from a file
}

void CryptoThreadSafeStateList::AddState(int state) {
    std::unique_lock<std::mutex> lock(mutex);
    if (stateList.size() < maxCapacity) {
        stateList.push_back(state);
        lastState = state;
        cv.notify_all();
    }
}

bool CryptoThreadSafeStateList::RemoveState(int state) {
    std::unique_lock<std::mutex> lock(mutex);
    auto it = std::find(stateList.begin(), stateList.end(), state);
    if (it != stateList.end()) {
        stateList.erase(it);
        cv.notify_all();
        return true;
    }
    return false;
}

float CryptoThreadSafeStateList::GetRandomFloat(float minValue, float maxValue) {
    static std::random_device rd;
    static std::mt19937 gen(rd());
    std::uniform_real_distribution<> dis(minValue, maxValue);
    return dis(gen);
}

int CryptoThreadSafeStateList::GetRandomInt(int minValue, int maxValue) {
    static std::random_device rd;
    static std::mt19937 gen(rd());
    if (minValue == maxValue) return minValue;
    std::uniform_int_distribution<> dis(minValue, maxValue - 1);
    return dis(gen);
}

bool CryptoThreadSafeStateList::ValidateOAuth2TokenResponse(const std::string& tokenResponse) {
    nlohmann::json json = nlohmann::json::parse(tokenResponse);
    if (json.contains("access_token") && json["access_token"].is_string() &&
        json.contains("expires_in") && json["expires_in"].is_number_integer() &&
        json["expires_in"] > 0 &&
        json.contains("token_type") && json["token_type"].is_string() &&
        json["token_type"] == "Bearer" &&
        (json.contains("refresh_token") ? json["refresh_token"].is_string() : true)) {
        return true;
    }
    return false;
}

EVP_CIPHER* CryptoThreadSafeStateList::GetCipher(EVP_CIPHER_ID cipherId) {
    switch (cipherId) {
        case EVP_des_ecb:
            return EVP_des_ecb();
        case EVP_des_ede3_ecb:
            return EVP_des_ede3_ecb();
        // Add cases for other ciphers
        default:
            return nullptr;
    }
}

