    float reliability_score;
} ConnectionState;

ConnectionState* init_connections(int N, int valid_range_start, int valid_range_end) {
    if (N > MAX_CONNECTIONS) {
        fprintf(stderr, "Error: Number of connections exceeds system limit.\n");
        return NULL;
    }

    ConnectionState* connections = (ConnectionState*)malloc(N * sizeof(ConnectionState));
    if (!connections) {
        fprintf(stderr, "Error: Insufficient memory to allocate connections.\n");
        return NULL;
    }

    srand(time(NULL)); // Seed the random number generator

    int valid_identifiers[MAX_CONNECTIONS];
    int valid_count = 0;

    for (int i = 0; i < N; ++i) {
        int identifier;
        do {
            identifier = rand() % (valid_range_end - valid_range_start + 1) + valid_range_start;
        } while (!is_valid_identifier(identifier, valid_identifiers, &valid_count));

        connections[i].connection_identifier = identifier;
        connections[i].current_bandwidth = ((float)rand() / RAND_MAX) * 100.0f; // Random bandwidth between 0 and 100
        connections[i].latency_metrics = ((float)rand() / RAND_MAX) * 20.0f;   // Random latency between 0 and 20
        connections[i].reliability_score = ((float)rand() / RAND_MAX) * 10.0f; // Random reliability score between 0 and 10

        valid_identifiers[valid_count++] = identifier;
    }

    return connections;
}

int is_valid_identifier(int identifier, int* valid_identifiers, int* valid_count) {
    for (int i = 0; i < *valid_count; ++i) {
        if (identifier == valid_identifiers[i]) {
            fprintf(stderr, "Warning: Out-of-bounds CONNECTION_IDENTIFIER value detected.\n");
            return 0;
        }
    }
    return 1;
}

void free_connections(ConnectionState* connections) {
    free(connections);
}

int main() {
    int N = 5000;
    ConnectionState* connections = init_connections(N, MIN_IDENTIFIER, MAX_IDENTIFIER);

    if (connections) {
        // Use the connections array here

        free_connections(connections);
    }

    return 0;
}
