#include <pthread.h>

#define INITIAL_PACKET_SIZE 1024

typedef struct Packet {
    // Define packet structure fields here
    int header;
    char payload[256];
    int metadata;
} Packet;

typedef struct PacketList {
    Packet** packets;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} PacketList;

void initPacketList(PacketList* list) {
    list->packets = (Packet**)malloc(INITIAL_PACKET_SIZE * sizeof(Packet*));
    if (list->packets == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    list->capacity = INITIAL_PACKET_SIZE;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);
}

void resizePacketList(PacketList* list) {
    size_t new_capacity = list->capacity * 2;
    Packet** new_packets = (Packet**)realloc(list->packets, new_capacity * sizeof(Packet*));
    if (new_packets == NULL) {
        fprintf(stderr, "Memory reallocation failed\n");
        exit(EXIT_FAILURE);
    }
    list->packets = new_packets;
    list->capacity = new_capacity;
}

void addPacketToQueue(PacketList* list, Packet* packet) {
    pthread_mutex_lock(&list->lock);
    if (list->size == list->capacity) {
        resizePacketList(list);
    }
    list->packets[list->size++] = packet;
    pthread_mutex_unlock(&list->lock);
}

Packet* getPacketFromQueue(PacketList* list) {
    Packet* packet = NULL;
    pthread_mutex_lock(&list->lock);
    if (list->size > 0) {
        packet = list->packets[--list->size];
        list->packets[list->size] = NULL; // Avoid dangling pointer
    }
    pthread_mutex_unlock(&list->lock);
    return packet;
}

void destroyPacketList(PacketList* list) {
    for (size_t i = 0; i < list->size; ++i) {
        free(list->packets[i]);
    }
    free(list->packets);
    pthread_mutex_destroy(&list->lock);
}
