    NetworkPacket* new_packets = (NetworkPacket*)realloc(list->packets, new_capacity * sizeof(NetworkPacket));
    if (!new_packets) {
        perror("Failed to reallocate memory for packet list");
        exit(EXIT_FAILURE);
    }
    list->packets = new_packets;
    list->capacity = new_capacity;
}

void add_packet(PacketList* list, NetworkPacket packet) {
    pthread_mutex_lock(&list->lock);
    if (list->size >= list->capacity) {
        resize_packet_list(list, list->capacity * 2);
    }
    list->packets[list->size++] = packet;
    pthread_mutex_unlock(&list->lock);
}

NetworkPacket get_packet(PacketList* list, size_t index) {
    NetworkPacket packet;
    pthread_mutex_lock(&list->lock);
    if (index < list->size) {
        packet = list->packets[index];
    } else {
        // Handle out-of-bounds access or return a default packet
        memset(&packet, 0, sizeof(NetworkPacket));
    }
    pthread_mutex_unlock(&list->lock);
    return packet;
}

