    int num_pdus_per_thread = MAX_PDUS / num_threads;
    pthread_t threads[num_threads];
    void** thread_results = (void**)malloc(num_threads * sizeof(void*));
    size_t total_memory_used = 0;

    if (!thread_results) {
        fprintf(stderr, "Failed to allocate memory for thread results\n");
