            fprintf(stderr, "Failed to join thread %d\n", i);
            free(thread_results);
            return EXIT_FAILURE;
        }
        total_memory_used += sizeof(NFAPI_CRC_INDICATION_PDU_T) * num_pdus_per_thread;
    }

    printf("Total memory used: %zu bytes\n", total_memory_used);

    for (int i = 0; i < num_threads; i++) {
        free(thread_results[i]);
    }
    free(thread_results);

    return EXIT_SUCCESS;
}
