#include <iostream>
#include <fstream>
#include <string>
#include <thread>
#include <mutex>
#include <queue>
#include <condition_variable>
#include <atomic>
#include <zlib.h>

enum LogLevel {
    DEBUG,
    INFO,
    WARNING,
    ERROR,
    CRITICAL
};

class Logger {
public:
    static Logger& getInstance() {
        static Logger instance;
        return instance;
    }

    void init(const std::string& logFile, int maxFileSize = 1024 * 1024 * 5) {
        logFilePath = logFile;
        maxLogSize = maxFileSize;
        startAsyncWriter();
    }

    void setMinLogLevel(LogLevel level) {
        minLogLevel = level;
    }

    template <typename... Args>
    void log(LogLevel level, const std::string& tag, const std::string& context, Args&&... args) {
        if (level >= minLogLevel) {
            std::lock_guard<std::mutex> lock(mutex);
            auto now = std::chrono::system_clock::now();
            std::time_t now_c = std::chrono::system_clock::to_time_t(now);
            std::string logMessage = "[" + std::ctime(&now_c) + "] [" + getLevelString(level) + "] [" + tag + "] [" + context + "] ";
            (logMessage += ... << args);
            queue.push(logMessage);
            cond.notify_one();
        }
    }

private:
    Logger() : minLogLevel(DEBUG), maxLogSize(0), running(true) {}
    ~Logger() { stopAsyncWriter(); }

    void startAsyncWriter() {
        writerThread = std::thread([this]() {
            while (running.load()) {
                std::string logMessage;
                {
                    std::unique_lock<std::mutex> lock(mutex);
                    cond.wait(lock, [this] { return !queue.empty() || !running.load(); });
                    if (!queue.empty()) {
                        logMessage = queue.front();
                        queue.pop();
                    }
                }
                if (!logMessage.empty()) {
                    writeLog(logMessage);
                }
            }
        });
    }

    void stopAsyncWriter() {
        running.store(false);
        cond.notify_one();
        writerThread.join();
    }

    void writeLog(const std::string& logMessage) {
        std::ofstream fileStream(logFilePath, std::ios::app | std::ios::binary);
        if (fileStream.is_open()) {
            fileStream << logMessage;
            fileStream.close();

            if (getCurrentFileSize() > maxLogSize) {
                compressLogFile();
            }
        } else {
            // Handle error
        }
    }

    void compressLogFile() {
        std::ifstream inFile(logFilePath, std::ios::binary);
        std::ofstream outFile(logFilePath + ".gz", std::ios::binary);

        if (inFile.is_open() && outFile.is_open()) {
            char buffer[1024];
            z_stream stream;
            stream.zalloc = Z_NULL;
            stream.zfree = Z_NULL;
            stream.opaque = Z_NULL;
            deflateInit(&stream, Z_DEFAULT_COMPRESSION);
            stream.next_in = reinterpret_cast<Bytef*>(buffer);
            stream.avail_in = 0;

            while (true) {
                if (stream.avail_in == 0) {
                    stream.next_in = reinterpret_cast<Bytef*>(&buffer);
                    stream.avail_in = inFile.read(buffer, sizeof(buffer)).gcount();
                    if (stream.avail_in == 0) break;
                }

                deflate(&stream, Z_FINISH);
                outFile.write(reinterpret_cast<char*>(stream.next_out), stream.total_out);

                if (stream.avail_out == 0) {
                    outFile.flush();
                }
            }

            deflateEnd(&stream);
        } else {
            // Handle error
        }
    }

    std::string getLevelString(LogLevel level) {
        switch (level) {
            case DEBUG: return "DEBUG";
            case INFO: return "INFO";
            case WARNING: return "WARNING";
            case ERROR: return "ERROR";
            case CRITICAL: return "CRITICAL";
            default: return "UNKNOWN";
        }
    }

    std::string logFilePath;
    int maxLogSize;
    LogLevel minLogLevel;
    std::mutex mutex;
    std::condition_variable cond;
    std::queue<std::string> queue;
    std::thread writerThread;
    std::atomic<bool> running;
};

int main() {
    Logger& logger = Logger::getInstance();
    logger.init("app.log");

    logger.log(INFO, "SYSTEM", "Starting application...", 123);
    logger.log(ERROR, "DATABASE", "Connection failed", "Retry in 5 minutes");
    logger.setMinLogLevel(CRITICAL);

    return 0;
}
