#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct Cache {
    void* data;
    size_t size;
    time_t last_accessed;
    struct Cache* next;
    struct Cache* prev;
} Cache;

typedef struct CachePartition {
    char name[64];
    size_t max_size;
    size_t used_size;
    Cache* head;
    Cache* tail;
    pthread_mutex_t lock;
} CachePartition;

typedef struct CacheManager {
    CachePartition partitions[10];
    pthread_mutex_t global_lock;
} CacheManager;

void cache_init(CacheManager* cm) {
    for (int i = 0; i < 10; i++) {
        snprintf(cm->partitions[i].name, sizeof(cm->partitions[i].name), "Partition%d", i);
        cm->partitions[i].max_size = 1024 * 1024 * 10; // 10MB per partition
        cm->partitions[i].used_size = 0;
        cm->partitions[i].head = NULL;
        cm->partitions[i].tail = NULL;
        pthread_mutex_init(&cm->partitions[i].lock, NULL);
    }
    pthread_mutex_init(&cm->global_lock, NULL);
}

void* cache_allocate(CacheManager* cm, const char* partition_name, size_t size) {
    pthread_mutex_lock(&cm->global_lock);
    for (int i = 0; i < 10; i++) {
        if (strcmp(cm->partitions[i].name, partition_name) == 0) {
            pthread_mutex_lock(&cm->partitions[i].lock);
            while (size + cm->partitions[i].used_size > cm->partitions[i].max_size) {
                // Evict least recently used item
                Cache* evict = cm->partitions[i].tail;
                if (evict) {
                    cm->partitions[i].tail = evict->prev;
                    if (cm->partitions[i].tail)
                        cm->partitions[i].tail->next = NULL;
                    else
                        cm->partitions[i].head = NULL;
                    cm->partitions[i].used_size -= evict->size;
                    free(evict);
                } else {
                    // Handle memory allocation failure gracefully
                    pthread_mutex_unlock(&cm->partitions[i].lock);
                    pthread_mutex_unlock(&cm->global_lock);
                    return NULL;
                }
            }
            Cache* new_item = (Cache*)malloc(sizeof(Cache));
            if (!new_item) {
                pthread_mutex_unlock(&cm->partitions[i].lock);
                pthread_mutex_unlock(&cm->global_lock);
                return NULL;
            }
            new_item->data = malloc(size);
            if (!new_item->data) {
                free(new_item);
                pthread_mutex_unlock(&cm->partitions[i].lock);
                pthread_mutex_unlock(&cm->global_lock);
                return NULL;
            }
            new_item->size = size;
            new_item->last_accessed = time(NULL);
            new_item->next = cm->partitions[i].head;
            new_item->prev = NULL;
            if (cm->partitions[i].head)
                cm->partitions[i].head->prev = new_item;
            else
                cm->partitions[i].tail = new_item;
            cm->partitions[i].head = new_item;
            cm->partitions[i].used_size += size;
            pthread_mutex_unlock(&cm->partitions[i].lock);
            pthread_mutex_unlock(&cm->global_lock);
            return new_item->data;
        }
    }
    pthread_mutex_unlock(&cm->global_lock);
    return NULL;
}

void cache_free(CacheManager* cm, const char* partition_name, void* data) {
    pthread_mutex_lock(&cm->global_lock);
    for (int i = 0; i < 10; i++) {
        if (strcmp(cm->partitions[i].name, partition_name) == 0) {
            pthread_mutex_lock(&cm->partitions[i].lock);
            Cache* current = cm->partitions[i].head;
            while (current) {
                if (current->data == data) {
                    if (current->prev)
                        current->prev->next = current->next;
                    else
                        cm->partitions[i].head = current->next;
                    if (current->next)
                        current->next->prev = current->prev;
                    else
                        cm->partitions[i].tail = current->prev;
                    cm->partitions[i].used_size -= current->size;
                    free(current->data);
                    free(current);
                    pthread_mutex_unlock(&cm->partitions[i].lock);
                    pthread_mutex_unlock(&cm->global_lock);
                    return;
                }
                current = current->next;
            }
            pthread_mutex_unlock(&cm->partitions[i].lock);
        }
    }
    pthread_mutex_unlock(&cm->global_lock);
}

void cache_update_access_time(CacheManager* cm, const char* partition_name, void* data) {
    pthread_mutex_lock(&cm->global_lock);
    for (int i = 0; i < 10; i++) {
        if (strcmp(cm->partitions[i].name, partition_name) == 0) {
            pthread_mutex_lock(&cm->partitions[i].lock);
            Cache* current = cm->partitions[i].head;
            while (current) {
                if (current->data == data) {
                    time_t now = time(NULL);
                    if (current->last_accessed != now) {
                        current->last_accessed = now;
                        // Update list order based on LRU
                        if (current->prev) {
                            if (current->next) {
                                current->prev->next = current->next;
                                current->next->prev = current->prev;
                            } else {
                                cm->partitions[i].tail = current->prev;
                            }
                            current->prev->next = NULL;
                            current->next = cm->partitions[i].head;
                            cm->partitions[i].head->prev = current;
                            cm->partitions[i].head = current;
                        }
                    }
                    pthread_mutex_unlock(&cm->partitions[i].lock);
                    pthread_mutex_unlock(&cm->global_lock);
                    return;
                }
                current = current->next;
            }
            pthread_mutex_unlock(&cm->partitions[i].lock);
        }
    }
    pthread_mutex_unlock(&cm->global_lock);
}
