#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define the Message structure
typedef struct {
    char* data;
    size_t size;
    int priority;
} Message;

// Define the Queue structure
typedef struct {
    Message** messages;
    size_t front;
    size_t rear;
    size_t capacity;
    pthread_mutex_t lock;
    pthread_cond_t not_full;
    pthread_cond_t not_empty;
} Queue;

// Initialize the queue
Queue* init_queue(size_t capacity) {
    Queue* q = (Queue*)malloc(sizeof(Queue));
    q->messages = (Message**)malloc(capacity * sizeof(Message*));
    for (size_t i = 0; i < capacity; i++) {
        q->messages[i] = NULL;
    }
    q->front = 0;
    q->rear = -1;
    q->capacity = capacity;
    pthread_mutex_init(&q->lock, NULL);
    pthread_cond_init(&q->not_full, NULL);
    pthread_cond_init(&q->not_empty, NULL);
    return q;
}

// Enqueue a message
void enqueue(Queue* q, Message* msg) {
    pthread_mutex_lock(&q->lock);
    while ((q->rear + 1) % q->capacity == q->front) {
        pthread_cond_wait(&q->not_full, &q->lock);
    }
    q->rear = (q->rear + 1) % q->capacity;
    q->messages[q->rear] = msg;
    if (q->front == -1) {
        q->front = 0;
    }
    pthread_cond_signal(&q->not_empty);
    pthread_mutex_unlock(&q->lock);
}

// Dequeue a message
Message* dequeue(Queue* q) {
    pthread_mutex_lock(&q->lock);
    while (q->front == -1) {
        pthread_cond_wait(&q->not_empty, &q->lock);
    }
    Message* msg = q->messages[q->front];
    if (q->front == q->rear) {
        q->front = -1;
        q->rear = -1;
    } else {
        q->front = (q->front + 1) % q->capacity;
    }
    pthread_cond_signal(&q->not_full);
    pthread_mutex_unlock(&q->lock);
    return msg;
}

// Free the queue
void free_queue(Queue* q) {
    for (size_t i = 0; i < q->capacity; i++) {
        if (q->messages[i] != NULL) {
            free(q->messages[i]->data);
            free(q->messages[i]);
        }
    }
    free(q->messages);
    pthread_mutex_destroy(&q->lock);
    pthread_cond_destroy(&q->not_full);
    pthread_cond_destroy(&q->not_empty);
    free(q);
}

// Main function to simulate message queue management
int main() {
    Queue* q = init_queue(10);

    // Enqueue messages
    for (size_t i = 0; i < 5; i++) {
        Message* msg = (Message*)malloc(sizeof(Message));
        msg->data = (char*)malloc(i + 1);
        snprintf(msg->data, i + 1, "%zu", i);
        msg->size = i;
        msg->priority = 0;
        enqueue(q, msg);
    }

    // Dequeue messages
    for (size_t i = 0; i < 5; i++) {
        Message* msg = dequeue(q);
        printf("Dequeued message: %s\n", msg->data);
        free(msg->data);
        free(msg);
    }

    free_queue(q);
    return 0;
}
