#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_MAC_PDUS 5000

typedef struct {
    // Define MAC_HEADER fields
    int headerField1;
    char headerField2[64];
} MAC_HEADER;

typedef struct {
    // Define MAC_PAYLOAD fields
    unsigned char payloadData[1024];
    int payloadSize;
} MAC_PAYLOAD;

typedef struct {
    MAC_HEADER macHeader;
    MAC_PAYLOAD macPayload;
    int sequenceNumber;
} MAC_PDU;

pthread_mutex_t memoryMutex = PTHREAD_MUTEX_INITIALIZER;

MAC_PDU* allocateAndInitializePDUs(int N) {
    pthread_mutex_lock(&memoryMutex);
    if (N < 1 || N > MAX_MAC_PDUS) {
        printf("Invalid number of PDUs. Must be between 1 and %d.\n", MAX_MAC_PDUS);
        pthread_mutex_unlock(&memoryMutex);
        return NULL;
    }

    MAC_PDU* pdus = (MAC_PDU*)malloc(N * sizeof(MAC_PDU));
    if (!pdus) {
        printf("Memory allocation failed.\n");
        pthread_mutex_unlock(&memoryMutex);
        return NULL;
    }

    for (int i = 0; i < N; i++) {
        // Initialize each MAC_PDU fields
        pdus[i].macHeader.headerField1 = i + 1;
        snprintf(pdus[i].macHeader.headerField2, sizeof(pdus[i].macHeader.headerField2), "Header%d", i + 1);
        pdus[i].macPayload.payloadSize = 50 * (i + 1);
        for (int j = 0; j < pdus[i].macPayload.payloadSize; j++) {
            pdus[i].macPayload.payloadData[j] = (unsigned char)(j % 256);
        }
        pdus[i].sequenceNumber = i;
    }

    pthread_mutex_unlock(&memoryMutex);
    return pdus;
}

void freePDUs(MAC_PDU* pdus, int N) {
    if (pdus != NULL) {
        pthread_mutex_lock(&memoryMutex);
        free(pdus);
        pthread_mutex_unlock(&memoryMutex);
    }
}
