#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>

typedef struct {
    // Define your data structure here for event storage
    int event_id;
    void* event_data;
} Event;

typedef struct {
    Event** events;
    int size;
    sem_t* write_sem;
    sem_t* read_sem;
    pthread_mutex_t lock;
} EventStore;

EventStore* create_event_store() {
    EventStore* store = (EventStore*)malloc(sizeof(EventStore));
    if (!store) {
        return NULL;
    }
    store->events = (Event**)malloc(10 * sizeof(Event*)); // Initial size
    store->size = 10;
    sem_init(&store->write_sem, 0, 9); // Allow up to 9 concurrent writers
    sem_init(&store->read_sem, 0, 10); // Allow up to 10 concurrent readers
    pthread_mutex_init(&store->lock, NULL);
    return store;
}

void add_event(EventStore* store, Event* event) {
    sem_wait(&store->write_sem);
    pthread_mutex_lock(&store->lock);

    if (store->size <= 0) {
        // Resize the events array
        store->events = realloc(store->events, store->size * 2 * sizeof(Event*));
        if (!store->events) {
            sem_post(&store->write_sem);
            pthread_mutex_unlock(&store->lock);
            return;
        }
        store->size *= 2;
    }

    store->events[store->size - 1] = event;

    pthread_mutex_unlock(&store->lock);
    sem_post(&store->write_sem);
}

Event* get_event(EventStore* store) {
    sem_wait(&store->read_sem);
    pthread_mutex_lock(&store->lock);

    Event* event = NULL;
    if (store->size > 0) {
        event = store->events[store->size - 1];
        store->size--;
    }

    pthread_mutex_unlock(&store->lock);
    sem_post(&store->read_sem);
    return event;
}

void destroy_event_store(EventStore* store) {
    // Free the events and other resources
    free(store->events);
    sem_destroy(&store->write_sem);
    sem_destroy(&store->read_sem);
    pthread_mutex_destroy(&store->lock);
    free(store);
}
```

