#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct Event {
    int type;
    int size;
    void* data;
    struct Event* next;
} Event;

typedef struct EventQueue {
    pthread_mutex_t lock;
    Event* head;
    Event* tail;
} EventQueue;

EventQueue* create_event_queue() {
    EventQueue* queue = malloc(sizeof(EventQueue));
    if (queue == NULL) {
        perror("Failed to allocate memory for event queue");
        return NULL;
    }
    pthread_mutex_init(&queue->lock, NULL);
    queue->head = queue->tail = NULL;
    return queue;
}

void enqueue_event(EventQueue* queue, Event* event) {
    pthread_mutex_lock(&queue->lock);
    if (queue->tail != NULL) {
        queue->tail->next = event;
    } else {
        queue->head = event;
    }
    queue->tail = event;
    pthread_mutex_unlock(&queue->lock);
}

Event* dequeue_event(EventQueue* queue) {
    pthread_mutex_lock(&queue->lock);
    if (queue->head == NULL) {
        pthread_mutex_unlock(&queue->lock);
        return NULL;
    }
    Event* event = queue->head;
    queue->head = event->next;
    if (queue->head == NULL) {
        queue->tail = NULL;
    }
    pthread_mutex_unlock(&queue->lock);
    return event;
}

void free_event(Event* event) {
    free(event->data);
    free(event);
}
