#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>
#include <string.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct BufferNode {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct BufferNode* next;
} BufferNode;

typedef struct BufferManager {
    BufferNode* head;
    BufferNode* tail;
    size_t current_size;
    size_t max_size;
    pthread_mutex_t lock;
    pthread_cond_t not_full;
    pthread_cond_t not_empty;
} BufferManager;

BufferManager* buffer_manager_init(size_t initial_size) {
    BufferManager* manager = (BufferManager*)malloc(sizeof(BufferManager));
    if (!manager) return NULL;
    manager->head = NULL;
    manager->tail = NULL;
    manager->current_size = 0;
    manager->max_size = initial_size;
    pthread_mutex_init(&manager->lock, NULL);
    pthread_cond_init(&manager->not_full, NULL);
    pthread_cond_init(&manager->not_empty, NULL);
    return manager;
}

void buffer_manager_destroy(BufferManager* manager) {
    while (manager->head) {
        BufferNode* node = manager->head;
        manager->head = manager->head->next;
        free(node);
    }
    pthread_mutex_destroy(&manager->lock);
    pthread_cond_destroy(&manager->not_full);
    pthread_cond_destroy(&manager->not_empty);
    free(manager);
}

void buffer_manager_push(BufferManager* manager, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&manager->lock);
    while (manager->current_size == manager->max_size) {
        pthread_cond_wait(&manager->not_full, &manager->lock);
    }
    BufferNode* node = (BufferNode*)malloc(sizeof(BufferNode));
    if (!node) {
        pthread_mutex_unlock(&manager->lock);
        return;
    }
    node->data = data;
    node->next = NULL;
    if (manager->tail) {
        manager->tail->next = node;
    } else {
        manager->head = node;
    }
    manager->tail = node;
    manager->current_size++;
    pthread_cond_signal(&manager->not_empty);
    pthread_mutex_unlock(&manager->lock);
}

void buffer_manager_pop(BufferManager* manager, NFAPI_CRC_INDICATION_PDU_T* data) {
    pthread_mutex_lock(&manager->lock);
    while (manager->current_size == 0) {
        pthread_cond_wait(&manager->not_empty, &manager->lock);
    }
    BufferNode* node = manager->head;
    *data = node->data;
    manager->head = manager->head->next;
    if (!manager->head) {
        manager->tail = NULL;
    }
    free(node);
    manager->current_size--;
    pthread_cond_signal(&manager->not_full);
    pthread_mutex_unlock(&manager->lock);
}

