use tokio::{sync::mpsc, task};
use std::{env, process, time::Duration};

#[derive(Debug)]
enum Operation {
    ModeA(u32, Duration),
    ModeB,
    ModeC(u32, Duration),
}

#[derive(Debug)]
struct NFAPI_CRC_INDICATION_PDU_T {
    rx_ue_information_tag: String,
    rnti: u16,
    crc_indication_rel8_tag: bool,
}

async fn generate_structures(mode: Operation) -> Result<Vec<NFAPI_CRC_INDICATION_PDU_T>, Box<dyn std::error::Error>> {
    let mut structures = Vec::new();

    match mode {
        Operation::ModeA(count, duration) => {
            let start_time = tokio::time::Instant::now();
            while structures.len() < count as usize && start_time.elapsed() < duration {
                let pdu = generate_structure().await?;
                structures.push(pdu);
            }
        },
        Operation::ModeB => {
            loop {
                let pdu = generate_structure().await?;
                structures.push(pdu);
            }
        },
        Operation::ModeC(count, interval) => {
            for _ in 0..count {
                let pdu = generate_structure().await?;
                structures.push(pdu);
                tokio::time::sleep(interval).await;
            }
        },
    }

    Ok(structures)
}

async fn generate_structure() -> Result<NFAPI_CRC_INDICATION_PDU_T, Box<dyn std::error::Error>> {
    // Simulate fetching UE information from an external source
    let rx_ue_information_tag = "UE12345".to_string();
    let rnti = 0x1234;
    let crc_indication_rel8_tag = rand::random();

    Ok(NFAPI_CRC_INDICATION_PDU_T {
        rx_ue_information_tag,
        rnti,
        crc_indication_rel8_tag,
    })
}

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    let args: Vec<String> = env::args().collect();
    if args.len() < 3 {
        eprintln!("Usage: {} <mode> <parameters>", args[0]);
        process::exit(1);
    }

    let mode = match args[1].as_str() {
        "A" => Operation::ModeA(
            args[2].parse().map_err(|_| "Invalid count for Mode A")?,
            Duration::from_secs(args[3].parse().map_err(|_| "Invalid duration for Mode A")?),
        ),
        "B" => Operation::ModeB,
        "C" => Operation::ModeC(
            args[2].parse().map_err(|_| "Invalid count for Mode C")?,
            Duration::from_secs(args[3].parse().map_err(|_| "Invalid interval for Mode C")?),
        ),
        _ => {
            eprintln!("Unsupported mode: {}", args[1]);
            process::exit(1);
        }
    };

    let structures = generate_structures(mode).await?;
    println!("{:#?}", structures);

    Ok(())
}
