#define MAX_FRAMES 100
#define SUBFRAMES_PER_FRAME 10

typedef struct {
    int frameNum;
    int subframeNum;
    // Add other necessary fields for LTE_DL_FRAMEINFO
} LTE_DL_FRAMEINFO;

typedef struct {
    LTE_DL_FRAMEINFO *frames;
    int size;
    int capacity;
} DynamicArray;

DynamicArray* create_dynamic_array() {
    DynamicArray *array = (DynamicArray*)malloc(sizeof(DynamicArray));
    array->size = 0;
    array->capacity = MAX_FRAMES;
    array->frames = (LTE_DL_FRAMEINFO*)malloc(array->capacity * sizeof(LTE_DL_FRAMEINFO));
    return array;
}

void destroy_dynamic_array(DynamicArray *array) {
    free(array->frames);
    free(array);
}

bool add_frame(DynamicArray *array, LTE_DL_FRAMEINFO frame) {
    if (array->size >= array->capacity) {
        int new_capacity = array->capacity * 2;
        LTE_DL_FRAMEINFO* new_frames = (LTE_DL_FRAMEINFO*)realloc(array->frames, new_capacity * sizeof(LTE_DL_FRAMEINFO));
        if (!new_frames) return false;
        array->frames = new_frames;
        array->capacity = new_capacity;
    }
    array->frames[array->size++] = frame;
    return true;
}

void calculate_cumulative_throughput(DynamicArray *array, float data_rate[]) {
    for (int i = 0; i < array->size; ++i) {
        if (i == 0 || array->frames[i].frameNum != array->frames[i - 1].frameNum) {
            // Reset throughput for new frame
            data_rate[array->frames[i].frameNum] = 0;
        }
        // Add subframe's data rate to the cumulative throughput
        data_rate[array->frames[i].frameNum] += data_rate[array->frames[i].subframeNum];
    }
}

// Example usage
int main() {
    DynamicArray *array = create_dynamic_array();
    LTE_DL_FRAMEINFO frame1 = {1, 1, /* other fields */};
    LTE_DL_FRAMEINFO frame2 = {1, 2, /* other fields */};
    float data_rate[MAX_FRAMES] = {0};

    add_frame(array, frame1);
    add_frame(array, frame2);

    calculate_cumulative_throughput(array, data_rate);

    destroy_dynamic_array(array);
    return 0;
}
