#define MAX_ENTRIES 10000
#define TIME_BUDGET 5

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    // Define the structure fields as per the API documentation
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data[MAX_ENTRIES];
    int count;
    pthread_mutex_t lock;
} NFAPI_LIST_T;

NFAPI_LIST_T *nfaapi_list_create() {
    NFAPI_LIST_T *list = malloc(sizeof(NFAPI_LIST_T));
    if (!list) return NULL;
    list->count = 0;
    if (pthread_mutex_init(&list->lock, NULL) != 0) {
        free(list);
        return NULL;
    }
    return list;
}

void nfaapi_list_destroy(NFAPI_LIST_T *list) {
    for (int i = 0; i < list->count; i++) {
        free(list->data[i]);
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

bool nfaapi_list_add_entry(NFAPI_LIST_T *list, NFAPI_CRC_INDICATION_PDU_T *entry) {
    pthread_mutex_lock(&list->lock);
    if (list->count >= MAX_ENTRIES) {
        pthread_mutex_unlock(&list->lock);
        return false;
    }
    list->data[list->count++] = entry;
    pthread_mutex_unlock(&list->lock);
    return true;
}

NFAPI_CRC_INDICATION_PDU_T** nfaapi_list_get_entries(NFAPI_LIST_T *list, int *num_entries) {
    pthread_mutex_lock(&list->lock);
    if (*num_entries == 0) {
        *num_entries = list->count;
    }
    NFAPI_CRC_INDICATION_PDU_T **entries = malloc(*num_entries * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    if (!entries) {
        pthread_mutex_unlock(&list->lock);
        return NULL;
    }
    for (int i = 0; i < *num_entries; i++) {
        entries[i] = list->data[i];
    }
    pthread_mutex_unlock(&list->lock);
    return entries;
}
