#include <stdio.h>
#include <stdlib.h>

typedef struct State {
    int index;
    struct State* next;
} State;

typedef struct FSA {
    // Define the necessary fields for your FSA structure
    int** transitionTable;
    int startState;
    int* endStates;
    int numEndStates;
} FSA;

State* createStateListNode(int stateIndex, State* previousState) {
    State* newState = (State*)malloc(sizeof(State));
    if (newState == NULL) {
        return NULL; // Memory allocation failed
    }
    newState->index = stateIndex;
    newState->next = NULL;
    if (previousState != NULL) {
        previousState->next = newState;
    }
    return newState;
}

State* createAndLinkStates(int* initialStateArray, int initialCount, FSA* fsa, int lastStateIndex, State** currentListHead) {
    if (initialStateArray == NULL || initialCount <= 0 || fsa == NULL || currentListHead == NULL) {
        return NULL; // Invalid input
    }

    if (lastStateIndex >= initialCount) {
        return NULL; // Last state index out of bounds
    }

    State* head = *currentListHead;
    for (int i = 0; i <= lastStateIndex; i++) {
        int currentStateIndex = initialStateArray[i];
        if (currentStateIndex < 0 || currentStateIndex >= fsa->numEndStates) {
            return NULL; // Invalid state index
        }
        if (i == lastStateIndex) {
            *currentListHead = createAndLinkStates(initialStateArray, initialCount, fsa, i - 1, &head);
            break;
        } else {
            head = createAndLinkStates(initialStateArray, initialCount, fsa, i + 1, &head);
        }
    }

    return *currentListHead;
}

int main() {
    // Example usage
    int initialStateArray[] = {0, 1, 2};
    int initialCount = 3;
    FSA fsa;
    // Initialize the FSA structure here

    State* currentStateList = NULL;
    State* newStateList = createAndLinkStates(initialStateArray, initialCount, &fsa, initialCount - 1, &currentStateList);

    if (newStateList != NULL) {
        printf("State list created successfully.\n");
    } else {
        printf("Failed to create state list.\n");
    }

    // Clean up allocated memory
    State* temp;
    while (currentStateList != NULL) {
        temp = currentStateList;
        currentStateList = currentStateList->next;
        free(temp);
    }

    return 0;
}
