#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    let args: Vec<String> = env::args().collect();
    let mode = &args[1];

    let listener = TcpListener::bind("0.0.0.0:8080").await?;

    loop {
        let (mut socket, addr) = listener.accept().await?;

        tokio::spawn(async move {
            let mut buffer = [0; 1024];
            match socket.read(&mut buffer).await {
                Ok(n) if n == 0 => return,
                Ok(n) => {
                    let request = String::from_utf8_lossy(&buffer[..n]);
                    handle_request(request, mode).await;
                }
                Err(e) => eprintln!("Failed to read from socket: {}", e),
            }
        });
    }
}

async fn handle_request(request: String, mode: &str) {
    // Parse request
    let value: Value = from_str(&request).unwrap();

    // Validate token
    let access_token = value.get("access_token").unwrap().as_str().unwrap();
    let client = Client::new();
    let response = client.get(format!("https://api.example.com/validate?token={}", access_token))
        .send()
        .await
        .unwrap();

    if !response.status().is_success() {
        // Handle token validation failure
        return;
    }

    // Process request based on mode
    match mode {
        "A" => process_mode_a(),
        "B" => process_mode_b(),
        "C" => process_mode_c(),
        _ => {}
    }
}

