}

fn validate_oauth2_token(token_json: &str) -> bool {
    let value: Value = from_str(token_json).unwrap();
    value.get("access_token").is_some()
        && value.get("expires_in").is_some()
        && value.get("token_type").is_some()
}

fn des_algorithm(input: &[u8], key: &[u8]) -> Vec<u8> {
    let mut des_key = [0; 8];
    des_key.copy_from_slice(&key[..8]);
    let cipher = des::DesCbcMode::new_var(&des_key, &des_key).unwrap();
    cipher.encrypt_vec(input)
}

fn rsa_encryption(input: &[u8], key: &[u8]) -> Vec<u8> {
