    int used;
    pthread_mutex_t mutex;
} MemoryPool;

MemoryPool pool = {0, PTHREAD_MUTEX_INITIALIZER};

void* allocate_memory(size_t size) {
    if (size > sizeof(NFAPI_CRC_INDICATION_PDU_T)) {
        return NULL;
    }
    for (int i = 0; i < MAX_ELEMENTS; ++i) {
        pthread_mutex_lock(&pool.mutex);
        if (pool.elements[i].RNTI == 0) {
            void* ptr = &pool.elements[i];
            pool.used++;
            pthread_mutex_unlock(&pool.mutex);
            return ptr;
        }
        pthread_mutex_unlock(&pool.mutex);
    }
    return NULL; // Memory pool full
}

void deallocate_memory(void* ptr) {
    for (int i = 0; i < MAX_ELEMENTS; ++i) {
        if (&pool.elements[i] == ptr) {
            pthread_mutex_lock(&pool.mutex);
            pool.elements[i].RNTI = 0;
            pool.used--;
            pthread_mutex_unlock(&pool.mutex);
            return;
        }
