    int elements_to_allocate = (N > max_elements_per_call) ? max_elements_per_call : N;
    for (int i = 0; i < elements_to_allocate; ++i) {
        array[i] = allocate_memory(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!array[i]) {
            pthread_mutex_unlock(&pool.mutex);
            free(array);
            return NULL; // Memory allocation failed
        }
