#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>
#include <time.h>

#define MAX_ELEMENTS 10000
#define MEMORY_POOL_SIZE 1024 * 1024 // 1 MB

typedef struct {
    int RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    void* pool;
    size_t size;
    size_t used;
    pthread_mutex_t lock;
} MemoryPool_T;

MemoryPool_T memory_pool = {NULL, 0, 0, PTHREAD_MUTEX_INITIALIZER};

void init_memory_pool() {
    memory_pool.pool = malloc(MEMORY_POOL_SIZE);
    if (memory_pool.pool == NULL) {
        // Handle memory allocation failure
        exit(EXIT_FAILURE);
    }
    memory_pool.size = MEMORY_POOL_SIZE;
    memory_pool.used = 0;
}

void* allocate_from_pool(size_t size) {
    pthread_mutex_lock(&memory_pool.lock);
    void* ptr = (char*)memory_pool.pool + memory_pool.used;
    if ((memory_pool.used + size) > memory_pool.size) {
        // Resize memory pool
        size_t new_size = memory_pool.size * 2;
        void* new_pool = realloc(memory_pool.pool, new_size);
        if (new_pool == NULL) {
            // Handle memory allocation failure
            pthread_mutex_unlock(&memory_pool.lock);
            exit(EXIT_FAILURE);
        }
        memory_pool.pool = new_pool;
        memory_pool.size = new_size;
    }
    memory_pool.used += size;
    pthread_mutex_unlock(&memory_pool.lock);
    return ptr;
}

void free_memory_pool() {
    free(memory_pool.pool);
    memory_pool.pool = NULL;
    memory_pool.size = 0;
    memory_pool.used = 0;
}

int generate_random_crc_flag() {
    // Use third-party library for random number generation
    static int initialized = 0;
    if (!initialized) {
        srand(time(NULL));
        initialized = 1;
    }
    return rand() % 2; // Randomly generate either 0 or 1
}

void populate_array(NFAPI_CRC_INDICATION_PDU_T* array, size_t num_elements) {
    for (size_t i = 0; i < num_elements; i++) {
        NFAPI_CRC_INDICATION_PDU_T* element = (NFAPI_CRC_INDICATION_PDU_T*)allocate_from_pool(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (element == NULL) {
            // Handle allocation failure
            continue;
        }
        element->RX_UE_INFORMATION_TAG = i;
        element->RNTI = rand() % 1024; // Randomly generate RNTI between 0 and 1023
        element->CRC_INDICATION_REL8_TAG = generate_random_crc_flag();
        array[i] = *element;
    }
}

int main() {
    init_memory_pool();

    NFAPI_CRC_INDICATION_PDU_T* array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(MAX_ELEMENTS * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (array == NULL) {
        // Handle memory allocation failure
        free_memory_pool();
        return EXIT_FAILURE;
    }

    populate_array(array, MAX_ELEMENTS);

    // Use the array...

    free(array);
    free_memory_pool();

    return EXIT_SUCCESS;
}
