#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    char *filename;
    int access_count;
    // Other file metadata fields
} FileEntry;

typedef struct {
    FileEntry **entries;
    int size;
    int capacity;
    pthread_mutex_t lock;
} DynamicIndex;

DynamicIndex* create_dynamic_index(int initial_capacity) {
    DynamicIndex *index = (DynamicIndex*)malloc(sizeof(DynamicIndex));
    index->size = 0;
    index->capacity = initial_capacity;
    index->entries = (FileEntry**)calloc(initial_capacity, sizeof(FileEntry*));
    pthread_mutex_init(&index->lock, NULL);
    return index;
}

void destroy_dynamic_index(DynamicIndex *index) {
    for (int i = 0; i < index->size; i++) {
        free(index->entries[i]->filename);
        free(index->entries[i]);
    }
    free(index->entries);
    pthread_mutex_destroy(&index->lock);
    free(index);
}

void add_file(DynamicIndex *index, const char *filename) {
    pthread_mutex_lock(&index->lock);
    if (index->size >= index->capacity) {
        // Evict the least frequently used file
        int lfu_index = 0;
        for (int i = 1; i < index->size; i++) {
            if (index->entries[i]->access_count < index->entries[lfu_index]->access_count) {
                lfu_index = i;
            }
        }
        free(index->entries[lfu_index]->filename);
        free(index->entries[lfu_index]);
    } else {
        index->size++;
    }
    FileEntry *entry = (FileEntry*)malloc(sizeof(FileEntry));
    entry->filename = strdup(filename);
    entry->access_count = 1;
    index->entries[index->size - 1] = entry;
    pthread_mutex_unlock(&index->lock);
}

void update_file_access(DynamicIndex *index, const char *filename) {
    pthread_mutex_lock(&index->lock);
    for (int i = 0; i < index->size; i++) {
        if (strcmp(index->entries[i]->filename, filename) == 0) {
            index->entries[i]->access_count++;
            break;
        }
    }
    pthread_mutex_unlock(&index->lock);
}

// Other functions to support file partitioning, custom eviction policies, and other features
