#include <stdlib.h>
#include <pthread.h>
#include <stdio.h>

// Define the NFAPI_CRC_INDICATION_PDU_T structure
typedef struct {
    int pduData;
} NFAPI_CRC_INDICATION_PDU_T;

// Define a node for the linked list
typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

// Define the head of the list and mutex for thread safety
Node* head = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Function to dynamically allocate a new node
Node* allocateNode() {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) {
        perror("Memory allocation failed");
        return NULL;
    }
    pthread_mutex_lock(&lock);
    newNode->next = head;
    head = newNode;
    pthread_mutex_unlock(&lock);
    return newNode;
}

// Function to insert data into the list
int insertData(int pduData, int N) {
    for (int i = 0; i < N; i++) {
        Node* newNode = allocateNode();
        if (!newNode) {
            // Handle partial allocation failure
            while (head != NULL) {
                Node* temp = head;
                head = head->next;
                free(temp);
            }
            return -1;
        }
        newNode->data.pduData = pduData;
    }
    return N;
}

// Function to get the total number of entries in the list
int getTotalEntries() {
    pthread_mutex_lock(&lock);
    int count = 0;
    Node* current = head;
    while (current != NULL) {
        count++;
        current = current->next;
    }
    pthread_mutex_unlock(&lock);
    return count;
}

// Function to clean up the list
void cleanupList() {
    while (head != NULL) {
        Node* temp = head;
        head = head->next;
        free(temp);
    }
}
