    int stateIndex;
    struct StateNode* next;
    struct StateNode* prev;
} StateNode;

typedef struct FSA {
    // Define FSA structure members here
    int** transitionTable;
    int startState;
    int* endStates;
    int numEndStates;
    // Add other necessary members for FSA structure
} FSA;

typedef struct MemoryPool {
    StateNode* freeList;
    size_t nodeSize;
    size_t poolSize;
} MemoryPool;

MemoryPool createMemoryPool(size_t nodeSize, size_t poolSize) {
    MemoryPool pool = {NULL, nodeSize, poolSize};
    // Initialize memory pool here
    return pool;
}

StateNode* allocateNode(MemoryPool* pool) {
    StateNode* node = pool->freeList;
    if (node == NULL) {
        // Allocate new nodes from the heap
        node = (StateNode*)malloc(pool->nodeSize * pool->poolSize);
        if (node == NULL) {
            return NULL;  // Handle memory allocation failure
        }
        // Initialize newly allocated nodes and link them into the free list
    } else {
        pool->freeList = node->next;
    }
    return node;
}

void deallocateNode(MemoryPool* pool, StateNode* node) {
    node->next = pool->freeList;
    pool->freeList = node;
}

StateNode* createAndLinkStates(int* initialStates, int numInitialStates, FSA* fsa, int lastStateIndex, StateNode** head) {
    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    pthread_mutex_lock(&lock);
    StateNode* newNode = allocateNode(fsa->memoryPool);
    if (newNode == NULL) {
        pthread_mutex_unlock(&lock);
        return NULL;  // Handle memory allocation failure
    }

    newNode->stateIndex = lastStateIndex + 1;
    newNode->next = NULL;
    newNode->prev = (*head);

    if (*head != NULL) {
        (*head)->next = newNode;
    } else {
        *head = newNode;
    }

    pthread_mutex_unlock(&lock);
    return newNode;
}

// Additional helper functions and documentation can be added as needed
