use std::collections::HashMap;
use std::error::Error;
use std::sync::{Arc, Mutex};
use std::time::{Instant, Duration};
use tokio::task;
use tokio::sync::Semaphore;

#[derive(Debug)]
enum RX_UE_INFORMATION_TAG {
    Tag1,
    Tag2,
    // Add more tags as needed
}

#[derive(Debug)]
struct NFAPI_CRC_INDICATION_PDU_T {
    rx_ue_information_tag: RX_UE_INFORMATION_TAG,
    rnti: u32,
    crc_indication_rel8_tag: CRC_INDICATION_REL8_TAG,
    crcflag: bool,
}

#[derive(Debug)]
enum CRC_INDICATION_REL8_TAG {
    Indication1,
    Indication2,
    // Add more indications as needed
}

async fn generate_pdu(tag_type: RX_UE_INFORMATION_TAG, rnti: u32, crc_indication_rel8_tag: CRC_INDICATION_REL8_TAG, rng: &mut rand::Rng) -> NFAPI_CRC_INDICATION_PDU_T {
    NFAPI_CRC_INDICATION_PDU_T {
        rx_ue_information_tag: tag_type,
        rnti,
        crc_indication_rel8_tag,
        crcflag: rng.gen(),
    }
}

async fn handle_concurrent_tasks(tasks: Vec<task::JoinHandle<Result<NFAPI_CRC_INDICATION_PDU_T, Box<dyn Error>>>>, semaphore: Arc<Semaphore>, total_pusch: usize) -> Result<(), Box<dyn Error>> {
    let mut total_time = Duration::from_secs(0);
    let mut pdu_count = 0;

    for task in tasks {
        match semaphore.acquire().await {
            Ok(_) => {
                let pdu = task.await??;
                total_time += Duration::from_secs_f32(pdu.crcflag as f32 / 1000.0); // Assuming CRCFLAG is in milliseconds
                pdu_count += 1;
            }
            Err(_) => break,
        }
    }

    println!("Total PDU count: {}", pdu_count);
    println!("Average processing time per PDU: {:?}", total_time / pdu_count as u32);
    Ok(())
}

#[tokio::main]
async fn main() -> Result<(), Box<dyn Error>> {
    let args: Vec<String> = std::env::args().collect();
    if args.len() < 4 {
        eprintln!("Usage: {} <num_pusch> <seed> <tag_type>", args[0]);
        return Err("Invalid arguments".into());
    }

    let num_pusch: usize = args[1].parse()?;
    let seed: u64 = args[2].parse()?;
    let tag_type_str = &args[3];
    let tag_type: RX_UE_INFORMATION_TAG = match tag_type_str {
        "Tag1" => RX_UE_INFORMATION_TAG::Tag1,
        "Tag2" => RX_UE_INFORMATION_TAG::Tag2,
        _ => return Err("Invalid tag type".into()),
    };

    let mut rng = rand::SeedableRng::seed_from_u64(seed);
    let rnti: u32 = rng.gen();
    let crc_indication_rel8_tag: CRC_INDICATION_REL8_TAG = rng.gen();

    let semaphore = Arc::new(Semaphore::new(10)); // Limit to 10 concurrent tasks

    let mut tasks = Vec::with_capacity(num_pusch);
    for _ in 0..num_pusch {
        let task_semaphore = Arc::clone(&semaphore);
        tasks.push(task::spawn(async move {
            generate_pdu(tag_type, rnti, crc_indication_rel8_tag, &mut rng).await
        }));
    }

    handle_concurrent_tasks(tasks, semaphore, num_pusch).await?;

    Ok(())
}
