    int SESSION_ID;
} NETWORK_CONNECTION_T;

typedef struct {
    char STREAM_SOURCE[100];
    int STREAM_TYPE;
    double TRANSFER_RATE;
    unsigned int CHECKSUM;
} DATA_STREAM_T;

typedef struct TCP_PACKET_T {
    int PACKET_SEQ_NUM;
    int PAYLOAD_SIZE;
    int FLAGS;
} TCP_PACKET_T;

typedef enum {
    SUCCESS,
    MEMORY_FAILURE,
    INVALID_INPUT,
    OTHER_ERROR
} ERROR_STATUS_T;

ERROR_STATUS_T manageNetworkConnectionsAndStreams(
    NETWORK_CONNECTION_T** networkConnections,
    DATA_STREAM_T** dataStreams,
    TCP_PACKET_T*** packets,
    int* numConnections,
    int* numStreams,
    const char* remoteAddress,
    int portNumber,
    const char* streamSource,
    int streamType,
    double transferRate
) {
    if (remoteAddress == NULL || streamSource == NULL) {
        return INVALID_INPUT;
    }

    *networkConnections = (NETWORK_CONNECTION_T*)malloc(sizeof(NETWORK_CONNECTION_T));
    *dataStreams = (DATA_STREAM_T*)malloc(sizeof(DATA_STREAM_T));
    *packets = (TCP_PACKET_T**)malloc(10 * sizeof(TCP_PACKET_T*)); // Assuming up to 10 packets

    if (*networkConnections == NULL || *dataStreams == NULL || *packets == NULL) {
        free(*networkConnections);
        free(*dataStreams);
        for (int i = 0; i < 10; i++) {
            free((*packets)[i]);
        }
        free(*packets);
        return MEMORY_FAILURE;
    }

    (*networkConnections)->REMOTE_ADDRESS = strdup(remoteAddress);
    (*networkConnections)->PORT_NUMBER = portNumber;
    (*networkConnections)->CONNECTION_STATE = 1; // Assuming connected
    (*networkConnections)->LAST_HEARTBEAT = time(NULL);
    (*networkConnections)->SESSION_ID = rand();

    (*dataStreams)->STREAM_SOURCE = strdup(streamSource);
    (*dataStreams)->STREAM_TYPE = streamType;
    (*dataStreams)->TRANSFER_RATE = transferRate;

    for (int i = 0; i < 10; i++) {
        (*packets)[i] = (TCP_PACKET_T*)malloc(sizeof(TCP_PACKET_T));
        if ((*packets)[i] == NULL) {
            for (int j = 0; j <= i; j++) {
                free((*packets)[j]);
            }
            free(*networkConnections);
            free(*dataStreams);
            free(*packets);
            return MEMORY_FAILURE;
        }
        (*packets)[i]->PACKET_SEQ_NUM = i;
        (*packets)[i]->PAYLOAD_SIZE = 1024; // Assuming payload size of 1024 bytes
        (*packets)[i]->FLAGS = (i % 3 == 0) ? 1 : (i % 3 == 1) ? 2 : 3; // Data, ACK, Error
    }

    *numConnections = 1;
    *numStreams = 1;

    printf("Network connection established: %s:%d\n", (*networkConnections)->REMOTE_ADDRESS, (*networkConnections)->PORT_NUMBER);
