typedef struct {
    int PACKET_ID;
    int PROCESSING_STATUS;
    double DELAY_METRIC;
} DATA_PACKET_PROCESSING_RESULT_T;

ERROR_STATUS_T manage_network_collections(int num_connections, int num_packets, NETWORK_CONNECTION_T** connections, DATA_PACKET_T** packets) {
    if (connections == NULL || packets == NULL) {
        return INVALID_IP_ADDRESS;
    }

    *connections = (NETWORK_CONNECTION_T*)malloc(num_connections * sizeof(NETWORK_CONNECTION_T));
    if (*connections == NULL) {
        return MEMORY_ALLOCATION_FAILED;
    }

    *packets = (DATA_PACKET_T*)malloc(num_packets * sizeof(DATA_PACKET_T));
    if (*packets == NULL) {
        free(*connections);
        return MEMORY_ALLOCATION_FAILED;
    }

    for (int i = 0; i < num_connections; ++i) {
        // Initialize and populate network connections
        (*connections)[i].UNIQUE_ID = i + 1;
        snprintf((*connections)[i].IP_ADDRESS, sizeof((*connections)[i].IP_ADDRESS), "192.168.0.%d", i);
        (*connections)[i].PORT_NUMBER = 5000 + i;
        (*connections)[i].CONNECTION_STATE = 1; // Assume active
        time(&(*connections)[i].LAST_ACTIVE_TIME);
    }

    for (int i = 0; i < num_packets; ++i) {
        // Initialize and populate data packets
        (*packets)[i].PACKET_ID = i + 1;
        snprintf((*packets)[i].SOURCE_IP, sizeof((*packets)[i].SOURCE_IP), "192.168.0.%d", i % num_connections);
        snprintf((*packets)[i].DESTINATION_IP, sizeof((*packets)[i].DESTINATION_IP), "192.168.0.%d", (i + 1) % num_connections);
        (*packets)[i].PAYLOAD_SIZE = rand() % 1000;
        time(&(*packets)[i].TIMESTAMP);
    }

    // Log creation of each network connection and data packet
    for (int i = 0; i < num_connections; ++i) {
        printf("Network Connection Created: ID=%d, IP=%s, Port=%d\n", (*connections)[i].UNIQUE_ID, (*connections)[i].IP_ADDRESS, (*connections)[i].PORT_NUMBER);
    }

