        printf("Data Packet Created: ID=%d, Source IP=%s, Destination IP=%s\n", (*packets)[i].PACKET_ID, (*packets)[i].SOURCE_IP, (*packets)[i].DESTINATION_IP);
    }

    return SUCCESS;
