typedef struct {
    uint16_t RNTI;
    uint8_t CRC_status;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    pthread_mutex_t mutex;
    NFAPI_CRC_INDICATION_PDU_T *sessions[100];
    int session_count;
} LTE_UE_SESSIONS;

LTE_UE_SESSIONS* init_lte_sessions() {
    LTE_UE_SESSIONS *sessions = malloc(sizeof(LTE_UE_SESSIONS));
    if (sessions == NULL) {
        return NULL; // Handle memory allocation failure
    }
    pthread_mutex_init(&sessions->mutex, NULL);
    sessions->session_count = 0;
    for (int i = 0; i < 100; i++) {
        sessions->sessions[i] = NULL;
    }
    return sessions;
}

void add_session(LTE_UE_SESSIONS *sessions, uint16_t RNTI, uint8_t CRC_status) {
    pthread_mutex_lock(&sessions->mutex);
    if (sessions->session_count < 100) {
        NFAPI_CRC_INDICATION_PDU_T *new_session = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (new_session == NULL) {
            pthread_mutex_unlock(&sessions->mutex);
            return; // Handle memory allocation failure
        }
        new_session->RNTI = RNTI;
        new_session->CRC_status = CRC_status;
        sessions->sessions[sessions->session_count] = new_session;
        sessions->session_count++;
    } else {
        pthread_mutex_unlock(&sessions->mutex);
        return; // Handle too many sessions
    }
    pthread_mutex_unlock(&sessions->mutex);
}

void free_lte_sessions(LTE_UE_SESSIONS *sessions) {
    pthread_mutex_lock(&sessions->mutex);
    for (int i = 0; i < sessions->session_count; i++) {
        free(sessions->sessions[i]);
    }
    sessions->session_count = 0;
    pthread_mutex_unlock(&sessions->mutex);
    pthread_mutex_destroy(&sessions->mutex);
    free(sessions);
}
