#include <stdlib.h>
#include <time.h>
#include <string.h>
#include <pthread.h>

#define MAX_SESSIONS 500
#define RNTI_RANGE_START 1
#define RNTI_RANGE_END 4093
#define CRC_INDICATION_THRESHOLD 20

typedef struct {
    uint64_t timestamp;
    int rnti;
    int crcFlag;
} LTE_CRC_Indication;

LTE_CRC_Indication* generateLteSessionCrcIndications(int numSessions) {
    if (numSessions > MAX_SESSIONS || numSessions <= 0) {
        return NULL; // Invalid number of sessions
    }

    LTE_CRC_Indication* crcList = (LTE_CRC_Indication*)malloc(numSessions * sizeof(LTE_CRC_Indication));
    if (!crcList) {
        return NULL; // Memory allocation failed
    }

    pthread_mutex_t mutex;
    pthread_mutex_init(&mutex, NULL);

    srand(time(NULL));

    for (int i = 0; i < numSessions; i++) {
        pthread_mutex_lock(&mutex);
        do {
            crcList[i].rnti = rand() % (RNTI_RANGE_END - RNTI_RANGE_START + 1) + RNTI_RANGE_START;
        } while (i > 0 && crcList[i-1].rnti == crcList[i].rnti);

        do {
            crcList[i].crcFlag = rand() % 256; // Example CRC flag generation
        } while (i > CRC_INDICATION_THRESHOLD && crcList[i-CRC_INDICATION_THRESHOLD].crcFlag == crcList[i].crcFlag);

        crcList[i].timestamp = time(NULL);
        pthread_mutex_unlock(&mutex);
    }

    pthread_mutex_destroy(&mutex);

    return crcList;
}
