#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_LOG_ENTRIES 10000
#define BUFFER_RESIZE_THRESHOLD 8000

typedef struct {
    char sourceIP[16];
    char destinationIP[16];
    int protocolType;
    size_t packetSize;
    time_t timestamp;
} LogEntry;

typedef struct {
    LogEntry logs[MAX_LOG_ENTRIES];
    size_t count;
    pthread_mutex_t lock;
    pthread_cond_t cond;
    size_t read_index, write_index;
} TrafficLogBuffer;

TrafficLogBuffer log_buffer;

void init_log_buffer() {
    memset(&log_buffer, 0, sizeof(log_buffer));
    pthread_mutex_init(&log_buffer.lock, NULL);
    pthread_cond_init(&log_buffer.cond, NULL);
}

void resize_log_buffer() {
    LogEntry* new_logs = (LogEntry*)realloc(log_buffer.logs, BUFFER_RESIZE_THRESHOLD * sizeof(LogEntry));
    if (new_logs) {
        log_buffer.logs = new_logs;
    } else {
        fprintf(stderr, "Failed to resize log buffer\n");
    }
}

void add_log_entry(const LogEntry* entry) {
    pthread_mutex_lock(&log_buffer.lock);
    while (log_buffer.count == MAX_LOG_ENTRIES) {
        pthread_cond_wait(&log_buffer.cond, &log_buffer.lock);
    }
    if (log_buffer.count >= BUFFER_RESIZE_THRESHOLD) {
        resize_log_buffer();
    }
    log_buffer.logs[log_buffer.write_index] = *entry;
    log_buffer.write_index = (log_buffer.write_index + 1) % MAX_LOG_ENTRIES;
    log_buffer.count++;
    pthread_cond_signal(&log_buffer.cond);
    pthread_mutex_unlock(&log_buffer.lock);
}

void* traffic_log_processor(void* arg) {
    while (1) {
        LogEntry entry;
        pthread_mutex_lock(&log_buffer.lock);
        while (log_buffer.count == 0) {
            pthread_cond_wait(&log_buffer.cond, &log_buffer.lock);
        }
        entry = log_buffer.logs[log_buffer.read_index];
        log_buffer.read_index = (log_buffer.read_index + 1) % MAX_LOG_ENTRIES;
        log_buffer.count--;
        pthread_mutex_unlock(&log_buffer.lock);

        // Process the log entry
        printf("Processing log entry: srcIP=%s, destIP=%s, protocolType=%d, packetSize=%zu\n",
               entry.sourceIP, entry.destinationIP, entry.protocolType, entry.packetSize);
    }
    return NULL;
}

int main() {
    init_log_buffer();

    pthread_t processor_thread;
    pthread_create(&processor_thread, NULL, traffic_log_processor, NULL);

    // Simulate log entries
    LogEntry new_entry;
    for (int i = 0; i < 15000; i++) {
        strcpy(new_entry.sourceIP, "192.168.1.1");
        strcpy(new_entry.destinationIP, "10.0.0.1");
        new_entry.protocolType = i % 7;
        new_entry.packetSize = i * 1024;
        new_entry.timestamp = time(NULL);
        add_log_entry(&new_entry);
    }

    pthread_join(processor_thread, NULL);

    return 0;
}
