#define MAX_DOCS 5000
#define BUFFER_THRESHOLD 4000

typedef struct Document {
    char title[256];
    char author[128];
    int publication_date;
    char content[1024];
    char metadata[256];
} Document;

Document doc_buffer[MAX_DOCS];
int buffer_size = 0;
int next_index = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t cond = PTHREAD_COND_INITIALIZER;

void* parseAndIndexDocuments(void* arg) {
    Document* docs = (Document*)arg;
    for (int i = 0; i < MAX_DOCS; i++) {
        pthread_mutex_lock(&lock);
        while (buffer_size >= BUFFER_THRESHOLD) {
            pthread_cond_wait(&cond, &lock);
        }
        if (next_index == MAX_DOCS) {
            next_index = 0;
        }
        doc_buffer[next_index] = docs[i];
        buffer_size++;
        next_index++;
        pthread_mutex_unlock(&lock);
        pthread_cond_signal(&cond);
    }
    return NULL;
}

int main() {
    Document* documents = (Document*)malloc(MAX_DOCS * sizeof(Document));
    // Populate documents array with data
    pthread_t thread;
    pthread_create(&thread, NULL, parseAndIndexDocuments, documents);
    pthread_join(thread, NULL);
    free(documents);
    return 0;
}
