uint16_t generateUniqueRNTI(uint16_t rnti, uint16_t *usedRNTIs, size_t usedSize) {
    if (!rnti || (usedSize > 0 && rnti == usedRNTIs[0])) {
        // Generate a random RNTI
        srand(time(NULL));
        do {
            rnti = rand() % MAX_RNTI + 1;
        } while (usedSize > 0 && rnti == usedRNTIs[0]);
