#define N 10000

typedef struct {
    uint32_t crc_value;
    // Other fields as per NFAPI_CRC_INDICATION_PDU_T
} CRC_Indication_PDU;

typedef struct {
    CRC_Indication_PDU *pool;
    size_t pool_size;
    size_t next_index;
    pthread_mutex_t lock;
} CRC_Pool;

CRC_Pool *init_crc_pool(size_t initial_size) {
    CRC_Pool *pool = (CRC_Pool *)malloc(sizeof(CRC_Pool));
    pool->pool = (CRC_Indication_PDU *)aligned_alloc(4096, initial_size * sizeof(CRC_Indication_PDU));
    pool->pool_size = initial_size;
    pool->next_index = 0;
    pthread_mutex_init(&pool->lock, NULL);
    return pool;
}

void destroy_crc_pool(CRC_Pool *pool) {
    free(pool->pool);
    pthread_mutex_destroy(&pool->lock);
    free(pool);
}

int add_crc_indication(CRC_Pool *pool, CRC_Indication_PDU new_data) {
    pthread_mutex_lock(&pool->lock);
    if (pool->next_index >= pool->pool_size) {
        size_t new_size = pool->pool_size * 2;
        CRC_Indication_PDU *new_pool = (CRC_Indication_PDU *)aligned_alloc(4096, new_size * sizeof(CRC_Indication_PDU));
        memcpy(new_pool, pool->pool, pool->next_index * sizeof(CRC_Indication_PDU));
        free(pool->pool);
        pool->pool = new_pool;
        pool->pool_size = new_size;
    }
    pool->pool[pool->next_index++] = new_data;
    pthread_mutex_unlock(&pool->lock);
    return 0;
}

// Example usage
int main() {
    CRC_Pool *pool = init_crc_pool(1000);

    // Simulate adding data
    for (size_t i = 0; i < N; ++i) {
        CRC_Indication_PDU new_data = { .crc_value = i }; // Example initialization
        add_crc_indication(pool, new_data);
    }

    destroy_crc_pool(pool);
    return 0;
}
