#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int tag;
    int rnti;
    int crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* array = NULL;
int size = 0;
int capacity = 10;
int successful_allocations = 0;
int failed_allocations = 0;
clock_t allocation_times[100];
int total_allocation_time = 0;

void resize_array() {
    capacity *= 2;
    NFAPI_CRC_INDICATION_PDU_T* new_array = (NFAPI_CRC_INDICATION_PDU_T*)realloc(array, capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (new_array == NULL) {
        printf("Memory allocation failed\n");
        exit(1);
    }
    array = new_array;
}

void print_statistics() {
    double avg_time = (double)total_allocation_time / successful_allocations;
    printf("Total elements: %d\n", size);
    printf("Successful allocations: %d\n", successful_allocations);
    printf("Failed allocations: %d\n", failed_allocations);
    printf("Average allocation time: %.2f ms\n", avg_time);
}

void* populate_array(void* arg) {
    int tag = *(int*)arg;
    for (int i = 0; i < 10; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        pdu.tag = tag;
        pdu.rnti = rand() % 1000;
        pdu.crcflag = rand() % 2;

        if (size == capacity) {
            resize_array();
        }

        clock_t start_time = clock();
        array[size++] = pdu;
        clock_t end_time = clock();

        allocation_times[successful_allocations] = end_time - start_time;
        total_allocation_time += (int)allocation_times[successful_allocations];
        successful_allocations++;
    }
    return NULL;
}

int main(int argc, char* argv[]) {
    if (argc != 2) {
        printf("Usage: %s <number_of_threads>\n", argv[0]);
        exit(1);
    }

    int num_threads = atoi(argv[1]);
    pthread_t threads[num_threads];
    int tags[num_threads];

    srand(time(NULL));

    for (int i = 0; i < num_threads; ++i) {
        tags[i] = i;
        if (pthread_create(&threads[i], NULL, populate_array, &tags[i]) != 0) {
            printf("Thread creation failed\n");
            exit(1);
        }
    }

    for (int i = 0; i < num_threads; ++i) {
        pthread_join(threads[i], NULL);
    }

    print_statistics();

    free(array);

    return 0;
}
