#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_PAYLOAD_SIZE 1024
#define SESSION_ID_LEN 32

typedef struct TCP_CONNECTION_T {
    char CLIENT_IP[16];
    char SERVER_IP[16];
    int CONNECTION_PORT;
    time_t ESTABLISHED_TIME;
    time_t LAST_DATA_TIMESTAMP;
    char SESSION_ID[SESSION_ID_LEN];
    long BYTES_RECEIVED;
    long BYTES_SENT;
    int CONNECTION_STATE;
    // Add other fields as needed
} TCP_CONNECTION_T;

typedef struct {
    TCP_CONNECTION_T *sessions;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
} TCP_CONNECTION_MANAGER_T;

void tcp_connection_manager_init(TCP_CONNECTION_MANAGER_T *manager) {
    manager->sessions = NULL;
    manager->size = 0;
    manager->capacity = 0;
    pthread_mutex_init(&manager->lock, NULL);
}

int tcp_connection_manager_add(TCP_CONNECTION_MANAGER_T *manager, TCP_CONNECTION_T *session) {
    pthread_mutex_lock(&manager->lock);
    if (manager->size >= manager->capacity) {
        size_t new_capacity = manager->capacity == 0 ? 1 : manager->capacity * 2;
        TCP_CONNECTION_T *new_sessions = realloc(manager->sessions, new_capacity * sizeof(TCP_CONNECTION_T));
        if (!new_sessions) {
            perror("Memory allocation failed");
            pthread_mutex_unlock(&manager->lock);
            return -1;
        }
        manager->sessions = new_sessions;
        manager->capacity = new_capacity;
    }
    memcpy(&manager->sessions[manager->size], session, sizeof(TCP_CONNECTION_T));
    manager->size++;
    pthread_mutex_unlock(&manager->lock);
    return 0;
}

int tcp_connection_manager_update(TCP_CONNECTION_MANAGER_T *manager, char *session_id, TCP_CONNECTION_T *new_session) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->size; i++) {
        if (strcmp(manager->sessions[i].SESSION_ID, session_id) == 0) {
            memcpy(&manager->sessions[i], new_session, sizeof(TCP_CONNECTION_T));
            pthread_mutex_unlock(&manager->lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&manager->lock);
    return -1;
}

TCP_CONNECTION_T* tcp_connection_manager_get_by_id(TCP_CONNECTION_MANAGER_T *manager, char *session_id) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->size; i++) {
        if (strcmp(manager->sessions[i].SESSION_ID, session_id) == 0) {
            TCP_CONNECTION_T *result = malloc(sizeof(TCP_CONNECTION_T));
            if (!result) {
                perror("Memory allocation failed");
                pthread_mutex_unlock(&manager->lock);
                return NULL;
            }
            memcpy(result, &manager->sessions[i], sizeof(TCP_CONNECTION_T));
            pthread_mutex_unlock(&manager->lock);
            return result;
        }
    }
    pthread_mutex_unlock(&manager->lock);
    return NULL;
}

int tcp_connection_manager_export_to_csv(TCP_CONNECTION_MANAGER_T *manager, char *filename) {
    pthread_mutex_lock(&manager->lock);
    FILE *file = fopen(filename, "w");
    if (!file) {
        perror("Failed to open file for writing");
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }
    fprintf(file, "CLIENT_IP,SERVER_IP,CONNECTION_PORT,ESTABLISHED_TIME,LAST_DATA_TIMESTAMP,SESSION_ID,BYTES_RECEIVED,BYTES_SENT,CONNECTION_STATE\n");
    for (size_t i = 0; i < manager->size; i++) {
        TCP_CONNECTION_T *session = &manager->sessions[i];
        fprintf(file, "%s,%s,%d,%ld,%ld,%s,%ld,%ld,%d\n",
                session->CLIENT_IP,
                session->SERVER_IP,
                session->CONNECTION_PORT,
                session->ESTABLISHED_TIME,
                session->LAST_DATA_TIMESTAMP,
                session->SESSION_ID,
                session->BYTES_RECEIVED,
                session->BYTES_SENT,
                session->CONNECTION_STATE);
    }
    fclose(file);
    pthread_mutex_unlock(&manager->lock);
    return 0;
}

void tcp_connection_manager_cleanup(TCP_CONNECTION_MANAGER_T *manager) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->size; i++) {
        free(manager->sessions[i].SESSION_ID);
    }
    free(manager->sessions);
    manager->sessions = NULL;
    manager->size = 0;
    manager->capacity = 0;
    pthread_mutex_unlock(&manager->lock);
    pthread_mutex_destroy(&manager->lock);
}
