#include <arpa/inet.h>
#include <sys/socket.h>
#include <netdb.h>

#define WHITELIST_SIZE 100
#define MAX_HOSTNAME_LEN 256

typedef struct {
    char hostnames[WHITELIST_SIZE][MAX_HOSTNAME_LEN];
    int size;
} Whitelist;

u_char* resolve_hostname(const char* hostname, Whitelist* whitelist) {
    if (whitelist->size > WHITELIST_SIZE || hostname == NULL) {
        return NULL; // Error handling for invalid inputs
    }

    int i;
    for (i = 0; i < whitelist->size; i++) {
        if (strcmp(whitelist->hostnames[i], hostname) == 0) {
            break;
        }
    }

    if (i == whitelist->size) {
        return NULL; // Hostname not in whitelist
    }

    struct hostent* he = gethostbyname(hostname);
    if (he == NULL) {
        herror("gethostbyname");
        return NULL; // Error handling for DNS resolution failure
    }

    struct in_addr** addr_list = (struct in_addr**)he->h_addr_list;
    char ip_str[INET_ADDRSTRLEN];
    inet_ntop(AF_INET, addr_list[0], ip_str, INET_ADDRSTRLEN);

    u_char* ip_address = (u_char*)malloc(4);
    if (ip_address == NULL) {
        return NULL; // Memory allocation failure
    }

    memcpy(ip_address, addr_list[0]->s_addr, 4);

    return ip_address;
}

int main() {
    Whitelist whitelist;
    whitelist.size = 2;
    strcpy(whitelist.hostnames[0], "example.com");
    strcpy(whitelist.hostnames[1], "test.com");

    u_char* ip_address = resolve_hostname("example.com", &whitelist);
    if (ip_address != NULL) {
        printf("IP Address: %d.%d.%d.%d\n",
               ip_address[0], ip_address[1],
               ip_address[2], ip_address[3]);
        free(ip_address);
    } else {
        printf("Failed to resolve hostname or not in whitelist.\n");
    }

    return 0;
}
