#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_SESSIONS 1000

typedef enum {
    CONN_STATE_ESTABLISHED,
    CONN_STATE_CLOSING,
    CONN_STATE_CLOSED
} CONNECTION_STATE;

typedef struct TCP_CONNECTION_T {
    char CLIENT_IP[50];
    char SERVER_IP[50];
    int CONNECTION_PORT;
    long ESTABLISHED_TIME;
    long LAST_DATA_TIMESTAMP;
    unsigned int SESSION_ID;
    CONNECTION_STATE state;
    unsigned long BYTES_RECEIVED;
    unsigned long BYTES_SENT;
} TCP_CONNECTION_T;

typedef struct {
    TCP_CONNECTION_T sessions[MAX_SESSIONS];
    int count;
    pthread_mutex_t mutex;
} TCP_CONNECTION_MANAGER_T;

TCP_CONNECTION_MANAGER_T connection_manager;

int add_session(const char* client_ip, const char* server_ip, int port, unsigned int session_id) {
    if (client_ip == NULL || server_ip == NULL) {
        return -1; // Error: IP addresses cannot be null
    }

    pthread_mutex_lock(&connection_manager.mutex);
    for (int i = 0; i < connection_manager.count; i++) {
        if (connection_manager.sessions[i].SESSION_ID == session_id) {
            pthread_mutex_unlock(&connection_manager.mutex);
            return -2; // Error: Session ID already exists
        }
    }

    if (connection_manager.count >= MAX_SESSIONS) {
        pthread_mutex_unlock(&connection_manager.mutex);
        return -3; // Error: Maximum number of sessions reached
    }

    TCP_CONNECTION_T new_session = {0};
    strcpy(new_session.CLIENT_IP, client_ip);
    strcpy(new_session.SERVER_IP, server_ip);
    new_session.CONNECTION_PORT = port;
    new_session.ESTABLISHED_TIME = time(NULL);
    new_session.LAST_DATA_TIMESTAMP = time(NULL);
    new_session.SESSION_ID = session_id;
    new_session.state = CONN_STATE_ESTABLISHED;

    connection_manager.sessions[connection_manager.count++] = new_session;
    pthread_mutex_unlock(&connection_manager.mutex);

    return 0; // Success
}

// Additional functions for updating, retrieving, and managing sessions

int main() {
    pthread_mutex_init(&connection_manager.mutex, NULL);
    int result = add_session("192.168.1.1", "172.16.0.1", 8080, 12345);
    if (result == 0) {
        printf("Session added successfully.\n");
    } else {
        printf("Failed to add session: %d\n", result);
    }
    pthread_mutex_destroy(&connection_manager.mutex);
    return 0;
}
```

