    int CONNECTION_STATE;
    time_t LAST_ACTIVE_TIME;
    int ID;
} NETWORK_CONNECTION_T;

typedef struct {
    int PACKET_ID;
    char SOURCE_IP[MAX_IP_LENGTH];
    char DESTINATION_IP[MAX_IP_LENGTH];
    int PAYLOAD_SIZE;
    time_t TIMESTAMP;
} DATA_PACKET_T;

typedef struct {
    // Define your NFAPI_CRC_INDICATION_PDU_T structure here
} NFAPI_CRC_INDICATION_PDU_T;

pthread_mutex_t connection_mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_mutex_t packet_mutex = PTHREAD_MUTEX_INITIALIZER;

NETWORK_CONNECTION_T* connections[MAX_CONNECTIONS];
DATA_PACKET_T* packets[MAX_PACKETS];

int create_network_connection(char* IP_ADDRESS, int PORT_NUMBER) {
    if (IP_ADDRESS == NULL) {
        return -1; // Error: IP_ADDRESS is null
    }

    pthread_mutex_lock(&connection_mutex);
    for (int i = 0; i < MAX_CONNECTIONS; ++i) {
        if (connections[i] == NULL) {
            connections[i] = malloc(sizeof(NETWORK_CONNECTION_T));
            if (connections[i] == NULL) {
                pthread_mutex_unlock(&connection_mutex);
                return -2; // Error: Memory allocation failed
            }
            strcpy(connections[i]->IP_ADDRESS, IP_ADDRESS);
            connections[i]->PORT_NUMBER = PORT_NUMBER;
            connections[i]->CONNECTION_STATE = 1; // Assuming state is established
            time_t now = time(NULL);
            connections[i]->LAST_ACTIVE_TIME = now;
            connections[i]->ID = i;
            printf("Network connection created: ID=%d, IP=%s, Port=%d\n", i, IP_ADDRESS, PORT_NUMBER);
            pthread_mutex_unlock(&connection_mutex);
            return i; // Return the ID of the new connection
        }
    }
    pthread_mutex_unlock(&connection_mutex);
    return -3; // Error: No available slots for new connections
}

int create_data_packet(char* SOURCE_IP, char* DESTINATION_IP, int PAYLOAD_SIZE) {
    if (SOURCE_IP == NULL || DESTINATION_IP == NULL) {
        return -1; // Error: Either SOURCE_IP or DESTINATION_IP is null
    }

    pthread_mutex_lock(&packet_mutex);
    for (int i = 0; i < MAX_PACKETS; ++i) {
        if (packets[i] == NULL) {
            packets[i] = malloc(sizeof(DATA_PACKET_T));
            if (packets[i] == NULL) {
                pthread_mutex_unlock(&packet_mutex);
                return -2; // Error: Memory allocation failed
            }
            strcpy(packets[i]->SOURCE_IP, SOURCE_IP);
            strcpy(packets[i]->DESTINATION_IP, DESTINATION_IP);
            packets[i]->PAYLOAD_SIZE = PAYLOAD_SIZE;
            time_t now = time(NULL);
            packets[i]->TIMESTAMP = now;
            packets[i]->PACKET_ID = i;
            printf("Data packet created: ID=%d, Source IP=%s, Destination IP=%s, Payload Size=%d\n", i, SOURCE_IP, DESTINATION_IP, PAYLOAD_SIZE);
            pthread_mutex_unlock(&packet_mutex);
            return i; // Return the ID of the new data packet
        }
    }
    pthread_mutex_unlock(&packet_mutex);
    return -3; // Error: No available slots for new packets
}

void destroy_network_connection(int connection_id) {
    if (connection_id < 0 || connection_id >= MAX_CONNECTIONS || connections[connection_id] == NULL) {
        printf("Error: Invalid connection ID\n");
        return;
    }

    pthread_mutex_lock(&connection_mutex);
    free(connections[connection_id]);
    connections[connection_id] = NULL;
    pthread_mutex_unlock(&connection_mutex);
    printf("Network connection destroyed: ID=%d\n", connection_id);
}

void destroy_data_packet(int packet_id) {
    if (packet_id < 0 || packet_id >= MAX_PACKETS || packets[packet_id] == NULL) {
        printf("Error: Invalid packet ID\n");
        return;
    }

    pthread_mutex_lock(&packet_mutex);
    free(packets[packet_id]);
    packets[packet_id] = NULL;
    pthread_mutex_unlock(&packet_mutex);
    printf("Data packet destroyed: ID=%d\n", packet_id);
}

