    if (manager->used_count < manager->array_size) {
        memcpy(&manager->pdu_array[manager->used_count], pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
        manager->used_count++;
    } else {
        fprintf(stderr, "PDU array is full\n");
