#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    Node* tail;
    pthread_mutex_t mutex;
} LinkedList;

void initializeList(LinkedList* list) {
    list->head = NULL;
    list->tail = NULL;
    pthread_mutex_init(&list->mutex, NULL);
}

int appendNode(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) return -1; // Memory allocation failed

    newNode->data = data;
    newNode->next = NULL;

    pthread_mutex_lock(&list->mutex);
    if (!list->head) {
        list->head = newNode;
    } else {
        list->tail->next = newNode;
    }
    list->tail = newNode;
    pthread_mutex_unlock(&list->mutex);

    return 0; // Success
}

void freeList(LinkedList* list) {
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->mutex);
}

void* populateArray(void* arg) {
    LinkedList* list = (LinkedList*)arg;
    int N = 10000; // Example size
    for (int i = 0; i < N; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        pdu.RX_UE_INFORMATION_TAG = rand() % 100;
        pdu.RNTI = rand() % 65536;
        pdu.CRC_INDICATION_REL8_TAG = rand() % 2; // Randomly generate CRC flag

        if (appendNode(list, pdu) != 0) {
            fprintf(stderr, "Memory allocation failed\n");
            break;
        }
    }
    return NULL;
}

int main() {
    LinkedList list;
    initializeList(&list);

    pthread_t thread;
    if (pthread_create(&thread, NULL, populateArray, &list) != 0) {
        fprintf(stderr, "Thread creation failed\n");
        freeList(&list);
        return 1;
    }

    pthread_join(thread, NULL);

    // Additional code to measure and report performance metrics
    // ...

    freeList(&list);
    return 0;
}
