#[derive(Debug)]
struct NFAPI_CRC_INDICATION_PDU_T {
    rx_ue_information_tag: u32,
    rnti: u16,
    crc_indication_rel8_tag: bool,
}

const MAX_CONCURRENT_TASKS: usize = 100;
const API_TOKEN: &str = "your_api_token_here";
const NMS_API_URL: &str = "https://nms.api.example.com/report";

async fn generate_and_report_pdu(rx_ue_information_tag: u32, rnti: u16) {
    let pdu = NFAPI_CRC_INDICATION_PDU_T {
        rx_ue_information_tag,
        rnti,
        crc_indication_rel8_tag: rand::random(),
    };

    let client = Client::new();
    let semaphore = Arc::new(Semaphore::new(MAX_CONCURRENT_TASKS));

    for _ in 0..3 {
        if let Ok(_) = semaphore.try_acquire() {
            task::spawn(async move {
                match client.post(NMS_API_URL)
                    .header("Authorization", format!("Bearer {}", API_TOKEN))
                    .json(&pdu)
                    .send()
                    .await
                {
                    Ok(response) if response.status().is_success() => println!("Reported successfully"),
                    Err(_) | Ok(_) => time::sleep(Duration::from_secs(1)).await,
                }
            });
        } else {
            break;
        }
    }
}

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    let args: Vec<String> = env::args().collect();
    if args.len() != 2 {
        eprintln!("Usage: {} <N>", args[0]);
        return Ok(());
    }

    let n: usize = args[1].parse()?;

    for i in 0..n {
        generate_and_report_pdu(i as u32, (i * 100) as u16).await;
    }

    Ok(())
}
