#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/time.h>
#include <pthread.h>
#include <arpa/inet.h>

#define MAX_IPS_PER_HOST 10
#define CACHE_SIZE 256

typedef struct {
    char hostname[256];
    u_char ips[MAX_IPS_PER_HOST][4];
    time_t last_resolved;
} DnsCacheEntry;

DnsCacheEntry cache[CACHE_SIZE];
pthread_mutex_t cache_lock = PTHREAD_MUTEX_INITIALIZER;

int resolve_hostname(const char *hostname, u_char **ips, size_t *num_ips) {
    // Check cache first
    pthread_mutex_lock(&cache_lock);
    for (size_t i = 0; i < CACHE_SIZE; ++i) {
        if (strcmp(cache[i].hostname, hostname) == 0 && time(NULL) - cache[i].last_resolved < 3600) {
            *ips = (u_char *)malloc(MAX_IPS_PER_HOST * 4);
            if (*ips == NULL) {
                pthread_mutex_unlock(&cache_lock);
                return -1; // Memory allocation failed
            }
            memcpy(*ips, cache[i].ips, MAX_IPS_PER_HOST * 4);
            *num_ips = MAX_IPS_PER_HOST;
            pthread_mutex_unlock(&cache_lock);
            return 0; // Success from cache
        }
    }
    pthread_mutex_unlock(&cache_lock);

    // Perform actual DNS resolution
    struct addrinfo hints, *res, *p;
    int status;
    char ipstr[INET6_ADDRSTRLEN];

    memset(&hints, 0, sizeof hints);
    hints.ai_family = AF_UNSPEC; 
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        fprintf(stderr, "getaddrinfo: %s\n", gai_strerror(status));
        return -1; // DNS resolution failed
    }

    *num_ips = 0;
    for (p = res;p != NULL; p = p->ai_next) {
        void *addr;
        char *ipver;

        if (p->ai_family == AF_INET) { 
            struct sockaddr_in *ipv4 = (struct sockaddr_in *)p->ai_addr;
            addr = &(ipv4->sin_addr);
            ipver = "IPv4";
        } else { // should never reach here
            struct sockaddr_in6 *ipv6 = (struct sockaddr_in6 *)p->ai_addr;
            addr = &(ipv6->sin6_addr);
            ipver = "IPv6";
        }

        inet_ntop(p->ai_family, addr, ipstr, sizeof ipstr);
        memcpy((*ips) + (*num_ips) * 4, &addr, 4);
        (*num_ips)++;
    }
    freeaddrinfo(res);

    // Store in cache
    pthread_mutex_lock(&cache_lock);
    for (size_t i = 0; i < CACHE_SIZE; ++i) {
        if (cache[i].hostname[0] == '\0') {
            strcpy(cache[i].hostname, hostname);
            memcpy(cache[i].ips, *ips, *num_ips * 4);
            cache[i].last_resolved = time(NULL);
            break;
        }
    }
    pthread_mutex_unlock(&cache_lock);

    return 0; // Success
}

int main() {
    u_char *ips;
    size_t num_ips;

    if (resolve_hostname("www.example.com", &ips, &num_ips) == 0) {
        for (size_t i = 0; i < num_ips; ++i) {
            printf("%d.%d.%d.%d\n", ips[i*4], ips[i*4+1], ips[i*4+2], ips[i*4+3]);
        }
        free(ips);
    }

    return 0;
}
