CRCArray* create_crc_array() {
    CRCArray *array = (CRCArray *)malloc(sizeof(CRCArray));
    if (!array) {
        log_error("Failed to allocate memory for CRC array");
        return NULL;
    }
    array->data = (NFAPI_CRC_INDICATION_PDU_T *)calloc(MAX_ELEMENTS, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array->data) {
        free(array);
        log_error("Failed to allocate memory for CRC data");
        return NULL;
    }
    array->count = 0;
    array->capacity = MAX_ELEMENTS;
    pthread_mutex_init(&array->mutex, NULL);
    return array;
}

void destroy_crc_array(CRCArray *array) {
    if (array) {
        free(array->data);
        pthread_mutex_destroy(&array->mutex);
        free(array);
    }
}

int populate_crc_array(CRCArray *array) {
    if (!array || !array->data) {
        return -1;
    }

    for (size_t i = 0; i < array->capacity; ++i) {
        pthread_mutex_lock(&array->mutex);
        if (array->count >= array->capacity) {
            // Resize array or handle error
            pthread_mutex_unlock(&array->mutex);
            log_error("CRC array is full");
            return -1;
