        // Initialize stream fields
    }

    // Connect network and send data streams
    for (int i = 0; i < MAX_CONNECTIONS; ++i) {
        if (connectNetwork(connections[i]) != CONNECTED) {
            fprintf(stderr, "Failed to connect network\n");
            return EXIT_FAILURE;
        }
        for (int j = 0; j < MAX_STREAMS_PER_CONNECTION; ++j) {
            if (sendDataStream(connections[i], streams[j]) != SUCCESS) {
                fprintf(stderr, "Failed to send data stream\n");
                return EXIT_FAILURE;
            }
        }
    }

    // Export connections to JSON
    exportConnectionsToJson(connections, MAX_CONNECTIONS);

    // Free allocated memory
    for (int i = 0; i < MAX_CONNECTIONS; ++i) {
        free(connections[i]);
    }
    for (int i = 0; i < MAX_STREAMS_PER_CONNECTION; ++i) {
        free(streams[i]);
    }

    return EXIT_SUCCESS;
}
