int add_structure_to_list(DynamicList *list, NFAPI_CRC_INDICATION_PDU_T *new_struct) {
    pthread_mutex_lock(&list->lock);
    if (list->count >= MAX_STRUCTS) {
        pthread_mutex_unlock(&list->lock);
        return -1; // List is full
    }
    list->list[list->count++] = new_struct;
    pthread_mutex_unlock(&list->lock);
    return 0;
}

void resize_list(DynamicList *list) {
    if (list->count < THRESHOLD)
        return;

    pthread_mutex_lock(&list->lock);
    NFAPI_CRC_INDICATION_PDU_T **new_list = realloc(list->list, MAX_STRUCTS * 2 * sizeof(NFAPI_CRC_INDICATION_PDU_T *));
    if (new_list == NULL) {
        pthread_mutex_unlock(&list->lock);
        return; // Memory allocation failed
