    info.original_size = strlen(input);
    info.new_size = info.original_size;

    if (info.original_size < max_size && info.original_string[info.original_size - 1] != '/') {
        char* new_string = realloc(info.original_string, (max_size + 2) * sizeof(char));
        if (new_string == NULL) {
            perror("Memory reallocation failed");
            free(info.original_string);
            return NULL;
        }
        new_string[max_size + 1] = '\0';
        new_string[max_size] = '/';
        info.new_size++;
    } else {
        new_string = info.original_string;
    }

    fprintf(log_file, "String: %s, Original size: %zu, New size: %zu\n", new_string, info.original_size, info.new_size);

