#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>

// Define the maximum number of connections in the pool
#define MAX_CONNECTIONS 100

typedef struct {
    int id;
    int status; // 0 for free, 1 for in use
    void* data; // Pointer to connection-specific data
} Connection;

typedef struct {
    Connection connections[MAX_CONNECTIONS];
    int min_size;
    int max_size;
    int current_size;
    pthread_mutex_t pool_mutex;
    pthread_cond_t pool_condition;
    int log_level;
    FILE* log_file;
} ConnectionPool;

void init_pool(ConnectionPool *pool, int min_size, int max_size) {
    memset(pool->connections, 0, sizeof(Connection) * MAX_CONNECTIONS);
    pool->min_size = min_size;
    pool->max_size = max_size;
    pool->current_size = min_size;
    pthread_mutex_init(&pool->pool_mutex, NULL);
    pthread_cond_init(&pool->pool_condition, NULL);
    pool->log_level = 1; // Default log level
    pool->log_file = stdout;
}

Connection* get_connection(ConnectionPool *pool) {
    pthread_mutex_lock(&pool->pool_mutex);
    while (pool->current_size == 0 && pool->min_size > 0) {
        pthread_cond_wait(&pool->pool_condition, &pool->pool_mutex);
    }
    if (pool->current_size == 0) {
        pthread_mutex_unlock(&pool->pool_mutex);
        return NULL; // No available connections
    }
    Connection* conn = &pool->connections[pool->max_size - pool->current_size];
    conn->status = 1;
    pool->current_size--;
    pthread_mutex_unlock(&pool->pool_mutex);
    return conn;
}

void release_connection(ConnectionPool *pool, Connection *conn) {
    pthread_mutex_lock(&pool->pool_mutex);
    if (pool->current_size < pool->max_size) {
        conn->status = 0;
        pool->current_size++;
        pthread_cond_signal(&pool->pool_condition);
    }
    pthread_mutex_unlock(&pool->pool_mutex);
}

void set_log_level(ConnectionPool *pool, int level) {
    pool->log_level = level;
}

void log_event(ConnectionPool *pool, const char* message) {
    if (pool->log_level > 0) {
        fprintf(pool->log_file, "%s\n", message);
    }
}
```

