// Function to perform AES encryption using OpenSSL
int aes_encrypt(const unsigned char* plaintext, int plaintext_len, const unsigned char* key, const unsigned char* iv, unsigned char* ciphertext) {
    EVP_CIPHER_CTX *ctx;
    int len;
    int ciphertext_len;

    if (!(ctx = EVP_CIPHER_CTX_new())) return 0; // Error

    if (1 != EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv)) return 0; // Error
    if (1 != EVP_EncryptUpdate(ctx, ciphertext, &len, plaintext, plaintext_len)) return 0; // Error
    ciphertext_len = len;
    if (1 != EVP_EncryptFinal_ex(ctx, ciphertext + len, &len)) return 0; // Error
    ciphertext_len += len;

    EVP_CIPHER_CTX_free(ctx);

    return ciphertext_len;
}

// Function to perform Camellia encryption using OpenSSL
int camellia_encrypt(const unsigned char* plaintext, int plaintext_len, const unsigned char* key, const unsigned char* iv, unsigned char* ciphertext) {
    EVP_CIPHER_CTX *ctx;
    int len;
    int ciphertext_len;

    if (!(ctx = EVP_CIPHER_CTX_new())) return 0; // Error

    if (1 != EVP_EncryptInit_ex(ctx, EVP_camellia_256_cbc(), NULL, key, iv)) return 0; // Error
    if (1 != EVP_EncryptUpdate(ctx, ciphertext, &len, plaintext, plaintext_len)) return 0; // Error
    ciphertext_len = len;
    if (1 != EVP_EncryptFinal_ex(ctx, ciphertext + len, &len)) return 0; // Error
    ciphertext_len += len;

    EVP_CIPHER_CTX_free(ctx);

    return ciphertext_len;
}

// Function to perform MD5 hash using OpenSSL
void md5_hash(const unsigned char* data, size_t length, unsigned char* output) {
    MD5_CTX md5;
    MD5_Init(&md5);
    MD5_Update(&md5, data, length);
    MD5_Final(output, &md5);
}

// Function to perform SHA1 hash using OpenSSL
void sha1_hash(const unsigned char* data, size_t length, unsigned char* output) {
    SHA_CTX sha1;
    SHA1_Init(&sha1);
    SHA1_Update(&sha1, data, length);
    SHA1_Final(output, &sha1);
}

// Function to sign data using RSA with SHA1 and OpenSSL
int rsa_sign(const unsigned char* data, size_t data_len, const unsigned char* private_key, unsigned char* signature, size_t* sig_len) {
    EVP_PKEY* pkey = load_private_key(private_key);

    if (1 != EVP_SignInit_ex(NULL, EVP_sha1(), NULL)) return 0; // Error
    if (1 != EVP_SignUpdate(NULL, data, data_len)) return 0; // Error

    *sig_len = RSA_size(pkey->pkey.rsa);
    if (1 != EVP_SignFinal(NULL, signature, sig_len, pkey)) return 0; // Error

    EVP_PKEY_free(pkey);

    return 1; // Success
}

// Function to load a private key from file using OpenSSL
EVP_PKEY* load_private_key(const char* filename) {
    FILE *fp = fopen(filename, "r");
    if (!fp) return NULL;

    EVP_PKEY* pkey = PEM_read_PrivateKey(fp, NULL, NULL, NULL);
    fclose(fp);

    return pkey;
