NFAPI_CRC_INDICATION_PDU_T *list[MAX_STRUCTURES];
int list_size = 0;
pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *entry;
    int next_position;
} LOG_ENTRY;

LOG_ENTRY log_entries[LOG_SIZE];
int log_head = 0, log_tail = 0;
pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;

void add_to_list(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pthread_mutex_lock(&list_mutex);
    if (list_size >= MAX_STRUCTURES) {
        // Resize list
        NFAPI_CRC_INDICATION_PDU_T **new_list = realloc(list, MAX_STRUCTURES * 2 * sizeof(NFAPI_CRC_INDICATION_PDU_T *));
        if (!new_list) {
            perror("Failed to resize list");
            pthread_mutex_unlock(&list_mutex);
            return;
        }
        list = new_list;
    }
    list[list_size++] = pdu;
    pthread_mutex_unlock(&list_mutex);
}

void add_to_log(NFAPI_CRC_INDICATION_PDU_T *entry) {
    pthread_mutex_lock(&log_mutex);
    log_entries[log_head].entry = entry;
    log_entries[log_head].next_position = (log_head + 1) % LOG_SIZE;
    if (log_tail == log_head) {
        // Log is full, clear the oldest entry
        log_tail = (log_tail + 1) % LOG_SIZE;
    }
    log_head = (log_head + 1) % LOG_SIZE;
    pthread_mutex_unlock(&log_mutex);
}

void *scheduler_thread(void *arg) {
