        // Execute network processing task at specific interval
        for (int i = 0; i < list_size; i++) {
            NFAPI_CRC_INDICATION_PDU_T *pdu = list[i];
            // Process each structure here
            add_to_log(pdu);
        }
        // Add delay to match desired interval
        sleep(1); // Example: 1 second interval
    }
}

int main() {
