typedef struct {
    EVP_CIPHER *cipher;
} CipherContext;

CipherContext* initialize_secure_crypto_cipher(const char *password) {
    static const int key_length = 32;
    static const int iv_length = 16;
    static const int salt_length = 16;
    static const int iterations = 100000;
    unsigned char salt[salt_length];
    unsigned char key[key_length];
    unsigned char iv[iv_length];

    if (!RAND_bytes(salt, salt_length)) {
        fprintf(stderr, "Failed to generate random salt.\n");
        return NULL;
    }

    if (PKCS5_PBKDF2_HMAC(password, strlen(password), salt, salt_length, iterations,
                           EVP_sha256(), key_length, key) != 1) {
        fprintf(stderr, "PBKDF2 failed.\n");
        return NULL;
    }

    CipherContext *context = malloc(sizeof(CipherContext));
    if (!context) {
        fprintf(stderr, "Memory allocation failed.\n");
        return NULL;
    }

    // Example for AES-256-CBC
    context->cipher = EVP_aes_256_cbc();
    if (EVP_CIPHER_iv_length(context->cipher) != iv_length) {
        fprintf(stderr, "IV length mismatch.\n");
        free(context);
        return NULL;
    }

    memcpy(context->iv, iv, iv_length);

    // Additional ciphers can be added here following the same pattern

    return context;
}

// Example usage:
int main() {
    CipherContext *ctx = initialize_secure_crypto_cipher("mySecretPassword123");
    if (ctx) {
        printf("Cipher initialized successfully.\n");
        EVP_CIPHER_free(ctx->cipher);
        free(ctx);
    } else {
        printf("Failed to initialize cipher.\n");
    }
    return 0;
}
