#include <string.h>

typedef enum {
    ALGO_AES,
    ALGO_CAMELLIA,
    ALGO_MD5,
    ALGO_SHA,
    ALGO_RSA_WITH_SHA1,
    ALGO_SHA256,
    ALGO_SHA384
} AlgorithmType;

typedef struct {
    const char* name;
    int type;
} AlgorithmConfig;

int load_algorithm(const AlgorithmConfig* config) {
    EVP_add_cipher_byobj(config->type);
    return 0;
}

void unload_all_algorithms() {
    EVP_cleanup();
}

int configure_crypto_library(const char* config_str) {
    AlgorithmConfig algorithms[] = {
        {"AES", ALGO_AES},
        {"Camellia", ALGO_CAMELLIA},
        {"MD5", ALGO_MD5},
        {"SHA", ALGO_SHA},
        {"RSA_WITH_SHA1", ALGO_RSA_WITH_SHA1}
    };

    char* token = strtok((char*)config_str, ",");
    while (token) {
        int type = -1;
        for (int i = 0; i < sizeof(algorithms)/sizeof(AlgorithmConfig); i++) {
            if (strcmp(token, algorithms[i].name) == 0) {
                type = algorithms[i].type;
                break;
            }
        }

        if (type != -1) {
            load_algorithm(&algorithms[type]);
        } else {
            fprintf(stderr, "Unknown algorithm: %s\n", token);
            return 1;
        }

        token = strtok(NULL, ",");
    }

    return 0;
}

int main() {
    const char* config_str = "AES,Camellia,MD5,SHA,RSA_WITH_SHA1";
    int result = configure_crypto_library(config_str);

    if (result == 0) {
        printf("Library configured successfully.\n");
    } else {
        printf("Failed to configure library.\n");
    }

    unload_all_algorithms();
    return 0;
}
