char* add_slash_if_within_limit(const char* input, size_t limit, FILE* log_file) {
    if (input == NULL || log_file == NULL) {
        return NULL;
    }

    size_t length = strlen(input);

    if (length >= limit) {
        log_string_manipulation(input, length, 0);
        return NULL;
    }

    char* new_string = malloc(length + 2); // +1 for slash and +1 for null terminator
    if (new_string == NULL) {
        return NULL; // Handle memory allocation failure
    }

    strcpy(new_string, input);
    new_string[length] = '/';
    new_string[length + 1] = '\0';

    log_string_manipulation(input, length, 1);

    return new_string;
}

int main() {
    const char* input = "HelloWorld";
    size_t limit = 10;
    FILE* log_file = stdout;

    char* result = add_slash_if_within_limit(input, limit, log_file);
    if (result != NULL) {
        printf("Result: %s\n", result);
        free(result); // Free dynamically allocated memory
    } else {
        printf("String not modified or allocation failed.\n");
    }

    return 0;
}
