#include <time.h>

#define MAX_ENTRIES 1024

typedef struct {
    int RX_UE_INFORMATION_TAG;
    unsigned short RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *entries;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} CRC_LIST_T;

void init_crc_list(CRC_LIST_T *list) {
    list->entries = NULL;
    list->count = 0;
    list->capacity = 0;
    pthread_mutex_init(&list->lock, NULL);
}

void destroy_crc_list(CRC_LIST_T *list) {
    free(list->entries);
    pthread_mutex_destroy(&list->lock);
}

NFAPI_CRC_INDICATION_PDU_T* create_entry() {
    NFAPI_CRC_INDICATION_PDU_T *entry = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    entry->RX_UE_INFORMATION_TAG = rand();
    entry->RNTI = (unsigned short)rand();
    entry->CRC_INDICATION_REL8_TAG = rand();
    entry->CRCFLAG = rand() % 2; // Randomly set to either 0 or 1
    return entry;
}

int add_entry_to_list(CRC_LIST_T *list, NFAPI_CRC_INDICATION_PDU_T *entry) {
    pthread_mutex_lock(&list->lock);
    if (list->count >= list->capacity) {
        size_t new_capacity = list->capacity > 0 ? list->capacity * 2 : 1;
        NFAPI_CRC_INDICATION_PDU_T *new_entries = realloc(list->entries, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_entries) {
            pthread_mutex_unlock(&list->lock);
            return -1; // Memory allocation failed
        }
        list->entries = new_entries;
        list->capacity = new_capacity;
    }
    list->entries[list->count++] = *entry;
    pthread_mutex_unlock(&list->lock);
    return 0;
}

int ensure_unique_rnti(CRC_LIST_T *list, NFAPI_CRC_INDICATION_PDU_T *entry) {
    for (size_t i = 0; i < list->count; ++i) {
        if (list->entries[i].RNTI == entry->RNTI) {
            return -1; // RNTI already exists
        }
    }
    return 0;
}

int create_crc_indication_list(CRC_LIST_T *list, size_t requested_entries) {
    pthread_mutex_lock(&list->lock);
    size_t entries_to_create = requested_entries > MAX_ENTRIES ? MAX_ENTRIES : requested_entries;
    for (size_t i = 0; i < entries_to_create; ++i) {
        NFAPI_CRC_INDICATION_PDU_T *entry = create_entry();
        if (!entry) {
            pthread_mutex_unlock(&list->lock);
            return -1; // Memory allocation failed
        }
        if (ensure_unique_rnti(list, entry) != 0) {
            free(entry); // Free the allocated memory for invalid entry
            pthread_mutex_unlock(&list->lock);
            return -1; // Duplicate RNTI found
        }
        if (add_entry_to_list(list, entry) != 0) {
            free(entry); // Free the allocated memory before returning error
            pthread_mutex_unlock(&list->lock);
            return -1;
        }
    }
    pthread_mutex_unlock(&list->lock);
    return 0;
}
