#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct LTE_UE_Bearer {
    int bearerId;
    struct LTE_UE_Bearer* next;
} LTE_UE_Bearer;

typedef struct LTE_UE_Context {
    int ueId;
    char servingPlmnId[16];
    LTE_UE_Bearer* activeBearers;
    pthread_mutex_t mutex;
} LTE_UE_Context;

typedef struct LTE_UE_List {
    LTE_UE_Context** contexts;
    int capacity;
    int size;
    pthread_mutex_t lock;
} LTE_UE_List;

LTE_UE_List* createLTE_UE_List(int initialCapacity) {
    LTE_UE_List* list = (LTE_UE_List*)malloc(sizeof(LTE_UE_List));
    if (!list) return NULL;
    list->contexts = (LTE_UE_Context**)calloc(initialCapacity, sizeof(LTE_UE_Context*));
    if (!list->contexts) {
        free(list);
        return NULL;
    }
    list->capacity = initialCapacity;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void destroyLTE_UE_List(LTE_UE_List* list) {
    if (!list) return;
    for (int i = 0; i < list->size; ++i) {
        LTE_UE_Context* ctx = list->contexts[i];
        pthread_mutex_destroy(&ctx->mutex);
        LTE_UE_Bearer* bearer = ctx->activeBearers;
        while (bearer) {
            LTE_UE_Bearer* next = bearer->next;
            free(bearer);
            bearer = next;
        }
        free(ctx);
    }
    free(list->contexts);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

LTE_UE_Context* addNewUE(LTE_UE_List* list, int ueId, const char* servingPlmnId) {
    if (!list || !servingPlmnId) return NULL;
    pthread_mutex_lock(&list->lock);
    if (list->size == list->capacity) {
        list->contexts = (LTE_UE_Context**)realloc(list->contexts, list->capacity * 2 * sizeof(LTE_UE_Context*));
        if (!list->contexts) {
            pthread_mutex_unlock(&list->lock);
            return NULL;
        }
        list->capacity *= 2;
    }
    LTE_UE_Context* ctx = (LTE_UE_Context*)malloc(sizeof(LTE_UE_Context));
    if (!ctx) {
        pthread_mutex_unlock(&list->lock);
        return NULL;
    }
    pthread_mutex_init(&ctx->mutex, NULL);
    ctx->ueId = ueId;
    snprintf(ctx->servingPlmnId, sizeof(ctx->servingPlmnId), "%s", servingPlmnId);
    ctx->activeBearers = NULL;
    list->contexts[list->size++] = ctx;
    pthread_mutex_unlock(&list->lock);
    return ctx;
}

LTE_UE_Context* getUEContext(LTE_UE_List* list, int ueId) {
    if (!list) return NULL;
    pthread_mutex_lock(&list->lock);
    for (int i = 0; i < list->size; ++i) {
        LTE_UE_Context* ctx = list->contexts[i];
        pthread_mutex_lock(&ctx->mutex);
        if (ctx->ueId == ueId) {
            pthread_mutex_unlock(&ctx->mutex);
            pthread_mutex_unlock(&list->lock);
            return ctx;
        }
        pthread_mutex_unlock(&ctx->mutex);
    }
    pthread_mutex_unlock(&list->lock);
    return NULL;
}
```

This code defines a dynamic list of LTE UE Contexts, including functions to initialize, add new contexts, and retrieve contexts by UE ID. It uses mutexes for concurrent access synchronization and memory management to ensure efficient performance in large-scale deployment scenarios.']

