#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Function to append a slash to a string if it does not exceed the size limit
char* appendSlashIfUnderLimit(const char* input, size_t maxSize, FILE* logFile) {
    // Allocate memory for the new string
    char* result = (char*)malloc((maxSize + 2) * sizeof(char)); // Extra space for slash and null terminator
    if (!result) {
        perror("Memory allocation failed");
        return NULL;
    }

    // Check if the input exceeds the size limit
    if (strlen(input) < maxSize) {
        strcpy(result, input);
        result[maxSize] = '/'; // Append a slash
        result[maxSize + 1] = '\0';
    } else {
        result[0] = '\0'; // Return an empty string if exceeds limit
    }

    // Log the operation details
    fprintf(logFile, "String: %s\n", input);
    fprintf(logFile, "Original Size: %zu\n", strlen(input));
    fprintf(logFile, "Slash Added: %s\n", (strlen(result) > strlen(input)) ? "Yes" : "No");
    fprintf(logFile, "-----------------\n");

    return result;
}

// Example usage
int main() {
    const char* input = "HelloWorld";
    size_t maxSize = 10;
    FILE* logFile = fopen("log.txt", "a");

    if (logFile == NULL) {
        perror("Failed to open log file");
        return EXIT_FAILURE;
    }

    char* output = appendSlashIfUnderLimit(input, maxSize, logFile);
    if (output != NULL) {
        printf("Processed String: %s\n", output);
        free(output); // Free the allocated memory
    } else {
        printf("Failed to process string.\n");
    }

    fclose(logFile);
    return EXIT_SUCCESS;
}
