#include <stdlib.h>
#include <pthread.h>

#define MAX_ENTRIES 1000

typedef struct {
    RX_UE_INFORMATION_TAG ue_info;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_flag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *buffer;
    int size;
    int capacity;
    pthread_mutex_t mutex;
    pthread_cond_t not_full;
    pthread_cond_t not_empty;
} CRC_QUEUE_T;

void init_crc_queue(CRC_QUEUE_T *queue, int initial_capacity) {
    queue->buffer = malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    queue->size = 0;
    queue->capacity = initial_capacity;
    pthread_mutex_init(&queue->mutex, NULL);
    pthread_cond_init(&queue->not_full, NULL);
    pthread_cond_init(&queue->not_empty, NULL);
}

void destroy_crc_queue(CRC_QUEUE_T *queue) {
    free(queue->buffer);
    pthread_mutex_destroy(&queue->mutex);
    pthread_cond_destroy(&queue->not_full);
    pthread_cond_destroy(&queue->not_empty);
}

int enqueue_entry(CRC_QUEUE_T *queue, NFAPI_CRC_INDICATION_PDU_T entry) {
    pthread_mutex_lock(&queue->mutex);
    while (queue->size == queue->capacity) {
        pthread_cond_wait(&queue->not_full, &queue->mutex);
    }
    if (queue->size < queue->capacity) {
        queue->buffer[queue->size++] = entry;
        pthread_cond_signal(&queue->not_empty);
        pthread_mutex_unlock(&queue->mutex);
        return 0; // Success
    }
    pthread_mutex_unlock(&queue->mutex);
    return -1; // Queue full
}

int dequeue_entry(CRC_QUEUE_T *queue, NFAPI_CRC_INDICATION_PDU_T *entry) {
    pthread_mutex_lock(&queue->mutex);
    while (queue->size == 0) {
        pthread_cond_wait(&queue->not_empty, &queue->mutex);
    }
    if (queue->size > 0) {
        *entry = queue->buffer[--queue->size];
        pthread_cond_signal(&queue->not_full);
        pthread_mutex_unlock(&queue->mutex);
        return 0; // Success
    }
    pthread_mutex_unlock(&queue->mutex);
    return -1; // Queue empty
}

int create_crc_entries(CRC_QUEUE_T *queue, int num_entries) {
    pthread_mutex_lock(&queue->mutex);
    if (num_entries + queue->size > MAX_ENTRIES) {
        pthread_mutex_unlock(&queue->mutex);
        return -1; // Exceeds maximum capacity
    }
    for (int i = 0; i < num_entries; ++i) {
        NFAPI_CRC_INDICATION_PDU_T entry;
        // Populate entry with valid data, ensuring unique RNTI and random CRCFLAG
        // ...
        enqueue_entry(queue, entry);
    }
    pthread_mutex_unlock(&queue->mutex);
    return 0; // Success
}
