NFAPI_CRC_INDICATION_PDU_T* create_and_populate_pdus(uint32_t N, pthread_mutex_t* mutex, ErrorCodes* error_code) {
    NFAPI_CRC_INDICATION_PDU_T* pdus = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (pdus == NULL) {
