#include <stdlib.h>
#include <pthread.h>
#include <stdio.h>

#define MAX_RNTI 0x3FFFFF

typedef struct {
    uint16_t RNTI;
    uint8_t CRCFLAG;
} RX_UE_INFORMATION_TAG;

typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_info;
    // Add other necessary fields as per NFAPI_CRC_INDICATION_PDU_T structure
} NFAPI_CRC_INDICATION_PDU_T;

void* initialize_and_populate_pdu_list(void* arg) {
    int num_pdus = *(int*)arg;
    NFAPI_CRC_INDICATION_PDU_T** pdu_list = (NFAPI_CRC_INDICATION_PDU_T**)malloc(num_pdus * sizeof(NFAPI_CRC_INDICATION_PDU_T*));

    if (!pdu_list) {
        perror("Failed to allocate memory for PDU list");
        return NULL;
    }

    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

    for (int i = 0; i < num_pdus; ++i) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));

        if (!pdu) {
            perror("Failed to allocate memory for PDU");
            for (int j = 0; j < i; ++j) free(pdu_list[j]);
            free(pdu_list);
            return NULL;
        }

        pthread_mutex_lock(&lock);

        uint16_t rnti = rand() % (MAX_RNTI + 1); // Generate a random RNTI
        if (rnti == 0 || rnti > MAX_RNTI) {
            fprintf(stderr, "Invalid RNTI value generated: 0x%X\n", rnti);
            free(pdu);
        } else {
            pdu->rx_ue_info.RNTI = rnti;
            // Initialize other fields as per NFAPI_CRC_INDICATION_PDU_T structure
            pdu->rx_ue_info.CRCFLAG = rand() % 2; // Randomly set CRCFLAG

            pdu_list[i] = pdu;
        }

        pthread_mutex_unlock(&lock);
    }

    *arg = (int)num_pdus; // Return the number of PDUs initialized successfully
    return pdu_list;
}

// Usage example:
int main() {
    int num_threads = 4;
    int num_pdus_per_thread = 100;

    pthread_t threads[num_threads];
    int thread_args[num_threads];

    for (int i = 0; i < num_threads; ++i) {
        thread_args[i] = num_pdus_per_thread;
        if (pthread_create(&threads[i], NULL, initialize_and_populate_pdu_list, &thread_args[i]) != 0) {
            perror("Failed to create thread");
            return EXIT_FAILURE;
        }
    }

    for (int i = 0; i < num_threads; ++i) {
        NFAPI_CRC_INDICATION_PDU_T** pdu_list;
        if (pthread_join(threads[i], (void**)&pdu_list) != 0) {
            perror("Failed to join thread");
            return EXIT_FAILURE;
        }

        // Process the PDU list as needed
        for (int j = 0; j < thread_args[i]; ++j) free(pdu_list[j]);
        free(pdu_list);
    }

    return EXIT_SUCCESS;
}
