typedef struct {
    PduData *pdus;
    size_t allocatedSize;
    size_t usedSize;
    sem_t mutex;
    sem_t semaphore;
} PduList;

void initPduList(PduList *list, size_t initialSize) {
    list->allocatedSize = initialSize;
    list->usedSize = 0;
    list->pdus = (PduData *)malloc(initialSize * sizeof(PduData));
    sem_init(&list->mutex, 0, 1);
    sem_init(&list->semaphore, 0, 1);
}

void freePduList(PduList *list) {
    sem_wait(&list->mutex);
    free(list->pdus);
    list->pdus = NULL;
    list->allocatedSize = 0;
    list->usedSize = 0;
    sem_post(&list->mutex);
    sem_destroy(&list->mutex);
    sem_destroy(&list->semaphore);
}

int addPdu(PduList *list, PduData pdu) {
    sem_wait(&list->mutex);
    if (list->usedSize >= list->allocatedSize) {
        size_t newSize = list->allocatedSize ? list->allocatedSize * 2 : 10;
        PduData *newPdus = realloc(list->pdus, newSize * sizeof(PduData));
        if (!newPdus) {
            sem_post(&list->mutex);
            return -1; // Out of memory
        }
        list->pdus = newPdus;
        list->allocatedSize = newSize;
    }
    list->pdus[list->usedSize++] = pdu;
    sem_post(&list->mutex);
    return 0;
