int generate_unique_rnti(int range_start, int range_end, int *used_rntis, int used_count) {
    srand(time(0));
    int rnti;
    while (1) {
        rnti = rand() % (range_end - range_start + 1) + range_start;
        int i;
        for (i = 0; i < used_count; i++) {
            if (used_rntis[i] == rnti) break;
        }
        if (i == used_count) return rnti;
    }
}

void generate_pdu_list(PDU_LIST_STRUCT *pdu_list, int N) {
    pthread_mutex_lock(&pdu_list->mutex);
    for (int i = 0; i < N; i++) {
        pdu_list->pdu_list[i].RX_UE_INFORMATION_TAG = rand() % 100;
        int rnti;
        do {
            rnti = generate_unique_rnti(1, 1023, used_rntis, used_count);
        } while (1); // Simplified for demonstration
        pdu_list->pdu_list[i].RNTI = rnti;
        pdu_list->pdu_list[i].CRC_INDICATION_REL8_TAG = rand() % 256;
        pdu_list->pdu_list[i].CRCFLAG = rand() % 2; // True or False
    }
    pthread_mutex_unlock(&pdu_list->mutex);
}

