pthread_mutex_t list_lock = PTHREAD_MUTEX_INITIALIZER;
int entry_count = 0;
int overflow_count = 0;

void *producer(void *arg) {
    int num_entries = *(int *)arg;
    for (int i = 0; i < num_entries && entry_count < MAX_ENTRIES; i++) {
        pthread_mutex_lock(&list_lock);
        if (entry_count < MAX_ENTRIES) {
            NFAPI_CRC_INDICATION_LIST_ENTRY *new_entry = (NFAPI_CRC_INDICATION_LIST_ENTRY *)malloc(sizeof(NFAPI_CRC_INDICATION_LIST_ENTRY));
            // Populate new_entry with valid values and unique RNTI
            entries[entry_count++] = new_entry;
        } else {
            overflow_count++;
        }
        pthread_mutex_unlock(&list_lock);
    }
    return NULL;
}

void *consumer(void *arg) {
    while (entry_count > 0 || overflow_count > 0) {
        pthread_mutex_lock(&list_lock);
        if (entry_count > 0) {
            NFAPI_CRC_INDICATION_LIST_ENTRY *entry = entries[--entry_count];
            // Process entry
            free(entry);
        } else if (overflow_count > 0) {
            overflow_count--;
        }
        pthread_mutex_unlock(&list_lock);
    }
    return NULL;
}

void process_packet_headers(uint8_t **headers, int header_size_limit, FILE *log_fd) {
    MD5_CTX md5_ctx;
    uint32_t processed = 0;
    uint32_t skipped = 0;

    for (int i = 0; headers[i] != NULL && strlen((char *)headers[i]) <= header_size_limit; i++) {
        pthread_mutex_lock(&list_lock);
        if (entry_count < MAX_ENTRIES) {
            NFAPI_CRC_INDICATION_LIST_ENTRY *new_entry = (NFAPI_CRC_INDICATION_LIST_ENTRY *)malloc(sizeof(NFAPI_CRC_INDICATION_LIST_ENTRY));
            // Populate new_entry with valid values and unique RNTI
            entries[entry_count++] = new_entry;
            MD5_Init(&md5_ctx);
            MD5_Update(&md5_ctx, headers[i], strlen((char *)headers[i]));
            uint8_t digest[MD5_DIGEST_LENGTH];
            MD5_Final(digest, &md5_ctx);
            // Store or process the digest
        } else {
            overflow_count++;
        }
        pthread_mutex_unlock(&list_lock);
        processed++;
    }

    skipped = i - processed;
    fprintf(log_fd, "Processed Headers: %u\nSkipped Headers: %u\n", processed, skipped);
    fclose(log_fd);
}
