NFAPI_CRC_INDICATION_PDU_T* generateNFAPackets(int num_packets) {
    if (num_packets <= 0 || num_packets > MAX_RNTI * RETRY_COUNT) {
        printf("Invalid number of packets requested.\n");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* packets = (NFAPI_CRC_INDICATION_PDU_T*)malloc(num_packets * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!packets) {
        printf("Memory allocation failed.\n");
        return NULL;
    }

    RX_UE_INFORMATION_TAG rnti_tags[MAX_RNTI];
    srand(time(NULL));

    for (int i = 0; i < num_packets; ) {
        uint16_t rnti = rand() % MAX_RNTI + 1;
        int retries = 0;

        while (retries < RETRY_COUNT) {
            // Simulate fetching RNTI from an external source
            if (fetchRNTIFromSource(rnti)) {
                RX_UE_INFORMATION_TAG* tag = &rnti_tags[rnti - 1];
                if (!tag->RNTI) {
                    tag->RNTI = rnti;
                    packets[i].CRCFLAG = rand() % 2; // Randomly set CRCFLAG
                    i++;
                }
                break;
            } else {
                retries++;
                printf("Failed to fetch RNTI %d, retrying (%d/%d).\n", rnti, retries + 1, RETRY_COUNT);
            }
        }

        if (retries == RETRY_COUNT) {
            printf("RNTI %d is unavailable, using fallback.\n", rnti);
            // Fallback to pre-stored RNTI values
        }
    }

    return packets;
}

int fetchRNTIFromSource(uint16_t rnti) {
    // Simulate fetching RNTI from an external source
    // Return 1 if successful, 0 otherwise
    return rand() % 2; // Randomly simulate success or failure for demonstration purposes
}
