#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <openssl/sha.h>

#define MAX_ENTRIES 1000

typedef struct DataPacket {
    int packet_id;
    int data_length;
    int priority_level;
    // Add other fields as needed
} DataPacket;

typedef struct QueueNode {
    DataPacket* packet;
    struct QueueNode* next;
} QueueNode;

typedef struct ThreadSafeQueue {
    QueueNode* front;
    QueueNode* rear;
    pthread_mutex_t mutex;
    pthread_cond_t cond_not_full;
    pthread_cond_t cond_not_empty;
    int capacity;
    int size;
} ThreadSafeQueue;

void init_queue(ThreadSafeQueue* queue, int max_entries) {
    queue->front = queue->rear = NULL;
    pthread_mutex_init(&queue->mutex, NULL);
    pthread_cond_init(&queue->cond_not_full, NULL);
    pthread_cond_init(&queue->cond_not_empty, NULL);
    queue->capacity = max_entries;
    queue->size = 0;
}

void enqueue(ThreadSafeQueue* queue, DataPacket* packet) {
    QueueNode* new_node = (QueueNode*)malloc(sizeof(QueueNode));
    new_node->packet = packet;
    new_node->next = NULL;

    pthread_mutex_lock(&queue->mutex);
    while (queue->size == queue->capacity) {
        pthread_cond_wait(&queue->cond_not_full, &queue->mutex);
    }

    if (queue->rear == NULL) {
        queue->front = queue->rear = new_node;
    } else {
        queue->rear->next = new_node;
        queue->rear = new_node;
    }
    queue->size++;
    pthread_cond_signal(&queue->cond_not_empty);
    pthread_mutex_unlock(&queue->mutex);
}

DataPacket* dequeue(ThreadSafeQueue* queue) {
    DataPacket* packet = NULL;

    pthread_mutex_lock(&queue->mutex);
    while (queue->size == 0) {
        pthread_cond_wait(&queue->cond_not_empty, &queue->mutex);
    }

    if (queue->front != NULL) {
        QueueNode* temp = queue->front;
        packet = queue->front->packet;
        queue->front = queue->front->next;

        if (queue->front == NULL) {
            queue->rear = NULL;
        }
        free(temp);
        queue->size--;
        pthread_cond_signal(&queue->cond_not_full);
    }

    pthread_mutex_unlock(&queue->mutex);
    return packet;
}

void destroy_queue(ThreadSafeQueue* queue) {
    while (queue->front != NULL) {
        QueueNode* temp = queue->front;
        free(queue->front->packet);
        queue->front = queue->front->next;
        free(temp);
    }
    pthread_mutex_destroy(&queue->mutex);
    pthread_cond_destroy(&queue->cond_not_full);
    pthread_cond_destroy(&queue->cond_not_empty);
}

// Add other functions as needed
