#define HTTP_STATUS_OK 200
#define HTTP_STATUS_INTERNAL_SERVER_ERROR 599

typedef struct HttpResponse {
    int statusCode;
    char* body;
    // Add other headers here
} HttpResponse;

typedef struct ResponseList {
    HttpResponse** responses;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
} ResponseList;

ResponseList* createResponseList(size_t initialCapacity) {
    ResponseList* list = (ResponseList*)malloc(sizeof(ResponseList));
    if (!list) return NULL;

    list->responses = (HttpResponse**)calloc(initialCapacity, sizeof(HttpResponse*));
    if (!list->responses) {
        free(list);
        return NULL;
    }

    list->size = 0;
    list->capacity = initialCapacity;
    pthread_mutex_init(&list->lock, NULL);

    return list;
}

void destroyResponseList(ResponseList* list) {
    for (size_t i = 0; i < list->size; ++i) {
        free(list->responses[i]->body);
        free(list->responses[i]);
    }
    free(list->responses);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

bool addResponse(ResponseList* list, int statusCode, const char* body) {
    if (statusCode < HTTP_STATUS_OK || statusCode > HTTP_STATUS_INTERNAL_SERVER_ERROR) return false;

    pthread_mutex_lock(&list->lock);

    if (list->size >= list->capacity) {
        size_t newCapacity = list->capacity == 0 ? 1 : list->capacity * 2;
        HttpResponse** newResponses = (HttpResponse**)realloc(list->responses, newCapacity * sizeof(HttpResponse*));
        if (!newResponses) {
            pthread_mutex_unlock(&list->lock);
            return false;
        }
        list->responses = newResponses;
        list->capacity = newCapacity;
    }

    HttpResponse* response = (HttpResponse*)malloc(sizeof(HttpResponse));
    if (!response) {
        pthread_mutex_unlock(&list->lock);
        return false;
    }

    response->statusCode = statusCode;
    response->body = strdup(body); // Assuming body is a string
    list->responses[list->size++] = response;

    pthread_mutex_unlock(&list->lock);
    return true;
}

